@app.get("/api/analytics/snapshots", dependencies=[Depends(verify_dashboard_token)])
async def get_snapshot_dates(x_workspace_slug: Optional[str] = Header(None)):
    """Returns list of dates for which snapshots exist for this workspace."""
    dates = _list_snapshot_dates(x_workspace_slug or 'global')
    return {"dates": dates, "count": len(dates), "retention_days": SNAPSHOT_RETENTION_DAYS}

@app.post("/api/analytics/snapshots/capture", dependencies=[Depends(verify_dashboard_token)])
async def trigger_snapshot(
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None)
):
    """Manually trigger a snapshot capture for today. Useful for first-time setup."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(401, "Missing credentials")
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    captured = await _capture_daily_snapshot(authorization, x_workspace_slug, today)
    return {"status": "ok", "date": today, "sources_captured": captured}

@app.get("/api/analytics/device-risk-trend", dependencies=[Depends(verify_dashboard_token)])
async def get_device_risk_trend(days: int = 30, x_workspace_slug: Optional[str] = Header(None)):
    """Reads back the 'device_risk_summary' snapshots saved by
    _capture_daily_snapshot — one point per day the snapshot job has run,
    each with the fleet's average/max risk score and a tier breakdown at
    that point in time. Answers "is the fleet's risk drifting up or down",
    which the live Devices view (point-in-time only) can't show on its own."""
    slug_key = x_workspace_slug or 'global'
    dates = _list_snapshot_dates(slug_key)[-max(1, min(days, 365)):]
    points = []
    for date_str in dates:
        summary = _load_snapshot(slug_key, date_str, "device_risk_summary")
        if summary:
            points.append({"date": date_str, **summary})
    return {"items": points}

# ─── DEVICE FLEET API (SOAR foundation) ───
# Dedicated, normalized device endpoint for the Devices view and, later, the
# Conditional Access Policy engine — rules will evaluate against this same
# normalized shape, and actions will target devices via platformDeviceId.
# Deliberately separate from the analytics widget proxy below: reporting and
# dashboard widgets keep using their existing code path untouched.
#
# Org-level calls only: ONE call for all devices + ONE call for compliant
# devices (to derive isCompliant), regardless of fleet size — no per-device
# requests. Reuses the existing in-memory live cache (5 min TTL) so the
# Devices view, dashboard widgets, and Playground globe don't multiply calls
# to the Applivery API when loaded together.

DEVICES_CACHE_SOURCE = "devices_full"

async def _resolve_org_base(client: httpx.AsyncClient, headers: dict, x_workspace_slug: str) -> str:
    """Resolve a workspace slug or hex ID to the '{base_url}/organizations/{hexId}' root."""
    base_url = "https://api.applivery.io/v1"
    hex_id = x_workspace_slug
    if not re.match(r'^[a-fA-F0-9]{24}$', hex_id):
        org_res = await _applivery_call(client, 'GET', f"{base_url}/organizations/{x_workspace_slug}", headers=headers)
        if org_res.status_code == 200:
            d = org_res.json().get("data", org_res.json())
            hex_id = d.get("_id", d.get("id", hex_id))
    return f"{base_url}/organizations/{hex_id}"

def _parse_capacity_gb(val: Any) -> Optional[float]:
    """Best-effort parse of a storage/RAM value into GB. Ported from the Flutter
    reference's parseCap() — values look like raw bytes when > ~1e6."""
    if val is None:
        return None
    try:
        v = float(val) if not isinstance(val, str) else float(re.sub(r'[^0-9.]', '', val) or 0)
    except (TypeError, ValueError):
        return None
    if v <= 0:
        return None
    return v / (1024 ** 3) if v > 1_000_000 else v

# Policy keys carrying a single applied-policy object, keyed by the platform they imply.
_SINGLE_POLICY_KEYS = [
    ('appliedEmmPolicy', 'android'), ('deviceEmmPolicy', 'android'), ('emmPolicy', 'android'),
    ('appliedAdmPolicy', 'apple'), ('deviceAdmPolicy', 'apple'), ('admPolicy', 'apple'),
    ('appliedWinPolicy', 'windows'), ('deviceWinPolicy', 'windows'), ('winPolicy', 'windows'),
]
# Policy keys carrying an array of assignment objects, keyed by the platform they imply.
_ARRAY_POLICY_KEYS = [
    ('emmPolicyAssignments', 'android'), ('emmPolicyAssignmentsEnforced', 'android'),
    ('admPolicyAssignments', 'apple'), ('admPolicyAssignmentsEnforced', 'apple'),
    ('winPolicyAssignments', 'windows'), ('winPolicyAssignmentsEnforced', 'windows'),
]

def _extract_active_policies(raw: dict) -> List[Dict[str, Any]]:
    """
    Simplified port of the Flutter reference's robust policy extraction: reads
    both the "single applied policy" keys and the "assignment array" keys
    Applivery uses across platforms, and returns a clean, de-duplicated
    [{id, name, platform}] list for display and for reassignment (policy PUT).
    """
    found: List[Dict[str, Any]] = []
    seen = set()

    def add(p: Any, platform: str):
        if not p:
            return
        pid, name = None, None
        if isinstance(p, dict):
            pid = p.get('id') or p.get('_id') or p.get('policyId') or p.get('emmPolicyId') or p.get('admPolicyId') or p.get('winPolicyId')
            name = p.get('name') or p.get('policyName') or p.get('emmPolicyName') or p.get('admPolicyName') or p.get('winPolicyName')
        elif isinstance(p, str) and p.strip():
            name = pid = p.strip()
        if pid is not None:
            pid = str(pid)
        if not name or not str(name).strip():
            return
        key = (platform, pid or name)
        if key in seen:
            return
        seen.add(key)
        found.append({"id": pid, "name": str(name).strip(), "platform": platform})

    for key, platform in _SINGLE_POLICY_KEYS:
        add(raw.get(key), platform)

    for key, platform in _ARRAY_POLICY_KEYS:
        items = raw.get(key)
        if isinstance(items, list):
            for entry in items:
                if isinstance(entry, dict):
                    nested = entry.get('admPolicy') or entry.get('emmPolicy') or entry.get('winPolicy')
                    add(nested if nested else entry, platform)
                else:
                    add(entry, platform)

    return found

async def _fetch_device_audience_membership_map(client: httpx.AsyncClient, headers: dict, org_base: str, raw_devices: Optional[list] = None) -> Dict[str, list]:
    """Device Audiences are a dynamic, cross-platform device grouping
    feature — NOT the same resource as MDM Policies or Segments. Membership
    isn't carried on the device record itself, so this fetches every
    audience once and inverts each one's member list into a per-device map,
    the same pattern already used for `comp_ids`/isCompliant above. Cheap in
    practice — organizations typically have a handful of audiences, not
    hundreds.

    CONFIRMED API contract — and this time confirmed against a REAL response
    body from a live tenant (the user ran the curl themselves and pasted the
    actual JSON), which is the ground truth this function now matches. Two
    earlier passes at this bug both trusted secondary sources over that —
    Applivery's own published OpenAPI reference (fetched via their docs MCP)
    — which turned out to describe a DIFFERENT, stale response shape than
    what the live API actually returns for this endpoint:

    - GET {org_base}/mdm/device-audiences lists audiences (id, name, etc).
      This part was never wrong.
    - GET {org_base}/mdm/device-audiences/{deviceAudienceId}/preview is the
      right URL (also never wrong) — but its actual response is:
      {"status": true, "data": {"items": [...], "totalDocs", "limit",
      "page", "hasNextPage", ...}} — a flat, PAGINATED list of full device
      records (same "items" + hasNextPage pagination envelope every other
      Applivery list endpoint in this app already uses, see
      _fetch_all_pages/extract_items), each shaped like
      {"id", "displayName", "deviceType", "state", "summary": {...},
      "tags", "reasons", "mdmUser", "segmentId"} — essentially a device
      record, not a slim {id, displayName, mdmUserId, state, summary} split
      across emmDevices/admDevices/winDevices/aosDevices sub-arrays the way
      Applivery's OpenAPI reference documents it. The documented shape may
      be accurate for some other account/version, but it is NOT what this
      tenant returns, and this function must match the real response, not
      the reference doc, to work.

    History, kept rather than scrubbed, because each pass narrowed the
    problem correctly even when the specific fix was wrong: pass 1 correctly
    predicted an id-space mismatch would matter here (right instinct, see
    below); pass 2 misdiagnosed the URL as nonexistent from an incomplete
    docs search and detoured to the wrong (unrelated, ad-hoc-selectors) POST
    endpoint; pass 3 reverted to the right URL per the OpenAPI reference but
    kept parsing the documented-but-wrong emmDevices/admDevices/winDevices/
    aosDevices split, which is why raw_member_count was always 0 regardless
    of URL correctness — the parsing code was looking for keys the real
    response never has, so it silently found nothing on every single call,
    every time, no matter how many other things got fixed around it. This
    pass parses `data.items` (via extract_items, the same helper every other
    Applivery list response in this app already goes through) and paginates
    properly via hasNextPage instead of trusting a single large `limit`.

    ID handling: each item's own `id` field is, per the live response, the
    same kind of full-device-record id this app already normalizes via
    _normalize_device_full — almost certainly the unified device id, not a
    platform-native one (unlike the documented-but-wrong split-array shape,
    which genuinely would have needed the reverse lookup below). The
    reverse-lookup resolution through raw_devices' admDevice/emmDevice/
    winDevice fields is kept anyway as a defensive fallback (unified id
    always maps to itself, so this is a no-op in the common case) — cheap
    insurance against a future account/response variant, not required for
    correctness against the shape confirmed here.
    """
    platform_id_to_unified_id: Dict[str, str] = {}
    for raw in (raw_devices or []):
        unified_id = str(raw.get('id') or raw.get('_id') or '')
        if not unified_id:
            continue
        platform_id_to_unified_id[unified_id] = unified_id
        for platform_field in ('admDevice', 'emmDevice', 'winDevice'):
            pid = raw.get(platform_field)
            if pid:
                platform_id_to_unified_id[str(pid)] = unified_id
    # NOTE: every failure branch below is logged (not just silently
    # returning an empty/partial map) — an empty audience_map is otherwise
    # indistinguishable downstream from "this audience genuinely has no
    # members," which would make a real Applivery API failure here look
    # exactly like a healthy compliance evaluation that found 0 devices to
    # check (see _run_compliance_evaluation's targetDeviceAudienceId
    # scoping). This bit an admin who created a Device Audience, scoped a
    # Compliance Policy to it, and got zero results with no visible error.
    audience_map: Dict[str, list] = {}
    try:
        res = await _applivery_call(client, 'GET', f"{org_base}/mdm/device-audiences", headers=headers, params={"limit": 500})
        if res.status_code != 200:
            print(f"[Device Audiences] Failed to list audiences: HTTP {res.status_code} — {res.text[:300]}")
            return audience_map
        audiences = extract_items(res.json())
    except Exception as e:
        print(f"[Device Audiences] Failed to list audiences: {e}")
        return audience_map

    for aud in audiences:
        aud_id = str(aud.get('id') or aud.get('_id') or '')
        aud_name = aud.get('name') or 'Unnamed audience'
        if not aud_id:
            continue
        try:
            # GET .../mdm/device-audiences/{deviceAudienceId}/preview — the
            # real per-audience members endpoint. Response is the standard
            # {data: {items, hasNextPage, ...}} pagination envelope (see the
            # docstring above for why this no longer parses the documented-
            # but-wrong emmDevices/admDevices/winDevices/aosDevices split),
            # so this walks every page the same way every other Applivery
            # list call in this app does, rather than trusting one large
            # `limit` to always return everything in a single response.
            preview_items = await _fetch_all_pages(client, headers, f"{org_base}/mdm/device-audiences/{aud_id}/preview")
        except HTTPException as e:
            print(f"[Device Audiences] Failed to preview membership for \"{aud_name}\" ({aud_id}): HTTP {e.status_code} — {e.detail}")
            continue
        except Exception as e:
            print(f"[Device Audiences] Failed to preview membership for \"{aud_name}\" ({aud_id}): {e}")
            continue
        member_ids = set()
        unresolved_count = 0
        raw_member_count = 0
        for dev in preview_items:
            raw_member_id = dev.get('id') or dev.get('_id')
            if not raw_member_id:
                continue
            raw_member_count += 1
            raw_member_id = str(raw_member_id)
            unified_id = platform_id_to_unified_id.get(raw_member_id)
            if unified_id:
                member_ids.add(unified_id)
            else:
                # Couldn't map this member's id back to a unified device id
                # via either id space (unified, or admDevice/emmDevice/
                # winDevice) — fall back to trusting it's already unified
                # rather than dropping the device from the audience
                # entirely, but count it so a persistent mismatch is
                # visible in logs instead of silently under-counting.
                member_ids.add(raw_member_id)
                unresolved_count += 1
        if raw_member_count and unresolved_count:
            print(f"[Device Audiences] \"{aud_name}\" ({aud_id}): {unresolved_count}/{raw_member_count} member id(s) didn't match any known device id (unified or platform-native) — membership for those may be wrong.")
        for dev_id in member_ids:
            audience_map.setdefault(dev_id, []).append({"id": aud_id, "name": aud_name})

    return audience_map

def _normalize_device_full(raw: dict, comp_ids: set, loc_cache: dict, audience_map: Optional[Dict[str, list]] = None, pushdata_cache: Optional[Dict[str, dict]] = None) -> dict:
    """
    Normalize a raw Applivery device record into the shape the Devices view
    (and eventually the compliance rule engine + action executor) consumes.
    """
    dev_id = str(raw.get('id', raw.get('_id', '')))
    raw_platform = str(raw.get('type') or raw.get('platform') or '')
    platform = normalize_platform(raw_platform)
    summary = raw.get('summary') or {}

    # Platform-native device ID — needed later to target MDM commands
    # (Android commands need emmDevice, iOS/macOS need admDevice, Windows needs winDevice).
    if platform in ('apple', 'macos'):
        platform_device_id = raw.get('admDevice') or dev_id
    elif platform == 'android':
        platform_device_id = raw.get('emmDevice') or dev_id
    elif platform == 'windows':
        platform_device_id = raw.get('winDevice') or dev_id
    else:
        platform_device_id = dev_id

    battery = summary.get('battery', raw.get('battery'))
    try:
        battery = int(battery) if battery is not None else None
    except (TypeError, ValueError):
        battery = None

    total_gb = _parse_capacity_gb(summary.get('totalStorage') or summary.get('totalCapacity') or raw.get('totalCapacity'))
    avail_gb = _parse_capacity_gb(summary.get('availableStorage') or summary.get('availableCapacity') or raw.get('availableCapacity'))
    ram_gb = _parse_capacity_gb(summary.get('totalMemory'))

    smart_attrs_raw = raw.get('smartAttributes') or raw.get('customAttributes') or summary.get('customAttributes')
    smart_attributes = []
    if isinstance(smart_attrs_raw, list):
        for attr in smart_attrs_raw:
            if isinstance(attr, dict):
                name = attr.get('name') or attr.get('key')
                value = attr.get('value') or attr.get('val')
                if name:
                    smart_attributes.append({"name": str(name), "value": '—' if value in (None, '') else str(value)})
    elif isinstance(smart_attrs_raw, dict):
        for k, v in smart_attrs_raw.items():
            smart_attributes.append({"name": str(k), "value": '—' if v in (None, '') else str(v)})

    # Which Smart Attribute *definitions* are currently attached to this device —
    # confirmed writable via the platform device PUT's smartAttributeAssignments
    # array (see _apply_compliance_smart_attribute). Distinct from `smartAttributes`
    # above, which holds the resolved name/value pairs for display.
    smart_attribute_assignment_ids = []
    for a in (raw.get('smartAttributeAssignments') or []):
        if isinstance(a, dict) and a.get('smartAttributeId'):
            smart_attribute_assignment_ids.append(str(a['smartAttributeId']))

    serial_number = summary.get('serialNumber') or raw.get('serialNumber') or ''
    # Data self-reported by the optional Windows/macOS push-webhook script,
    # matched by serial number — see the "DEVICE PUSH DATA" section further
    # down. None until the device has actually reported at least once.
    self_reported = (pushdata_cache or {}).get(serial_number) if serial_number else None

    # Android's emmDevice record already carries rich, live security state
    # natively from Google's Android Management API — confirmed via the
    # Applivery API docs (GET .../mdm/android/enterprise/devices/:emmDeviceId)
    # — so unlike Windows/macOS, Android needs no self-report script at all;
    # this is that platform's equivalent of `selfReported` above. Extracted
    # defensively (every field optional) since the exact shape returned by
    # the LIST endpoint this function's `raw` comes from hasn't been directly
    # observed against a live tenant — if a field is genuinely absent here,
    # this just yields None for it rather than raising a KeyError, and
    # _compute_device_risk skips fields it doesn't have.
    native_security = None
    if platform == 'android':
        device_settings = raw.get('deviceSettings') or {}
        security_posture = raw.get('securityPosture') or {}
        native_security = {
            "isDeviceSecure": device_settings.get('isDeviceSecure'),
            "encryptionStatus": device_settings.get('encryptionStatus'),
            "isEncrypted": device_settings.get('isEncrypted'),
            "adbEnabled": device_settings.get('adbEnabled'),
            "unknownSourcesEnabled": device_settings.get('unknownSourcesEnabled'),
            "developmentSettingsEnabled": device_settings.get('developmentSettingsEnabled'),
            "verifyAppsEnabled": device_settings.get('verifyAppsEnabled'),
            "policyCompliant": raw.get('policyCompliant'),
            "devicePosture": security_posture.get('devicePosture'),
            "postureDetails": security_posture.get('postureDetails') or [],
            "nonComplianceDetails": raw.get('nonComplianceDetails') or [],
        }
        # Only treat this as "we have native data" if at least one field
        # actually came back non-None — an all-None dict means the LIST
        # endpoint didn't include these fields for this tenant/call, so risk
        # scoring should fall back to its generic "no attestation" signal
        # rather than silently treating an empty shell as a clean device.
        if not any(v not in (None, [], {}) for v in native_security.values()):
            native_security = None

    return {
        "id": dev_id,
        # Falls back to summary.name (confirmed present there — e.g.
        # {"summary": {"name": "iPhone 14 Pro Max", ...}} — via a live
        # Device Audience preview response for a device whose /mdm/devices/
        # list record apparently omits both top-level displayName and name)
        # before giving up and showing "Unknown Device". Same "summary
        # first, then raw" pattern already used for imei/model/manufacturer/
        # osVersion just below.
        "displayName": raw.get('displayName') or raw.get('name') or summary.get('name') or 'Unknown Device',
        "platform": platform,
        "platformLabel": human_platform(platform),
        "rawPlatform": raw_platform,
        "platformDeviceId": platform_device_id,
        "serialNumber": serial_number,
        "imei": summary.get('imei') or raw.get('imei') or '',
        "model": summary.get('model') or raw.get('model') or raw.get('deviceModel') or '',
        "manufacturer": summary.get('manufacturer') or raw.get('manufacturer') or raw.get('brand') or '',
        "osVersion": summary.get('osVersion') or raw.get('osVersion') or '',
        "battery": battery,
        "state": str(raw.get('state') or raw.get('status') or 'unknown').lower(),
        "lastSeen": raw.get('lastStatusReportTime') or raw.get('lastSeen') or raw.get('updatedAt'),
        "enrolledAt": raw.get('enrolledDate') or raw.get('createdAt'),
        "isCompliant": dev_id in comp_ids,
        "tags": raw.get('tags') or [],
        "segmentId": raw.get('segmentId'),
        "deviceAudiences": (audience_map or {}).get(dev_id, []),
        "mdmUser": raw.get('mdmUser'),
        "location": loc_cache.get(dev_id),
        "selfReported": self_reported,
        "nativeSecurity": native_security,
        # Identifiers — shown in the detail view, not the list.
        "identifiers": {
            "udid": raw.get('udid') or summary.get('udid') or '',
            "emmDeviceId": raw.get('emmDeviceId') or '',
            "winId": raw.get('winId') or '',
        },
        "smartAttributes": smart_attributes,
        "smartAttributeAssignmentIds": smart_attribute_assignment_ids,
        "totalStorageGb": total_gb,
        "availableStorageGb": avail_gb,
        "ramGb": ram_gb,
        # Clean, de-duplicated view of currently-applied policies — used for display
        # and as the starting point for reassignment (PUT /api/devices/{id}/policies).
        "activePolicies": _extract_active_policies(raw),
        # Raw policy-assignment passthrough — the future rule engine reads these directly;
        # kept as-is (not reshaped) so we don't have to guess the schema twice.
        "policies": {
            "admPolicyAssignmentsEnforced": raw.get('admPolicyAssignmentsEnforced'),
            "emmPolicyAssignmentsEnforced": raw.get('emmPolicyAssignmentsEnforced'),
            "winPolicyAssignmentsEnforced": raw.get('winPolicyAssignmentsEnforced'),
        },
    }

def _compute_device_risk(device: dict, open_cases: Optional[List[dict]] = None, active_violations: Optional[List[dict]] = None) -> dict:
    """Additive, fully-explainable device risk score (0-100, higher = riskier)
    plus a human-readable factor breakdown — deliberately a transparent point
    system rather than a black-box model, so the Devices UI can show exactly
    why a device landed in a given tier. Rolls up four signal families
    already present on (or attached alongside) the normalized device dict:
    Applivery's own native compliance flag, self-reported security posture
    (see WINDOWS_ATTR_ALIASES/MACOS_ATTR_ALIASES / selfReported), this app's
    OWN Compliance Policy engine's currently-pending violations (a distinct
    signal from Applivery's native flag above — a device can be native-
    compliant while violating one of our own custom conditions, or vice
    versa), and open Cases against this device. `open_cases`/
    `active_violations` are passed in by the caller (get_devices_full),
    which loads Cases/Violations once per fleet-wide call rather than per
    device. Returns a dict meant to be `.update()`d onto the device:
    riskScore, riskTier, riskFactors. Called once per device from
    get_devices_full and read back via the riskScore/riskTier Compliance
    condition fields (see _evaluate_condition) — no other call site needed."""
    score = 0
    factors: List[Dict[str, Any]] = []

    if device.get('isCompliant') is False:
        score += 25
        factors.append({"label": "Out of compliance with an assigned Applivery policy", "points": 25})

    # Our own Compliance Policy engine's violations — named per policy so the
    # "why" is concrete, not a generic flag. Capped so one device stuck
    # cycling many stale policies can't alone blow the score to 100.
    for v in (active_violations or [])[:3]:
        points = 15
        score += points
        factors.append({"label": f'Violates policy: "{v.get("policyName") or "Unknown policy"}"', "points": points})

    self_reported = device.get('selfReported') or {}
    attrs = self_reported.get('attributes') or {}
    native_security = device.get('nativeSecurity')

    if self_reported and attrs:
        attr_penalties = [
            ("diskEncryptionEnabled", "Disk encryption disabled", 15),
            ("firewallEnabled", "Firewall disabled", 10),
            ("antivirusEnabled", "Antivirus disabled", 15),
            ("secureBootEnabled", "Secure Boot disabled", 10),
            ("tpmEnabled", "TPM not enabled", 5),
            ("vbsEnabled", "Virtualization-based security disabled", 5),
            ("credentialGuardEnabled", "Credential Guard disabled", 5),
        ]
        for attr_key, label, points in attr_penalties:
            if attrs.get(attr_key) is False:
                score += points
                factors.append({"label": label, "points": points})

        last_reported = self_reported.get('lastReportedAt')
        if last_reported:
            try:
                dt = datetime.fromisoformat(str(last_reported).replace('Z', '+00:00'))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                stale_days = (datetime.now(timezone.utc) - dt).total_seconds() / 86400.0
                if stale_days > 30:
                    score += 10
                    factors.append({"label": "Security attestation stale (30+ days)", "points": 10})
            except Exception:
                pass
    elif native_security:
        # Android: no self-report script needed — Applivery's emmDevice
        # record already carries live security state from Google's Android
        # Management API. See _normalize_device_full for field provenance.
        if native_security.get('isDeviceSecure') is False:
            score += 15
            factors.append({"label": "Android: device not secure (lock screen/encryption check failed)", "points": 15})
        encryption_status = str(native_security.get('encryptionStatus') or '').upper()
        if encryption_status and encryption_status not in ('ENCRYPTED', 'ENCRYPTED_PER_USER'):
            score += 15
            factors.append({"label": f"Android: encryption status is {encryption_status.replace('_', ' ').title()}", "points": 15})
        if native_security.get('adbEnabled') is True:
            score += 5
            factors.append({"label": "Android: USB debugging (ADB) enabled", "points": 5})
        if native_security.get('unknownSourcesEnabled') is True:
            score += 10
            factors.append({"label": "Android: install from unknown sources allowed", "points": 10})
        if native_security.get('policyCompliant') is False:
            score += 15
            factors.append({"label": "Android: not compliant with its Android Management policy", "points": 15})
        posture = native_security.get('devicePosture')
        if posture in ('AT_RISK', 'POTENTIALLY_COMPROMISED'):
            points = 25 if posture == 'POTENTIALLY_COMPROMISED' else 15
            score += points
            factors.append({"label": f"Android device posture: {posture.replace('_', ' ').title()}", "points": points})
        for detail in (native_security.get('nonComplianceDetails') or [])[:3]:
            points = 10
            score += points
            setting = detail.get('settingName') or detail.get('nonComplianceReason') or 'unknown setting'
            factors.append({"label": f"Android policy non-compliance: {setting}", "points": points})
    else:
        # No self-reported agent data AND no native security data at all —
        # can't verify posture, treated as a moderate signal rather than
        # either extreme.
        score += 10
        factors.append({"label": "No security attestation reported", "points": 10})

    open_case_count = len(open_cases or [])
    if open_case_count > 0:
        points = min(open_case_count * 10, 20)
        score += points
        factors.append({"label": f"{open_case_count} open case{'s' if open_case_count != 1 else ''}", "points": points})

    # OS/vuln/lifecycle/app-update intelligence — closes the loop between
    # the foundation-phase catalogs (OS Update Intelligence, Vulnerability
    # Catalog, OS Lifecycle, Apple App Updates) and risk scoring, same
    # fields the osUpdatePendingCount/vulnPendingCveCount/osEol/
    # appleAppUpdatesPending Compliance condition fields read (see
    # _evaluate_condition). All four are read directly off `device` since
    # get_devices_full always sets them before calling this function.
    os_update_status = device.get('osUpdateStatus')
    if os_update_status and (os_update_status.get('pendingCount') or 0) > 0:
        pending = os_update_status['pendingCount']
        points = min(pending * 5, 20)
        score += points
        factors.append({"label": f"{pending} pending Windows security update{'s' if pending != 1 else ''}", "points": points})
        if any(kb.get('exploited') for kb in (os_update_status.get('pendingKbs') or [])):
            score += 20
            factors.append({"label": "A pending Windows update fixes an exploited CVE", "points": 20})

    vuln_status = device.get('vulnStatus')
    if vuln_status and vuln_status.get('confidence') != 'unknown' and (vuln_status.get('pendingCount') or 0) > 0:
        pending = vuln_status['pendingCount']
        points = min(pending * 5, 20)
        score += points
        factors.append({"label": f"{pending} pending known CVE{'s' if pending != 1 else ''}", "points": points})
        if any(c.get('exploited') for c in (vuln_status.get('pendingCves') or [])):
            score += 25
            factors.append({"label": "A pending CVE is exploited in the wild", "points": 25})

    # Vulnerability Service (Applivery-hosted, opt-in) — independent, additive
    # signal alongside vuln_status/EUVD above, not a replacement: a device can
    # score points from both if both flag issues. Only scores when a workspace
    # has the integration enabled AND this device's platform/apps have actually
    # been checked (checked: False means "integration on, nothing cached yet
    # for this device" — deliberately not scored, same "don't guess past what's
    # confirmed" posture as the rest of this function).
    vuln_service_status = device.get('vulnServiceStatus')
    if vuln_service_status and vuln_service_status.get('checked'):
        counts = vuln_service_status.get('counts') or {}
        critical_high = (counts.get('CRITICAL') or 0) + (counts.get('HIGH') or 0)
        if critical_high > 0:
            points = min(critical_high * 5, 20)
            score += points
            factors.append({"label": f"{critical_high} critical/high CVE{'s' if critical_high != 1 else ''} (Vulnerability Service)", "points": points})
        if vuln_service_status.get('hasKev'):
            score += 25
            factors.append({"label": "A known-exploited CVE (CISA KEV) is present (Vulnerability Service)", "points": 25})
        elif (vuln_service_status.get('maxEpss') or 0) >= 0.5:
            score += 15
            factors.append({"label": "A CVE has a high exploitation-probability (EPSS) score (Vulnerability Service)", "points": 15})

    os_lifecycle_status = device.get('osLifecycleStatus')
    if os_lifecycle_status and os_lifecycle_status.get('isEol'):
        score += 20
        factors.append({"label": "OS version has reached end of life for security support", "points": 20})

    apple_app_update_status = device.get('appleAppUpdateStatus')
    if apple_app_update_status and (apple_app_update_status.get('pendingCount') or 0) > 0:
        pending = apple_app_update_status['pendingCount']
        points = min(pending * 2, 10)
        score += points
        factors.append({"label": f"{pending} app{'s' if pending != 1 else ''} with an update available", "points": points})

    score = min(score, 100)
    if score >= 75:
        tier = "critical"
    elif score >= 50:
        tier = "high"
    elif score >= 25:
        tier = "medium"
    else:
        tier = "low"

    return {"riskScore": score, "riskTier": tier, "riskFactors": factors}

@app.get("/api/devices", dependencies=[Depends(verify_dashboard_token)])
async def get_devices_full(
    refresh: bool = False,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """
    Full normalized device fleet for the Devices view — one org-level call for
    all devices, one for the compliant subset, no per-device requests.
    Cached for LIVE_CACHE_TTL_SECONDS (5 min); pass ?refresh=true to force a live pull.
    """
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")

    slug_key = x_workspace_slug or 'global'

    if not refresh:
        cached = _live_cache_get(slug_key, DEVICES_CACHE_SOURCE)
        if cached is not None:
            return cached

    timeout_config = httpx.Timeout(60.0, connect=15.0, read=60.0)
    async with httpx.AsyncClient(timeout=timeout_config) as client:
        headers = {"Authorization": authorization, "Content-Type": "application/json"}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)

        items_all = await _fetch_all_pages(client, headers, f"{org_base}/mdm/devices/")
        items_comp = await _fetch_all_pages(client, headers, f"{org_base}/mdm/devices/", base_params={"isCompliance": "true"})
        comp_ids = set(str(i.get('id', i.get('_id', ''))) for i in items_comp)
        audience_map = await _fetch_device_audience_membership_map(client, headers, org_base, raw_devices=items_all)

        try:
            loc_cache = _load_locations_cache()
        except Exception:
            loc_cache = {}

        pushdata_cache = _load_device_pushdata(slug_key)

        normalized = [_normalize_device_full(d, comp_ids, loc_cache, audience_map, pushdata_cache) for d in items_all]

        # Risk scoring, plus the same per-device Cases/Violations lookup
        # surfaced directly on the device (Devices view/detail drawer link
        # out to the Cases view and Audit Log respectively) — loaded once per
        # fleet-wide call (same batching philosophy as compliance evaluation
        # elsewhere in this file), not per device, to avoid N JSON-file reads
        # for a device list that can run into the thousands.
        open_cases_by_device: Dict[str, List[dict]] = {}
        try:
            for case in _load_cases(slug_key):
                if case.get('status') in CASE_OPEN_STATUSES and case.get('deviceId'):
                    open_cases_by_device.setdefault(case['deviceId'], []).append({
                        "id": case['id'], "title": case.get('title'), "severity": case.get('severity'), "status": case.get('status'),
                    })
        except Exception:
            pass
        active_violations_by_device: Dict[str, List[dict]] = {}
        try:
            for v in _load_compliance_violations(slug_key):
                # "pending" = still awaiting review (see the Compliance view's
                # own "Awaiting review" queue) — the meaningful "still an open
                # problem" state; approved/dismissed violations already had an
                # analyst decide what to do about them.
                if v.get('status') == 'pending' and v.get('deviceId'):
                    active_violations_by_device.setdefault(v['deviceId'], []).append({
                        "id": v['id'], "policyId": v.get('policyId'), "policyName": v.get('policyName'), "detectedAt": v.get('detectedAt'),
                    })
        except Exception:
            pass

        # Policy-based compliance — a temporary workaround column for the
        # Devices view. Applivery's own isCompliant flag only reflects
        # whatever Applivery itself can see (their own MDM policy checks);
        # it can't yet consume our Compliance Policies' conditions or any
        # 3rd-party telemetry, so it's an unreliable "are we actually okay"
        # signal on its own. _load_compliance_state is the live source of
        # truth for "still currently violating" — one entry per
        # policy+device pair, added the moment _run_compliance_evaluation
        # detects a violation and deleted the moment the device recovers
        # (regardless of what review status — pending/approved/auto_fired/
        # etc — the violation record itself carries). So unlike
        # active_violations_by_device above (deliberately narrowed to
        # 'pending' for the review queue), this is *every* still-open
        # violation, which is what "is this device compliant with our
        # policies right now" actually needs.
        policy_violations_by_device: Dict[str, List[dict]] = {}
        try:
            state = _load_compliance_state(slug_key)
            policies_by_id = {p['id']: p for p in _load_compliance_policies(slug_key)}
            for key, entry in state.items():
                policy_id, sep, device_id = key.partition(':')
                if not sep or not device_id:
                    continue
                policy = policies_by_id.get(policy_id)
                policy_violations_by_device.setdefault(device_id, []).append({
                    "policyId": policy_id,
                    "policyName": policy.get('name') if policy else None,
                    "status": entry.get('status'),
                    "lastDetectedAt": entry.get('lastDetectedAt'),
                })
        except Exception:
            pass

        # Windows OS update status — foundation-phase comparison against the
        # MSRC-sourced catalog (see "OS UPDATE INTELLIGENCE" section). Loaded
        # once per fleet-wide call, same batching philosophy as everything
        # else above. Non-Windows devices simply get None; not yet wired into
        # risk scoring or compliance (that's the explicitly separate,
        # later phase).
        os_update_catalog = _load_os_update_catalog()
        # Apple/Android vulnerability catalog (EUVD) — see "APPLE & ANDROID
        # VULNERABILITY INTELLIGENCE" section. Same one-load-per-fleet-call
        # batching as the Windows catalog above.
        vuln_catalog = _load_vuln_catalog()
        # OS lifecycle/EOL catalog (endoflife.date) — see "OS LIFECYCLE"
        # section. Same one-load-per-fleet-call batching as the other two.
        lifecycle_catalog = _load_os_lifecycle_catalog()
        gdmf_catalog = _load_gdmf_catalog()
        # Apple pending app updates (HasUpdateAvailable) — per-workspace store
        # populated by installed_apps_refresher_loop (see "INSTALLED APPS /
        # APP-LIST COMPLIANCE" section). Unlike the four catalogs above this
        # isn't global reference data, it's per-tenant per-device Applivery
        # data, but it's still one JSON read per fleet-wide call, same
        # batching philosophy.
        installed_apps_store = _load_installed_apps_store(slug_key)
        # Vulnerability Service (Applivery-hosted CVE matching) — see
        # "VULNERABILITY SERVICE" section. Local-cache-only per device
        # (never calls the Worker inline); only loaded when the integration
        # is actually enabled for this workspace so disabled/unconfigured
        # tenants get a cheap `None` rather than an empty "checked: false"
        # shell on every device.
        vuln_service_cfg = _load_vuln_service_config(slug_key)
        vuln_service_cache = _load_vuln_service_cache(slug_key) if vuln_service_cfg.get('enabled') else None

        for d in normalized:
            device_id = d.get('id')
            open_cases = open_cases_by_device.get(device_id, [])
            active_violations = active_violations_by_device.get(device_id, [])
            d['openCases'] = open_cases
            d['activeViolations'] = active_violations
            policy_violations = policy_violations_by_device.get(device_id, [])
            d['policyViolations'] = policy_violations
            d['policyCompliant'] = len(policy_violations) == 0
            d['osUpdateStatus'] = _compute_windows_pending_updates(d.get('osVersion'), os_update_catalog) if d.get('platform') == 'windows' else None
            if d.get('platform') in ('apple', 'macos'):
                d['vulnStatus'] = _compute_apple_pending_vulns(d.get('platform'), d.get('osVersion'), vuln_catalog)
            elif d.get('platform') == 'android':
                d['vulnStatus'] = _compute_android_pending_vulns(d.get('osVersion'), vuln_catalog)
            else:
                d['vulnStatus'] = None
            d['osLifecycleStatus'] = _compute_os_lifecycle_status(d.get('platform'), d.get('osVersion'), lifecycle_catalog, device_model=d.get('model'), gdmf_catalog=gdmf_catalog)
            # installed_apps_store now carries a versioned "apps" list for
            # every platform (see _fetch_and_store_installed_apps), not just
            # Apple — appleAppUpdateStatus stays Apple-only (it's sourced
            # from Applivery's own HasUpdateAvailable flag, which only Apple
            # exposes), but the raw app_entry itself is used for all
            # platforms below to feed the Vulnerability Service lookup.
            app_entry = installed_apps_store.get(str(device_id)) or {}
            d['appleAppUpdateStatus'] = app_entry.get('appleAppUpdates') if d.get('platform') in ('apple', 'macos') else None
            d['vulnServiceStatus'] = _compute_vuln_service_status(d, vuln_service_cache, app_entry) if vuln_service_cache is not None else None
            d.update(_compute_device_risk(d, open_cases=open_cases, active_violations=active_violations))

        response_data = {
            "items": normalized,
            "total": len(normalized),
            "fetchedAt": datetime.now(timezone.utc).isoformat(),
        }

        _live_cache_set(slug_key, DEVICES_CACHE_SOURCE, response_data, ttl_seconds=DEVICES_CACHE_TTL_SECONDS)
        return response_data

@app.get("/api/devices/{device_id}/compliance", dependencies=[Depends(verify_dashboard_token)])
async def get_device_compliance(
    device_id: str,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Single-device compliance/risk detail — powers the Compliance tab on
    the Playground device modal (DeviceInsightCard), whose underlying device
    data comes from the lighter mdm_devices widget source and never carries
    riskScore/riskFactors/policyViolations. Deliberately reuses
    get_devices_full's own cached-or-live fleet computation rather than
    duplicating the risk-scoring/violation-lookup logic in a second place —
    the Devices view's existing 5-minute live cache (DEVICES_CACHE_TTL_SECONDS)
    makes every call after the first one cheap, and guarantees this tab's
    numbers can never drift out of sync with the Devices view/detail
    drawer's own, which read from the exact same computation."""
    full = await get_devices_full(authorization=authorization, x_workspace_slug=x_workspace_slug)
    match = next((d for d in full.get('items', []) if str(d.get('id')) == str(device_id)), None)
    if not match:
        raise HTTPException(status_code=404, detail="Device not found in the current fleet snapshot")
    return {
        "id": match.get('id'),
        "isCompliant": match.get('isCompliant'),
        "policyCompliant": match.get('policyCompliant'),
        "riskScore": match.get('riskScore'),
        "riskTier": match.get('riskTier'),
        "riskFactors": match.get('riskFactors'),
        "policyViolations": match.get('policyViolations'),
        "activeViolations": match.get('activeViolations'),
        "openCases": match.get('openCases'),
    }

# ─── DEVICE EDIT ACTIONS (segment / tags / policies) ───
# Manual, single-device edits — ported from the Flutter reference's device
# profile sheet. Deliberately proxied through the backend (not called directly
# from the browser) even though it's one extra hop: these are the same three
# mutations the future rule/action engine will need to trigger automatically,
# so we want one server-side code path for them from the start rather than a
# browser-direct one now and a backend one later.

def _platform_path_segment(platform: str) -> Optional[str]:
    """Map our normalized platform to the Applivery URL segment used for
    platform-specific device endpoints."""
    if platform in ('apple', 'macos'):
        return 'apple'
    if platform == 'android':
        return 'android'
    if platform == 'windows':
        return 'windows'
    if platform == 'aosp':
        return 'aosp'
    return None

def _invalidate_devices_cache(slug_key: str):
    _live_cache.pop(f"{slug_key}:{DEVICES_CACHE_SOURCE}", None)

class SegmentUpdatePayload(BaseModel):
    platform: str
    segmentId: int

class TagsUpdatePayload(BaseModel):
    platform: str
    tags: List[str]

class PolicyRef(BaseModel):
    id: Optional[str] = None
    name: Optional[str] = None

class PoliciesUpdatePayload(BaseModel):
    platform: str
    policies: List[PolicyRef] = []  # ordered — first is primary, rest are priority-ordered fallbacks

@app.get("/api/policies", dependencies=[Depends(verify_dashboard_token)])
async def get_policies(
    platform: str,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """List assignable MDM policies for a platform, for the device detail view's policy picker."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    platform_path = _platform_path_segment(platform)
    if not platform_path:
        raise HTTPException(status_code=400, detail=f"Unsupported platform '{platform}' for policy listing")

    slug_key = x_workspace_slug or 'global'
    cache_source = f"policies_{platform_path}"
    cached = _live_cache_get(slug_key, cache_source)
    if cached is not None:
        return cached

    timeout_config = httpx.Timeout(30.0, connect=15.0, read=30.0)
    async with httpx.AsyncClient(timeout=timeout_config) as client:
        headers = {"Authorization": authorization, "Content-Type": "application/json"}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        res = await _applivery_call(client, 'GET', f"{org_base}/mdm/{platform_path}/enterprise/policies/", headers=headers, params={"limit": 500})
        if res.status_code != 200:
            raise HTTPException(status_code=502, detail=f"Applivery API returned {res.status_code}: {res.text[:300]}")
        items = extract_items(res.json())
        result = {"items": [{"id": str(p.get('id') or p.get('_id') or ''), "name": p.get('name') or 'Unnamed policy'} for p in items]}
        _live_cache_set(slug_key, cache_source, result)
        return result

