            {"name": "Block RDP inbound", "direction": "inbound", "action": "block", "protocol": "TCP", "localPorts": "3389", "remoteAddresses": "Any", "profile": "Any", "enabled": True},
            {"name": "Block WinRM inbound", "direction": "inbound", "action": "block", "protocol": "TCP", "localPorts": "5985-5986", "remoteAddresses": "Any", "profile": "Any", "enabled": True},
