@app.get("/api/firewall-ruleset-templates", dependencies=[Depends(require_permission(area="workflows", level="read"))])
async def get_firewall_ruleset_templates():
    return {"items": FIREWALL_RULESET_TEMPLATES}

@app.get("/api/firewall-rulesets", dependencies=[Depends(require_permission(area="workflows", level="read"))])
async def list_firewall_rulesets(x_workspace_slug: Optional[str] = Header(None)):
    return {"items": _load_firewall_library(x_workspace_slug or 'global')}

@app.post("/api/firewall-rulesets", dependencies=[Depends(require_permission(area="workflows", level="manage"))])
async def create_firewall_ruleset(
    payload: FirewallRuleSetPayload, x_workspace_slug: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token),
):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing credentials")
    slug_key = x_workspace_slug or 'global'
    now = datetime.now(timezone.utc).isoformat()
    rule_set = payload.dict()
    rule_set['id'] = str(uuid.uuid4())
    rule_set['rules'] = [{**r, 'id': r.get('id') or str(uuid.uuid4())} for r in rule_set['rules']]
    rule_set['createdAt'] = now
    rule_set['updatedAt'] = now

    headers = {"Authorization": authorization, "Content-Type": "application/json"}
    async with httpx.AsyncClient(timeout=30.0) as client:
        org_base = await _resolve_org_base(client, headers, x_workspace_slug or slug_key)
        apply_id, restore_id, error = await _provision_firewall_ruleset_library_entries(client, headers, org_base, slug_key, rule_set, None, None)
    if error:
        raise HTTPException(status_code=502, detail=error)
    rule_set['applyLibraryId'] = apply_id
    rule_set['restoreLibraryId'] = restore_id

    items = _load_firewall_library(slug_key)
    items.append(rule_set)
    _save_firewall_library(slug_key, items)
    _record_audit_event(slug_key, category="workflow", action="firewall_ruleset_created", actor=dash.get('sub'),
                         target_type="firewall_ruleset", target_id=rule_set['id'], target_name=rule_set.get('name'),
                         message=f'Firewall Rule Set "{rule_set.get("name")}" created ({len(rule_set["rules"])} rule(s), '
                                 f'{"no EDR — will ensure firewall enabled" if rule_set["ensureFirewallEnabled"] else "EDR present — firewall state left alone"})')
    return rule_set

@app.put("/api/firewall-rulesets/{ruleset_id}", dependencies=[Depends(require_permission(area="workflows", level="manage"))])
async def update_firewall_ruleset(
    ruleset_id: str, payload: FirewallRuleSetPayload, x_workspace_slug: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token),
):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing credentials")
    slug_key = x_workspace_slug or 'global'
    items = _load_firewall_library(slug_key)
    existing = next((r for r in items if r.get('id') == ruleset_id), None)
    if not existing:
        raise HTTPException(status_code=404, detail="Firewall Rule Set not found")

    updated = payload.dict()
    updated['id'] = ruleset_id
    updated['rules'] = [{**r, 'id': r.get('id') or str(uuid.uuid4())} for r in updated['rules']]
    updated['createdAt'] = existing.get('createdAt')
    updated['updatedAt'] = datetime.now(timezone.utc).isoformat()

    headers = {"Authorization": authorization, "Content-Type": "application/json"}
    async with httpx.AsyncClient(timeout=30.0) as client:
        org_base = await _resolve_org_base(client, headers, x_workspace_slug or slug_key)
        apply_id, restore_id, error = await _provision_firewall_ruleset_library_entries(
            client, headers, org_base, slug_key, updated, existing.get('applyLibraryId'), existing.get('restoreLibraryId'))
    if error:
        raise HTTPException(status_code=502, detail=error)
    updated['applyLibraryId'] = apply_id
    updated['restoreLibraryId'] = restore_id

    items = [updated if r.get('id') == ruleset_id else r for r in items]
    _save_firewall_library(slug_key, items)
    _record_audit_event(slug_key, category="workflow", action="firewall_ruleset_updated", actor=dash.get('sub'),
                         target_type="firewall_ruleset", target_id=ruleset_id, target_name=updated.get('name'),
                         message=f'Firewall Rule Set "{updated.get("name")}" updated ({len(updated["rules"])} rule(s)) — '
                                 f'on-device scripts regenerated, already-applied devices need the workflow action re-run to pick up the change')
    return updated

@app.delete("/api/firewall-rulesets/{ruleset_id}", dependencies=[Depends(require_permission(area="workflows", level="manage", action="canDeletePolicyOrWorkflow"))])
async def delete_firewall_ruleset(ruleset_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    items = _load_firewall_library(slug_key)
    match = next((r for r in items if r.get('id') == ruleset_id), None)
    if not match:
        raise HTTPException(status_code=404, detail="Firewall Rule Set not found")
    # Deliberately does NOT auto-restore any device currently carrying this
    # rule set's tagged rules — deleting the library entry only removes our
    # ability to apply/restore it via a new workflow action going forward.
    # A device with the rules already on it keeps them until an explicit
    # Restore action (or manual removal) runs; the library entry being gone
    # would otherwise silently strand whoever's still isolated.
    items = [r for r in items if r.get('id') != ruleset_id]
    _save_firewall_library(slug_key, items)
    _record_audit_event(slug_key, category="workflow", action="firewall_ruleset_deleted", actor=dash.get('sub'),
                         target_type="firewall_ruleset", target_id=ruleset_id, target_name=match.get('name'),
                         message=f'Firewall Rule Set "{match.get("name")}" deleted from the library. Devices it was already applied to keep those rules until explicitly restored.')
    return {"status": "deleted"}

@app.get("/api/devices/{device_id}/firewall-state", dependencies=[Depends(require_permission(area="devices", level="read"))])
async def get_device_firewall_state(device_id: str, x_workspace_slug: Optional[str] = Header(None)):
    slug_key = x_workspace_slug or 'global'
    state = _load_firewall_remediation_state(slug_key).get(str(device_id)) or {"active": []}
    return state

# Deployment model options offered in the workflow builder — Step 2, shown
# only for iOS/macOS/Android (Windows has one management model, so it's
# skipped entirely).
DEPLOYMENT_MODELS = {
    "apple": [
        {"value": "supervised", "label": "Supervised"},
        {"value": "unsupervised", "label": "Unsupervised"},
    ],
    "macos": [
        {"value": "supervised", "label": "Supervised"},
        {"value": "unsupervised", "label": "Unsupervised"},
    ],
    "android": [
        {"value": "work_profile", "label": "Work Profile (BYOD)"},
        {"value": "cope", "label": "Corporate-Owned, Personally Enabled (COPE)"},
        {"value": "device_owner", "label": "Device Owner (Fully Managed)"},
    ],
}

@app.get("/api/deployment-models", dependencies=[Depends(verify_dashboard_token)])
async def get_deployment_models():
    """Deployment model options per platform, for the workflow builder's Step 2."""
    return {"items": DEPLOYMENT_MODELS}

async def _execute_mdm_action(
    client: httpx.AsyncClient, headers: dict, org_base: str, platform: str, platform_device_id: str, action_key: str,
    deployment_model: Optional[str] = None, params: Optional[dict] = None, *,
    authorization: Optional[str] = None, x_workspace_slug: Optional[str] = None, device_id: Optional[str] = None,
    device_context: Optional[dict] = None, workflow_resume: Optional[dict] = None,
) -> tuple:
    """Dispatch one MDM command to a device. Returns (ok, detail).

    `workflow_resume` — only ever passed by the durable workflow engine's
    'run_script_wait' step handler. When set, it's stashed onto the
    script_run_tracking entry this dispatch creates (see below), so
    script_log_reconciler_loop can resume the parked workflow chain the
    moment it resolves this script's result instead of that only ever
    happening via the slower, timer-based fallback resumer.

    `deployment_model` is the WORKFLOW's own declared deployment model (set by
    the admin in the builder — see DEPLOYMENT_MODELS), not something read off
    the real device. The Step 2 picker already prevents adding an incompatible
    action to begin with; this is a defensive re-check in case the workflow's
    steps were edited after the fact (e.g. platform changed post-hoc).

    `params` is the admin-filled values for this action's `fields` (see
    MDM_ACTIONS), e.g. {"newPassword": "...", "message": "...", "path": "..."}.

    `authorization`/`x_workspace_slug`/`device_id` (Applivery's own internal
    device id, NOT `platform_device_id`) are only needed by 'runScript', which
    reads and rewrites the device's policy stack (see comment below).
    `device_context` is the same {device: {...}} dict the workflow engine
    already builds for http_request/notification templating — passed through
    here so 'customOmaUri' can template its `value` field the same way."""
    params = params or {}
    if action_key not in MDM_ACTIONS:
        return False, f"Unknown MDM action '{action_key}'"
    if not platform_device_id:
        return False, "Device is missing a platform device ID"

    platform_path = _platform_path_segment(platform)
    if not platform_path:
        return False, f"Unsupported platform '{platform}'"

    allowed = MDM_ACTIONS[action_key]["platforms"]
    if allowed is not None and platform_path not in allowed:
        return False, f"'{MDM_ACTIONS[action_key]['label']}' is not supported on {platform_path}"

    allowed_models = (MDM_ACTIONS[action_key].get("deploymentModels") or {}).get(platform)
    if allowed_models and deployment_model and deployment_model not in allowed_models:
        model_labels = '/'.join(allowed_models)
        return False, f"'{MDM_ACTIONS[action_key]['label']}' requires {model_labels} deployment mode (workflow targets {deployment_model})"

    if action_key in UNCONFIRMED_API_ACTIONS:
        return False, f"'{MDM_ACTIONS[action_key]['label']}' is not yet wired to a verified Applivery API call — run it from the Applivery Dashboard directly for now."

    for field in MDM_ACTIONS[action_key].get("fields") or []:
        if field.get("required") and not (params.get(field["key"]) or "").strip():
            return False, f"'{MDM_ACTIONS[action_key]['label']}' requires a value for '{field['label']}'"

    try:
        if action_key == 'runScript':
            # UNDOCUMENTED but confirmed working — see MDM_ACTIONS['runScript']
            # comment above for the full rationale. PUTting a `scripts` array
            # directly onto the device (same endpoint used elsewhere for
            # tags/policy assignments) runs the referenced script Asset
            # immediately, with no Policy involved. `type: "once"` + a fresh
            # `resetDate` on every push makes the SAME script id fire again
            # rather than being treated as an already-executed no-op.
            #
            # This endpoint's list fields (tags, winPolicyAssignments, etc.)
            # behave as full-array replace, and a device can already have
            # OTHER scripts assigned via a Policy's own scripts[] array — so
            # the device's CURRENT scripts array is read first and the new/
            # updated entry merged in by id, rather than blindly overwriting
            # whatever's already there.
            slug_key = x_workspace_slug or 'global'
            library_id = params.get('libraryId')
            if not library_id:
                return False, "No script selected from the Library"
            entry = next((e for e in _load_action_library(slug_key) if e.get('id') == library_id and e.get('type') == 'script'), None)
            if not entry:
                return False, "Script library entry not found — it may have been deleted"
            entry_platform_path = _platform_path_segment(entry.get('platform'))
            if entry_platform_path != platform_path:
                return False, f"'{entry.get('name')}' is a {entry.get('platform')} script — this device is {platform}"
            asset_id = entry.get('assetId')
            if not asset_id:
                return False, "Script library entry is missing its Applivery script Asset ID"

            # Confirmed via Applivery's own docs (docs.applivery.com/en/device-
            # management/windows/policies/scripts/): Applivery interpolates
            # {{device.x}}/{{user.x}} mustache variables in `arguments` ITSELF
            # at execution time (the GET response's `argumentsProcessed` field
            # is exactly this resolved value) — so, unlike `customOmaUri`'s
            # `value` (which we template locally since OMA-URI pushes don't go
            # through Applivery's own variable engine), `arguments` here is
            # passed through untouched. No local Jinja2 rendering.
            arguments = entry.get('arguments') or ''
            scope = entry.get('scope') or 'machine'
            reset_date = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S.') + f"{datetime.now(timezone.utc).microsecond // 1000:03d}Z"

            device_url = f"{org_base}/mdm/{platform_path}/enterprise/devices/{platform_device_id}"
            get_res = await _applivery_call(client, 'GET', device_url, headers=headers)
            current_scripts = []
            if get_res.status_code < 300:
                try:
                    for s in ((get_res.json().get('data') or {}).get('scripts')) or []:
                        if not isinstance(s, dict) or not s.get('id'):
                            continue
                        # Strip down to just the writable subset confirmed by
                        # testing — the GET response includes read-only
                        # metadata (name, description, runner,
                        # argumentsProcessed) alongside it that shouldn't be
                        # echoed back into the PUT.
                        sanitized = {"id": s['id'], "type": s.get('type') or 'once', "resetDate": s.get('resetDate'), "arguments": s.get('arguments') or '', "scope": s.get('scope') or 'machine'}
                        if s.get('type') == 'loop' and s.get('loopTime') is not None:
                            sanitized["loopTime"] = s['loopTime']
                        current_scripts.append(sanitized)
                except Exception:
                    current_scripts = []

            new_entry = {"id": asset_id, "type": "once", "resetDate": reset_date, "arguments": arguments, "scope": scope}
            merged = [s for s in current_scripts if s.get('id') != asset_id] + [new_entry]

            # Snapshot this script's current success/error counts BEFORE
            # dispatch — script_log_reconciler_loop compares against this
            # baseline to detect the NEW execution our PUT below causes,
            # since Applivery's script-logs/summary only exposes rolling
            # totals per (device, script), not a "give me just the latest
            # run" query. Best-effort: a failure here just means we skip
            # tracking this dispatch for Audit Log follow-up, never blocks
            # the actual script run.
            baseline_success, baseline_error = 0, 0
            try:
                baseline_entry = await _fetch_script_log_summary_entry(client, headers, org_base, platform_path, platform_device_id, asset_id)
                if baseline_entry:
                    baseline_success = (baseline_entry.get('status') or {}).get('success', 0)
                    baseline_error = (baseline_entry.get('status') or {}).get('error', 0)
            except Exception:
                pass

            res = await _applivery_call(client, 'PUT', device_url, headers=headers, json={"scripts": merged})
            if res.status_code >= 300:
                return False, f"API returned {res.status_code}: {res.text[:200]}"

            try:
                device_name = ((device_context or {}).get('device') or {}).get('displayName')
                tracking = _load_script_run_tracking(slug_key)
                tracking_entry = {
                    "deviceId": device_id, "deviceName": device_name,
                    "platformPath": platform_path, "platformDeviceId": platform_device_id,
                    "assetId": asset_id, "scriptName": entry.get('name') or asset_id,
                    "dispatchedAt": datetime.now(timezone.utc).isoformat(),
                    "baselineSuccess": baseline_success, "baselineError": baseline_error,
                    "attempts": 0,
                }
                if workflow_resume:
                    tracking_entry["workflowResume"] = workflow_resume
                tracking[str(uuid.uuid4())] = tracking_entry
                _save_script_run_tracking(slug_key, tracking)
            except Exception as e:
                print(f"[runScript] Failed to record dispatch for Audit Log follow-up: {e}")

            return True, f"Ran script '{entry.get('name') or asset_id}' directly on device (scope={scope})"

        if action_key in ('applyFirewallRuleSet', 'restoreFirewallRuleSet'):
            # Delegates straight to 'runScript' internals (same Applivery
            # scripts[] merge-PUT dance, same script_run_tracking/Audit Log
            # follow-up via script_log_reconciler_loop) — this branch only
            # resolves a Firewall Rule Set id to its auto-provisioned Apply/
            # Restore script and records which rule sets are active per
            # device. See "FIREWALL RULE SETS" section above for how those
            # scripts get generated and provisioned.
            slug_key = x_workspace_slug or 'global'
            rule_set_id = params.get('ruleSetId')
            if not rule_set_id:
                return False, "No Firewall Rule Set selected"
            rule_set = next((r for r in _load_firewall_library(slug_key) if r.get('id') == rule_set_id), None)
            if not rule_set:
                return False, "Firewall Rule Set not found — it may have been deleted"
            applying = action_key == 'applyFirewallRuleSet'
            resolved_library_id = rule_set.get('applyLibraryId') if applying else rule_set.get('restoreLibraryId')
            if not resolved_library_id:
                return False, f"'{rule_set.get('name')}' hasn't finished provisioning its on-device script — try saving it again in the Firewall Policy Library."
            ok, detail = await _execute_mdm_action(
                client, headers, org_base, platform, platform_device_id, 'runScript',
                deployment_model=deployment_model, params={"libraryId": resolved_library_id},
                authorization=authorization, x_workspace_slug=x_workspace_slug, device_id=device_id,
                device_context=device_context, workflow_resume=workflow_resume,
            )
            if not ok:
                return False, detail
            _record_firewall_remediation_dispatch(slug_key, device_id, rule_set, applying=applying)
            verb = "Applied" if applying else "Restored device from"
            return True, f"{verb} firewall rule set '{rule_set.get('name')}'"

        if action_key == 'deleteDevice' and platform_path == 'android' and deployment_model == 'cope':
            # "Relinquish ownership" — the COPE-specific flavor of unenroll.
            # Removes company management/the work profile only; the personal
            # side of the device is left untouched. NOT a data wipe (Android
            # has no confirmed full-wipe command via this API at all).
            url = f"{org_base}/mdm/android/enterprise/devices/{platform_device_id}/commands"
            res = await _applivery_call(client, 'POST', url, headers=headers, json={"type": "RELINQUISH_OWNERSHIP"})
        elif action_key == 'deleteDevice':
            # Confirmed for apple/macos/android/windows/aosp — the AOSP variant
            # (DELETE .../aosp/enterprise/devices/{aosDeviceId}) is documented
            # to create a DISENROLL command server-side, same shape as the rest.
            url = f"{org_base}/mdm/{platform_path}/enterprise/devices/{platform_device_id}"
            res = await _applivery_call(client, 'DELETE', url, headers=headers)
        elif action_key in ('installApp', 'uninstallApp'):
            # Confirmed via Applivery's OpenAPI schema — same shape across
            # apple/android/windows: POST .../{platform}/enterprise/devices/
            # {id}/action, body {"entity": "application", "action": ...,
            # "id": <appId>}. (This "action" endpoint is distinct from the
            # "commands" endpoint used for RequestType/type-style MDM
            # commands elsewhere in this function.)
            body = {
                "entity": "application",
                "action": "install" if action_key == 'installApp' else "uninstall",
                "id": params.get('appId') or '',
            }
            url = f"{org_base}/mdm/{platform_path}/enterprise/devices/{platform_device_id}/action"
            res = await _applivery_call(client, 'POST', url, headers=headers, json=body)
        elif platform_path == 'apple' and action_key in (
            'setBluetooth', 'setDataRoaming', 'setVoiceRoaming', 'setPersonalHotspot',
            'setTimeZone', 'setSoftwareUpdateCadence',
        ):
            # Confirmed via Apple's own public MDM protocol reference
            # (github.com/apple/device-management, mdm/commands/settings.yaml)
            # — these are all sub-items of the single 'Settings' command, a
            # different wire shape from every other Apple RequestType here:
            # {"RequestType": "Settings", "Settings": [{"Item": ..., ...}]}.
            cadence_map = {"Show all available": 0, "Prefer oldest available": 1, "Prefer latest available": 2}
            settings_item_map = {
                'setBluetooth': {"Item": "Bluetooth", "Enabled": params.get('enabled') == 'Enabled'},
                'setDataRoaming': {"Item": "DataRoaming", "Enabled": params.get('enabled') == 'Enabled'},
                'setVoiceRoaming': {"Item": "VoiceRoaming", "Enabled": params.get('enabled') == 'Enabled'},
                'setPersonalHotspot': {"Item": "PersonalHotspot", "Enabled": params.get('enabled') == 'Enabled'},
                'setTimeZone': {"Item": "TimeZone", "TimeZone": params.get('timeZone') or ''},
                'setSoftwareUpdateCadence': {"Item": "SoftwareUpdateSettings", "RecommendationCadence": cadence_map.get(params.get('cadence'), 0)},
            }
            body = {"RequestType": "Settings", "Settings": [settings_item_map[action_key]]}
            url = f"{org_base}/mdm/apple/enterprise/commands/device/{platform_device_id}"
            res = await _applivery_call(client, 'POST', url, headers=headers, json=body)
        elif platform_path == 'apple' and action_key == 'setRemoteDesktop':
            # Two distinct RequestTypes selected by the admin-chosen value,
            # rather than a static map entry — see MDM_ACTIONS comment.
            body = {"RequestType": "EnableRemoteDesktop" if params.get('enabled') == 'Enabled' else "DisableRemoteDesktop"}
            url = f"{org_base}/mdm/apple/enterprise/commands/device/{platform_device_id}"
            res = await _applivery_call(client, 'POST', url, headers=headers, json=body)
        elif platform_path == 'apple':
            request_type_map = {
                'wipeDevice': 'EraseDevice', 'lockDevice': 'DeviceLock', 'clearPasscode': 'ClearPasscode',
                'rebootDevice': 'RestartDevice', 'shutdownDevice': 'ShutDownDevice',
                'enableLostMode': 'EnableLostMode', 'disableLostMode': 'DisableLostMode',
                'playLostModeSound': 'PlayLostModeSound',
                'syncDevice': 'DeviceInformation',
                'scheduleOsUpdate': 'ScheduleOSUpdate',
                'removeProfile': 'RemoveProfile',
                'getActivationLockBypassCode': 'ActivationLockBypassCode',
                'rotateFileVaultKey': 'RotateFileVaultKey',
                'recoveryLock': 'SetRecoveryLock',
                'unlockUserAccount': 'UnlockUserAccount',
                'clearRestrictionsPassword': 'ClearRestrictionsPassword',
            }
            body = {"RequestType": request_type_map.get(action_key, action_key)}
            if action_key == 'wipeDevice' and platform == 'macos':
                body['PIN'] = '123456'
            if action_key == 'enableLostMode':
                # Apple's public EnableLostMode command takes these three
                # top-level keys directly (no nesting).
                if params.get('message'):
                    body['Message'] = params['message']
                if params.get('phoneNumber'):
                    body['PhoneNumber'] = params['phoneNumber']
                if params.get('footnote'):
                    body['Footnote'] = params['footnote']
            if action_key == 'scheduleOsUpdate':
                # productVersion supports the same {{ device.x }} templating
                # as customOmaUri's value field (see that branch's comment
                # below) — specifically so a policy-triggered workflow can
                # set it to {{ device.osLifecycleStatus.latestKnownVersion }}
                # and resolve each device's own target version at run time
                # from the OS Lifecycle catalog (GDMF-enriched for Apple),
                # instead of a version hardcoded into the workflow at build
                # time that goes stale the moment Apple ships a new release.
                # osLifecycleStatus is only populated when this workflow was
                # launched from a Compliance Policy's autoRun (see
                # WorkflowDeviceRef.osLifecycleStatus) — a manually-run
                # workflow using the template without that data would
                # otherwise silently render an empty string and send a blank
                # ProductVersion to Apple, so that case is caught explicitly
                # below rather than trusting the raw (pre-render) required-
                # field check above, which only sees the template text.
                target_version = params.get('productVersion') or ''
                if target_version and device_context is not None:
                    try:
                        from jinja2 import Template
                        target_version = Template(target_version).render(**device_context)
                    except Exception:
                        pass
                if not target_version.strip():
                    return False, "'Schedule OS update' resolved to an empty target version — the OS Lifecycle catalog has no confirmed latest version for this device yet, or this workflow wasn't triggered with that data available."
                body['Updates'] = [{
                    "ProductVersion": target_version,
                    "InstallAction": params.get('installAction') or 'Default',
                }]
            if action_key == 'removeProfile':
                body['Identifier'] = params.get('identifier') or ''
            if action_key == 'rotateFileVaultKey':
                body['KeyType'] = 'personal'
                body['FileVaultUnlock'] = {"Password": params['currentPassword']} if params.get('currentPassword') else {}
            if action_key == 'recoveryLock':
                # "" is a deliberate, valid value here (clears the Recovery
                # Lock password) — not treated as "missing" the way the
                # required-fields check above treats blanks, since this
                # field is marked optional.
                body['NewPassword'] = params.get('newPassword') or ''
                if params.get('currentPassword'):
                    body['CurrentPassword'] = params['currentPassword']
            if action_key == 'unlockUserAccount':
                body['UserName'] = params.get('userName') or ''
            url = f"{org_base}/mdm/apple/enterprise/commands/device/{platform_device_id}"
            res = await _applivery_call(client, 'POST', url, headers=headers, json=body)
        elif platform_path == 'android' and action_key in ('disableDevice', 'enableDevice'):
            # Confirmed via Applivery's PUT emmDevice schema — this is a
            # device *state* update, not an AMAPI command (the /commands
            # endpoint's `type` enum has no DISABLE/ENABLE). Same generic
            # device-update endpoint already used for tags/segment.
            url = f"{org_base}/mdm/android/enterprise/devices/{platform_device_id}"
            res = await _applivery_call(client, 'PUT', url, headers=headers, json={"state": "DISABLED" if action_key == 'disableDevice' else "ACTIVE"})
        elif platform_path == 'android':
            # Confirmed via Applivery's OpenAPI schema for this endpoint —
            # `type` enum is LOCK/RESET_PASSWORD/REBOOT/START_LOST_MODE/
            # STOP_LOST_MODE/RELINQUISH_OWNERSHIP/ADD_ESIM/REMOVE_ESIM/
            # CLEAR_APP_DATA. No WIPE — see wipeDevice's platform list above.
            android_type_map = {
                'lockDevice': 'LOCK', 'clearPasscode': 'RESET_PASSWORD',
                'rebootDevice': 'REBOOT', 'enableLostMode': 'START_LOST_MODE', 'disableLostMode': 'STOP_LOST_MODE',
                'clearAppData': 'CLEAR_APP_DATA',
            }
            body = {"type": android_type_map.get(action_key, action_key.upper())}
            if action_key == 'clearPasscode' and params.get('newPassword'):
                body['newPassword'] = params['newPassword']
            if action_key == 'enableLostMode':
                if params.get('message'):
                    body['startLostModeParams'] = {"lostMessage": {"defaultMessage": params['message']}}
                if params.get('phoneNumber'):
                    body.setdefault('startLostModeParams', {})['lostPhoneNumber'] = {"defaultMessage": params['phoneNumber']}
            if action_key == 'clearAppData' and params.get('packageNames'):
                package_names = [p.strip() for p in params['packageNames'].split(',') if p.strip()]
                body['clearAppsDataParams'] = {"packageNames": package_names}
            url = f"{org_base}/mdm/android/enterprise/devices/{platform_device_id}/commands"
            res = await _applivery_call(client, 'POST', url, headers=headers, json=body)
        elif platform_path == 'aosp':
            # Confirmed via Applivery's OpenAPI schema — distinct wire shape
            # from AMAPI above: key is "command", not "type", and the target
            # path segment/param name is aosDeviceId. Dispatched over Pushy
            # (not AMAPI) and executed by the Applivery DPC. The schema
            # allows an optional freeform "params" object; sub-field names
            # inside it aren't documented beyond CLEAR_APP_DATA's packageNames,
            # which mirrors the AMAPI shape closely enough to reuse here.
            aosp_type_map = {
                'lockDevice': 'LOCK', 'clearPasscode': 'RESET_PASSWORD',
                'rebootDevice': 'REBOOT', 'clearAppData': 'CLEAR_APP_DATA',
            }
            body = {"command": aosp_type_map.get(action_key, action_key.upper())}
            if action_key == 'clearPasscode' and params.get('newPassword'):
                body['params'] = {"newPassword": params['newPassword']}
            if action_key == 'clearAppData' and params.get('packageNames'):
                package_names = [p.strip() for p in params['packageNames'].split(',') if p.strip()]
                body['params'] = {"packageNames": package_names}
            url = f"{org_base}/mdm/aosp/enterprise/devices/{platform_device_id}/commands"
            res = await _applivery_call(client, 'POST', url, headers=headers, json=body)
        elif action_key in ('wipeDevice', 'rebootDevice'):
            # Confirmed via Applivery's OpenAPI schema for POST
            # .../windows/enterprise/devices/{id}/action — entity="command",
            # action="wipe"|"reboot", with an optional wipe `type`
            # ("protected" fully cleans the internal drive before reset,
            # "default" is a standard factory reset). This is a more
            # directly-confirmed path than the OMA-URI RemoteWipe/Reboot CSPs
            # used for other Windows actions below, so it's used here instead.
            body = {"entity": "command", "action": "wipe" if action_key == 'wipeDevice' else "reboot"}
            if action_key == 'wipeDevice':
                body['type'] = params.get('wipeType') or 'default'
            url = f"{org_base}/mdm/windows/enterprise/devices/{platform_device_id}/action"
            res = await _applivery_call(client, 'POST', url, headers=headers, json=body)
        elif action_key == 'setRemovableStorageWindows':
            # Bundles 4 Storage CSPs into one multi-command SyncML request —
            # see the MDM_ACTIONS comment for what each covers. ADMX-backed
            # chr policies take a literal "<enabled/>"/"<disabled/>" SyncML
            # fragment as their value (confirmed via Microsoft's "Understanding
            # ADMX policies" doc), not a plain 1/0.
            blocked = params.get('enabled') == 'Block all'
            configs = [
                {"path": "./Device/Vendor/MSFT/Policy/Config/Storage/RemovableDiskDenyWriteAccess", "action": "Replace", "format": "int", "value": "1" if blocked else "0"},
                {"path": "./Device/Vendor/MSFT/Policy/Config/Storage/WPDDevicesDenyWriteAccessPerDevice", "action": "Replace", "format": "chr", "value": "<enabled/>" if blocked else "<disabled/>"},
                {"path": "./Device/Vendor/MSFT/Policy/Config/Storage/WPDDevicesDenyReadAccessPerDevice", "action": "Replace", "format": "chr", "value": "<enabled/>" if blocked else "<disabled/>"},
                {"path": "./Device/Vendor/MSFT/Policy/Config/ADMX_RemovableStorage/CDandDVD_DenyWrite_Access_2", "action": "Replace", "format": "chr", "value": "<enabled/>" if blocked else "<disabled/>"},
            ]
            body = {"commands": [{"config": c} for c in configs]}
            url = f"{org_base}/mdm/windows/enterprise/devices/{platform_device_id}/commands"
            res = await _applivery_call(client, 'POST', url, headers=headers, json=body)
        else:  # windows — SyncML OMA-URI configuration (no confirmed 'action'-endpoint equivalent for these)
            if action_key == 'customOmaUri':
                # Confirmed shape — admin-supplied path/action/value/format,
                # same request body our other Windows actions send below with
                # hardcoded values. `value` is a direct, ad-hoc command (not
                # part of a stored Policy), so Applivery's own {{device.x}}
                # interpolation isn't confirmed to apply here — templated
                # locally instead, using the same {{ device.x }} naming, so it
                # resolves correctly regardless.
                path = params.get('path') or ''
                oma_action = params.get('action') or 'Replace'
                value = params.get('value') or ''
                if value and device_context is not None:
                    try:
                        from jinja2 import Template
                        value = Template(value).render(**device_context)
                    except Exception:
                        pass
                fmt = params.get('format') or 'chr'
            elif action_key in ('setBluetoothWindows', 'setWifiWindows', 'setCameraWindows'):
                allowed = params.get('enabled') == 'Allow'
                toggle_map = {
                    # (path, allowValue, blockValue) — AllowBluetooth is the
                    # oddball with 2=Allow instead of 1 (see MDM_ACTIONS comment).
                    'setBluetoothWindows': ('./Device/Vendor/MSFT/Policy/Config/Connectivity/AllowBluetooth', '2', '0'),
                    'setWifiWindows': ('./Device/Vendor/MSFT/Policy/Config/Wifi/AllowWiFi', '1', '0'),
                    'setCameraWindows': ('./Device/Vendor/MSFT/Policy/Config/Camera/AllowCamera', '1', '0'),
                }
                path, allow_value, block_value = toggle_map[action_key]
                oma_action = 'Replace'
                value = allow_value if allowed else block_value
                fmt = 'int'
            elif action_key == 'enableVbsWindows':
                # Policy CSP - DeviceGuard: EnableVirtualizationBasedSecurity, int.
                path = './Device/Vendor/MSFT/Policy/Config/DeviceGuard/EnableVirtualizationBasedSecurity'
                oma_action = 'Replace'
                value = '1' if params.get('enabled') == 'Enable' else '0'
                fmt = 'int'
            elif action_key == 'setCredentialGuardWindows':
                # Policy CSP - DeviceGuard: LsaCfgFlags, int. 0=disabled,
                # 1=enabled with UEFI lock, 2=enabled without lock.
                path = './Device/Vendor/MSFT/Policy/Config/DeviceGuard/LsaCfgFlags'
                oma_action = 'Replace'
                mode_map = {
                    'Disabled': '0',
                    'Enabled without lock (recommended for UEM)': '2',
                    'Enabled with UEFI lock': '1',
                }
                value = mode_map.get(params.get('mode'), '2')
                fmt = 'int'
            elif action_key == 'mdmUnenrollWindows':
                # DMClient CSP short form: ./Vendor/MSFT/DMClient/Unenroll,
                # Exec, Data = the UEM's ProviderID.
                path = './Vendor/MSFT/DMClient/Unenroll'
                oma_action = 'Exec'
                value = params.get('providerId') or ''
                fmt = 'chr'
            elif action_key == 'autopilotResetWindows':
                # RemoteWipe CSP — corrected nested path per Microsoft docs
                # (nested under AutomaticRedeployment, not directly under
                # RemoteWipe). Exec, no data payload needed.
                path = './Vendor/MSFT/RemoteWipe/AutomaticRedeployment/doAutomaticRedeployment'
                oma_action = 'Exec'
                value = ''
                fmt = 'chr'
            else:
                path_action_map = {
                    'lockDevice': ('./Vendor/MSFT/RemoteLock/DeviceLock', 'Exec'),
                    'syncDevice': ('./DevInfo/DevId', 'Get'),
                }
                path, oma_action = path_action_map.get(action_key, (action_key, 'Exec'))
                value, fmt = '', 'chr'
            body = {"commands": [{"config": {"path": path, "action": oma_action, "format": fmt, "value": value}}]}
            url = f"{org_base}/mdm/windows/enterprise/devices/{platform_device_id}/commands"
            res = await _applivery_call(client, 'POST', url, headers=headers, json=body)

        if res.status_code < 300:
            return True, f"{MDM_ACTIONS[action_key]['label']} accepted ({res.status_code})"
        return False, f"API returned {res.status_code}: {res.text[:200]}"
    except Exception as e:
        return False, str(e)

async def _execute_http_step(client: httpx.AsyncClient, config: dict, context: dict) -> tuple:
    """Generic 3rd-party API call step. url/headers/body are Jinja2-templated
    against {device: {...}} so a step can reference e.g. {{ device.displayName }}."""
    from jinja2 import Template
    try:
        method = (config.get('method') or 'POST').upper()
        url = Template(config.get('url') or '').render(**context)
        if not url:
            return False, "Missing URL"
        req_headers = {k: Template(str(v)).render(**context) for k, v in (config.get('headers') or {}).items()}
        body_str = Template(config.get('body') or '').render(**context)

        kwargs = {"headers": req_headers, "timeout": 30.0}
        if body_str.strip():
            try:
                kwargs["json"] = json.loads(body_str)
            except Exception:
                kwargs["content"] = body_str

        res = await client.request(method, url, **kwargs)
        if res.status_code < 300:
            return True, f"HTTP {res.status_code}"
        return False, f"HTTP {res.status_code}: {res.text[:200]}"
    except Exception as e:
        return False, str(e)

async def _execute_notification_step(client: httpx.AsyncClient, org_base: str, headers: dict, config: dict, context: dict, state: dict) -> tuple:
    """channel: 'webhook' (Google Chat, reuses state.webhookUrl), 'email' (reuses
    state.smtpConfig), or 'applivery_push' (native Applivery Agent push —
    requires the Applivery Agent app installed and registered on the device).

    `target` ('admin' | 'user' | 'admin_and_user') controls recipients for the
    email channel — 'user' resolves to the device's assigned MDM user email
    (context.device.mdmUser.email). Push notifications are inherently
    device-scoped, so target doesn't apply there. Webhook is always an admin
    channel (a Google Chat space, not a per-user endpoint)."""
    from jinja2 import Template
    channel = config.get('channel', 'webhook')
    device = context.get('device') or {}
    try:
        message = Template(config.get('message') or '').render(**context)
        if channel == 'webhook':
            webhook_url = config.get('webhookUrl') or state.get('webhookUrl')
            if not webhook_url:
                return False, "No webhook URL configured"
            payload = {"text": message}
            async with httpx.AsyncClient(timeout=15.0) as webhook_client:
                res = await webhook_client.post(webhook_url, json=payload)
            if res.status_code < 300:
                return True, "Webhook sent"
            return False, f"Webhook returned {res.status_code}"

        elif channel == 'email':
            smtp_config = state.get('smtpConfig')
            target = config.get('target', 'admin')
            mdm_user = device.get('mdmUser') if isinstance(device.get('mdmUser'), dict) else {}
            user_email = mdm_user.get('email')
            admin_recipients = Template(config.get('recipients') or '').render(**context)

            parts = []
            if target in ('admin', 'admin_and_user') and admin_recipients:
                parts.append(admin_recipients)
            if target in ('user', 'admin_and_user'):
                if user_email:
                    parts.append(user_email)
                elif target == 'user':
                    return False, "Device has no assigned MDM user email"
            recipients = ', '.join(p for p in parts if p)

            subject = Template(config.get('subject') or 'Applivery SOAR notification').render(**context)
            if not smtp_config or not smtp_config.get('host') or not recipients:
                return False, "SMTP not configured or missing recipients"

            def _send():
                msg = EmailMessage()
                msg['Subject'] = subject
                msg['From'] = smtp_config.get('from') or smtp_config.get('user')
                msg['To'] = recipients
                msg.set_content(message)
                with smtplib.SMTP(smtp_config['host'], int(smtp_config.get('port', 587))) as server:
                    server.starttls()
                    server.login(smtp_config['user'], smtp_config['pass'])
                    server.send_message(msg)
            await asyncio.to_thread(_send)
            return True, f"Email sent to {recipients}"

        elif channel == 'applivery_push':
            device_id = device.get('id')
            if not device_id:
                return False, "Device is missing an Applivery device ID"
            os_map = {'apple': 'ios', 'macos': 'macos', 'android': 'android', 'windows': 'windows'}
            os_value = os_map.get(device.get('platform'), str(device.get('rawPlatform') or '').lower())
            title = Template(config.get('title') or 'Compliance notification').render(**context)
            body_text = Template(config.get('message') or message).render(**context)
            payload = {
                "os": os_value,
                "identifier": device_id,
                "app": "mdmAgent",
                "type": "notification",
                "notification": {"title": title, "body": body_text, "data": {}},
            }
            res = await _applivery_call(client, 'POST', f"{org_base}/mdm/push-notifications/send", headers=headers, json=payload)
            if res.status_code < 300:
                return True, "Push notification sent"
            text = res.text[:200]
            if '3001' in text or 'fbtoken' in text.lower():
                return False, "Applivery Agent not installed/registered on this device"
            return False, f"Push failed ({res.status_code}): {text}"

        return False, f"Unknown notification channel '{channel}'"
    except Exception as e:
        return False, str(e)

# ── Workflow storage (data/workflows/{slug}.json) ──

def _workflows_file(slug: str) -> str:
    slug_clean = re.sub(r'[^a-zA-Z0-9_-]', '_', slug or 'global')
    return os.path.join(WORKFLOWS_DIR, f"{slug_clean}.json")

_register_legacy_json('workflows', lambda slug, key: _workflows_file(slug))

def _load_workflows(slug: str) -> List[Dict[str, Any]]:
    return _store_load(slug, 'workflows', list)

def _save_workflows(slug: str, workflows: List[Dict[str, Any]]):
    _store_save(slug, 'workflows', workflows)

def _workflow_runs_file(slug: str) -> str:
    slug_clean = re.sub(r'[^a-zA-Z0-9_-]', '_', slug or 'global')
    return os.path.join(WORKFLOWS_DIR, f"{slug_clean}_runs.json")

_register_legacy_json('workflow_runs', lambda slug, key: _workflow_runs_file(slug))

def _load_workflow_runs(slug: str) -> List[Dict[str, Any]]:
    return _store_load(slug, 'workflow_runs', list)

def _append_workflow_run(slug: str, run_record: dict, cap: int = 200):
    runs = _load_workflow_runs(slug)
    runs.insert(0, run_record)
    runs = runs[:cap]
    _store_save(slug, 'workflow_runs', runs)

# ── Workflow versioning (data/workflows/{slug}_versions.json) ──
# A version is a point-in-time snapshot of a workflow's editable definition
# (name/description/steps/targetPlatform/targetDeploymentModel/recovery),
# captured automatically right before update_workflow overwrites it — so the
# very first entry in the list is always "what it looked like right before
# the most recent edit," never the current state (the current state is just
# the live workflow object itself, no need to duplicate it here). Restoring
# a version snapshots the pre-restore state too, so restore is itself always
# undoable the same way. Kept in the same per-workspace-slug JSON-file-store
# pattern as everything else in this file (cases, triggers, integrations).

def _workflow_versions_file(slug: str) -> str:
    slug_clean = re.sub(r'[^a-zA-Z0-9_-]', '_', slug or 'global')
    return os.path.join(WORKFLOWS_DIR, f"{slug_clean}_versions.json")

_register_legacy_json('workflow_versions', lambda slug, key: _workflow_versions_file(slug))

def _load_workflow_versions(slug: str) -> List[Dict[str, Any]]:
    return _store_load(slug, 'workflow_versions', list)

def _save_workflow_versions(slug: str, versions: List[Dict[str, Any]]):
    _store_save(slug, 'workflow_versions', versions)

_WORKFLOW_VERSION_FIELDS = ('name', 'description', 'steps', 'targetPlatform', 'targetDeploymentModel', 'recovery')

def _snapshot_workflow_version(slug: str, workflow: dict, reason: str, actor: Optional[str], cap: int = 50) -> dict:
    """Appends a new version entry capturing `workflow`'s current editable
    definition, capped at `cap` most-recent versions per workflow (older ones
    are silently dropped — this is an undo/audit aid, not a permanent
    archive). Called from update_workflow (reason='update', snapshotting the
    pre-update state) and from the version-restore endpoint (reason='restore',
    snapshotting the pre-restore state)."""
    versions = _load_workflow_versions(slug)
    entry = {
        "id": str(uuid.uuid4()),
        "workflowId": workflow.get('id'),
        "reason": reason,
        "createdAt": datetime.now(timezone.utc).isoformat(),
        "createdBy": actor,
        "definition": {k: workflow.get(k) for k in _WORKFLOW_VERSION_FIELDS},
    }
    versions.insert(0, entry)
    same_workflow = [v for v in versions if v.get('workflowId') == workflow.get('id')]
    if len(same_workflow) > cap:
        drop_ids = {v['id'] for v in same_workflow[cap:]}
        versions = [v for v in versions if v['id'] not in drop_ids]
    _save_workflow_versions(slug, versions)
    return entry

# ── Pydantic models ──

class WorkflowStep(BaseModel):
    id: str
    # 'mdm_action' | 'http_request' | 'notification' | 'policy_replace' |
    # 'policy_add' | 'policy_restore' | 'monitor' | 'wait'
    # Only mdm_action is gated behind targetPlatform — everything else
    # (including the policy/monitor/wait steps) is platform-agnostic and
    # always available, same as http_request/notification.
    type: str
    name: str
    config: Dict[str, Any] = {}
    onSuccess: Optional[str] = None  # step id, 'end', or None => next step in the list
    onFailure: Optional[str] = None  # step id, 'end', or None => stop the chain

class WorkflowRecoveryConfig(BaseModel):
    """The workflow's single, common 'is this device still out of compliance?'
    gate. Checked before every escalation step (steps above) runs. The
    moment the linked Compliance Policy is no longer violated for a device,
    the escalation chain stops right there — no further escalation steps
    run — and instead: (1) any already-executed 'Run script' escalation
    step that had a paired restore script configured gets that restore
    script fired automatically, then (2) `steps` below run once, linearly
    (no branching — this is a single cleanup pass, not another escalation
    chain), to put the device back the way it was (e.g. Restore Policies,
    Install App to bring back something that was removed, Re-enable device).
    """
    enabled: bool = False
    compliancePolicyId: Optional[str] = None
    steps: List[WorkflowStep] = []

class WorkflowPayload(BaseModel):
    name: str
    description: Optional[str] = ""
    steps: List[WorkflowStep] = []
    targetPlatform: Optional[str] = None  # 'apple' (iOS) | 'macos' | 'android' | 'windows' | None
    targetDeploymentModel: Optional[str] = None  # see DEPLOYMENT_MODELS; None for windows or unset
    recovery: WorkflowRecoveryConfig = WorkflowRecoveryConfig()
    # Author-level default for whether THIS workflow is meant to be safe to
    # fire unattended even though it contains a destructive step (see
    # _workflow_has_destructive_step). Deliberately NOT an enforcement gate
    # on its own — every consumer (CompliancePolicyPayload.
    # autoRunDestructiveAck, CaseAutoRunRulePayload.autoRunDestructiveAck,
    # ApplieryWebhookRule.autoRunDestructiveAck) still independently requires
    # its own explicit acknowledgment before autoRun can actually fire this
    # workflow, exactly as before this field existed — a workflow marked
    # True here does not bypass that check anywhere. All this does is (a)
    # surface the author's intent in the Workflow Builder/list so it's
    # visible before anyone gets to a Policy/Rule editor, and (b) let the
    # frontend pre-fill a new Policy/Rule's own acknowledgment checkbox to
    # match — the human still has to see and (for a NEW consumer, implicitly
    # by saving; for an existing one, explicitly by re-checking it) commit
    # to that checkbox being checked. Defaults False, same safe default as
    # every existing per-consumer acknowledgment field.
    allowUnattendedDestructive: bool = False

class WorkflowDeviceRef(BaseModel):
    id: str
    displayName: Optional[str] = None
    platform: str
    platformDeviceId: str
    # Optional, richer fields the frontend already has in memory for every
    # device in the fleet table — passed straight through here (no extra
    # Applivery API call) so http_request/notification/customOmaUri steps can
    # template against more than just the 4 original fields, e.g.
    # {{ device.serialNumber }} or {{ device.mdmUser.email }}. Mirrors (and
    # deliberately goes a bit further than) Applivery's own native
    # {{device.x}}/{{user.x}} variables, which are a separate mechanism that
    # only applies to Policy/Script content Applivery itself deploys.
    serialNumber: Optional[str] = None
    osVersion: Optional[str] = None
    manufacturer: Optional[str] = None
    model: Optional[str] = None
    udid: Optional[str] = None
    mdmUser: Optional[Dict[str, Any]] = None
    # OS Lifecycle status (isEol/latestKnownVersion/latestKnownBuild, GDMF-
    # enriched for Apple — see _compute_os_lifecycle_status) — only ever
    # populated by the Compliance autoRun call site (device dicts there
    # already carry it from get_devices_full), so a manually-run workflow
    # from the Devices view won't have it unless the frontend starts sending
    # it too. Exists purely so 'scheduleOsUpdate' can template its
    # productVersion field against {{ device.osLifecycleStatus.
    # latestKnownVersion }} instead of a version hardcoded at workflow-build
    # time — see MDM_ACTIONS['scheduleOsUpdate'] and the template resolution
    # in _execute_mdm_action.
    osLifecycleStatus: Optional[Dict[str, Any]] = None

class WorkflowRunRequest(BaseModel):
    devices: List[WorkflowDeviceRef]
    # Purely descriptive — the frontend already resolves the device list
    # itself (it has the full fleet, including each device's deviceAudiences
    # and tags, loaded for the picker) when targeting "everyone in Device
    # Audience X" or "everyone tagged Y" rather than hand-picking devices.
    # This just carries a human-readable label through so the run record and
    # audit log show what the bulk target was, instead of an opaque device
    # count — e.g. "Device Audience: EU Finance Laptops" or "Tag: kiosk".
    targetDescription: Optional[str] = None

# ── CRUD ──

@app.get("/api/workflows", dependencies=[Depends(verify_dashboard_token)])
async def list_workflows(x_workspace_slug: Optional[str] = Header(None)):
    return {"items": _load_workflows(x_workspace_slug or 'global')}

@app.get("/api/mdm-actions", dependencies=[Depends(verify_dashboard_token)])
async def get_mdm_actions():
    """Static catalog for the workflow step builder — label/destructive/platform/fields support per action, plus whether it's actually wired to a verified Applivery API call yet."""
    return {"items": [{"key": k, "unconfirmed": k in UNCONFIRMED_API_ACTIONS, **v} for k, v in MDM_ACTIONS.items()]}

@app.post("/api/workflows", dependencies=[Depends(verify_dashboard_token)])
async def create_workflow(payload: WorkflowPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    workflows = _load_workflows(slug_key)
    now = datetime.now(timezone.utc).isoformat()
    new_workflow = payload.dict()
    new_workflow['id'] = str(uuid.uuid4())
    new_workflow['createdAt'] = now
    new_workflow['updatedAt'] = now
    workflows.append(new_workflow)
    _save_workflows(slug_key, workflows)
    _record_audit_event(slug_key, category="workflow", action="workflow_created", actor=dash.get('sub'),
                         target_type="workflow", target_id=new_workflow['id'], target_name=new_workflow.get('name'),
                         message=f'Workflow "{new_workflow.get("name")}" created')
    return new_workflow

@app.put("/api/workflows/{workflow_id}", dependencies=[Depends(verify_dashboard_token)])
async def update_workflow(workflow_id: str, payload: WorkflowPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    workflows = _load_workflows(slug_key)
    idx = next((i for i, p in enumerate(workflows) if p.get('id') == workflow_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Workflow not found")
    # Snapshot the pre-update definition before it's overwritten below —
    # see _snapshot_workflow_version.
    _snapshot_workflow_version(slug_key, workflows[idx], reason="update", actor=dash.get('sub'))
    updated = payload.dict()
    updated['id'] = workflow_id
    updated['createdAt'] = workflows[idx].get('createdAt') or datetime.now(timezone.utc).isoformat()
    updated['updatedAt'] = datetime.now(timezone.utc).isoformat()
    workflows[idx] = updated
    _save_workflows(slug_key, workflows)
    _record_audit_event(slug_key, category="workflow", action="workflow_updated", actor=dash.get('sub'),
                         target_type="workflow", target_id=workflow_id, target_name=updated.get('name'),
                         message=f'Workflow "{updated.get("name")}" updated')
    return updated

@app.get("/api/workflows/{workflow_id}/versions", dependencies=[Depends(verify_dashboard_token)])
async def list_workflow_versions(workflow_id: str, x_workspace_slug: Optional[str] = Header(None)):
    slug_key = x_workspace_slug or 'global'
    versions = [v for v in _load_workflow_versions(slug_key) if v.get('workflowId') == workflow_id]
    return {"items": versions}

@app.get("/api/workflows/{workflow_id}/versions/{version_id}", dependencies=[Depends(verify_dashboard_token)])
async def get_workflow_version(workflow_id: str, version_id: str, x_workspace_slug: Optional[str] = Header(None)):
    slug_key = x_workspace_slug or 'global'
    version = next((v for v in _load_workflow_versions(slug_key) if v.get('id') == version_id and v.get('workflowId') == workflow_id), None)
    if not version:
        raise HTTPException(status_code=404, detail="Version not found")
    return version

@app.post("/api/workflows/{workflow_id}/versions/{version_id}/restore", dependencies=[Depends(verify_dashboard_token)])
async def restore_workflow_version(workflow_id: str, version_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    workflows = _load_workflows(slug_key)
    idx = next((i for i, w in enumerate(workflows) if w.get('id') == workflow_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Workflow not found")
    version = next((v for v in _load_workflow_versions(slug_key) if v.get('id') == version_id and v.get('workflowId') == workflow_id), None)
    if not version:
        raise HTTPException(status_code=404, detail="Version not found")
    # Snapshot the current (pre-restore) state too, so restoring is itself
    # undoable via the same version list.
    _snapshot_workflow_version(slug_key, workflows[idx], reason="restore", actor=dash.get('sub'))
    restored = dict(workflows[idx])
    restored.update(version['definition'])
    restored['updatedAt'] = datetime.now(timezone.utc).isoformat()
    workflows[idx] = restored
    _save_workflows(slug_key, workflows)
    _record_audit_event(slug_key, category="workflow", action="workflow_version_restored", actor=dash.get('sub'),
                         target_type="workflow", target_id=workflow_id, target_name=restored.get('name'),
                         message=f'Workflow "{restored.get("name")}" restored to a previous version')
    return restored

def _dry_run_workflow(workflow: dict, device_dict: dict) -> dict:
    """Safe, read-only preview of a workflow's step chain for a single device.
    Never calls Applivery, never makes an outbound HTTP request, never
    touches the durable/Postgres run engine or any JSON-file store —
    deliberately a standalone function rather than a `dry_run` flag threaded
    through _run_device_step_chain, which is durable (persisted pending
    steps), recovery-aware (live device refetches mid-chain), and already
    complex enough that duplicating its branch-resolution logic here in a
    minimal, side-effect-free form is safer than risking a stray write path
    inside the real engine.

    Documented simplification: since no step is actually executed, dry-run
    has no real "did it succeed" signal, so it always walks the assumed
    SUCCESS branch of each step. Both the resolved onSuccess and onFailure
    targets are still surfaced per step (with the target step's name, where
    resolvable) so branching is visible to whoever is reviewing the preview,
    even though only the success path is walked."""
    from jinja2 import Template

    steps = workflow.get('steps') or []
    steps_by_id = {s['id']: s for s in steps}
    step_order = [s['id'] for s in steps]
    context = {"device": device_dict}

    def render(value):
        if not value:
            return value
        try:
            return Template(str(value)).render(**context)
        except Exception:
            return value

    def describe_step(step: dict) -> str:
        step_type = step.get('type')
        config = step.get('config') or {}
        if step_type == 'mdm_action':
            action_key = config.get('action')
            action_meta = MDM_ACTIONS.get(action_key, {})
            summary = action_meta.get('label') or action_key or 'Unknown action'
            params = config.get('params') or {}
            if params:
                summary += " — " + ", ".join(f"{k}: {render(v)}" for k, v in params.items() if v not in (None, ''))
            return summary
        if step_type == 'http_request':
            method = (config.get('method') or 'POST').upper()
            return f"{method} {render(config.get('url') or '')}"
        if step_type == 'notification':
            channel = config.get('channel', 'webhook')
            target = config.get('target')
            label = f"Send {channel} notification" + (f" to {target}" if target else "")
            message = render(config.get('message') or '')
            if message:
                trimmed = message if len(message) <= 120 else message[:120] + '…'
                label += f': "{trimmed}"'
            return label
        if step_type == 'policy_replace':
            names = config.get('policyNames') or [p.get('name') for p in (config.get('policies') or []) if isinstance(p, dict)]
            return f"Replace active policies with: {', '.join(names)}" if names else "Replace active policies"
        if step_type == 'policy_add':
            names = config.get('policyNames') or [p.get('name') for p in (config.get('policies') or []) if isinstance(p, dict)]
            return f"Add polic{'y' if len(names) == 1 else 'ies'}: {', '.join(names)}" if names else "Add a policy"
        if step_type == 'policy_restore':
            return "Restore this device's previously-quarantined policies"
        if step_type == 'monitor':
            attr = config.get('attribute') or config.get('smartAttributeName') or config.get('name')
            return f"Monitor for: {attr}" if attr else "Monitor device state"
        if step_type == 'wait':
            return f"Wait {config.get('amount')} {config.get('unit') or 'minutes'}"
        if step_type == 'run_script_wait':
            script_name = config.get('scriptName') or config.get('assetName')
            return f"Run script{': ' + script_name if script_name else ''} and wait for its result"
        return f"Unrecognized step type '{step_type}'"

    def target_label(step_id: Optional[str]) -> str:
        if not step_id or step_id == 'end':
            return 'End'
        target_step = steps_by_id.get(step_id)
        return target_step.get('name') or step_id if target_step else step_id

    preview = []
    visited = set()
    current_id = step_order[0] if step_order else 'end'
    guard = 0
    while current_id and current_id != 'end' and guard < 50:
        guard += 1
        step = steps_by_id.get(current_id)
        if not step or current_id in visited:
            break
        visited.add(current_id)
        idx = step_order.index(current_id)
        on_success = step.get('onSuccess')
        default_next = step_order[idx + 1] if idx + 1 < len(step_order) else 'end'
        resolved_success = on_success if on_success is not None else default_next
        on_failure = step.get('onFailure') or 'end'

        preview.append({
            "stepId": step.get('id'),
            "name": step.get('name'),
            "type": step.get('type'),
            "summary": describe_step(step),
            "onSuccessStepId": resolved_success,
            "onSuccessLabel": target_label(resolved_success),
            "onFailureStepId": on_failure,
            "onFailureLabel": target_label(on_failure),
        })
        # Dry-run always continues down the assumed-success branch.
        current_id = resolved_success

    recovery_cfg = workflow.get('recovery') or {}
    recovery_preview = None
    if recovery_cfg.get('enabled'):
        recovery_preview = [
            {"stepId": s.get('id'), "name": s.get('name'), "type": s.get('type'), "summary": describe_step(s)}
            for s in (recovery_cfg.get('steps') or [])
        ]

    return {
        "workflowId": workflow.get('id'),
        "workflowName": workflow.get('name'),
        "device": {"id": device_dict.get('id'), "displayName": device_dict.get('displayName')},
        "steps": preview,
        "recoverySteps": recovery_preview,
        "note": "Dry run — no real actions were executed. Each step assumes it succeeds; onFailure targets are shown for reference only.",
    }

class WorkflowDryRunRequest(BaseModel):
    device: Optional[WorkflowDeviceRef] = None

@app.post("/api/workflows/{workflow_id}/dry-run", dependencies=[Depends(verify_dashboard_token)])
async def dry_run_workflow(workflow_id: str, payload: WorkflowDryRunRequest, x_workspace_slug: Optional[str] = Header(None)):
    slug_key = x_workspace_slug or 'global'
    workflow = next((w for w in _load_workflows(slug_key) if w.get('id') == workflow_id), None)
    if not workflow:
        raise HTTPException(status_code=404, detail="Workflow not found")
    if payload.device:
        device_dict = payload.device.dict()
    else:
        # No real device supplied — preview against a clearly-labeled sample
        # device so a workflow can be reviewed before any device is picked.
        device_dict = {
            "id": "sample-device", "displayName": "Sample Device", "platform": workflow.get('targetPlatform') or 'apple',
            "platformDeviceId": "sample-platform-id", "serialNumber": "SAMPLESERIAL01", "osVersion": "18.0",
            "manufacturer": "Apple", "model": "iPhone 15", "udid": "SAMPLE-UDID-0000",
            "mdmUser": {"email": "jane.doe@example.com", "firstName": "Jane", "lastName": "Doe"},
        }
    return _dry_run_workflow(workflow, device_dict)

@app.delete("/api/workflows/{workflow_id}", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="workflows", level="manage", action="canDeletePolicyOrWorkflow"))])
async def delete_workflow(workflow_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    workflows = _load_workflows(slug_key)
    deleted = next((w for w in workflows if w.get('id') == workflow_id), None)
    remaining = [p for p in workflows if p.get('id') != workflow_id]
    _save_workflows(slug_key, remaining)
    if deleted:
        _record_audit_event(slug_key, category="workflow", action="workflow_deleted", actor=dash.get('sub'), severity="warning",
                             target_type="workflow", target_id=workflow_id, target_name=deleted.get('name'),
                             message=f'Workflow "{deleted.get("name")}" deleted')
    return {"status": "ok"}

async def _gather_workflow_runs(slug_key: str) -> List[dict]:
    """Shared assembly logic behind both the paginated list endpoint and the
    CSV export below — pulled out so export doesn't duplicate the
    Postgres/in-memory/history merge-and-dedupe."""
    pg_open = await _pg_list_open_runs(slug_key)
    pg_ids = {r['id'] for r in pg_open}

    in_progress = [
        _public_run_view(r) for r in _active_runs.values()
        if r.get('slugKey') == slug_key and r.get('status') in ('running', 'waiting') and r.get('id') not in pg_ids
    ]
    in_progress = sorted(in_progress, key=lambda r: r.get('startedAt', ''), reverse=True)

    open_ids = pg_ids | {r.get('id') for r in in_progress}
    history = _load_workflow_runs(slug_key)
    # De-dupe: a run that just completed may exist in both the open sets above and history
    return pg_open + in_progress + [r for r in history if r.get('id') not in open_ids]

@app.get("/api/workflows/runs", dependencies=[Depends(verify_dashboard_token)])
async def get_workflow_runs(
    x_workspace_slug: Optional[str] = Header(None),
    limit: int = 50,
    date_from: Optional[str] = None,
    date_to: Optional[str] = None,
):
    """History of completed runs, most recent first, plus any still running
    or waiting. Durable (wait-containing) runs are read from Postgres —
    the authoritative store for those, kept current by the resumer loop
    even across an API restart — and take precedence over any stale
    in-memory copy."""
    slug_key = x_workspace_slug or 'global'
    combined = await _gather_workflow_runs(slug_key)
    if date_from:
        combined = [r for r in combined if (r.get('startedAt') or '') >= date_from]
    if date_to:
        combined = [r for r in combined if (r.get('startedAt') or '') <= date_to]
    return {"items": combined[:limit], "total": len(combined)}

@app.get("/api/workflows/runs/export", dependencies=[Depends(verify_dashboard_token)])
async def export_workflow_runs(x_workspace_slug: Optional[str] = Header(None), date_from: Optional[str] = None, date_to: Optional[str] = None):
    slug_key = x_workspace_slug or 'global'
    combined = await _gather_workflow_runs(slug_key)
    if date_from:
        combined = [r for r in combined if (r.get('startedAt') or '') >= date_from]
    if date_to:
        combined = [r for r in combined if (r.get('startedAt') or '') <= date_to]
    combined = sorted(combined, key=lambda r: r.get('startedAt', ''))

    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(["Started At", "Finished At", "Workflow", "Status", "Devices Completed", "Devices Total"])
    for r in combined:
        writer.writerow([
            r.get('startedAt', ''), r.get('finishedAt') or '', r.get('workflowName', ''), r.get('status', ''),
            r.get('completed', 0), r.get('total', 0),
        ])
    buf.seek(0)
    filename = f"workflow-runs-{_audit_slug_clean(slug_key)}-{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')}.csv"
    return StreamingResponse(iter([buf.getvalue()]), media_type="text/csv", headers={"Content-Disposition": f"attachment; filename={filename}"})

@app.get("/api/workflows/runs/{run_id}", dependencies=[Depends(verify_dashboard_token)])
async def get_workflow_run(run_id: str, x_workspace_slug: Optional[str] = Header(None)):
    """Polled by the frontend while a run is in progress. Durable runs are
    read from Postgres first — the resumer loop may run in a different
    process (or a later one, after a restart) than whichever launched the
    run, so Postgres — not _active_runs — is the source of truth for those."""
    pg_view = await _pg_run_view(run_id)
    if pg_view is not None:
        return pg_view
    if run_id in _active_runs:
        return _public_run_view(_active_runs[run_id])
    for r in _load_workflow_runs(x_workspace_slug or 'global'):
        if r.get('id') == run_id:
            return _public_run_view(r)
    raise HTTPException(status_code=404, detail="Run not found")

# ── Execution engine ──
# Runs happen in the background (FastAPI BackgroundTasks) so the HTTP request
# returns immediately regardless of fleet size — with thousands of devices, a
# synchronous request would blow past any client/proxy timeout long before
# finishing. Progress lives in _active_runs (in-memory) while running; the
# frontend polls GET /api/workflows/runs/{id} until status flips to "completed".
# Only the finished record is written to disk, once, to avoid a full-history
# rewrite on every single device completion.

WORKFLOW_RUN_CONCURRENCY = 20  # bounded concurrency across target devices — protects the Applivery API
COMPLIANCE_WRITE_CONCURRENCY = 20  # bounded concurrency across *devices* for compliance marker writes (see _run_compliance_evaluation)
_active_runs: Dict[str, dict] = {}
_ACTIVE_RUNS_CAP = 30  # oldest completed runs are evicted from memory beyond this; history file is unaffected

def _public_run_view(run: dict) -> dict:
    """Strip internal bookkeeping (slugKey) before returning to the client."""
    return {k: v for k, v in run.items() if k != 'slugKey'}

def _evict_old_active_runs():
    if len(_active_runs) <= _ACTIVE_RUNS_CAP:
        return
    completed = sorted(
        [r for r in _active_runs.values() if r.get('status') != 'running'],
        key=lambda r: r.get('startedAt', '')
    )
    for r in completed[: len(_active_runs) - _ACTIVE_RUNS_CAP]:
        _active_runs.pop(r['id'], None)

async def _get_full_device(authorization: str, x_workspace_slug: str, device_id: str, refresh: bool = True) -> Optional[dict]:
    """Fetch one device's full normalized record (activePolicies, live
    compliance fields, etc.) — the policy quarantine/monitor steps need more
    than the bare WorkflowDeviceRef (id/displayName/platform/platformDeviceId)
    carried through the run loop. `refresh` bypasses the 5-min device cache;
    used for Monitor so an escalation decision is made on live data."""
    try:
        resp = await get_devices_full(refresh=refresh, authorization=authorization, x_workspace_slug=x_workspace_slug)
    except Exception:
        return None
    for d in resp.get('items', []):
        if d.get('id') == device_id:
            return d
    return None

def _snapshot_policies_if_needed(quarantine: dict, device_id: str, device_full: dict, workflow_id: str):
    """Capture the device's current policy stack the first time a quarantine
    step touches it. Deliberately a no-op if a snapshot already exists — a
    later escalation tier must not clobber the original pre-quarantine
    baseline with an already-quarantined state."""
    if device_id in quarantine:
        return
    quarantine[device_id] = {
        "deviceId": device_id,
        "platform": device_full.get('platform'),
        "policies": device_full.get('activePolicies') or [],
        "snapshotAt": datetime.now(timezone.utc).isoformat(),
        "workflowId": workflow_id,
    }

async def _execute_policy_replace_step(client, headers, org_base, authorization, x_workspace_slug, device: "WorkflowDeviceRef", config: dict, quarantine: dict, workflow_id: str) -> tuple:
    """Quarantine: replace ALL of a device's currently-applied policies with
    exactly one selected policy. Snapshots the pre-quarantine stack first
    (once) so policy_restore / a compliant Monitor step can put it back."""
    policy_id = (config or {}).get('policyId')
    if not policy_id:
        return False, "No replacement policy selected"

    device_full = await _get_full_device(authorization, x_workspace_slug, device.id)
    if not device_full:
        return False, "Could not read the device's current policy stack"

    _snapshot_policies_if_needed(quarantine, device.id, device_full, workflow_id)

    ok, detail = await _apply_device_policies(client, headers, org_base, device.platform, device.platformDeviceId, [{"id": policy_id}])
    if not ok:
        return False, detail
    prior_count = len(device_full.get('activePolicies') or [])
    policy_name = (config or {}).get('policyName') or policy_id
    noun = 'policy' if prior_count == 1 else 'policies'
    return True, f"Quarantined — replaced {prior_count} {noun} with '{policy_name}'"

async def _execute_policy_add_step(client, headers, org_base, authorization, x_workspace_slug, device: "WorkflowDeviceRef", config: dict, quarantine: dict, workflow_id: str) -> tuple:
    """Add one policy alongside whatever's already assigned, at admin-chosen
    priority ('top' = becomes primary, 'bottom' = lowest-priority fallback).
    Also snapshots first (once) — this mutates the live stack too, so it
    needs to be recoverable the same way policy_replace is."""
    policy_id = (config or {}).get('policyId')
    if not policy_id:
        return False, "No policy selected"
    priority = (config or {}).get('priority') or 'bottom'

    device_full = await _get_full_device(authorization, x_workspace_slug, device.id)
    if not device_full:
        return False, "Could not read the device's current policy stack"

    _snapshot_policies_if_needed(quarantine, device.id, device_full, workflow_id)

    current = device_full.get('activePolicies') or []
    current_ids = [{"id": p.get('id')} for p in current if p.get('id')]
    new_entry = {"id": policy_id}
    new_stack = [new_entry] + current_ids if priority == 'top' else current_ids + [new_entry]

    ok, detail = await _apply_device_policies(client, headers, org_base, device.platform, device.platformDeviceId, new_stack)
    if not ok:
        return False, detail
    policy_name = (config or {}).get('policyName') or policy_id
    noun = 'policy' if len(new_stack) == 1 else 'policies'
    return True, f"Added '{policy_name}' as {'primary' if priority == 'top' else 'lowest-priority fallback'} ({len(new_stack)} {noun} total)"

async def _execute_policy_restore_step(client, headers, org_base, device: "WorkflowDeviceRef", quarantine: dict) -> tuple:
    """Recover: put back exactly the policy stack that was in place before
    the first quarantine step touched this device, then clear the snapshot."""
    snapshot = quarantine.get(device.id)
    if not snapshot:
        return False, "No saved policy snapshot for this device — nothing to restore"

    policies = [{"id": p.get('id')} for p in (snapshot.get('policies') or []) if p.get('id')]
    ok, detail = await _apply_device_policies(client, headers, org_base, device.platform, device.platformDeviceId, policies)
    if not ok:
        return False, detail
    quarantine.pop(device.id, None)
    noun = 'policy' if len(policies) == 1 else 'policies'
    return True, f"Restored {len(policies)} previous {noun}"

async def _execute_monitor_step(authorization: str, x_workspace_slug: str, device: "WorkflowDeviceRef", config: dict, quarantine: dict, client, headers, org_base) -> tuple:
    """Re-check the linked Compliance Policy against fresh device data.
    ok=True (compliant again) takes the step's onSuccess branch — default
    'stop', unless the admin wired it elsewhere — and optionally restores the
    quarantined policy stack. ok=False (still violating) takes onFailure —
    default 'next step' — which is how a tiered advisory→executioner flow
    escalates: trigger, act, wait, monitor, and either stop (resolved) or
    move to the next tier's actions (still bad)."""
    policy_id = (config or {}).get('compliancePolicyId')
    if not policy_id:
        return False, "No compliance policy selected to monitor against"

    policies = _load_compliance_policies(x_workspace_slug or 'global')
    policy = next((p for p in policies if p.get('id') == policy_id), None)
    if not policy:
        return False, "Linked compliance policy no longer exists"

    device_full = await _get_full_device(authorization, x_workspace_slug, device.id, refresh=True)
    if not device_full:
        return False, "Could not re-fetch device state to evaluate compliance"

    slug_key = x_workspace_slug or 'global'
    await _maybe_prefetch_installed_apps(client, headers, org_base, device_full, policy, slug_key)
    matched = _policy_violated(device_full, policy, slug_key)
    if matched:
        policy_name = policy.get('name') or 'policy'
        return False, f"Still violating '{policy_name}' — {len(matched)} condition(s) matched"

    if (config or {}).get('restoreOnCompliant'):
        if device.id in quarantine:
            ok, detail = await _execute_policy_restore_step(client, headers, org_base, device, quarantine)
            if not ok:
                return True, f"Compliant again, but restore failed: {detail}"
            return True, f"Compliant again — {detail}"
        return True, "Compliant again — no quarantine snapshot to restore"

    return True, "Compliant again"

async def _run_recovery_steps(client, headers, org_base, authorization: str, x_workspace_slug: str, device: "WorkflowDeviceRef", workflow: dict, quarantine: dict, state: dict, executed_log: list) -> list:
    """Fires once the workflow's Recovery gate detects the device is no
    longer violating the linked Compliance Policy. Two phases:

    1. Auto-reversal: any escalation step already run for this device (in
       `executed_log`) that was a 'Run script' MDM action with a paired
       restore script configured gets that restore script fired now — the
       two scripts are configured together on the same step specifically so
       this can happen automatically, without the admin re-declaring it here.
    2. The workflow's explicit `recovery.steps`, run linearly in order (no
       onSuccess/onFailure branching — this is one cleanup pass, not another
       escalation chain) — e.g. Restore Policies, Install App to bring back
       something that was removed, Re-enable device, a notification.

    Returns a log list in the same shape as the main escalation log, each
    entry tagged `"phase": "recovery"` so the run result view can tell the
    two apart."""
    out = []
    context = {"device": device.dict()}
    steps_by_id = {s['id']: s for s in (workflow.get('steps') or [])}

    for entry in executed_log:
        step = steps_by_id.get(entry.get('stepId'))
        if not step or step.get('type') != 'mdm_action':
            continue
        cfg = step.get('config') or {}
        if cfg.get('action') != 'runScript':
            continue
        restore_library_id = (cfg.get('params') or {}).get('restoreLibraryId')
        if not restore_library_id:
            continue
        ok, detail = await _execute_mdm_action(
            client, headers, org_base, device.platform, device.platformDeviceId, 'runScript',
            workflow.get('targetDeploymentModel'),
            {"libraryId": restore_library_id},
            authorization=authorization, x_workspace_slug=x_workspace_slug, device_id=device.id,
            device_context={"device": device.dict()},
        )
        out.append({"stepId": step.get('id'), "name": f"Restore script for \"{step.get('name') or 'Run script'}\"", "type": "mdm_action", "ok": ok, "detail": detail, "phase": "recovery"})

    for step in (workflow.get('recovery') or {}).get('steps') or []:
        step_type = step.get('type')
        cfg = step.get('config') or {}
        if step_type == 'mdm_action':
            ok, detail = await _execute_mdm_action(
                client, headers, org_base, device.platform, device.platformDeviceId, cfg.get('action'), workflow.get('targetDeploymentModel'), cfg.get('params'),
                authorization=authorization, x_workspace_slug=x_workspace_slug, device_id=device.id, device_context=context,
            )
        elif step_type == 'http_request':
            ok, detail = await _execute_http_step(client, cfg, context)
        elif step_type == 'notification':
            ok, detail = await _execute_notification_step(client, org_base, headers, cfg, context, state)
        elif step_type == 'policy_replace':
            ok, detail = await _execute_policy_replace_step(client, headers, org_base, authorization, x_workspace_slug, device, cfg, quarantine, workflow.get('id'))
        elif step_type == 'policy_add':
            ok, detail = await _execute_policy_add_step(client, headers, org_base, authorization, x_workspace_slug, device, cfg, quarantine, workflow.get('id'))
        elif step_type == 'policy_restore':
            ok, detail = await _execute_policy_restore_step(client, headers, org_base, device, quarantine)
        else:
            ok, detail = False, f"Unsupported recovery step type '{step_type}'"
        out.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": ok, "detail": detail, "phase": "recovery"})

    return out

async def _execute_workflow_run_in_memory(run_id: str, workflow: dict, devices: List[WorkflowDeviceRef], authorization: str, x_workspace_slug: str):
    """The original, fully in-memory engine — unchanged. Used for workflows
    with no 'wait' step, which is the common case: zero Postgres dependency,
    zero persistence overhead, same behavior as always."""
    slug_key = x_workspace_slug or 'global'
    run = _active_runs[run_id]

    steps = workflow.get('steps') or []
    steps_by_id = {s['id']: s for s in steps}
    step_order = [s['id'] for s in steps]

    state = _load_state(x_workspace_slug)

    quarantine = _load_policy_quarantine(slug_key)

    # The workflow's Recovery gate — resolved once per run, not per device,
    # since the linked Compliance Policy's definition doesn't vary by device
    # (only whether a given device currently violates it does, which is
    # checked fresh before every step below).
    recovery_cfg = workflow.get('recovery') or {}
    recovery_policy = None
    if recovery_cfg.get('enabled') and recovery_cfg.get('compliancePolicyId'):
        _all_compliance_policies = _load_compliance_policies(slug_key)
        recovery_policy = next((p for p in _all_compliance_policies if p.get('id') == recovery_cfg.get('compliancePolicyId')), None)

    headers = {"Authorization": authorization, "Content-Type": "application/json"}
    timeout_config = httpx.Timeout(60.0, connect=15.0, read=60.0)
    sem = asyncio.Semaphore(WORKFLOW_RUN_CONCURRENCY)

    async def run_for_device(device: WorkflowDeviceRef) -> dict:
        device_dict = device.dict()
        if not steps:
            return {"deviceId": device.id, "deviceName": device.displayName, "steps": [], "finalStatus": "success"}

        async with sem:
            async with httpx.AsyncClient(timeout=timeout_config) as client:
                org_base = await _resolve_org_base(client, headers, x_workspace_slug)
                log = []
                current_id = step_order[0]
                guard = 0

                while current_id and current_id != 'end' and guard < 50:
                    guard += 1
                    step = steps_by_id.get(current_id)
                    if not step:
                        break

                    # Recovery gate — checked before every escalation step
                    # (including the very first), on fresh device data. The
                    # instant the device no longer violates the linked
                    # Compliance Policy, escalation stops here for good —
                    # the remaining steps in this chain never run — and
                    # Recovery takes over instead (paired restore scripts,
                    # then the explicit recovery.steps).
                    if recovery_policy is not None:
                        device_full = await _get_full_device(authorization, x_workspace_slug, device.id, refresh=True)
                        if device_full:
                            await _maybe_prefetch_installed_apps(client, headers, org_base, device_full, recovery_policy, slug_key)
                        if device_full and not _policy_violated(device_full, recovery_policy, slug_key):
                            recovery_log = await _run_recovery_steps(client, headers, org_base, authorization, x_workspace_slug, device, workflow, quarantine, state, log)
                            log.extend(recovery_log)
                            break

                    context = {"device": device_dict}
                    step_type = step.get('type')
                    if step_type == 'mdm_action':
                        ok, detail = await _execute_mdm_action(
                            client, headers, org_base, device.platform, device.platformDeviceId, (step.get('config') or {}).get('action'), workflow.get('targetDeploymentModel'), (step.get('config') or {}).get('params'),
                            authorization=authorization, x_workspace_slug=x_workspace_slug, device_id=device.id, device_context=context,
                        )
                    elif step_type == 'http_request':
                        ok, detail = await _execute_http_step(client, step.get('config') or {}, context)
                    elif step_type == 'notification':
                        ok, detail = await _execute_notification_step(client, org_base, headers, step.get('config') or {}, context, state)
                    elif step_type == 'policy_replace':
                        ok, detail = await _execute_policy_replace_step(client, headers, org_base, authorization, x_workspace_slug, device, step.get('config') or {}, quarantine, workflow.get('id'))
                    elif step_type == 'policy_add':
                        ok, detail = await _execute_policy_add_step(client, headers, org_base, authorization, x_workspace_slug, device, step.get('config') or {}, quarantine, workflow.get('id'))
                    elif step_type == 'policy_restore':
                        ok, detail = await _execute_policy_restore_step(client, headers, org_base, device, quarantine)
                    elif step_type == 'monitor':
                        ok, detail = await _execute_monitor_step(authorization, x_workspace_slug, device, step.get('config') or {}, quarantine, client, headers, org_base)
                    elif step_type in ('wait', 'run_script_wait'):
                        # Should never be reached: workflows containing a
                        # 'wait' or 'run_script_wait' step are routed to the
                        # durable engine by _execute_workflow_run before this
                        # function is ever called. Fail loudly rather than
                        # silently sleeping/skipping the wait in-process if
                        # that routing is ever bypassed.
                        ok, detail = False, "Wait steps require the durable engine and cannot run here"
                    else:
                        ok, detail = False, f"Unknown step type '{step_type}'"

                    log.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": ok, "detail": detail})

                    if ok:
                        nxt = step.get('onSuccess')
                        if nxt is None:
                            idx = step_order.index(current_id)
                            nxt = step_order[idx + 1] if idx + 1 < len(step_order) else 'end'
                    else:
                        nxt = step.get('onFailure') or 'end'
                    current_id = nxt

                if not log or all(s['ok'] for s in log):
                    final_status = "success"
                elif any(s['ok'] for s in log):
                    final_status = "partial"
                else:
                    final_status = "failed"

                return {"deviceId": device.id, "deviceName": device.displayName, "steps": log, "finalStatus": final_status}

    async def run_and_record(device: WorkflowDeviceRef):
        result = await run_for_device(device)
        # Mutate the shared run dict in place — cheap, and every poll sees the latest state immediately.
        run["results"].append(result)
        run["completed"] += 1

    await asyncio.gather(*[run_and_record(d) for d in devices])

    run["status"] = "completed"
    run["finishedAt"] = datetime.now(timezone.utc).isoformat()

    _save_policy_quarantine(slug_key, quarantine)
    _append_workflow_run(slug_key, _public_run_view(run))
    _invalidate_devices_cache(slug_key)  # a step may have changed tags/segment/state
    _evict_old_active_runs()

# ─── DURABLE WORKFLOW ENGINE (Postgres-backed 'wait' support) ───
#
# Only used for workflows that contain at least one 'wait' step. Everything
# else keeps using _execute_workflow_run_in_memory above, completely
# unchanged. A 'wait' step here persists exactly enough to resume — the
# device snapshot, which step comes next, and the log so far — then returns
# immediately, freeing the WORKFLOW_RUN_CONCURRENCY slot and HTTP client
# instead of holding them for the wait duration. workflow_wait_resumer_loop
# (below) picks resumable rows back up on its own schedule, so a run
# survives an API restart mid-wait.

async def _pg_upsert_run_result(run_id: str, device_id: str, device_name: Optional[str], steps_log: list, status: str, final_status: Optional[str]):
    pool = await _get_pg_pool()
    if pool is None:
        return
    async with pool.acquire() as conn:
        await conn.execute(
            """INSERT INTO workflow_run_results (run_id, device_id, device_name, steps, status, final_status, updated_at)
               VALUES ($1, $2, $3, $4::jsonb, $5, $6, now())
               ON CONFLICT (run_id, device_id) DO UPDATE
               SET device_name = EXCLUDED.device_name, steps = EXCLUDED.steps,
                   status = EXCLUDED.status, final_status = EXCLUDED.final_status, updated_at = now()""",
            uuid.UUID(run_id), device_id, device_name, json.dumps(steps_log), status, final_status,
        )

async def _pg_finalize_run_if_done(run_id: str):
    """Marks a workflow_runs row 'completed' once every device's result is
    'done' (success/partial/failed) — i.e. no device is still 'waiting'."""
    pool = await _get_pg_pool()
    if pool is None:
        return
    async with pool.acquire() as conn:
        row = await conn.fetchrow(
            """SELECT wr.total AS total, count(*) FILTER (WHERE wrr.status = 'done') AS done_count
               FROM workflow_runs wr
               LEFT JOIN workflow_run_results wrr ON wrr.run_id = wr.id
               WHERE wr.id = $1
               GROUP BY wr.total""",
            uuid.UUID(run_id),
        )
        if row and row["done_count"] >= row["total"]:
            await conn.execute(
                "UPDATE workflow_runs SET status = 'completed', finished_at = now() WHERE id = $1 AND status != 'completed'",
                uuid.UUID(run_id),
            )

async def _persist_pending_step(run_id: str, device_snapshot: dict, workflow_id: str, slug_key: str, next_step_id: str, log: list, resume_at: datetime, step_kind: str = 'timer', on_failure_step_id: Optional[str] = None, pending_token: Optional[str] = None):
    """step_kind 'timer' is the original 'wait' step (resume_at is exactly
    when it should fire, always down next_step_id). step_kind 'script' is a
    'run_script_wait' step: resume_at here is a TIMEOUT deadline, not an
    expected resume time — the fast path is script_log_reconciler_loop
    resolving `pending_token` early and deleting this row itself; resume_at
    is only the fallback if that never happens (device offline, script
    Asset removed, etc.), at which point workflow_wait_resumer_loop treats
    it as a timeout and follows on_failure_step_id instead of next_step_id."""
    pool = await _get_pg_pool()
    if pool is None:
        return None
    async with pool.acquire() as conn:
        row = await conn.fetchrow(
            """INSERT INTO workflow_pending_steps (run_id, device_snapshot, workflow_id, slug_key, next_step_id, log, resume_at, step_kind, on_failure_step_id, pending_token)
               VALUES ($1, $2::jsonb, $3, $4, $5, $6::jsonb, $7, $8, $9, $10)
               RETURNING id""",
            uuid.UUID(run_id), json.dumps(device_snapshot), workflow_id, slug_key, next_step_id, json.dumps(log), resume_at, step_kind, on_failure_step_id, pending_token,
        )
    return row["id"] if row else None

async def _pg_run_view(run_id: str) -> Optional[dict]:
    """Reconstructs a run's public view straight from Postgres — the
    authoritative store for durable runs. Needed because the resumer loop
    updates workflow_run_results directly without touching the in-memory
    _active_runs dict (which may not even exist anymore if the API
    restarted since the run was launched, or may be stale if a device was
    resumed by a later poller/process than the one that launched it)."""
    pool = await _get_pg_pool()
    if pool is None:
        return None
    try:
        run_uuid = uuid.UUID(run_id)
    except ValueError:
        return None
    async with pool.acquire() as conn:
        run_row = await conn.fetchrow("SELECT * FROM workflow_runs WHERE id = $1", run_uuid)
        if run_row is None:
            return None
        result_rows = await conn.fetch(
            "SELECT device_id, device_name, steps, status, final_status FROM workflow_run_results WHERE run_id = $1",
            run_uuid,
        )
    results = []
    completed = 0
    any_waiting = False
    for r in result_rows:
        steps = json.loads(r["steps"]) if r["steps"] else []
        results.append({"deviceId": r["device_id"], "deviceName": r["device_name"], "steps": steps, "finalStatus": r["final_status"], "status": r["status"]})
        if r["status"] == "done":
            completed += 1
        elif r["status"] == "waiting":
            any_waiting = True

    if run_row["status"] == "completed":
        status = "completed"
    elif any_waiting:
        status = "waiting"
    elif run_row["total"] and completed >= run_row["total"]:
        status = "completed"  # every device done but the finalize UPDATE hasn't landed yet
    else:
        status = "running"

    return {
        "id": str(run_row["id"]),
        "workflowId": run_row["workflow_id"],
        "workflowName": run_row["workflow_name"],
        "startedAt": run_row["started_at"].isoformat() if run_row["started_at"] else None,
        "finishedAt": run_row["finished_at"].isoformat() if run_row["finished_at"] else None,
        "status": status,
        "total": run_row["total"],
        "completed": completed,
        "results": results,
    }

async def _pg_list_open_runs(slug_key: str) -> List[dict]:
    """All not-yet-completed durable runs for a workspace, read from
    Postgres so this list survives an API restart."""
    pool = await _get_pg_pool()
    if pool is None:
        return []
    async with pool.acquire() as conn:
        rows = await conn.fetch(
            "SELECT id FROM workflow_runs WHERE slug_key = $1 AND status != 'completed' ORDER BY started_at DESC",
            slug_key,
        )
    views = []
    for row in rows:
        view = await _pg_run_view(str(row["id"]))
        if view is not None:
            views.append(view)
    return views

async def _run_device_step_chain(
    run_id: str,
    workflow: dict,
    device,
    authorization: str,
    x_workspace_slug: str,
    start_step_id: Optional[str] = None,
    existing_log: Optional[list] = None,
) -> dict:
    """Walk one device's step chain from start_step_id (default: the
    workflow's first step). Used both for a fresh durable run and to resume
    a device after its persisted 'wait' comes due — the two call sites
    differ only in start_step_id/existing_log. Reloads state/quarantine
    fresh on every call rather than carrying it across the persistence
    boundary, since these are shared JSON-file state that other requests
    may have changed in the meantime."""
    slug_key = x_workspace_slug or 'global'

    if isinstance(device, dict):
        device_dict = dict(device)
    else:
        device_dict = device.dict()
    device_id = device_dict.get('id')
    device_name = device_dict.get('displayName')

    steps = workflow.get('steps') or []
    steps_by_id = {s['id']: s for s in steps}
    step_order = [s['id'] for s in steps]

    if not steps:
        await _pg_upsert_run_result(run_id, device_id, device_name, [], "done", "success")
        await _pg_finalize_run_if_done(run_id)
        return {"deviceId": device_id, "deviceName": device_name, "steps": [], "finalStatus": "success", "status": "done"}

    state = _load_state(x_workspace_slug)

    quarantine = _load_policy_quarantine(slug_key)

    recovery_cfg = workflow.get('recovery') or {}
    recovery_policy = None
    if recovery_cfg.get('enabled') and recovery_cfg.get('compliancePolicyId'):
        _all_compliance_policies = _load_compliance_policies(slug_key)
        recovery_policy = next((p for p in _all_compliance_policies if p.get('id') == recovery_cfg.get('compliancePolicyId')), None)

    # A resumed chain (start_step_id set) may run long after the launching
    # human's session token expired, so it switches to the automation
    # credential. A fresh/live chain still uses the launching request's own
    # token, same as the in-memory engine always has.
    creds_authorization = authorization
    if start_step_id is not None:
        automation_bearer = await _get_automation_bearer(slug_key)
        if automation_bearer:
            creds_authorization = automation_bearer

    headers = {"Authorization": creds_authorization, "Content-Type": "application/json"}
    timeout_config = httpx.Timeout(60.0, connect=15.0, read=60.0)

    log = list(existing_log or [])
    current_id = start_step_id or step_order[0]
    guard = len(log)

    async with httpx.AsyncClient(timeout=timeout_config) as client:
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)

        while current_id and current_id != 'end' and guard < 50:
            guard += 1
            step = steps_by_id.get(current_id)
            if not step:
                break

            device_ref = WorkflowDeviceRef(**device_dict)

            if recovery_policy is not None:
                device_full = await _get_full_device(creds_authorization, x_workspace_slug, device_id, refresh=True)
                if device_full:
                    await _maybe_prefetch_installed_apps(client, headers, org_base, device_full, recovery_policy, slug_key)
                if device_full and not _policy_violated(device_full, recovery_policy, slug_key):
                    recovery_log = await _run_recovery_steps(client, headers, org_base, creds_authorization, x_workspace_slug, device_ref, workflow, quarantine, state, log)
                    log.extend(recovery_log)
                    current_id = 'end'
                    break

            context = {"device": device_dict}
            step_type = step.get('type')

            if step_type == 'wait':
                cfg = step.get('config') or {}
                amount = cfg.get('amount')
                unit = cfg.get('unit') or 'minutes'
                try:
                    amount = float(amount)
                except (TypeError, ValueError):
                    amount = None
                if amount is None or amount <= 0:
                    log.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": False, "detail": "Invalid wait duration"})
                    current_id = step.get('onFailure') or 'end'
                    continue

                seconds_per_unit = {'minutes': 60, 'hours': 3600, 'days': 86400}
                seconds = amount * seconds_per_unit.get(unit, 60)
                resume_at = datetime.now(timezone.utc) + timedelta(seconds=seconds)
                idx = step_order.index(current_id)
                next_step_id = step.get('onSuccess')
                if next_step_id is None:
                    next_step_id = step_order[idx + 1] if idx + 1 < len(step_order) else 'end'
                amount_label = f"{amount:g}"
                log.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": True, "detail": f"Waiting {amount_label} {unit} — resumes at {resume_at.isoformat()}"})

                pool = await _get_pg_pool()
                if pool is None:
                    # Postgres dropped out from under an already-running durable
                    # workflow (e.g. DATABASE_URL removed mid-deployment) — fail
                    # this device's chain clearly rather than pretending to wait.
                    log.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": False, "detail": "Durable storage is unavailable — cannot persist this wait"})
                    await _pg_upsert_run_result(run_id, device_id, device_name, log, "done", "failed")
                    return {"deviceId": device_id, "deviceName": device_name, "steps": log, "finalStatus": "failed", "status": "done"}

                await _persist_pending_step(run_id, device_dict, workflow.get('id'), slug_key, next_step_id, log, resume_at)
                await _pg_upsert_run_result(run_id, device_id, device_name, log, "waiting", None)
                return {"deviceId": device_id, "deviceName": device_name, "steps": log, "finalStatus": None, "status": "waiting"}

            if step_type == 'run_script_wait':
                # Dispatches a script (same mechanism as the plain "Run
                # script" mdm_action step) then parks this device's chain
                # until the agent's actual execution result is known —
                # instead of only confirming the PUT was accepted, this lets
                # the workflow branch on whether the script itself
                # succeeded or failed. Resolution normally comes from
                # script_log_reconciler_loop spotting the result early (see
                # _resume_workflow_pending_step_by_token) — resume_at below
                # is only a timeout safety net in case that never happens
                # (device stays offline, script Asset gets deleted, etc.),
                # handled by workflow_wait_resumer_loop treating step_kind
                # 'script' rows as "timed out, follow the failure branch"
                # rather than "on schedule, follow the success branch".
                cfg = step.get('config') or {}
                library_id = cfg.get('libraryId')
                timeout_minutes = cfg.get('timeoutMinutes')
                try:
                    timeout_minutes = float(timeout_minutes)
                except (TypeError, ValueError):
                    timeout_minutes = None
                if not timeout_minutes or timeout_minutes <= 0:
                    timeout_minutes = 30

                idx = step_order.index(current_id)
                next_step_id = step.get('onSuccess')
                if next_step_id is None:
                    next_step_id = step_order[idx + 1] if idx + 1 < len(step_order) else 'end'
                failure_step_id = step.get('onFailure') or 'end'

                if not library_id:
                    log.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": False, "detail": "No script selected from the Library"})
                    current_id = failure_step_id
                    continue

                pool = await _get_pg_pool()
                if pool is None:
                    log.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": False, "detail": "Durable storage is unavailable — cannot wait for a script result"})
                    await _pg_upsert_run_result(run_id, device_id, device_name, log, "done", "failed")
                    return {"deviceId": device_id, "deviceName": device_name, "steps": log, "finalStatus": "failed", "status": "done"}

                pending_token = str(uuid.uuid4())
                ok, detail = await _execute_mdm_action(
                    client, headers, org_base, device_dict.get('platform'), device_dict.get('platformDeviceId'), 'runScript',
                    workflow.get('targetDeploymentModel'), {"libraryId": library_id},
                    authorization=creds_authorization, x_workspace_slug=x_workspace_slug, device_id=device_id, device_context=context,
                    workflow_resume={"pendingToken": pending_token, "slugKey": slug_key},
                )
                if not ok:
                    log.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": False, "detail": detail})
                    current_id = failure_step_id
                    continue

                timeout_at = datetime.now(timezone.utc) + timedelta(minutes=timeout_minutes)
                log.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": True, "detail": f"Dispatched — waiting up to {timeout_minutes:g} min for the script's actual result before continuing"})
                await _persist_pending_step(run_id, device_dict, workflow.get('id'), slug_key, next_step_id, log, timeout_at, step_kind='script', on_failure_step_id=failure_step_id, pending_token=pending_token)
                await _pg_upsert_run_result(run_id, device_id, device_name, log, "waiting", None)
                return {"deviceId": device_id, "deviceName": device_name, "steps": log, "finalStatus": None, "status": "waiting"}

            if step_type == 'mdm_action':
                ok, detail = await _execute_mdm_action(
                    client, headers, org_base, device_dict.get('platform'), device_dict.get('platformDeviceId'), (step.get('config') or {}).get('action'), workflow.get('targetDeploymentModel'), (step.get('config') or {}).get('params'),
                    authorization=creds_authorization, x_workspace_slug=x_workspace_slug, device_id=device_id, device_context=context,
                )
            elif step_type == 'http_request':
                ok, detail = await _execute_http_step(client, step.get('config') or {}, context)
            elif step_type == 'notification':
                ok, detail = await _execute_notification_step(client, org_base, headers, step.get('config') or {}, context, state)
            elif step_type == 'policy_replace':
                ok, detail = await _execute_policy_replace_step(client, headers, org_base, creds_authorization, x_workspace_slug, device_ref, step.get('config') or {}, quarantine, workflow.get('id'))
            elif step_type == 'policy_add':
                ok, detail = await _execute_policy_add_step(client, headers, org_base, creds_authorization, x_workspace_slug, device_ref, step.get('config') or {}, quarantine, workflow.get('id'))
            elif step_type == 'policy_restore':
                ok, detail = await _execute_policy_restore_step(client, headers, org_base, device_ref, quarantine)
            elif step_type == 'monitor':
                ok, detail = await _execute_monitor_step(creds_authorization, x_workspace_slug, device_ref, step.get('config') or {}, quarantine, client, headers, org_base)
            else:
                ok, detail = False, f"Unknown step type '{step_type}'"

            log.append({"stepId": step.get('id'), "name": step.get('name'), "type": step_type, "ok": ok, "detail": detail})

            if ok:
                nxt = step.get('onSuccess')
                if nxt is None:
                    idx = step_order.index(current_id)
                    nxt = step_order[idx + 1] if idx + 1 < len(step_order) else 'end'
            else:
                nxt = step.get('onFailure') or 'end'
            current_id = nxt

    if not log or all(s['ok'] for s in log):
        final_status = "success"
    elif any(s['ok'] for s in log):
        final_status = "partial"
    else:
        final_status = "failed"

    _save_policy_quarantine(slug_key, quarantine)
    await _pg_upsert_run_result(run_id, device_id, device_name, log, "done", final_status)
    await _pg_finalize_run_if_done(run_id)
    return {"deviceId": device_id, "deviceName": device_name, "steps": log, "finalStatus": final_status, "status": "done"}

async def _execute_workflow_run_durable(run_id: str, workflow: dict, devices: List[WorkflowDeviceRef], authorization: str, x_workspace_slug: str):
    slug_key = x_workspace_slug or 'global'
    run = _active_runs[run_id]
    pool = await _get_pg_pool()

    async with pool.acquire() as conn:
        await conn.execute(
            """INSERT INTO workflow_runs (id, workflow_id, workflow_name, slug_key, status, total, started_at)
               VALUES ($1, $2, $3, $4, 'running', $5, now())
               ON CONFLICT (id) DO NOTHING""",
            uuid.UUID(run_id), workflow.get('id'), workflow.get('name'), slug_key, len(devices),
        )

    sem = asyncio.Semaphore(WORKFLOW_RUN_CONCURRENCY)

    async def run_one(device: WorkflowDeviceRef):
        result = await _run_device_step_chain(run_id, workflow, device, authorization, x_workspace_slug)
        run["results"].append(result)
        run["completed"] += 1

    async def run_one_bounded(device: WorkflowDeviceRef):
        async with sem:
            await run_one(device)

    await asyncio.gather(*[run_one_bounded(d) for d in devices])

    still_waiting = any(r.get("status") == "waiting" for r in run["results"])
    run["status"] = "waiting" if still_waiting else "completed"
    if not still_waiting:
        run["finishedAt"] = datetime.now(timezone.utc).isoformat()
        _append_workflow_run(slug_key, _public_run_view(run))
        _evict_old_active_runs()
    _invalidate_devices_cache(slug_key)  # a step may have changed tags/segment/state

async def _execute_workflow_run(run_id: str, workflow: dict, devices: List[WorkflowDeviceRef], authorization: str, x_workspace_slug: str):
    """Dispatcher: workflows with a 'wait' step go through the durable
    (Postgres-backed) engine; everything else uses the original fully
    in-memory engine, unchanged."""
    steps = workflow.get('steps') or []
    has_wait = any(s.get('type') in ('wait', 'run_script_wait') for s in steps)
    if has_wait:
        await _execute_workflow_run_durable(run_id, workflow, devices, authorization, x_workspace_slug)
    else:
        await _execute_workflow_run_in_memory(run_id, workflow, devices, authorization, x_workspace_slug)

async def _launch_workflow_run(
    workflow: dict,
    devices: List["WorkflowDeviceRef"],
    authorization: str,
    x_workspace_slug: str,
    background_tasks: Optional[BackgroundTasks] = None,
    target_description: Optional[str] = None,
) -> Optional[dict]:
    """Create a run record and schedule its execution. Shared by the manual
    'run workflow' endpoint (has a BackgroundTasks from the request) and the
    compliance engine's auto-fire/approve paths (no request context, so we
    schedule directly on the event loop instead). Returns None if the
    workflow needs the durable engine (it has a 'wait' step) but no
    DATABASE_URL is configured — callers must handle that refusal rather
    than silently losing the wait state to an in-process asyncio.sleep."""
    steps = workflow.get('steps') or []
    has_wait = any(s.get('type') in ('wait', 'run_script_wait') for s in steps)
    if has_wait:
        pool = await _get_pg_pool()
        if pool is None:
            return None

    slug_key = x_workspace_slug or 'global'
    run_id = str(uuid.uuid4())
    run_record = {
        "id": run_id,
        "workflowId": workflow.get('id'),
        "workflowName": workflow.get('name'),
        "startedAt": datetime.now(timezone.utc).isoformat(),
        "status": "running",
        "total": len(devices),
        "completed": 0,
        "results": [],
        "slugKey": slug_key,
        "targetDescription": target_description,
    }
    _active_runs[run_id] = run_record
    if background_tasks is not None:
        background_tasks.add_task(_execute_workflow_run, run_id, workflow, devices, authorization, x_workspace_slug)
    else:
        asyncio.create_task(_execute_workflow_run(run_id, workflow, devices, authorization, x_workspace_slug))
    return run_record

WORKFLOW_RESUMER_TICK_SECONDS = 30

async def _resume_due_workflow_steps(limit: int = 50) -> int:
    """Claims due rows from workflow_pending_steps (resume_at <= now(),
    unclaimed) with FOR UPDATE SKIP LOCKED, so this can safely be called
    concurrently — by our own internal poller loop and, later, an external
    Cloudflare Worker Cron Trigger hitting POST /api/workflows/resume-due —
    without two callers ever resuming the same device twice. Each resumed
    device continues its chain from exactly the step after its 'wait' via
    _run_device_step_chain, using the automation credential (the human who
    launched the run may be long since logged out by the time this fires).
    Returns how many rows were resumed this call."""
    pool = await _get_pg_pool()
    if pool is None:
        return 0

    async with pool.acquire() as conn:
        rows = await conn.fetch(
            """UPDATE workflow_pending_steps
               SET claimed_at = now()
               WHERE id IN (
                   SELECT id FROM workflow_pending_steps
                   WHERE resume_at <= now() AND claimed_at IS NULL
                   ORDER BY resume_at
                   FOR UPDATE SKIP LOCKED
                   LIMIT $1
               )
               RETURNING id, run_id, device_snapshot, workflow_id, slug_key, next_step_id, log, step_kind, on_failure_step_id""",
            limit,
        )

    if not rows:
        return 0

    workflows_cache: Dict[str, Optional[dict]] = {}

    async def resume_one(row):
        run_id = str(row["run_id"])
        slug_key = row["slug_key"]
        device_snapshot = json.loads(row["device_snapshot"])
        log = json.loads(row["log"])
        is_script_kind = row["step_kind"] == 'script'
        # A step_kind='script' row only ever reaches this timer-based path
        # when script_log_reconciler_loop never resolved it in time (it
        # deletes the row itself the moment it resolves — see
        # _resume_workflow_pending_step_by_token) — so getting here always
        # means "timed out", and the target is the failure branch, not the
        # success one next_step_id points to.
        target_step_id = (row["on_failure_step_id"] or 'end') if is_script_kind else row["next_step_id"]
        step_label = "run_script_wait" if is_script_kind else "wait"

        # Each row carries its own workspace slug — different pending steps
        # can belong to different workspaces, so the automation credential
        # has to be resolved per-row rather than once for the whole batch.
        authorization = await _get_automation_bearer(slug_key) or ""

        cache_key = f"{slug_key}:{row['workflow_id']}"
        if cache_key not in workflows_cache:
            workflows = _load_workflows(slug_key)
            workflows_cache[cache_key] = next((w for w in workflows if w.get('id') == row['workflow_id']), None)
        workflow = workflows_cache[cache_key]

        try:
            if not workflow:
                log.append({"stepId": None, "name": "Resume", "type": step_label, "ok": False, "detail": "Linked workflow no longer exists"})
                await _pg_upsert_run_result(run_id, device_snapshot.get('id'), device_snapshot.get('displayName'), log, "done", "failed")
                await _pg_finalize_run_if_done(run_id)
            elif not authorization:
                log.append({"stepId": None, "name": "Resume", "type": step_label, "ok": False, "detail": "No automation credential is configured for this workspace — cannot resume without one. Configure one from Settings."})
                await _pg_upsert_run_result(run_id, device_snapshot.get('id'), device_snapshot.get('displayName'), log, "done", "failed")
                await _pg_finalize_run_if_done(run_id)
            else:
                if is_script_kind:
                    log.append({"stepId": None, "name": "Script result", "type": step_label, "ok": False, "detail": "No script result received before the timeout — following the failure branch"})
                result = await _run_device_step_chain(run_id, workflow, device_snapshot, authorization, slug_key, start_step_id=target_step_id, existing_log=log)
                if result.get("status") == "done":
                    _invalidate_devices_cache(slug_key)
        except Exception as e:
            print(f"[Workflow Resumer] Error resuming run {run_id} / device {device_snapshot.get('id')}: {e}")
        finally:
            pool2 = await _get_pg_pool()
            if pool2 is not None:
                async with pool2.acquire() as conn2:
                    await conn2.execute("DELETE FROM workflow_pending_steps WHERE id = $1", row["id"])

    await asyncio.gather(*[resume_one(r) for r in rows])
    return len(rows)

async def _resume_workflow_pending_step_by_token(resume_info: Optional[dict], outcome_ok: bool, extra_detail: str = ''):
    """Called from script_log_reconciler_loop the moment a tracking entry
    created by a 'run_script_wait' step resolves (script succeeded, failed,
    or gave up unconfirmed after SCRIPT_RUN_MAX_ATTEMPTS) — resumes that
    device's parked chain down whichever branch matches, well before the
    timer-based fallback in workflow_wait_resumer_loop would otherwise catch
    it at its timeout deadline. A safe no-op if the pending row is already
    gone (e.g. that fallback claimed it first) or resume_info wasn't set
    (a plain script dispatch, not one from a workflow step)."""
    token = (resume_info or {}).get('pendingToken')
    if not token:
        return
    pool = await _get_pg_pool()
    if pool is None:
        return
    async with pool.acquire() as conn:
        row = await conn.fetchrow(
            "DELETE FROM workflow_pending_steps WHERE pending_token = $1 RETURNING id, run_id, device_snapshot, workflow_id, slug_key, next_step_id, on_failure_step_id, log",
            token,
        )
    if not row:
        return

    run_id = str(row["run_id"])
    slug_key = row["slug_key"]
    device_snapshot = json.loads(row["device_snapshot"])
    log = json.loads(row["log"])
    target_step_id = row["next_step_id"] if outcome_ok else (row["on_failure_step_id"] or 'end')
    log.append({
        "stepId": None, "name": "Script result", "type": "run_script_wait", "ok": outcome_ok,
        "detail": extra_detail or ("Script completed successfully — resuming" if outcome_ok else "Script failed — following the failure branch"),
    })

    workflow = next((w for w in _load_workflows(slug_key) if w.get('id') == row['workflow_id']), None)
    if not workflow:
        log.append({"stepId": None, "name": "Resume", "type": "run_script_wait", "ok": False, "detail": "Linked workflow no longer exists"})
        await _pg_upsert_run_result(run_id, device_snapshot.get('id'), device_snapshot.get('displayName'), log, "done", "failed")
        await _pg_finalize_run_if_done(run_id)
        return

    authorization = await _get_automation_bearer(slug_key) or ""
    if not authorization:
        log.append({"stepId": None, "name": "Resume", "type": "run_script_wait", "ok": False, "detail": "No automation credential is configured for this workspace — cannot resume without one. Configure one from Settings."})
        await _pg_upsert_run_result(run_id, device_snapshot.get('id'), device_snapshot.get('displayName'), log, "done", "failed")
        await _pg_finalize_run_if_done(run_id)
        return

    try:
        result = await _run_device_step_chain(run_id, workflow, device_snapshot, authorization, slug_key, start_step_id=target_step_id, existing_log=log)
        if result.get("status") == "done":
            _invalidate_devices_cache(slug_key)
    except Exception as e:
        print(f"[Script Wait Resume] Error resuming run {run_id} / device {device_snapshot.get('id')}: {e}")

async def workflow_wait_resumer_loop():
    """Polls for due 'wait' resumes. Ticks every WORKFLOW_RESUMER_TICK_SECONDS
    (30s) — cheap, since a normal tick is a single indexed query
    (idx_pending_steps_due) returning zero rows. A complete no-op wherever
    Postgres isn't configured, so this loop is harmless on deployments that
    never use a 'wait' step."""
    await asyncio.sleep(25)  # let the server finish initializing first
    while True:
        try:
            pool = await _get_pg_pool()
            if pool is not None:
                resumed = await _resume_due_workflow_steps()
                if resumed:
                    print(f"[Workflow Resumer] Resumed {resumed} due wait step(s)")
            _record_job_heartbeat('workflow_wait_resumer', 'ok')
        except Exception as e:
            print(f"[Workflow Resumer] Error: {e}")
            _record_job_heartbeat('workflow_wait_resumer', 'error', str(e))
        await asyncio.sleep(WORKFLOW_RESUMER_TICK_SECONDS)

@app.post("/api/workflows/{workflow_id}/run", dependencies=[Depends(verify_dashboard_token)])
async def run_workflow(
    workflow_id: str,
    payload: WorkflowRunRequest,
    background_tasks: BackgroundTasks,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
    access: dict = Depends(require_permission(area="workflows", level="manage")),
):
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")

    slug_key = x_workspace_slug or 'global'
    workflows = _load_workflows(slug_key)
    workflow = next((p for p in workflows if p.get('id') == workflow_id), None)
    if not workflow:
        raise HTTPException(status_code=404, detail="Workflow not found")
    if not payload.devices:
        raise HTTPException(status_code=400, detail="No target devices provided")
    # Base "workflows: manage" access (checked above) is enough to run an
    # ordinary workflow; a workflow with a real destructive MDM step (wipe/
    # unenroll/etc.) additionally requires the specific canRunDestructiveWorkflow
    # flag — this can only be known once the workflow itself is loaded, so
    # it's checked here rather than in the route-level dependency.
    if _workflow_has_destructive_step(workflow) and not access.get("isSuperAdmin") and not (access.get("role") or {}).get("riskyActions", {}).get("canRunDestructiveWorkflow"):
        raise HTTPException(status_code=403, detail="This workflow contains a destructive MDM action (wipe/unenroll/etc.) — your role isn't permitted to run destructive workflows.")

    run_record = await _launch_workflow_run(workflow, payload.devices, authorization, x_workspace_slug, background_tasks=background_tasks, target_description=payload.targetDescription)
    if run_record is None:
        raise HTTPException(status_code=400, detail="This workflow includes a 'wait' or 'run script and wait for result' step, which requires durable storage. Set DATABASE_URL on the server to enable it.")
    target_suffix = f' ({payload.targetDescription})' if payload.targetDescription else ''
    _record_audit_event(slug_key, category="workflow", action="workflow_run_started", actor=dash.get('sub'),
                         target_type="workflow", target_id=workflow_id, target_name=workflow.get('name'),
                         message=f'Workflow "{workflow.get("name")}" run manually on {len(payload.devices)} device{"s" if len(payload.devices) != 1 else ""}{target_suffix}')
    return _public_run_view(run_record)

# ─── DEVICE PUSH DATA (self-reported by a Windows/macOS agent) ───
#
# Applivery's own MDM data is necessarily limited to what its enrollment
# profile/API exposes. For finer-grained OS-level signals (disk encryption
# status, firewall state, patch level, etc.) the plan is a lightweight
# scheduled script running locally on each device, pushing a small JSON
# report to this webhook — no agent install/management required on our end,
# just a POST. Matching an incoming report to an existing Applivery device
# record is done by serial number (see _normalize_device_full/get_devices_
# full below) since it's the only hardware identifier that's both already
# present on every Applivery-sourced device record AND trivially readable
# locally by an unattended script on either platform (`Get-CimInstance
# Win32_BIOS` on Windows, `ioreg -l | grep IOPlatformSerialNumber` on
# macOS). A report for a serial number Applivery doesn't know about yet is
# still stored — it just won't be merged onto any device until Applivery
# catches up — so ordering between enrollment and the first push doesn't
# matter.
#
# Auth: a random secret is generated per workspace from Settings and must
# be sent back on every report as the X-Device-Report-Secret header,
# alongside the existing X-Workspace-Slug header that already identifies
# the workspace everywhere else in this API. Deliberately NOT the same
# TRIGGER_SECRET used by /api/workflows/resume-due and /api/compliance/
# evaluate-due — those are single global secrets meant for one trusted
# internal caller (a Cron Trigger), whereas this secret is meant to be
# baked into a script distributed across an entire device fleet, so each
# workspace needs to be able to rotate its own independently without
# affecting any other workspace or the internal triggers.

DEVICE_REPORT_SECRETS_FILE = os.path.join(DATA_DIR, "device_report_secrets.json")

DEVICE_PUSHDATA_DIR = os.path.join(DATA_DIR, "device_pushdata")
if not os.path.exists(DEVICE_PUSHDATA_DIR):
    os.makedirs(DEVICE_PUSHDATA_DIR)

_device_pushdata_lock = asyncio.Lock()  # serializes read-modify-write of a workspace's pushdata file across concurrent webhook calls

_register_legacy_json('device_report_secrets', lambda slug, key: DEVICE_REPORT_SECRETS_FILE)

def _load_device_report_secrets() -> Dict[str, dict]:
    return _store_load(_GLOBAL_STORE_SLUG, 'device_report_secrets', dict)

def _save_device_report_secrets(store: Dict[str, dict]):
    _store_save(_GLOBAL_STORE_SLUG, 'device_report_secrets', store)

def _device_pushdata_file(slug: str) -> str:
    return os.path.join(DEVICE_PUSHDATA_DIR, f"{_slug_clean(slug)}.json")

_register_legacy_json('device_pushdata', lambda slug, key: _device_pushdata_file(slug))

def _load_device_pushdata(slug: str) -> Dict[str, dict]:
    """Keyed by serial number → {"platform", "attributes" (normalized), "rawKeys"
    (count only, for visibility), "agentVersion", "lastReportedAt", "reportCount"}."""
    return _store_load(slug, 'device_pushdata', dict)

def _save_device_pushdata(slug: str, data: Dict[str, dict]):
    _store_save(slug, 'device_pushdata', data)

# Raw attribute names a script might reasonably send, mapped to a shared
# canonical name so a compliance policy author can write ONE condition
# ("diskEncryptionEnabled") that works across both a Windows fleet sending
# "BitLockerStatus" and a macOS fleet sending "FileVaultEnabled". This is
# purely a translation convenience, not a schema/allowlist — any key not
# listed here still comes through unchanged under its original name, so
# nothing a script sends is ever silently dropped. Extend these tables
# freely; they don't require a matching frontend change since the policy
# builder's "Self-Reported Attribute" condition takes a free-typed name.
WINDOWS_ATTR_ALIASES = {
    "BitLockerStatus": "diskEncryptionEnabled",
    "BitLockerEnabled": "diskEncryptionEnabled",
    "FirewallEnabled": "firewallEnabled",
    "DefenderEnabled": "antivirusEnabled",
    "AntivirusEnabled": "antivirusEnabled",
    "AntivirusUpToDate": "antivirusUpToDate",
    "OsBuild": "osBuildNumber",
    "OsBuildNumber": "osBuildNumber",
    "PendingUpdatesCount": "pendingOsUpdates",
    "DomainJoined": "domainJoined",
    "AzureAdJoined": "entraJoined",
    "EntraJoined": "entraJoined",
    "UptimeDays": "uptimeDays",
    "DiskFreeGb": "diskFreeGb",
    "DiskUsedPercent": "diskUsedPercent",
    "ScreenLockEnabled": "screenLockEnabled",
    "TpmEnabled": "tpmEnabled",
    "TpmReady": "tpmEnabled",
    "SecureBootEnabled": "secureBootEnabled",
    "SecureBootAvailable": "secureBootAvailable",
    # Security-attestation reporter (report-security-attributes.ps1) —
    # these back the DeviceGuard/VBS workflow actions above: a compliance
    # condition can check these post-enforcement to confirm the OMA-URI
    # command actually took effect on the device, not just that it was
    # accepted by the MDM channel.
    "VbsEnabled": "vbsEnabled",             # VirtualizationBasedSecurityStatus >= 1 (enabled, may not be running yet)
    "VbsRunning": "vbsRunning",             # VirtualizationBasedSecurityStatus == 2 (enabled AND running)
    "CredentialGuardRunning": "credentialGuardEnabled",
    "HvciRunning": "memoryIntegrityEnabled",
    "ElamEnabled": "elamEnabled",           # proxied via the Defender ELAM driver (WdBoot) run state — see script comments
}
MACOS_ATTR_ALIASES = {
    "FileVaultEnabled": "diskEncryptionEnabled",
    "FileVaultStatus": "diskEncryptionEnabled",
    "FirewallEnabled": "firewallEnabled",
    "XProtectEnabled": "antivirusEnabled",
    "AntivirusEnabled": "antivirusEnabled",
    "OsBuild": "osBuildNumber",
    "OsBuildNumber": "osBuildNumber",
    "PendingUpdatesCount": "pendingOsUpdates",
    "MdmEnrolled": "domainJoined",
    "UptimeDays": "uptimeDays",
    "DiskFreeGb": "diskFreeGb",
    "DiskUsedPercent": "diskUsedPercent",
    "ScreenLockEnabled": "screenLockEnabled",
    "SecureTokenEnabled": "secureBootEnabled",
}

def _normalize_pushed_attributes(platform: str, attributes: Dict[str, Any]) -> Dict[str, Any]:
    alias_map = WINDOWS_ATTR_ALIASES if platform == 'windows' else (MACOS_ATTR_ALIASES if platform == 'macos' else {})
    return {alias_map.get(k, k): v for k, v in (attributes or {}).items()}

class DeviceReportPayload(BaseModel):
    platform: str  # "windows" | "macos" — selects which alias table normalizes `attributes`
    serialNumber: str
    attributes: Dict[str, Any] = {}
    agentVersion: Optional[str] = None
    reportedAt: Optional[str] = None  # the device's own clock, informational only — lastReportedAt below is server time

device_report_secret_scheme = APIKeyHeader(name="X-Device-Report-Secret", auto_error=False)

def verify_device_report_secret(
    secret: Optional[str] = Depends(device_report_secret_scheme),
    x_workspace_slug: Optional[str] = Header(None),
) -> str:
    """Fails closed: 503 if this workspace has never generated a secret
    (webhook effectively disabled), 401 on any mismatch. Constant-time
    compare, same as verify_trigger_secret, since this is another
    unattended-caller credential."""
    slug_key = x_workspace_slug or 'global'
    stored = _load_device_report_secrets().get(slug_key)
    if not stored or not stored.get('secret'):
        raise HTTPException(status_code=503, detail=f"No device-report webhook secret is configured for workspace '{slug_key}'. Generate one from Settings.")
    if not secret or not hmac.compare_digest(secret, stored['secret']):
        raise HTTPException(status_code=401, detail="Invalid device-report secret")
    return slug_key

@app.post("/api/device-data/report", dependencies=[Depends(verify_device_report_secret)])
async def report_device_data(payload: DeviceReportPayload, x_workspace_slug: Optional[str] = Header(None)):
    """The actual webhook a device's scheduled script POSTs to. Not
    dashboard-token protected — the caller is an unattended script on an
    end-user device, not a logged-in admin — auth is entirely the
    X-Device-Report-Secret + X-Workspace-Slug header pair checked above."""
    slug_key = x_workspace_slug or 'global'
    if not payload.serialNumber or not payload.serialNumber.strip():
        raise HTTPException(status_code=400, detail="serialNumber is required")
    normalized = _normalize_pushed_attributes(payload.platform, payload.attributes)
    now_iso = datetime.now(timezone.utc).isoformat()

    async with _device_pushdata_lock:
        store = _load_device_pushdata(slug_key)
        existing = store.get(payload.serialNumber) or {}
        store[payload.serialNumber] = {
            "platform": payload.platform,
            "attributes": normalized,
            "agentVersion": payload.agentVersion,
            "clientReportedAt": payload.reportedAt,
            "lastReportedAt": now_iso,
            "reportCount": (existing.get("reportCount") or 0) + 1,
        }
        _save_device_pushdata(slug_key, store)

    # Best-effort display name from whatever's already in the (possibly
    # stale) in-memory device cache — no live Applivery call from a webhook
    # handler, this is purely to make the audit entry more readable.
    device_name = payload.serialNumber
    cached_devices = _live_cache_get(slug_key, DEVICES_CACHE_SOURCE)
    if cached_devices:
        match = next((d for d in cached_devices.get('items', []) if d.get('serialNumber') == payload.serialNumber), None)
        if match:
            device_name = match.get('displayName') or device_name

    _record_audit_event(slug_key, category="system", action="device_data_received", actor="device",
                         target_type="device", target_id=payload.serialNumber, target_name=device_name,
                         message=f'Received self-reported data from "{device_name}" ({payload.platform}) — {len(normalized)} attribute(s)')

    return {"status": "ok", "serialNumber": payload.serialNumber, "attributesStored": len(normalized)}

@app.get("/api/settings/device-report-secret", dependencies=[Depends(verify_dashboard_token)])
async def get_device_report_secret_status(x_workspace_slug: Optional[str] = Header(None)):
    """Unlike the automation credential (someone else's Applivery token, kept
    write-only), this secret is one we minted ourselves purely to authenticate
    a script the admin is about to go write — so it's fine, and necessary, to
    hand the real value back here for them to copy into that script."""
    slug_key = x_workspace_slug or 'global'
    entry = _load_device_report_secrets().get(slug_key)
    if not entry:
        return {"configured": False, "secret": None}
    return {
        "configured": True,
        "secret": entry.get("secret"),
        "rotatedBy": entry.get("rotatedBy"),
        "rotatedAt": entry.get("rotatedAt"),
    }

@app.post("/api/settings/device-report-secret", dependencies=[Depends(verify_dashboard_token)])
async def rotate_device_report_secret(x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    """Always mints a brand-new secret (no update-in-place) — any script still
    configured with the old value starts getting 401s immediately, which is
    the intended behavior for a rotation."""
    slug_key = x_workspace_slug or 'global'
    store = _load_device_report_secrets()
    new_secret = secrets.token_urlsafe(24)
    store[slug_key] = {
        "secret": new_secret,
        "rotatedBy": dash.get('sub'),
        "rotatedAt": datetime.now(timezone.utc).isoformat(),
    }
    _save_device_report_secrets(store)
    _record_audit_event(slug_key, category="settings", action="device_report_secret_rotated", actor=dash.get('sub'),
                         message=f"Device-report webhook secret generated/rotated for this workspace by {dash.get('sub')}")
    return {"configured": True, "secret": new_secret}

@app.delete("/api/settings/device-report-secret", dependencies=[Depends(verify_dashboard_token)])
async def clear_device_report_secret(x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    store = _load_device_report_secrets()
    if slug_key in store:
        del store[slug_key]
        _save_device_report_secrets(store)
        _record_audit_event(slug_key, category="settings", action="device_report_secret_cleared", actor=dash.get('sub'), severity="warning",
                             message="Device-report webhook secret removed for this workspace — the webhook will reject all reports until a new one is generated")
    return {"status": "ok"}

# Raw script templates for the installed-app inventory reporter (see the
# "Self-reported installed-app inventory" section further down for the
# /api/device-data/report-apps endpoint these POST to). Served as-is, with
# their __WEBHOOK_URL__/__WORKSPACE_SLUG__/__REPORT_SECRET__ placeholders
# intact — the frontend fills those in with values it already has
# (window.location.origin, orgSlug, the fetched secret) before offering the
# file for download, since it's the browser that reliably knows the public
# URL an admin's fleet should reach, not this backend process.
SCRIPTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "scripts")
DEVICE_REPORT_SCRIPT_FILES = {
    "macos": "report-installed-apps.sh",
    "windows": "report-installed-apps.ps1",
}

@app.get("/api/settings/device-report-scripts/{platform}", dependencies=[Depends(verify_dashboard_token)])
async def get_device_report_script(platform: str):
    filename = DEVICE_REPORT_SCRIPT_FILES.get(platform)
    if not filename:
        raise HTTPException(status_code=404, detail="Unknown platform — expected 'macos' or 'windows'")
    path = os.path.join(SCRIPTS_DIR, filename)
    if not os.path.exists(path):
        raise HTTPException(status_code=404, detail="Script template not found on the server")
    with open(path, "r") as f:
        content = f.read()
    return PlainTextResponse(content, media_type="text/plain")

# Security-attestation reporter — separate template/endpoint from the
# app-inventory one above (different placeholders filled the same way, but
# posts to the generic /api/device-data/report webhook instead of
# /report-apps, and its attributes flow through WINDOWS_ATTR_ALIASES /
# MACOS_ATTR_ALIASES rather than the app-inventory store). Android/iOS have
# no equivalent here — neither platform lets a third party run an unattended
# background script with elevated local privileges the way Task
# Scheduler/launchd do; getting comparable attestation off those platforms
# would require a dedicated MDM agent app (Android Enterprise Device/Profile
# Owner, or a supervised-iOS app using Apple's MDM entitlements), a
# fundamentally different build than "download and schedule a script".
SECURITY_REPORT_SCRIPT_FILES = {
    "windows": "report-security-attributes.ps1",
    "macos": "report-security-attributes.sh",
}

@app.get("/api/settings/device-report-scripts-security/{platform}", dependencies=[Depends(verify_dashboard_token)])
async def get_security_report_script(platform: str):
    filename = SECURITY_REPORT_SCRIPT_FILES.get(platform)
    if not filename:
        raise HTTPException(status_code=404, detail="Unknown platform — expected 'windows' or 'macos'")
    path = os.path.join(SCRIPTS_DIR, filename)
    if not os.path.exists(path):
        raise HTTPException(status_code=404, detail="Script template not found on the server")
    with open(path, "r") as f:
        content = f.read()
    return PlainTextResponse(content, media_type="text/plain")

REATTEST_LIBRARY_ENTRY_NAME = {"windows": "Security Attestation Reporter (Windows)", "macos": "Security Attestation Reporter (macOS)"}

async def _ensure_reattest_library_entry(client: httpx.AsyncClient, headers: dict, org_base: str, slug_key: str, platform: str) -> Optional[dict]:
    """The security-attestation reporter scripts are normally installed ONCE
    as a scheduled task (see SECURITY_REPORT_SCRIPT_FILES/report-security-
    attributes.*) — there's no remote 'run this now' by default, since Task
    Scheduler/launchd own the recurring schedule, not Applivery. This finds
    (or, the first time it's needed, silently creates) an Action Library
    entry pointing at that same script uploaded as an Applivery Asset, so a
    bulk 're-attest now' has something it can push via the same runScript
    primitive used everywhere else in the app. Idempotent — once created,
    later calls just find the existing entry by name."""
    library = _load_action_library(slug_key)
    name = REATTEST_LIBRARY_ENTRY_NAME.get(platform)
    if not name:
        return None
    existing = next((e for e in library if e.get('type') == 'script' and e.get('platform') == platform and e.get('name') == name), None)
    if existing:
        return existing
    script_filename = SECURITY_REPORT_SCRIPT_FILES.get(platform)
    script_path = os.path.join(SCRIPTS_DIR, script_filename) if script_filename else None
    if not script_path or not os.path.exists(script_path):
        return None
    with open(script_path, "r") as f:
        content = f.read()
    upload_base = org_base.replace("https://api.applivery.io", "https://upload.applivery.io")
    asset, error = await _create_script_asset(client, headers, upload_base, name, "Auto-registered so 'Re-attest now' can push this on demand.", content, platform, None, True)
    if error or not asset:
        return None
    now = datetime.now(timezone.utc).isoformat()
    entry = {
        "id": str(uuid.uuid4()), "type": "script", "name": name,
        "description": "Auto-registered so 'Re-attest now' can push this on demand.",
        "platform": platform, "assetId": asset.get('id'), "assetName": asset.get('name'),
        "arguments": "", "scope": "machine", "createdAt": now, "updatedAt": now,
    }
    library.append(entry)
    _save_action_library(slug_key, library)
    return entry

class BulkReattestPayload(BaseModel):
    deviceIds: List[str]

@app.post("/api/devices/bulk-reattest", dependencies=[Depends(verify_dashboard_token)])
async def bulk_reattest_devices(
    payload: BulkReattestPayload,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    """Pushes the security-attestation reporter script to every selected
    Windows/macOS device right now, instead of waiting for its next scheduled
    run — see _ensure_reattest_library_entry for why that needs a one-time
    Asset registration step. Devices on platforms with no reporter script
    (Android/iOS — see the module comment above SECURITY_REPORT_SCRIPT_FILES)
    are skipped with an explicit reason rather than silently ignored."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    slug_key = x_workspace_slug or 'global'
    devices_res = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
    by_id = {d.get('id'): d for d in (devices_res.get('items') or [])}

    results = []
    async with httpx.AsyncClient(timeout=30.0) as client:
        headers = {"Authorization": authorization}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        library_entry_cache: Dict[str, Optional[dict]] = {}
        for device_id in payload.deviceIds:
            device = by_id.get(device_id)
            if not device:
                results.append({"deviceId": device_id, "ok": False, "detail": "Device not found in current fleet"})
                continue
            platform = device.get('platform')
            if platform not in SECURITY_REPORT_SCRIPT_FILES:
                results.append({"deviceId": device_id, "displayName": device.get('displayName'), "ok": False, "detail": f"No self-report script for platform '{platform}'"})
                continue
            if platform not in library_entry_cache:
                library_entry_cache[platform] = await _ensure_reattest_library_entry(client, headers, org_base, slug_key, platform)
            entry = library_entry_cache[platform]
            if not entry:
                results.append({"deviceId": device_id, "displayName": device.get('displayName'), "ok": False, "detail": "Could not register the attestation script as a runnable Asset"})
                continue
            ok, detail = await _execute_mdm_action(
                client, headers, org_base, platform, device.get('platformDeviceId'), 'runScript',
                params={"libraryId": entry['id']}, authorization=authorization, x_workspace_slug=x_workspace_slug, device_id=device_id,
            )
            results.append({"deviceId": device_id, "displayName": device.get('displayName'), "ok": ok, "detail": detail})

    succeeded = sum(1 for r in results if r['ok'])
    _record_audit_event(slug_key, category="device", action="bulk_reattest", actor=dash.get('sub'),
                         message=f'Re-attestation pushed to {succeeded}/{len(results)} selected device(s) by {dash.get("sub")}')
    return {"results": results, "succeeded": succeeded, "total": len(results)}

# ─── COMPLIANCE POLICIES: WHAT TO WATCH, LINKED TO WHAT TO RUN ───
# A Compliance Policy is a set of conditions ("rules") describing an OUT-OF-
# COMPLIANCE state, plus a link to the Workflow that should run against any
# device matching them. Policies are evaluated two ways: automatically, on a
# timer (compliance_scheduler_loop below), and on demand via "Evaluate now".
# Each policy has an independent autoRun switch: on means a violation fires
# its workflow immediately (no human in the loop); off means the violation is
# queued for an admin to approve or dismiss from the review queue.

COMPLIANCE_POLICIES_DIR = os.path.join(DATA_DIR, "compliance_policies")
if not os.path.exists(COMPLIANCE_POLICIES_DIR):
    os.makedirs(COMPLIANCE_POLICIES_DIR)

COMPLIANCE_VIOLATIONS_DIR = os.path.join(DATA_DIR, "compliance_violations")
if not os.path.exists(COMPLIANCE_VIOLATIONS_DIR):
    os.makedirs(COMPLIANCE_VIOLATIONS_DIR)

COMPLIANCE_STATE_DIR = os.path.join(DATA_DIR, "compliance_state")
if not os.path.exists(COMPLIANCE_STATE_DIR):
    os.makedirs(COMPLIANCE_STATE_DIR)

COMPLIANCE_SCHEDULER_TICK_SECONDS = 60  # how often the scheduler checks which policies are due — see _due_compliance_policy_ids. Each policy's own evaluationIntervalMinutes (60 min-24h, see CompliancePolicyPayload) governs how often it's actually evaluated; this just needs to be finer-grained than the shortest configured interval.

def _due_compliance_policy_ids(slug_key: str) -> List[str]:
    """Which enabled policies are due for automatic re-evaluation right now,
    based on each policy's own evaluationIntervalMinutes (or the org default,
    COMPLIANCE_DEFAULT_EVAL_INTERVAL_MINUTES) and lastEvaluatedAt. A policy
    that has never run, or has a malformed timestamp, is always due."""
    now = datetime.now(timezone.utc)
    due = []
    for p in _load_compliance_policies(slug_key):
        if not p.get('enabled', True):
            continue
        interval_minutes = p.get('evaluationIntervalMinutes') or COMPLIANCE_DEFAULT_EVAL_INTERVAL_MINUTES
        last = p.get('lastEvaluatedAt')
        if not last:
            due.append(p['id'])
            continue
        try:
            last_dt = datetime.fromisoformat(str(last).replace('Z', '+00:00'))
        except Exception:
            due.append(p['id'])
            continue
        if (now - last_dt).total_seconds() >= interval_minutes * 60:
            due.append(p['id'])
    return due

# ── APP LISTS (mandatory / disallowed apps per platform) ──
# Two related, per-workspace stores:
#   - App Catalog: a dedup'd (by platform+identifier), reusable pool of
#     "known apps" — once an app has been added to ANY list (or even just
#     looked up), it shows up as a one-click pick for every other list on
#     that platform instead of needing to be searched again.
#   - App Lists: named, platform-scoped collections of Catalog entries. A
#     List itself has no inherent "required" or "disallowed" meaning — that's
#     decided per-Compliance-Policy by which condition type references it
#     (requiredAppList vs disallowedAppList), so the same List (e.g. "Known
#     spyware") could be used as a disallowed-list in one policy today and,
#     in principle, referenced differently elsewhere.
APP_CATALOG_DIR = os.path.join(DATA_DIR, "app_catalog")
APP_LISTS_DIR = os.path.join(DATA_DIR, "app_lists")
for _d in (APP_CATALOG_DIR, APP_LISTS_DIR):
    if not os.path.exists(_d):
        os.makedirs(_d)

def _app_catalog_file(slug: str) -> str:
    slug_clean = re.sub(r'[^a-zA-Z0-9_-]', '_', slug or 'global')
    return os.path.join(APP_CATALOG_DIR, f"{slug_clean}.json")

_register_legacy_json('app_catalog', lambda slug, key: _app_catalog_file(slug))

def _load_app_catalog(slug: str) -> List[Dict[str, Any]]:
    return _store_load(slug, 'app_catalog', list)

def _save_app_catalog(slug: str, items: List[Dict[str, Any]]):
    _store_save(slug, 'app_catalog', items)

def _app_lists_file(slug: str) -> str:
    slug_clean = re.sub(r'[^a-zA-Z0-9_-]', '_', slug or 'global')
    return os.path.join(APP_LISTS_DIR, f"{slug_clean}.json")

_register_legacy_json('app_lists', lambda slug, key: _app_lists_file(slug))

def _load_app_lists(slug: str) -> List[Dict[str, Any]]:
    return _store_load(slug, 'app_lists', list)

def _save_app_lists(slug: str, items: List[Dict[str, Any]]):
    _store_save(slug, 'app_lists', items)

def _upsert_app_catalog_entry(slug: str, platform: str, identifier: str, name: str, icon_url: Optional[str], source: str) -> dict:
    """Dedup by (platform, identifier) — returns the existing entry if one
    already matches, otherwise creates and returns a new one. This is the
    mechanism behind 'apps already on a list are easy to reuse elsewhere':
    every add-to-list flow funnels through here first."""
    identifier = (identifier or '').strip()
    catalog = _load_app_catalog(slug)
    existing = next((e for e in catalog if e.get('platform') == platform and e.get('identifier', '').lower() == identifier.lower()), None)
    if existing:
        return existing
    entry = {
        "id": str(uuid.uuid4()), "platform": platform, "identifier": identifier,
        "name": name or identifier, "iconUrl": icon_url, "source": source,
        "createdAt": datetime.now(timezone.utc).isoformat(),
    }
    catalog.append(entry)
    _save_app_catalog(slug, catalog)
    return entry

class AppCatalogAddPayload(BaseModel):
    platform: str  # 'apple' | 'macos' | 'android' | 'windows'
    identifier: str
    name: Optional[str] = None
    iconUrl: Optional[str] = None
    source: str = "manual"

@app.get("/api/app-catalog", dependencies=[Depends(verify_dashboard_token)])
async def list_app_catalog(x_workspace_slug: Optional[str] = Header(None), platform: Optional[str] = None):
    items = _load_app_catalog(x_workspace_slug or 'global')
    if platform:
        items = [e for e in items if e.get('platform') == platform]
    return {"items": items}

@app.post("/api/app-catalog", dependencies=[Depends(verify_dashboard_token)])
async def add_app_catalog_entry(payload: AppCatalogAddPayload, x_workspace_slug: Optional[str] = Header(None)):
    if not payload.identifier.strip():
        raise HTTPException(status_code=400, detail="An app identifier (bundle ID / package name) is required")
    slug_key = x_workspace_slug or 'global'
    entry = _upsert_app_catalog_entry(slug_key, payload.platform, payload.identifier, payload.name, payload.iconUrl, payload.source)
    return entry

@app.delete("/api/app-catalog/{entry_id}", dependencies=[Depends(verify_dashboard_token)])
async def delete_app_catalog_entry(entry_id: str, x_workspace_slug: Optional[str] = Header(None)):
    slug_key = x_workspace_slug or 'global'
    referencing = [l for l in _load_app_lists(slug_key) if entry_id in (l.get('appIds') or [])]
    if referencing:
        names = ', '.join(l.get('name') or l.get('id') for l in referencing)
        raise HTTPException(status_code=409, detail=f"Still referenced by list(s): {names} — remove it from those first")
    catalog = _load_app_catalog(slug_key)
    remaining = [e for e in catalog if e.get('id') != entry_id]
    _save_app_catalog(slug_key, remaining)
    return {"status": "ok"}

class AppListPayload(BaseModel):
    name: str
    description: Optional[str] = ""
    platform: str
    appIds: List[str] = []

@app.get("/api/app-lists", dependencies=[Depends(verify_dashboard_token)])
async def list_app_lists(x_workspace_slug: Optional[str] = Header(None), platform: Optional[str] = None):
    items = _load_app_lists(x_workspace_slug or 'global')
    if platform:
        items = [l for l in items if l.get('platform') == platform]
    return {"items": items}

@app.post("/api/app-lists", dependencies=[Depends(verify_dashboard_token)])
async def create_app_list(payload: AppListPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    lists_ = _load_app_lists(slug_key)
    now = datetime.now(timezone.utc).isoformat()
    new_list = payload.dict()
    new_list['id'] = str(uuid.uuid4())
    new_list['createdAt'] = now
    new_list['updatedAt'] = now
    lists_.append(new_list)
    _save_app_lists(slug_key, lists_)
    _record_audit_event(slug_key, category="compliance", action="app_list_created", actor=dash.get('sub'),
                         target_type="app_list", target_id=new_list['id'], target_name=new_list.get('name'),
                         message=f'App list "{new_list.get("name")}" created ({len(new_list.get("appIds") or [])} apps)')
    return new_list

@app.put("/api/app-lists/{list_id}", dependencies=[Depends(verify_dashboard_token)])
async def update_app_list(list_id: str, payload: AppListPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    lists_ = _load_app_lists(slug_key)
    idx = next((i for i, l in enumerate(lists_) if l.get('id') == list_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="App list not found")
    updated = payload.dict()
    updated['id'] = list_id
    updated['createdAt'] = lists_[idx].get('createdAt') or datetime.now(timezone.utc).isoformat()
    updated['updatedAt'] = datetime.now(timezone.utc).isoformat()
    lists_[idx] = updated
    _save_app_lists(slug_key, lists_)
    _record_audit_event(slug_key, category="compliance", action="app_list_updated", actor=dash.get('sub'),
                         target_type="app_list", target_id=list_id, target_name=updated.get('name'),
                         message=f'App list "{updated.get("name")}" updated ({len(updated.get("appIds") or [])} apps)')
    return updated

@app.delete("/api/app-lists/{list_id}", dependencies=[Depends(verify_dashboard_token)])
async def delete_app_list(list_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    referencing = _policies_referencing_app_list(slug_key, list_id)
    if referencing:
        names = ', '.join(p.get('name') or p.get('id') for p in referencing)
        raise HTTPException(status_code=409, detail=f"Still referenced by Compliance Policy: {names} — remove that condition first")
    lists_ = _load_app_lists(slug_key)
    deleted = next((l for l in lists_ if l.get('id') == list_id), None)
    remaining = [l for l in lists_ if l.get('id') != list_id]
    _save_app_lists(slug_key, remaining)
    if deleted:
        _record_audit_event(slug_key, category="compliance", action="app_list_deleted", actor=dash.get('sub'), severity="warning",
                             target_type="app_list", target_id=list_id, target_name=deleted.get('name'),
                             message=f'App list "{deleted.get("name")}" deleted')
    return {"status": "ok"}

def _policies_referencing_app_list(slug: str, list_id: str) -> List[dict]:
    """Compliance Policies with a requiredAppList/disallowedAppList condition
    pointing at this list — powers the App Lists view's 'referenced by' badge
    and blocks deletion of an in-use list."""
    out = []
    for policy in _load_compliance_policies(slug):
        for cond in (policy.get('conditions') or []):
            if cond.get('field') in ('requiredAppList', 'disallowedAppList') and str(cond.get('value')) == str(list_id):
                out.append(policy)
                break
    return out

@app.get("/api/app-lists/{list_id}/usage", dependencies=[Depends(verify_dashboard_token)])
async def get_app_list_usage(list_id: str, x_workspace_slug: Optional[str] = Header(None)):
    policies = _policies_referencing_app_list(x_workspace_slug or 'global', list_id)
    return {"items": [{"id": p.get('id'), "name": p.get('name')} for p in policies]}

# ── App search — helps admins add apps to a list without knowing bundle
# IDs/package names by heart. Every platform has a different (and
# differently reliable) story here — see the code comments per branch. All
# results are normalized to {identifier, name, iconUrl, source} so the
# frontend doesn't need per-source special-casing. Every _search_* function
# returns (items, error) — error is None on success, or a short string the
# frontend can show verbatim, so a failure is visible instead of silently
# looking like "no matches". Failures are also print()-logged server-side
# for diagnosing from the container logs.
_HOMEBREW_CASK_CACHE: Dict[str, Any] = {"data": None, "expires": 0}

def _extract_search_results(body: Any) -> Optional[list]:
    """Applivery's app-store-search endpoints wrap results a couple of
    different ways depending on the call — try the plausible shapes in
    order rather than assuming one. Returns None (not []) if nothing
    recognizable was found, so callers can tell "wrong shape" apart from
    "zero matches"."""
    if isinstance(body, dict):
        data = body.get('data')
        if isinstance(data, dict):
            if isinstance(data.get('results'), list):
                return data['results']
            if isinstance(data.get('items'), list):
                return data['items']
        if isinstance(data, list):
            return data
        if isinstance(body.get('results'), list):
            return body['results']
        if isinstance(body.get('items'), list):
            return body['items']
    if isinstance(body, list):
        return body
    return None

async def _search_apple_store(client: httpx.AsyncClient, headers: dict, org_base: str, text: str, platform: str) -> tuple:
    # Confirmed via Applivery's OpenAPI schema: GET .../mdm/apple/enterprise/
    # applications/search?text=&country=&os=&kind=app — a live proxy to
    # Apple's own App Store search, no pre-add required. Response items carry
    # a real `bundleId`, which is exactly what Applivery's per-device
    # installed-applications endpoint reports back too — so results here are
    # directly usable as compliance-condition identifiers.
    os_value = 'macos' if platform == 'macos' else 'ios'
    url = f"{org_base}/mdm/apple/enterprise/applications/search"
    try:
        res = await _applivery_call(client, 'GET', url, headers=headers, params={"text": text, "os": os_value, "kind": "app", "country": "US"})
    except Exception as e:
        print(f"[app-search] Apple Store search failed (network): {e}")
        return [], f"Request to Applivery failed: {e}"
    if res.status_code >= 300:
        print(f"[app-search] Apple Store search returned {res.status_code}: {res.text[:300]}")
        return [], f"Applivery returned {res.status_code}: {res.text[:200]}"
    try:
        results = _extract_search_results(res.json())
    except Exception as e:
        print(f"[app-search] Apple Store search: could not parse JSON: {e}")
        return [], "Could not parse Applivery's response"
    if results is None:
        print(f"[app-search] Apple Store search: unrecognized response shape: {res.text[:300]}")
        return [], "Unrecognized response shape from Applivery — see server logs"
    out = []
    for item in results[:25]:
        if not isinstance(item, dict) or not item.get('bundleId'):
            continue
        out.append({"identifier": item['bundleId'], "name": item.get('name') or item['bundleId'], "iconUrl": item.get('icon'), "source": "apple_store"})
    return out, None

async def _search_ms_store(client: httpx.AsyncClient, headers: dict, org_base: str, text: str) -> tuple:
    # Confirmed to exist (GET .../mdm/windows/enterprise/applications/search
    # ?text=&country=) but Applivery's own OpenAPI doc leaves the response
    # schema undocumented (empty object) — so this parses defensively across
    # a few plausible field-name guesses rather than assuming one shape.
    # Windows identifier-matching is inherently the least reliable of the
    # four platforms (see MDM_ACTIONS/customOmaUri comments elsewhere) —
    # admins should double-check a first result against Settings > Apps on a
    # real device before relying on it for a disallowed-app condition.
    url = f"{org_base}/mdm/windows/enterprise/applications/search"
    try:
        res = await _applivery_call(client, 'GET', url, headers=headers, params={"text": text, "country": "US"})
    except Exception as e:
        print(f"[app-search] MS Store search failed (network): {e}")
        return [], f"Request to Applivery failed: {e}"
    if res.status_code >= 300:
        print(f"[app-search] MS Store search returned {res.status_code}: {res.text[:300]}")
        return [], f"Applivery returned {res.status_code}: {res.text[:200]}"
    try:
        results = _extract_search_results(res.json())
    except Exception as e:
        print(f"[app-search] MS Store search: could not parse JSON: {e}")
        return [], "Could not parse Applivery's response"
    if results is None:
        print(f"[app-search] MS Store search: unrecognized response shape: {res.text[:300]}")
        return [], "Unrecognized response shape from Applivery — see server logs"
    out = []
    for item in results[:25]:
        if not isinstance(item, dict):
            continue
        identifier = item.get('productId') or item.get('id') or item.get('packageFamilyName') or item.get('storeId')
        name = item.get('title') or item.get('name') or item.get('displayName')
        if not identifier or not name:
            continue
        out.append({"identifier": str(identifier), "name": name, "iconUrl": item.get('icon') or item.get('iconUrl'), "source": "ms_store"})
    return out, None

async def _search_winget(text: str) -> tuple:
    # Best-effort secondary source for Windows — api.winget.run is a live,
    # free, third-party (not Microsoft-run) index of the community
    # winget-pkgs repo. Its PackageIdentifier (e.g. "Mozilla.Firefox") is a
    # real, well-known convention, but the hosted dataset has been observed
    # stale (unrefreshed since 2023) — treated as a convenience suggestion
    # list, not authoritative.
    try:
        async with httpx.AsyncClient(timeout=8.0) as c:
            res = await c.get("https://api.winget.run/v2/packages", params={"query": text})
        if res.status_code >= 300:
            return [], f"winget.run returned {res.status_code}"
        items = (res.json() or {}).get('Packages') or []
    except Exception as e:
        print(f"[app-search] winget search failed: {e}")
        return [], f"winget.run request failed: {e}"
    out = []
    for item in items[:15]:
        pkg_id = item.get('Id')
        if not pkg_id:
            continue
        out.append({"identifier": pkg_id, "name": item.get('Latest', {}).get('Name') or item.get('Name') or pkg_id, "iconUrl": None, "source": "winget"})
    return out, None

async def _search_homebrew(text: str) -> tuple:
    # Best-effort secondary source for macOS — formulae.brew.sh/api/cask.json
    # is live/free/unauthenticated but (a) has no server-side search, so the
    # full ~5-7MB index is fetched once and cached in-process, filtered
    # locally per query, and (b) critically has NO bundle identifier field at
    # all (just a Homebrew "token" slug and the .app filename) — so results
    # here are name-only suggestions; the admin still has to confirm/enter
    # the real bundle ID (e.g. from `mdls -name kMDItemCFBundleIdentifier`)
    # before it'll match real installed-app data.
    now = datetime.now(timezone.utc).timestamp()
    if _HOMEBREW_CASK_CACHE["data"] is None or _HOMEBREW_CASK_CACHE["expires"] < now:
        try:
            async with httpx.AsyncClient(timeout=20.0) as c:
                res = await c.get("https://formulae.brew.sh/api/cask.json")
            if res.status_code >= 300:
                return [], f"formulae.brew.sh returned {res.status_code}"
            _HOMEBREW_CASK_CACHE["data"] = res.json()
            _HOMEBREW_CASK_CACHE["expires"] = now + 21600  # 6h — this index changes slowly
        except Exception as e:
            print(f"[app-search] Homebrew cask fetch failed: {e}")
            return [], f"formulae.brew.sh request failed: {e}"
    text_lower = text.lower()
    out = []
    for cask in (_HOMEBREW_CASK_CACHE["data"] or []):
        names = cask.get('name') or []
        if any(text_lower in (n or '').lower() for n in names) or text_lower in (cask.get('token') or ''):
            out.append({"identifier": cask.get('token'), "name": (names[0] if names else cask.get('token')), "iconUrl": None, "source": "homebrew_unconfirmed_id"})
        if len(out) >= 15:
            break
    return out, None

async def _search_android_known(client: httpx.AsyncClient, headers: dict, org_base: str, text: str) -> tuple:
    # No free-text Play Store search exists for EMMs (Google only exposes
    # Managed Google Play browsing through their own embedded iframe, not a
    # JSON API — confirmed via Applivery's web-token endpoint, which is just
    # a JWT for embedding that iframe). So the practical "search" for Android
    # is: apps already known to this org — either already added to
    # Applivery's App Distribution catalog, or already approved into this
    # org's Android Enterprise (Managed Google Play) catalog — filtered by
    # substring match. Free-text package names typed by the admin always
    # remain a fallback beyond this.
    text_lower = text.lower()
    out = []
    errors = []
    try:
        res = await _applivery_call(client, 'GET', f"{org_base}/apps", headers=headers, params={"oss": "android"})
        if res.status_code < 300:
            for item in extract_items(res.json()):
                name = item.get('name') or ''
                if text_lower in name.lower():
                    out.append({"identifier": str(item.get('id') or item.get('_id') or ''), "name": name, "iconUrl": item.get('icon'), "source": "applivery_catalog"})
        else:
            errors.append(f"App Distribution catalog: {res.status_code}")
    except Exception as e:
        print(f"[app-search] Android catalog search failed: {e}")
        errors.append(f"App Distribution catalog request failed: {e}")
    try:
        res = await _applivery_call(client, 'GET', f"{org_base}/mdm/android/enterprise/applications/emm-application", headers=headers)
        if res.status_code < 300:
            for item in extract_items(res.json()):
                info = item.get('info') or {}
                name = info.get('title') or info.get('name') or item.get('title') or ''
                pkg = info.get('bundleId') or item.get('packageName') or item.get('bundleId')
                if pkg and text_lower in (name or pkg).lower():
                    out.append({"identifier": pkg, "name": name or pkg, "iconUrl": info.get('icon'), "source": "android_enterprise"})
        elif res.status_code != 404:  # org may not have Android Enterprise set up at all — not an error worth surfacing
            errors.append(f"Android Enterprise catalog: {res.status_code}")
    except Exception as e:
        print(f"[app-search] Android Enterprise catalog search failed: {e}")
        errors.append(f"Android Enterprise catalog request failed: {e}")
    return out[:25], ('; '.join(errors) if errors and not out else None)

# ── Script Assets — powers the Script & OMA-URI Library's script picker ──
# Confirmed via Applivery's OpenAPI schema: GET .../mdm/assets supports
# `type` (enum includes "script") and `subType` (enum: windows/macos/ios/
# android) filters — scripts live in Applivery's general Asset library
# (Resources > Scripts in the Dashboard), not inside a Policy. No documented
# server-side text search on this endpoint, so — same approach as Homebrew/
# Android catalog search above — a batch is fetched and filtered client-side.
async def _search_script_assets(client: httpx.AsyncClient, headers: dict, org_base: str, platform: str, text: str, limit: int = 100) -> tuple:
    """platform: 'windows' | 'macos' | 'all' (no subType filter — used by the
    bulk-fetch browser, which lists every script Asset regardless of
    platform and lets the UI group/filter them client-side)."""
    params = {"type": "script", "limit": limit}
    if platform != 'all':
        params["subType"] = 'macos' if platform == 'macos' else 'windows'
    try:
        res = await _applivery_call(client, 'GET', f"{org_base}/mdm/assets", headers=headers, params=params)
    except Exception as e:
        print(f"[script-assets] search failed: {e}")
        return [], f"Request to Applivery failed: {e}"
    if res.status_code >= 300:
        print(f"[script-assets] search returned {res.status_code}: {res.text[:300]}")
        return [], f"Applivery returned {res.status_code}: {res.text[:200]}"
    try:
        items = ((res.json().get('data') or {}).get('items')) or []
    except Exception as e:
        return [], f"Could not parse Applivery's response: {e}"
    text_lower = (text or '').strip().lower()
    out = []
    for item in items:
        if not isinstance(item, dict) or not item.get('id'):
            continue
        name = item.get('name') or ''
        if text_lower and text_lower not in name.lower():
            continue
        out.append({"id": item['id'], "name": name, "description": item.get('description') or ''})
    return out, None

@app.get("/api/script-assets", dependencies=[Depends(verify_dashboard_token)])
async def search_script_assets(
    platform: str, text: str = "",
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Backs the Script & OMA-URI Library's script picker — lists Applivery's
    own script Assets (created/uploaded from the Applivery Dashboard's
    Resources > Scripts, or by anyone with API access) so an admin can pick
    one by name instead of copying its Asset ID by hand."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing Applivery session — try refreshing the page and logging in again")
    if platform not in ('windows', 'macos'):
        raise HTTPException(status_code=400, detail="platform must be 'windows' or 'macos'")
    async with httpx.AsyncClient(timeout=20.0) as client:
        headers = {"Authorization": authorization, "Content-Type": "application/json"}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        items, error = await _search_script_assets(client, headers, org_base, platform, text, limit=25)
    return {"items": items[:25], "error": error}

@app.get("/api/script-assets/browse", dependencies=[Depends(verify_dashboard_token)])
async def browse_script_assets(
    platform: str = "all",
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Lists every script Asset already in Applivery (both platforms by
    default), for the Script Library's "Fetch from Applivery" bulk-import
    browser — deliberately no text filter and a much higher cap than the
    picker above, since the point here is "show me everything so I can pick
    which ones to bring into the local library", not narrowing down."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing Applivery session — try refreshing the page and logging in again")
    if platform not in ('windows', 'macos', 'all'):
        raise HTTPException(status_code=400, detail="platform must be 'windows', 'macos', or 'all'")
    async with httpx.AsyncClient(timeout=30.0) as client:
        headers = {"Authorization": authorization, "Content-Type": "application/json"}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        windows_items, macos_items = [], []
        errors = []
        platforms_to_fetch = ['windows', 'macos'] if platform == 'all' else [platform]
        for p in platforms_to_fetch:
            items, error = await _search_script_assets(client, headers, org_base, p, '', limit=500)
            for it in items:
                it['platform'] = p
            (windows_items if p == 'windows' else macos_items).extend(items)
            if error:
                errors.append(error)
        all_items = windows_items + macos_items
        local_library = _load_action_library(x_workspace_slug or 'global')
        already_imported = {e.get('assetId') for e in local_library if e.get('type') == 'script' and e.get('assetId')}
        for it in all_items:
            it['alreadyInLibrary'] = it['id'] in already_imported
    return {"items": all_items, "error": '; '.join(errors) if errors and not all_items else None}

@app.get("/api/script-assets/{asset_id}/content", dependencies=[Depends(verify_dashboard_token)])
async def get_script_asset_content(
    asset_id: str,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Fetches a script Asset's raw source text via Applivery's undocumented
    .../mdm/assets/:id/view endpoint ({content, url}) — powers both the
    bulk-fetch browser's content preview and the in-app script editor's
    "load current content" step when editing an existing Applivery script."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing Applivery session — try refreshing the page and logging in again")
    async with httpx.AsyncClient(timeout=20.0) as client:
        headers = {"Authorization": authorization, "Content-Type": "application/json"}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        try:
            res = await _applivery_call(client, 'GET', f"{org_base}/mdm/assets/{asset_id}/view", headers=headers)
        except Exception as e:
            raise HTTPException(status_code=502, detail=f"Request to Applivery failed: {e}")
        if res.status_code >= 300:
            raise HTTPException(status_code=502, detail=f"Applivery returned {res.status_code}: {res.text[:200]}")
        try:
            data = res.json().get('data') or {}
        except Exception as e:
            raise HTTPException(status_code=502, detail=f"Could not parse Applivery's response: {e}")
    return {"content": data.get('content') or '', "url": data.get('url')}

# ── Script Asset content upload (create/edit) ──
# Confirmed via Applivery's OpenAPI schema that asset creation actually lives
# on a DIFFERENT host (upload.applivery.io, not api.applivery.io) and is
# genuinely multipart/form-data (the api.applivery.io "Add new asset" page's
# JSON-only schema is misleading — its own 400 responses, codes 5006/5007,
# confirm a real file part is required). There is no documented endpoint to
# replace an existing asset's file content — PUT .../mdm/assets/:id only
# updates name/description/segment/exposeToChildren. Per the Applivery
# console's own observed behavior (editing a script there produces a NEW
# Mongo _id under the hood, with the previous version left in place rather
# than deleted — almost certainly because a Policy can already reference the
# old Asset id, and deleting it out from under that Policy would silently
# break the assignment), "editing" a script here means: upload the new
# content as a fresh Asset, leave the old one alone, and repoint anything in
# our local library that referenced the old Asset id to the new one — with a
# " vN" suffix appended to the name so the version history is visible at a
# glance. The old Asset is intentionally NOT deleted.
SCRIPT_EXTENSION_BY_PLATFORM = {"windows": "ps1", "macos": "sh"}

def _script_asset_filename(name: str, platform: str) -> str:
    base = re.sub(r'[^a-zA-Z0-9_\-. ]', '', name or 'script').strip() or 'script'
    ext = SCRIPT_EXTENSION_BY_PLATFORM.get(platform, 'sh')
    return f"{base}.{ext}"

async def _create_script_asset(client: httpx.AsyncClient, headers: dict, upload_base: str, name: str, description: str, content: str, platform: str, segment_id: Optional[int] = None, expose_to_children: Optional[bool] = None) -> tuple:
    """POSTs a new script Asset with real file content to upload.applivery.io.
    Returns (asset_dict_or_None, error_or_None).

    segment_id defaults to 0 (the Global/root segment) when not given — new
    scripts should be reachable from workflows regardless of which segment a
    target device belongs to, and Global is the one segment every other
    segment descends from. exposeToChildren mirrors Applivery's own field:
    whether descendant segments can see/use this Asset."""
    filename = _script_asset_filename(name, platform)
    form_data = {"name": name, "description": description or '', "segmentId": str(segment_id if segment_id is not None else 0)}
    if expose_to_children is not None:
        form_data["exposeToChildren"] = 'true' if expose_to_children else 'false'
    files = {"file": (filename, (content or '').encode('utf-8'), 'text/plain')}
    try:
        res = await client.post(f"{upload_base}/mdm/assets", headers={"Authorization": headers.get("Authorization")}, data=form_data, files=files)
    except Exception as e:
        return None, f"Upload to Applivery failed: {e}"
    if res.status_code >= 300:
        return None, f"Applivery returned {res.status_code}: {res.text[:300]}"
    try:
        return (res.json().get('data') or {}), None
    except Exception as e:
        return None, f"Could not parse Applivery's response: {e}"

def _next_version_name(name: str) -> str:
    """'MyScript' -> 'MyScript v2'; 'MyScript v2' -> 'MyScript v3'."""
    m = re.match(r'^(.*)\sv(\d+)$', (name or '').strip())
    if m:
        return f"{m.group(1)} v{int(m.group(2)) + 1}"
    return f"{(name or '').strip()} v2"

class ScriptAssetCreatePayload(BaseModel):
    name: str
    description: Optional[str] = ""
    platform: str  # 'windows' | 'macos'
    content: str
    segmentId: Optional[int] = None  # defaults to 0 (Global) in _create_script_asset when omitted
    exposeToChildren: Optional[bool] = True  # Global is the whole point of defaulting here — expose by default so any segment's devices can reference it

@app.post("/api/script-assets", dependencies=[Depends(verify_dashboard_token)])
async def create_script_asset(
    payload: ScriptAssetCreatePayload,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    """Uploads brand-new script source as a new Applivery Asset — does not
    touch the local Action Library; callers add a library entry separately
    (see /api/action-library) once they have the resulting Asset id."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing Applivery session — try refreshing the page and logging in again")
    if payload.platform not in ('windows', 'macos'):
        raise HTTPException(status_code=400, detail="platform must be 'windows' or 'macos'")
    if not payload.content.strip():
        raise HTTPException(status_code=400, detail="Script content cannot be empty")
    slug_key = x_workspace_slug or 'global'
    async with httpx.AsyncClient(timeout=30.0) as client:
        headers = {"Authorization": authorization}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        upload_base = org_base.replace("https://api.applivery.io", "https://upload.applivery.io")
        asset, error = await _create_script_asset(client, headers, upload_base, payload.name, payload.description, payload.content, payload.platform, payload.segmentId, payload.exposeToChildren)
    if error:
        raise HTTPException(status_code=502, detail=error)
    _record_audit_event(slug_key, category="workflow", action="script_asset_created", actor=dash.get('sub'),
                         target_type="script_asset", target_id=asset.get('id'), target_name=asset.get('name'),
                         message=f'Created script Asset "{asset.get("name")}" on Applivery ({payload.platform})')
    return asset

class ScriptAssetEditPayload(BaseModel):
    name: Optional[str] = None
    description: Optional[str] = None
    platform: str  # 'windows' | 'macos' — needed to pick the right file extension for the new upload
    content: str
    segmentId: Optional[int] = None  # None = inherit the segment the asset being edited is already in
    exposeToChildren: Optional[bool] = None  # None = inherit the asset's current setting

@app.put("/api/script-assets/{asset_id}", dependencies=[Depends(verify_dashboard_token)])
async def edit_script_asset(
    asset_id: str,
    payload: ScriptAssetEditPayload,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    """"Editing" an existing script Asset — Applivery has no content-replace
    endpoint, so this uploads the edited content as a new Asset (name gets a
    " vN" suffix) and repoints every local Action Library entry that
    referenced the old Asset id to the new one so workflow steps built on it
    keep working without edits. The OLD Asset is deliberately left in place,
    not deleted — matching Applivery's own console behavior when you edit a
    script there (it creates a new record rather than replacing in place),
    almost certainly because a Policy on Applivery's side can already
    reference the old Asset id directly and deleting it would silently break
    that assignment."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing Applivery session — try refreshing the page and logging in again")
    if payload.platform not in ('windows', 'macos'):
        raise HTTPException(status_code=400, detail="platform must be 'windows' or 'macos'")
    if not payload.content.strip():
        raise HTTPException(status_code=400, detail="Script content cannot be empty")
    slug_key = x_workspace_slug or 'global'
    async with httpx.AsyncClient(timeout=30.0) as client:
        headers = {"Authorization": authorization}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        upload_base = org_base.replace("https://api.applivery.io", "https://upload.applivery.io")

        current_name, current_description = payload.name, payload.description
        current_segment_id, current_expose = payload.segmentId, payload.exposeToChildren
        if current_name is None or current_description is None or current_segment_id is None or current_expose is None:
            try:
                get_res = await _applivery_call(client, 'GET', f"{org_base}/mdm/assets/{asset_id}", headers=headers)
                if get_res.status_code < 300:
                    current = get_res.json().get('data') or {}
                    current_name = current_name or current.get('name')
                    current_description = current_description if current_description is not None else current.get('description')
                    current_segment_id = current_segment_id if current_segment_id is not None else current.get('segmentId')
                    current_expose = current_expose if current_expose is not None else current.get('exposeToChildren')
            except Exception:
                pass
        current_name = current_name or 'script'
        new_name = _next_version_name(current_name)

        asset, error = await _create_script_asset(client, headers, upload_base, new_name, current_description or '', payload.content, payload.platform, current_segment_id, current_expose)
        if error:
            raise HTTPException(status_code=502, detail=error)

    library = _load_action_library(slug_key)
    repointed = []
    for entry in library:
        if entry.get('type') == 'script' and entry.get('assetId') == asset_id:
            entry['assetId'] = asset['id']
            entry['assetName'] = asset.get('name')
            entry['updatedAt'] = datetime.now(timezone.utc).isoformat()
            repointed.append(entry.get('id'))
    if repointed:
        _save_action_library(slug_key, library)

    _record_audit_event(slug_key, category="workflow", action="script_asset_edited", actor=dash.get('sub'),
                         target_type="script_asset", target_id=asset.get('id'), target_name=asset.get('name'),
                         message=f'Edited script "{current_name}" — saved as new Applivery Asset "{new_name}" (previous version "{current_name}" left in place on Applivery)' + (f'; {len(repointed)} library entr{"y" if len(repointed) == 1 else "ies"} repointed' if repointed else ''))
    return {"asset": asset, "repointedLibraryEntryIds": repointed}

# ── External Git script repos ──
# Lets an admin point the Script Library at any public GitHub repo of script
# files (Applivery's own https://github.com/applivery/applivery-mdm-scripts,
# or a private team collection) and browse/import from it, instead of
# manually downloading a file and re-uploading it through Applivery's own
# Dashboard. Uses GitHub's public Contents API (no auth required for public
# repos; an optional GITHUB_TOKEN env var raises the otherwise-low
# unauthenticated rate limit if configured). Imported files are uploaded to
# Applivery as real script Assets (via _create_script_asset, same as the
# in-app editor) and get a matching local Action Library entry, so they
# immediately show up as pickable "Run script" steps in the workflow builder.
SCRIPT_REPOS_DIR = os.path.join(DATA_DIR, "script_repos")
if not os.path.exists(SCRIPT_REPOS_DIR):
    os.makedirs(SCRIPT_REPOS_DIR)

GITHUB_TOKEN = os.environ.get("GITHUB_TOKEN")  # optional — raises the unauthenticated 60/hr rate limit if set
SCRIPT_REPO_EXTENSIONS = {
    "ps1": "windows", "bat": "windows", "cmd": "windows", "psm1": "windows",
    "sh": "macos", "command": "macos", "zsh": "macos", "bash": "macos",
}

def _script_repos_file(slug: str) -> str:
    slug_clean = re.sub(r'[^a-zA-Z0-9_-]', '_', slug or 'global')
    return os.path.join(SCRIPT_REPOS_DIR, f"{slug_clean}.json")

_register_legacy_json('script_repos', lambda slug, key: _script_repos_file(slug))

def _load_script_repos(slug: str) -> List[Dict[str, Any]]:
    return _store_load(slug, 'script_repos', list)

def _save_script_repos(slug: str, items: List[Dict[str, Any]]):
    _store_save(slug, 'script_repos', items)

class ScriptRepoPayload(BaseModel):
    name: str
    owner: str
    repo: str
    branch: Optional[str] = "main"
    path: Optional[str] = ""  # subdirectory to start browsing from, e.g. "macOS" or "scripts/windows"

@app.get("/api/script-repos", dependencies=[Depends(verify_dashboard_token)])
async def list_script_repos(x_workspace_slug: Optional[str] = Header(None)):
    return {"items": _load_script_repos(x_workspace_slug or 'global')}

@app.post("/api/script-repos", dependencies=[Depends(verify_dashboard_token)])
async def create_script_repo(payload: ScriptRepoPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    items = _load_script_repos(slug_key)
    entry = payload.dict()
    entry['id'] = str(uuid.uuid4())
    entry['createdAt'] = datetime.now(timezone.utc).isoformat()
    items.append(entry)
    _save_script_repos(slug_key, items)
    _record_audit_event(slug_key, category="workflow", action="script_repo_connected", actor=dash.get('sub'),
                         target_type="script_repo", target_id=entry['id'], target_name=entry.get('name'),
                         message=f'Connected script repo "{entry.get("name")}" ({entry.get("owner")}/{entry.get("repo")})')
    return entry

@app.delete("/api/script-repos/{repo_id}", dependencies=[Depends(verify_dashboard_token)])
async def delete_script_repo(repo_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    items = _load_script_repos(slug_key)
    remaining = [e for e in items if e.get('id') != repo_id]
    _save_script_repos(slug_key, remaining)
    return {"status": "ok"}

@app.get("/api/script-repos/{repo_id}/browse", dependencies=[Depends(verify_dashboard_token)])
async def browse_script_repo(repo_id: str, path: Optional[str] = None, x_workspace_slug: Optional[str] = Header(None)):
    """Lists one directory of a connected repo via GitHub's Contents API.
    `path` overrides the repo's configured starting path — used for
    navigating into subdirectories from the browse modal."""
    slug_key = x_workspace_slug or 'global'
    repo = next((r for r in _load_script_repos(slug_key) if r.get('id') == repo_id), None)
    if not repo:
        raise HTTPException(status_code=404, detail="Script repo not found")
    effective_path = path if path is not None else (repo.get('path') or '')
    gh_headers = {"Accept": "application/vnd.github+json"}
    if GITHUB_TOKEN:
        gh_headers["Authorization"] = f"Bearer {GITHUB_TOKEN}"
    url = f"https://api.github.com/repos/{repo['owner']}/{repo['repo']}/contents/{effective_path.lstrip('/')}"
    try:
        async with httpx.AsyncClient(timeout=20.0) as client:
            res = await client.get(url, headers=gh_headers, params={"ref": repo.get('branch') or 'main'})
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"GitHub request failed: {e}")
    if res.status_code == 404:
        raise HTTPException(status_code=404, detail=f"Path not found in {repo['owner']}/{repo['repo']}: '{effective_path}'")
    if res.status_code == 403:
        raise HTTPException(status_code=502, detail="GitHub rate-limited this request — try again in a bit, or set a GITHUB_TOKEN on the server for a higher limit.")
    if res.status_code >= 300:
        raise HTTPException(status_code=502, detail=f"GitHub returned {res.status_code}: {res.text[:200]}")
    raw = res.json()
    entries = raw if isinstance(raw, list) else [raw]
    items = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        name = e.get('name') or ''
        ext = name.rsplit('.', 1)[-1].lower() if '.' in name else ''
        items.append({
            "name": name, "path": e.get('path') or '', "type": e.get('type') or 'file',
            "downloadUrl": e.get('download_url'), "sizeBytes": e.get('size'),
            "importable": e.get('type') == 'file' and ext in SCRIPT_REPO_EXTENSIONS,
            "inferredPlatform": SCRIPT_REPO_EXTENSIONS.get(ext),
        })
    items.sort(key=lambda i: (i['type'] != 'dir', i['name'].lower()))
    return {"path": effective_path, "items": items}

class ScriptRepoImportPayload(BaseModel):
    repoId: str
    files: List[Dict[str, Any]]  # [{name, path, downloadUrl, inferredPlatform}]
    segmentId: Optional[int] = None

@app.post("/api/script-repos/import", dependencies=[Depends(verify_dashboard_token)])
async def import_from_script_repo(
    payload: ScriptRepoImportPayload,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    """For each selected repo file: downloads its raw content from GitHub,
    uploads it to Applivery as a new script Asset, and adds a matching local
    Action Library entry — so it's immediately usable from the workflow
    builder. Best-effort per file; one failure doesn't block the rest."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing Applivery session — try refreshing the page and logging in again")
    slug_key = x_workspace_slug or 'global'
    imported, failed = [], []
    async with httpx.AsyncClient(timeout=30.0) as client:
        headers = {"Authorization": authorization}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        upload_base = org_base.replace("https://api.applivery.io", "https://upload.applivery.io")
        library = _load_action_library(slug_key)
        now = datetime.now(timezone.utc).isoformat()
        for f in payload.files:
            name, download_url = f.get('name'), f.get('downloadUrl')
            platform = f.get('inferredPlatform')
            if not download_url:
                failed.append({"name": name, "error": "No downloadable content for this file"})
                continue
            if platform not in ('windows', 'macos'):
                failed.append({"name": name, "error": "Could not infer platform (.ps1/.bat/.cmd → Windows, .sh/.command → macOS) — skip and add manually"})
                continue
            try:
                content_res = await client.get(download_url, timeout=20.0)
                if content_res.status_code >= 300:
                    failed.append({"name": name, "error": f"Download failed ({content_res.status_code})"})
                    continue
                content_text = content_res.text
            except Exception as e:
                failed.append({"name": name, "error": f"Download failed: {e}"})
                continue

            display_name = name.rsplit('.', 1)[0] if name and '.' in name else (name or 'script')
            asset, error = await _create_script_asset(client, headers, upload_base, display_name, f"Imported from {payload.repoId}", content_text, platform, payload.segmentId)
            if error:
                failed.append({"name": name, "error": error})
                continue

            new_entry = {
                "id": str(uuid.uuid4()), "type": "script", "name": display_name, "description": f"Imported from Git repo",
                "platform": platform, "assetId": asset['id'], "assetName": asset.get('name') or display_name,
                "arguments": "", "scope": "machine", "createdAt": now, "updatedAt": now,
            }
            library.append(new_entry)
            imported.append(new_entry)

    if imported:
        _save_action_library(slug_key, library)
        _record_audit_event(slug_key, category="workflow", action="script_repo_import", actor=dash.get('sub'),
                             message=f'Imported {len(imported)} script{"s" if len(imported) != 1 else ""} from a Git repo into the Script & OMA-URI library'
                                     + (f'; {len(failed)} failed' if failed else ''))
    return {"imported": imported, "failed": failed}

# ── Script execution results → Audit Logs ──
# Applivery's agent reports script run outcomes back through a dedicated
# per-device "script logs" resource (confirmed via Applivery's OpenAPI
# schema — GET .../mdm/{windows|apple}/enterprise/devices/{id}/script-logs/
# summary, one row per script Asset ever run on that device, with rolling
# {success, error} counts and the timestamp of its last run; the same path
# with a real script-log id instead of "summary" returns one execution's
# full detail — status/summary/log/logError). There's no push/webhook for
# this, so every time MDM_ACTIONS['runScript'] dispatches a script (see
# _execute_mdm_action's runScript branch) we snapshot that script's current
# counts as a baseline and record a pending-confirmation entry here;
# script_log_reconciler_loop below polls until the counts move past that
# baseline, then writes the outcome (success/error, with as much of the
# agent's own log/logError text as we can fetch) to this workspace's Audit
# Log — so a script silently failing on a device is actually visible
# somewhere, instead of the workflow step just reporting "dispatched" and
# nobody ever finding out whether it actually ran cleanly.
SCRIPT_RUN_TRACKING_DIR = os.path.join(DATA_DIR, "script_run_tracking")
if not os.path.exists(SCRIPT_RUN_TRACKING_DIR):
    os.makedirs(SCRIPT_RUN_TRACKING_DIR)

SCRIPT_RUN_RECONCILE_TICK_SECONDS = 90
SCRIPT_RUN_MAX_ATTEMPTS = 60  # ~90 minutes at the tick above before we give up waiting on one dispatch

def _script_run_tracking_file(slug: str) -> str:
    slug_clean = re.sub(r'[^a-zA-Z0-9_-]', '_', slug or 'global')
    return os.path.join(SCRIPT_RUN_TRACKING_DIR, f"{slug_clean}.json")

_register_legacy_json('script_run_tracking', lambda slug, key: _script_run_tracking_file(slug))

def _load_script_run_tracking(slug: str) -> Dict[str, dict]:
    return _store_load(slug, 'script_run_tracking', dict)

def _save_script_run_tracking(slug: str, data: Dict[str, dict]):
    _store_save(slug, 'script_run_tracking', data)

async def _fetch_script_log_summary_entry(client: httpx.AsyncClient, headers: dict, org_base: str, platform_path: str, platform_device_id: str, asset_id: str) -> Optional[dict]:
    """One row from .../script-logs/summary matching this script Asset id on
    this device, or None if that script has never run there (yet) or the
    call fails — always treated as "no new information", never as an error,
    since this is called opportunistically from multiple places."""
    try:
        url = f"{org_base}/mdm/{platform_path}/enterprise/devices/{platform_device_id}/script-logs/summary"
        res = await _applivery_call(client, 'GET', url, headers=headers)
        if res.status_code >= 300:
            return None
        for item in (res.json().get('data') or []):
            if isinstance(item, dict) and ((item.get('mdmAsset') or {}).get('id')) == asset_id:
                return item
    except Exception as e:
        print(f"[script-log-summary] fetch failed: {e}")
    return None

async def _fetch_script_log_detail(client: httpx.AsyncClient, headers: dict, org_base: str, platform_path: str, platform_device_id: str, log_id: str) -> Optional[dict]:
    """Best-effort fetch of one execution's full record (status/summary/log/
    logError) by the id embedded in its summary row. Not confirmed whether
    that id is always resolvable this way (undocumented linkage) — callers
    must tolerate None and fall back to the summary counts alone."""
    if not log_id:
        return None
    try:
        url = f"{org_base}/mdm/{platform_path}/enterprise/devices/{platform_device_id}/script-logs/{log_id}"
        res = await _applivery_call(client, 'GET', url, headers=headers)
        if res.status_code >= 300:
            return None
        return res.json().get('data') or None
    except Exception as e:
        print(f"[script-log-detail] fetch failed: {e}")
        return None

async def script_log_reconciler_loop():
    """Polls Applivery's per-device script-logs/summary for every dispatch
    recorded by _execute_mdm_action's runScript branch, until the script's
    rolling success/error counts move past the baseline snapshotted at
    dispatch time — then writes the outcome to this workspace's Audit Log
    (category 'workflow', severity 'critical' on error so it's easy to spot
    among routine entries). Gives up after SCRIPT_RUN_MAX_ATTEMPTS and logs
    that as a lower-severity 'no confirmation received' entry instead of
    tracking a dispatch forever (e.g. a device that never checks in again)."""
    await asyncio.sleep(40)  # let the server finish initializing first
    while True:
        try:
            for slug_key in _automation_workspaces():
                tracking = _load_script_run_tracking(slug_key)
                if not tracking:
                    continue
                bearer = await _get_automation_bearer(slug_key)
                if not bearer:
                    continue

                headers = {"Authorization": bearer, "Content-Type": "application/json"}
                new_audit_events = []
                resolved_ids = []
                async with httpx.AsyncClient(timeout=20.0) as client:
                    org_base = await _resolve_org_base(client, headers, slug_key)
                    # Bounded per tick — script dispatches are rare (manual/
                    # workflow-triggered, not fleet-wide like app inventory),
                    # so this budget is generous relative to expected volume.
                    for tracking_id, rec in list(tracking.items())[:50]:
                        entry = await _fetch_script_log_summary_entry(client, headers, org_base, rec['platformPath'], rec['platformDeviceId'], rec['assetId'])
                        if entry is None:
                            rec['attempts'] = rec.get('attempts', 0) + 1
                            if rec['attempts'] >= SCRIPT_RUN_MAX_ATTEMPTS:
                                unconfirmed_msg = f"No execution result received for script '{rec.get('scriptName')}' on {rec.get('deviceName') or 'device'} after {SCRIPT_RUN_MAX_ATTEMPTS} checks — device may be offline or the script asset may have been removed."
                                new_audit_events.append({
                                    "id": str(uuid.uuid4()), "timestamp": datetime.now(timezone.utc).isoformat(),
                                    "category": "workflow", "action": "script_execution_unconfirmed", "severity": "warning",
                                    "actor": "system", "targetType": "device", "targetId": rec.get('deviceId'), "targetName": rec.get('deviceName'),
                                    "message": unconfirmed_msg,
                                })
                                resolved_ids.append(tracking_id)
                                if rec.get('workflowResume'):
                                    await _resume_workflow_pending_step_by_token(rec['workflowResume'], False, unconfirmed_msg)
                            continue

                        # Counts are monotonically-increasing rolling totals per
                        # (device, script) — total_now > total_baseline by itself
                        # already proves at least one NEW execution happened
                        # since we snapshotted the baseline right before dispatch,
                        # with no need to also compare lastDate (whose format
                        # isn't guaranteed to match our own isoformat() string
                        # closely enough for a safe lexicographic comparison).
                        total_now = (entry.get('status') or {}).get('success', 0) + (entry.get('status') or {}).get('error', 0)
                        total_baseline = rec.get('baselineSuccess', 0) + rec.get('baselineError', 0)
                        if total_now <= total_baseline:
                            rec['attempts'] = rec.get('attempts', 0) + 1
                            if rec['attempts'] >= SCRIPT_RUN_MAX_ATTEMPTS:
                                unconfirmed_msg = f"No execution result received for script '{rec.get('scriptName')}' on {rec.get('deviceName') or 'device'} after {SCRIPT_RUN_MAX_ATTEMPTS} checks — device may be offline or the script asset may have been removed."
                                new_audit_events.append({
                                    "id": str(uuid.uuid4()), "timestamp": datetime.now(timezone.utc).isoformat(),
                                    "category": "workflow", "action": "script_execution_unconfirmed", "severity": "warning",
                                    "actor": "system", "targetType": "device", "targetId": rec.get('deviceId'), "targetName": rec.get('deviceName'),
                                    "message": unconfirmed_msg,
                                })
                                resolved_ids.append(tracking_id)
                                if rec.get('workflowResume'):
                                    await _resume_workflow_pending_step_by_token(rec['workflowResume'], False, unconfirmed_msg)
                            continue

                        delta_error = (entry.get('status') or {}).get('error', 0) - rec.get('baselineError', 0)
                        outcome_ok = delta_error <= 0

                        detail = await _fetch_script_log_detail(client, headers, org_base, rec['platformPath'], rec['platformDeviceId'], entry.get('id'))
                        excerpt = ''
                        if isinstance(detail, dict):
                            raw = (detail.get('logError') or detail.get('log') or detail.get('summary') or '').strip()
                            if raw:
                                excerpt = f" — {raw[:300]}"

                        script_name = rec.get('scriptName') or rec.get('assetId')
                        device_label = rec.get('deviceName') or 'device'
                        if outcome_ok:
                            message = f"Script '{script_name}' ran successfully on {device_label}."
                        else:
                            message = f"Script '{script_name}' FAILED on {device_label}{excerpt}"
                        new_audit_events.append({
                            "id": str(uuid.uuid4()), "timestamp": datetime.now(timezone.utc).isoformat(),
                            "category": "workflow", "action": "script_execution_succeeded" if outcome_ok else "script_execution_failed",
                            "severity": "info" if outcome_ok else "critical",
                            "actor": "system", "targetType": "device", "targetId": rec.get('deviceId'), "targetName": rec.get('deviceName'),
                            "message": message,
                        })
                        resolved_ids.append(tracking_id)
                        if rec.get('workflowResume'):
                            await _resume_workflow_pending_step_by_token(rec['workflowResume'], outcome_ok, message)

                if resolved_ids:
                    for tid in resolved_ids:
                        tracking.pop(tid, None)
                    _save_script_run_tracking(slug_key, tracking)
                elif tracking:
                    # attempts counters were bumped in place above
                    _save_script_run_tracking(slug_key, tracking)
                if new_audit_events:
                    _append_audit_events(slug_key, new_audit_events)
            _record_job_heartbeat('script_log_reconciler', 'ok')
        except Exception as e:
            print(f"[Script Log Reconciler] Error: {e}")
            _record_job_heartbeat('script_log_reconciler', 'error', str(e))
        await asyncio.sleep(SCRIPT_RUN_RECONCILE_TICK_SECONDS)

SEARCH_SOURCES_BY_PLATFORM = {
    'apple': ['apple_store'],
    'macos': ['apple_store', 'homebrew'],
    'windows': ['ms_store', 'winget'],
    'android': ['android_known'],
}

@app.get("/api/app-search", dependencies=[Depends(verify_dashboard_token)])
async def search_apps(
    platform: str, text: str, source: Optional[str] = None,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Live app-store search, keyed off `platform` (apple|macos|android|windows)
    and an explicit `source` (see SEARCH_SOURCES_BY_PLATFORM — e.g. macOS can
    search 'apple_store' or 'homebrew', Windows 'ms_store' or 'winget').
    Defaults to that platform's primary source if `source` is omitted.
    Requires >=2 chars (the frontend already gates this at 4, this is just a
    server-side sanity floor to avoid a giant unfiltered Homebrew scan etc.).
    Returns {"items": [...], "error": null | "message"} — `error` is set
    when the call itself failed, so the frontend can show *why* zero results
    came back instead of it looking like a genuine no-match."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing Applivery session — try refreshing the page and logging in again")
    text = (text or '').strip()
    if len(text) < 2:
        return {"items": [], "error": None}
    valid_sources = SEARCH_SOURCES_BY_PLATFORM.get(platform)
    if not valid_sources:
        raise HTTPException(status_code=400, detail=f"Unknown platform '{platform}'")
    source = source or valid_sources[0]
    if source not in valid_sources:
        raise HTTPException(status_code=400, detail=f"'{source}' isn't a valid source for {platform} — expected one of {valid_sources}")

    async with httpx.AsyncClient(timeout=20.0) as client:
        headers = {"Authorization": authorization, "Content-Type": "application/json"}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        if source == 'apple_store':
            items, error = await _search_apple_store(client, headers, org_base, text, platform)
        elif source == 'ms_store':
            items, error = await _search_ms_store(client, headers, org_base, text)
        elif source == 'winget':
            items, error = await _search_winget(text)
        elif source == 'homebrew':
            items, error = await _search_homebrew(text)
        elif source == 'android_known':
            items, error = await _search_android_known(client, headers, org_base, text)
        else:
            items, error = [], None
    return {"items": items, "error": error}

# ── Installed-app inventory: persistent store + rolling refresher ──
# The naive approach — fetch every scoped device's installed apps live,
# in-line, every time a policy is evaluated — doesn't scale: there's no bulk
# endpoint (confirmed against Applivery's own API docs — Apple/Android/AOSP/
# Windows all only expose a per-DEVICE applications endpoint, nothing that
# takes a device list) and no webhook fires on app install/uninstall either
# (Applivery's webhook events cover enrollment/certificate/inventory-item
# changes only). So compliance evaluation is fully decoupled from live
# Applivery calls for this feature:
#   - installed_apps_refresher_loop (below) is the ONLY thing that ever
#     calls the live per-device applications endpoint for fleet-wide
#     app-list compliance. It runs continuously in the background, refreshes
#     the stalest devices first, and persists results to
#     data/installed_apps/{slug}.json.
#   - _run_compliance_evaluation (and the compliance fields UI) only ever
#     reads that persisted store (_read_installed_apps_from_store) — a
#     no-network dict lookup — so evaluation stays instant regardless of
#     fleet size, and a slow/degraded Applivery API can never block or delay
#     a compliance run.
#   - The refresher paces itself under its own hourly sub-budget (see
#     _installed_apps_claim_batch), separate from — but still inside —
#     the shared global limiter (_applivery_call/_applivery_rate_limiter),
#     so a large app-list-scoped fleet can't crowd out every other feature's
#     Applivery traffic.
#   - Single-device on-demand paths (workflow monitor/recovery gate checks,
#     via _maybe_prefetch_installed_apps) still do a live fetch when needed —
#     that's inherently bounded (one device, tied to an active workflow run)
#     and writes through to the same persistent store.
INSTALLED_APPS_DIR = os.path.join(DATA_DIR, "installed_apps")
if not os.path.exists(INSTALLED_APPS_DIR):
    os.makedirs(INSTALLED_APPS_DIR)

def _installed_apps_file(slug: str) -> str:
    safe_slug = re.sub(r'[^a-zA-Z0-9_-]', '_', slug or 'global')
    return os.path.join(INSTALLED_APPS_DIR, f"{safe_slug}.json")

_register_legacy_json('installed_apps', lambda slug, key: _installed_apps_file(slug))

def _load_installed_apps_store(slug: str) -> Dict[str, dict]:
    """{device_id: {identifiers: [...], platform, fetchedAt, error}}."""
    return _store_load(slug, 'installed_apps', dict)

def _save_installed_apps_store(slug: str, store: Dict[str, dict]):
    _store_save(slug, 'installed_apps', store)

def _read_installed_apps_from_store(slug_key: str, device_id: str) -> Optional[set]:
    """Pure, no-network read — this is ALL _run_compliance_evaluation ever
    touches for app-list conditions. Returns None if this device has never
    been synced yet (distinct from an empty set, which means it WAS synced
    and none of its reported identifiers matter here) — see
    _evaluate_condition, which treats None as 'no data yet' rather than
    assuming every required app is missing."""
    entry = _load_installed_apps_store(slug_key).get(str(device_id))
    if entry is None:
        return None
    return set(entry.get('identifiers') or [])

def _app_list_scoped_device_ids(devices: List[dict], policies: List[dict]) -> set:
    """Every device covered by at least one enabled policy that has a
    requiredAppList/disallowedAppList condition — scoped to that policy's
    targetDeviceAudienceId if set, otherwise every device. Shared by
    _run_compliance_evaluation, installed_apps_refresher_loop, and the
    status/manual-refresh endpoints so 'which devices need app data' is
    computed identically everywhere."""
    ids: set = set()
    for policy in policies:
        if not policy.get('enabled', True):
            continue
        if not any(c.get('field') in ('requiredAppList', 'disallowedAppList') for c in (policy.get('conditions') or [])):
            continue
        target_audience_id = policy.get('targetDeviceAudienceId')
        if target_audience_id:
            ids.update(d['id'] for d in devices if any(str(a.get('id')) == str(target_audience_id) for a in (d.get('deviceAudiences') or [])))
        else:
            ids.update(d['id'] for d in devices)
    return ids

async def _fetch_and_store_installed_apps(client: httpx.AsyncClient, headers: dict, org_base: str, device: dict, slug_key: str, store: Optional[Dict[str, dict]] = None) -> set:
    """The only place that actually calls Applivery's per-device applications
    endpoint. Writes the result into `store` (an in-memory dict the caller
    owns and saves once per batch — see installed_apps_refresher_loop /
    _manual_refresh_installed_apps); if no `store` is passed, loads/updates/
    saves the on-disk store itself for that one device, so on-demand
    single-device callers (_get_device_installed_apps) keep the persistent
    record current too without the caller having to manage the file."""
    device_id = device.get('id')
    platform_path = _platform_path_segment(device.get('platform'))
    owns_store = store is None
    if owns_store:
        store = _load_installed_apps_store(slug_key)
    if not device_id or platform_path not in ('apple', 'android', 'aosp', 'windows'):
        return set()

    url = f"{org_base}/mdm/{platform_path}/enterprise/devices/{device_id}/applications"
    identifiers: set = set()
    error = None
    # Apple only: HasUpdateAvailable is a genuine native signal straight from
    # this same response (App Store/VPP metadata Applivery already surfaces
    # per app) — no separate catalog or extra API call needed, unlike
    # Windows/Android where Applivery reports installed versions but never
    # computes "is this outdated". Captured here, piggybacking on the exact
    # same fetch this function already makes for app-list compliance, so
    # Apple pending-app-update coverage costs zero extra Applivery requests
    # for any device already being synced for that purpose.
    apple_pending_apps: List[dict] = []
    apple_total_apps = 0
    # Per-app installed VERSION, for every app on every platform where a
    # version is available — feeds the Vulnerability Service integration's
    # app-level CVE matching (needs {identifier, version, platform}), which
    # the plain `identifiers` set below can't supply. Confirmed field names
    # per Applivery's own API docs: Android/AOSP device-applications
    # (packageName/versionName/displayName/state — same schema both
    # platforms). Windows' per-device applications response is NOT
    # documented in Applivery's OpenAPI spec beyond a generic object (their
    # docs prose says "including version details" but doesn't name the
    # field), so several plausible keys are checked defensively, same
    # posture as the identifier fallback chain already below.
    versioned_apps: List[dict] = []
    try:
        res = await _applivery_call(client, 'GET', url, headers=headers)
        if res.status_code < 300:
            for item in extract_items(res.json()):
                if not isinstance(item, dict):
                    continue
                if platform_path == 'apple':
                    ident = item.get('Identifier') or item.get('identifier')
                    apple_total_apps += 1
                    version = item.get('ShortVersion') or item.get('Version')
                    if item.get('HasUpdateAvailable'):
                        apple_pending_apps.append({
                            "identifier": ident,
                            "name": item.get('Name'),
                            "installedVersion": version,
                            "build": item.get('Version'),
                            "isBetaApp": bool(item.get('BetaApp')),
                        })
                    if ident and version:
                        versioned_apps.append({"identifier": str(ident).lower(), "name": item.get('Name'), "version": str(version)})
                elif platform_path in ('android', 'aosp'):
                    ident = item.get('packageName')
                    # REMOVED apps are still reported by this endpoint for a
                    # while after uninstall — exclude them from the
                    # versioned list (a stale version shouldn't be flagged
                    # vulnerable) but keep them in `identifiers` unchanged,
                    # matching this function's pre-existing behavior there.
                    if item.get('state') != 'REMOVED':
                        version = item.get('versionName')
                        if ident and version:
                            versioned_apps.append({"identifier": str(ident).lower(), "name": item.get('displayName'), "version": str(version)})
                else:  # windows — undocumented per-device schema, defensive extraction (see comment above)
                    ident = item.get('packageName') or item.get('Identifier') or item.get('id') or item.get('productId') or item.get('name')
                    version = item.get('Version') or item.get('version') or item.get('DisplayVersion') or item.get('AppVersion') or item.get('versionName')
                    if ident and version:
                        versioned_apps.append({"identifier": str(ident).lower(), "name": item.get('DisplayName') or item.get('displayName') or item.get('Name'), "version": str(version)})
                if ident:
                    identifiers.add(str(ident).lower())
        else:
            error = f"Applivery returned {res.status_code}"
    except Exception as e:
        error = str(e)
        print(f"[Installed Apps] Fetch failed for device {device_id} ({slug_key}): {e}")

    store[str(device_id)] = {
        "identifiers": sorted(identifiers),
        "apps": sorted(versioned_apps, key=lambda a: (a.get('identifier') or '')) if error is None else (store.get(str(device_id)) or {}).get('apps') or [],
        "platform": platform_path,
        "fetchedAt": datetime.now(timezone.utc).isoformat(),
        "error": error,
        "source": "server_fetch",
        "appleAppUpdates": ({
            "pendingCount": len(apple_pending_apps),
            "totalApps": apple_total_apps,
            "pendingApps": sorted(apple_pending_apps, key=lambda a: (a.get('name') or '').lower()),
        } if platform_path == 'apple' and error is None else (store.get(str(device_id)) or {}).get('appleAppUpdates') if platform_path == 'apple' else None),
    }
    if owns_store:
        _save_installed_apps_store(slug_key, store)
    return identifiers

INSTALLED_APPS_LIVE_DEDUPE_TTL_SECONDS = 300  # 5 min — just to stop a single workflow run's monitor/recovery steps hammering the same device's apps endpoint back-to-back; the persistent store above is the real cache.

async def _get_device_installed_apps(client: httpx.AsyncClient, headers: dict, org_base: str, device: dict, slug_key: str) -> set:
    """On-demand single-device fetch for workflow monitor/recovery gate
    checks (see _maybe_prefetch_installed_apps below) — inherently a one-off
    tied to an active workflow run on one specific device, so a live call
    here is fine and doesn't need the fleet-wide pacing
    installed_apps_refresher_loop applies. Writes through to the persistent
    store via _fetch_and_store_installed_apps so the fleet-wide picture
    benefits too, not just this one workflow run."""
    device_id = device.get('id')
    if not device_id:
        return set()
    cache_source = f"installed_apps_live:{device_id}"
    cached = _live_cache_get(slug_key, cache_source)
    if cached is not None:
        return set(cached)
    identifiers = await _fetch_and_store_installed_apps(client, headers, org_base, device, slug_key)
    _live_cache_set(slug_key, cache_source, list(identifiers), ttl_seconds=INSTALLED_APPS_LIVE_DEDUPE_TTL_SECONDS)
    return identifiers

async def _maybe_prefetch_installed_apps(client: httpx.AsyncClient, headers: dict, org_base: str, device_full: dict, policy: dict, slug_key: str):
    """Attaches device_full['installedApps'] only if `policy` actually has a
    requiredAppList/disallowedAppList condition — every single-device
    _policy_violated call site (monitor step, recovery gate checks) routes
    through this so the live per-device apps call never happens unless it's
    actually needed."""
    if any(c.get('field') in ('requiredAppList', 'disallowedAppList') for c in (policy.get('conditions') or [])):
        device_full['installedApps'] = await _get_device_installed_apps(client, headers, org_base, device_full, slug_key)

# ── Refresh sub-budget ──
# A dedicated, smaller slice of the shared Applivery budget (see
# _applivery_rate_limiter) set aside specifically for the installed-app
# refresher loop. Without this, a large app-list-scoped fleet could crowd
# out every other feature's Applivery traffic — device-list refreshes,
# workflow runs, location sync, other workspaces — since they all draw from
# the same global ceiling. This is a soft, best-effort pacing layer on top
# of (not a replacement for) the hard global limiter inside _applivery_call.
INSTALLED_APPS_REFRESH_DEFAULT_BUDGET_PER_HOUR = 2000
INSTALLED_APPS_REFRESH_MIN_BUDGET_PER_HOUR = 200
INSTALLED_APPS_REFRESH_MAX_BUDGET_PER_HOUR = 4000  # half the shared 8,000/hour ceiling — always leave room for everything else
INSTALLED_APPS_REFRESH_TICK_SECONDS = 30
INSTALLED_APPS_REFRESH_CONCURRENCY = 8

def _clamp_installed_apps_budget(value: Optional[int]) -> int:
    if not value:
        return INSTALLED_APPS_REFRESH_DEFAULT_BUDGET_PER_HOUR
    return max(INSTALLED_APPS_REFRESH_MIN_BUDGET_PER_HOUR, min(INSTALLED_APPS_REFRESH_MAX_BUDGET_PER_HOUR, int(value)))

def _installed_apps_budget_for(slug_key: str) -> int:
    """Reads StatePayload.installedAppsRefreshBudgetPerHour for this
    workspace (re-read every tick — one small JSON file — so a change made
    from the App Lists status panel takes effect within one tick, no
    restart needed), falling back to the default."""
    try:
        state = _load_state(slug_key)
        return _clamp_installed_apps_budget(state.get("installedAppsRefreshBudgetPerHour"))
    except Exception:
        pass
    return INSTALLED_APPS_REFRESH_DEFAULT_BUDGET_PER_HOUR

_installed_apps_budget_tokens: Dict[str, dict] = {}  # slug -> {"tokens": float, "last": monotonic}

def _installed_apps_claim_batch(slug_key: str, max_want: int) -> int:
    """How many devices the refresher may fetch for this workspace right
    now, given its configured hourly budget — a simple leaky bucket refilled
    based on elapsed wall-clock time since the last claim."""
    budget_per_hour = _installed_apps_budget_for(slug_key)
    now = time.monotonic()
    state = _installed_apps_budget_tokens.setdefault(slug_key, {"tokens": min(50.0, float(budget_per_hour)), "last": now})
    elapsed = now - state["last"]
    state["tokens"] = min(float(budget_per_hour), state["tokens"] + elapsed * (budget_per_hour / 3600.0))
    state["last"] = now
    take = min(max_want, int(state["tokens"]))
    state["tokens"] -= take
    return max(0, take)

async def _refresh_installed_apps_batch(target_ids: List[str], devices_by_id: Dict[str, dict], authorization: str, x_workspace_slug: str, slug_key: str, store: Dict[str, dict]):
    """Bounded-concurrency fetch of exactly `target_ids` — shared by the
    background rolling refresher and the manual 'Refresh now' endpoint.
    Mutates `store` in place; caller is responsible for saving it."""
    async with httpx.AsyncClient(timeout=30.0) as client:
        headers = {"Authorization": authorization, "Content-Type": "application/json"}
        org_base = await _resolve_org_base(client, headers, x_workspace_slug)
        sem = asyncio.Semaphore(INSTALLED_APPS_REFRESH_CONCURRENCY)

        async def refresh_one(device_id):
            device = devices_by_id.get(device_id)
            if device is None:
                return
            async with sem:
                await _fetch_and_store_installed_apps(client, headers, org_base, device, slug_key, store)

        await asyncio.gather(*(refresh_one(did) for did in target_ids))

async def _manual_refresh_installed_apps(target_ids: List[str], devices: List[dict], authorization: str, x_workspace_slug: str, slug_key: str):
    devices_by_id = {d['id']: d for d in devices}
    store = _load_installed_apps_store(slug_key)
    await _refresh_installed_apps_batch(target_ids, devices_by_id, authorization, x_workspace_slug, slug_key, store)
    _save_installed_apps_store(slug_key, store)
    print(f"[Installed Apps] Manual refresh: {len(target_ids)} device(s) in {slug_key}")

def _apple_app_update_device_ids(devices: List[dict]) -> set:
    """Every Apple/macOS device — pending-app-update coverage (HasUpdateAvailable,
    see _fetch_and_store_installed_apps) is a fleet-wide SOAR visibility
    signal, not gated behind whether any Compliance Policy happens to use an
    app-list condition, unlike _app_list_scoped_device_ids above. Shared by
    installed_apps_refresher_loop and the /api/apple-app-updates/* endpoints
    so 'which devices are in scope' is computed identically everywhere."""
    return {d['id'] for d in devices if _platform_path_segment(d.get('platform')) == 'apple'}

async def installed_apps_refresher_loop():
    """Background rolling refresher — the only thing that pulls fresh
    per-device app inventories from Applivery, for two independent purposes
    that happen to share one store/one API call per device:
      1. Fleet-wide app-list compliance (requiredAppList/disallowedAppList
         conditions) — scoped to devices covered by an enabled policy using
         those conditions (_app_list_scoped_device_ids), zero cost otherwise.
      2. Apple pending-app-update visibility (HasUpdateAvailable) — every
         Apple/macOS device, unconditionally, since this is core SOAR
         visibility (same philosophy as OS Update Intelligence), not an
         opt-in compliance feature.
    Every tick, for every workspace with an automation credential:
      a. Compute the union of both scopes above.
      b. Sort it stalest-first (never-fetched devices first, then oldest
         fetchedAt) so a large fleet gets full coverage over time instead of
         the same devices winning every tick.
      c. Claim as many devices as this workspace's sub-budget allows right
         now (_installed_apps_claim_batch) and fetch them with bounded
         concurrency, persisting after each batch.
    """
    await asyncio.sleep(25)  # let the server finish initializing first
    while True:
        try:
            for slug_key in _automation_workspaces():
                policies = [p for p in _load_compliance_policies(slug_key) if p.get('enabled', True)]
                app_list_active = any(any(c.get('field') in ('requiredAppList', 'disallowedAppList') for c in (p.get('conditions') or [])) for p in policies)

                bearer = await _get_automation_bearer(slug_key)
                if not bearer:
                    continue

                devices_resp = await get_devices_full(refresh=False, authorization=bearer, x_workspace_slug=slug_key)
                devices = devices_resp.get('items', [])

                # Migrate any self-reports that arrived before their device
                # was known (see /api/device-data/report-apps) — cheap, and
                # means a device that self-reports right after enrollment
                # doesn't wait for a live fetch it doesn't need.
                reconciled = _reconcile_pending_app_reports(slug_key, devices)
                if reconciled:
                    print(f"[Installed Apps Refresher] {slug_key}: reconciled {reconciled} pending self-report(s)")

                target_ids = _apple_app_update_device_ids(devices)
                if app_list_active:
                    target_ids |= _app_list_scoped_device_ids(devices, policies)
                if not target_ids:
                    continue

                store = _load_installed_apps_store(slug_key)
                ordered = sorted(target_ids, key=lambda did: (store.get(did) or {}).get('fetchedAt') or '')  # '' sorts before any ISO date — never-fetched goes first

                batch_size = _installed_apps_claim_batch(slug_key, len(ordered))
                if batch_size <= 0:
                    continue
                batch = ordered[:batch_size]

                devices_by_id = {d['id']: d for d in devices}
                await _refresh_installed_apps_batch(batch, devices_by_id, bearer, slug_key, slug_key, store)
                _save_installed_apps_store(slug_key, store)
                print(f"[Installed Apps Refresher] {slug_key}: refreshed {len(batch)}/{len(ordered)} target device(s)")
            _record_job_heartbeat('installed_apps_refresher', 'ok')
        except Exception as e:
            print(f"[Installed Apps Refresher] Error: {e}")
            _record_job_heartbeat('installed_apps_refresher', 'error', str(e))
        await asyncio.sleep(INSTALLED_APPS_REFRESH_TICK_SECONDS)

@app.get("/api/app-lists/installed-apps-status", dependencies=[Depends(verify_dashboard_token)])
async def get_installed_apps_status(
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Coverage/staleness snapshot for the installed-app inventory refresher
    (installed_apps_refresher_loop) — lets an admin see whether app-list
    compliance conditions actually have data to evaluate against, and how
    long a full refresh cycle takes given the current fleet size and budget,
    instead of guessing from server logs."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    slug_key = x_workspace_slug or 'global'
    policies = [p for p in _load_compliance_policies(slug_key) if p.get('enabled', True)]
    devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
    devices = devices_resp.get('items', [])
    target_ids = _app_list_scoped_device_ids(devices, policies)
    store = _load_installed_apps_store(slug_key)
    now = datetime.now(timezone.utc)

    ages_minutes = []
    never_synced = 0
    error_count = 0
    self_reported_count = 0
    for did in target_ids:
        entry = store.get(str(did))
        if not entry or not entry.get('fetchedAt'):
            never_synced += 1
            continue
        if entry.get('error'):
            error_count += 1
        if entry.get('source') == 'self_reported':
            self_reported_count += 1
        try:
            fetched_at = datetime.fromisoformat(entry['fetchedAt'])
            ages_minutes.append((now - fetched_at).total_seconds() / 60.0)
        except Exception:
            never_synced += 1

    # Self-reporting devices don't draw from the sub-budget at all — they're
    # written directly by /api/device-data/report-apps, not fetched by this
    # loop — so the cycle-time estimate should only account for devices this
    # loop still has to fetch itself.
    devices_needing_live_fetch = max(0, len(target_ids) - self_reported_count)
    budget = _installed_apps_budget_for(slug_key)
    estimated_full_cycle_hours = round(devices_needing_live_fetch / budget, 1) if budget and devices_needing_live_fetch else 0
    ages_minutes.sort()

    return {
        "targetDeviceCount": len(target_ids),
        "syncedCount": len(ages_minutes),
        "neverSyncedCount": never_synced,
        "errorCount": error_count,
        "selfReportedCount": self_reported_count,
        "oldestSyncAgeMinutes": round(ages_minutes[-1], 1) if ages_minutes else None,
        "medianSyncAgeMinutes": round(ages_minutes[len(ages_minutes) // 2], 1) if ages_minutes else None,
        "refreshBudgetPerHour": budget,
        "refreshBudgetMin": INSTALLED_APPS_REFRESH_MIN_BUDGET_PER_HOUR,
        "refreshBudgetMax": INSTALLED_APPS_REFRESH_MAX_BUDGET_PER_HOUR,
        "estimatedFullCycleHours": estimated_full_cycle_hours,
    }

class InstalledAppsBudgetPayload(BaseModel):
    budgetPerHour: int

@app.put("/api/app-lists/installed-apps-budget", dependencies=[Depends(verify_dashboard_token)])
async def set_installed_apps_budget(payload: InstalledAppsBudgetPayload, x_workspace_slug: Optional[str] = Header(None)):
    """Thin wrapper around StatePayload.installedAppsRefreshBudgetPerHour so
    the App Lists status panel can adjust the refresh sub-budget directly,
    without routing an admin through the general Settings modal for one
    number."""
    existing = _load_state(x_workspace_slug)
    existing['installedAppsRefreshBudgetPerHour'] = _clamp_installed_apps_budget(payload.budgetPerHour)
    _save_state(x_workspace_slug, existing)
    return {"installedAppsRefreshBudgetPerHour": existing['installedAppsRefreshBudgetPerHour']}

@app.post("/api/app-lists/refresh-installed-apps", dependencies=[Depends(verify_dashboard_token)])
async def refresh_installed_apps_now(
    background_tasks: BackgroundTasks,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Manual, immediate refresh — bypasses the rolling stalest-first
    schedule for cases like 'I just built this App List, don't make me wait
    for the next tick.' Still bounded by concurrency and the hard global
    Applivery rate limiter (_applivery_call); it just isn't paced by the
    sub-budget the background loop uses, since this is an explicit one-off
    admin action rather than continuous background traffic."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    slug_key = x_workspace_slug or 'global'
    policies = [p for p in _load_compliance_policies(slug_key) if p.get('enabled', True)]
    devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
    devices = devices_resp.get('items', [])
    target_ids = _app_list_scoped_device_ids(devices, policies)
    if not target_ids:
        return {"queued": 0}
    background_tasks.add_task(_manual_refresh_installed_apps, list(target_ids), devices, authorization, x_workspace_slug, slug_key)
    return {"queued": len(target_ids)}

# ── Apple pending app updates (HasUpdateAvailable) ──
# Reads the SAME per-workspace installed-apps store as the app-list
# compliance feature above (installed_apps_refresher_loop now covers every
# Apple/macOS device unconditionally, see _apple_app_update_device_ids) —
# this is just a dedicated coverage/status view and manual-refresh trigger
# scoped to that Apple-only subset, since its target set and what "coverage"
# means differ from the app-list-scoped view.
@app.get("/api/apple-app-updates/status", dependencies=[Depends(verify_dashboard_token)])
async def get_apple_app_updates_status(
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Coverage/staleness snapshot for Apple pending-app-update tracking —
    mirrors get_installed_apps_status but scoped to every Apple/macOS
    device (not just app-list-policy-covered ones), plus a fleet-wide
    pending-updates rollup (devices affected, most common outdated apps)."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    slug_key = x_workspace_slug or 'global'
    devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
    devices = devices_resp.get('items', [])
    target_ids = _apple_app_update_device_ids(devices)
    store = _load_installed_apps_store(slug_key)
    now = datetime.now(timezone.utc)

    ages_minutes = []
    never_synced = 0
    error_count = 0
    devices_with_pending = 0
    total_pending_app_instances = 0
    app_frequency: Dict[str, int] = {}
    for did in target_ids:
        entry = store.get(str(did))
        if not entry or not entry.get('fetchedAt'):
            never_synced += 1
            continue
        if entry.get('error'):
            error_count += 1
        try:
            fetched_at = datetime.fromisoformat(entry['fetchedAt'])
            ages_minutes.append((now - fetched_at).total_seconds() / 60.0)
        except Exception:
            pass
        app_updates = entry.get('appleAppUpdates') or {}
        pending_apps = app_updates.get('pendingApps') or []
        if pending_apps:
            devices_with_pending += 1
            total_pending_app_instances += len(pending_apps)
            for a in pending_apps:
                name = a.get('name') or a.get('identifier') or 'Unknown app'
                app_frequency[name] = app_frequency.get(name, 0) + 1

    budget = _installed_apps_budget_for(slug_key)
    estimated_full_cycle_hours = round(len(target_ids) / budget, 1) if budget and target_ids else 0
    ages_minutes.sort()
    top_apps = sorted(app_frequency.items(), key=lambda kv: kv[1], reverse=True)[:15]

    return {
        "targetDeviceCount": len(target_ids),
        "syncedCount": len(ages_minutes),
        "neverSyncedCount": never_synced,
        "errorCount": error_count,
        "devicesWithPendingUpdates": devices_with_pending,
        "totalPendingAppInstances": total_pending_app_instances,
        "topPendingApps": [{"name": k, "deviceCount": v} for k, v in top_apps],
        "oldestSyncAgeMinutes": round(ages_minutes[-1], 1) if ages_minutes else None,
        "medianSyncAgeMinutes": round(ages_minutes[len(ages_minutes) // 2], 1) if ages_minutes else None,
        "refreshBudgetPerHour": budget,
        "estimatedFullCycleHours": estimated_full_cycle_hours,
    }

@app.post("/api/apple-app-updates/refresh", dependencies=[Depends(verify_dashboard_token)])
async def refresh_apple_app_updates_now(
    background_tasks: BackgroundTasks,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Manual, immediate refresh of every Apple/macOS device's app inventory
    (and thus its HasUpdateAvailable signal) — same bypass-the-schedule
    reasoning as refresh_installed_apps_now above, just scoped to the
    Apple-only target set."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    slug_key = x_workspace_slug or 'global'
    devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
    devices = devices_resp.get('items', [])
    target_ids = _apple_app_update_device_ids(devices)
    if not target_ids:
        return {"queued": 0}
    background_tasks.add_task(_manual_refresh_installed_apps, list(target_ids), devices, authorization, x_workspace_slug, slug_key)
    return {"queued": len(target_ids)}

# ── Self-reported installed-app inventory ──
# Reuses the SAME device-report secret/endpoint pattern as the general
# attribute-reporting webhook (see "DEVICE PUSH DATA" section above) — same
# trust model (an unattended script on an end-user device), same
# workspace-scoped secret an admin already generates from Settings. The
# difference is what happens to the payload: instead of merging into
# device.selfReported for display, a report here is matched to an Applivery
# device id (by serial number, against the cached device list — never a
# live Applivery call from a webhook handler, same principle as the
# existing push-data endpoint) and written STRAIGHT into the same
# persistent installed-apps store the refresher loop reads/writes. A
# self-reporting device effectively refreshes itself for free —
# installed_apps_refresher_loop's stalest-first sort naturally deprioritizes
# it (fresh fetchedAt), so its share of the sub-budget goes to devices that
# can't self-report yet. See the macOS/Windows scripts offered from
# Settings > Device Data Webhook > App Inventory Reporting.
PENDING_APP_REPORTS_DIR = os.path.join(DATA_DIR, "pending_app_reports")
if not os.path.exists(PENDING_APP_REPORTS_DIR):
    os.makedirs(PENDING_APP_REPORTS_DIR)

def _pending_app_reports_file(slug: str) -> str:
    return os.path.join(PENDING_APP_REPORTS_DIR, f"{_slug_clean(slug)}.json")

_register_legacy_json('pending_app_reports', lambda slug, key: _pending_app_reports_file(slug))

def _load_pending_app_reports(slug: str) -> Dict[str, dict]:
    """Keyed by serial number — reports that arrived before Applivery (and
    therefore our device-list cache) knew about that device yet. Reconciled
    opportunistically by installed_apps_refresher_loop each tick."""
    return _store_load(slug, 'pending_app_reports', dict)

def _save_pending_app_reports(slug: str, data: Dict[str, dict]):
    _store_save(slug, 'pending_app_reports', data)

def _reconcile_pending_app_reports(slug_key: str, devices: List[dict]) -> int:
    """Matches any buffered self-reports (see _load_pending_app_reports)
    against a fresh device list and migrates matches into the real
    installed-apps store. Called once per workspace per refresher tick —
    cheap (dict lookups only) and self-limiting (returns immediately if
    nothing's pending)."""
    pending = _load_pending_app_reports(slug_key)
    if not pending:
        return 0
    by_serial = {d.get('serialNumber'): d for d in devices if d.get('serialNumber')}
    resolved = 0
    store = None
    for serial, record in list(pending.items()):
        device = by_serial.get(serial)
        if not device:
            continue
        if store is None:
            store = _load_installed_apps_store(slug_key)
        store[str(device['id'])] = record
        del pending[serial]
        resolved += 1
    if resolved:
        _save_installed_apps_store(slug_key, store)
        _save_pending_app_reports(slug_key, pending)
    return resolved

class DeviceAppReportPayload(BaseModel):
    platform: str  # "windows" | "macos"
    serialNumber: str
    apps: List[Dict[str, Any]] = []  # [{"identifier": "com.apple.Safari", "name": "Safari", "version": "17.4"}, ...] — version is optional (older script builds omit it)
    agentVersion: Optional[str] = None
    reportedAt: Optional[str] = None  # the device's own clock, informational only

@app.post("/api/device-data/report-apps", dependencies=[Depends(verify_device_report_secret)])
async def report_device_apps(payload: DeviceAppReportPayload, x_workspace_slug: Optional[str] = Header(None)):
    """The webhook a device's scheduled installed-apps script POSTs to (see
    the macOS/Windows scripts offered from Settings > Device Data Webhook >
    App Inventory Reporting). Not dashboard-token protected — same
    unattended-script trust model as /api/device-data/report — auth is
    entirely the X-Device-Report-Secret + X-Workspace-Slug header pair
    (verify_device_report_secret)."""
    slug_key = x_workspace_slug or 'global'
    if not payload.serialNumber or not payload.serialNumber.strip():
        raise HTTPException(status_code=400, detail="serialNumber is required")
    identifiers = sorted({str(a.get('identifier')).lower() for a in payload.apps if isinstance(a, dict) and a.get('identifier')})
    # Same {identifier, name, version} shape _fetch_and_store_installed_apps
    # writes for the MDM-sourced path, so downstream consumers (Vulnerability
    # Service's app matching, in particular — this is what makes Windows
    # app-version coverage reliable instead of depending on the undocumented
    # MDM applications endpoint schema) read one uniform "apps" list
    # regardless of whether the data came from Applivery's MDM API or this
    # self-report script. Apps reported without a version (older script
    # builds, or an app winget/registry couldn't resolve a version for)
    # still count toward `identifiers` for App List compliance, they just
    # don't contribute a versioned_apps entry — same "don't guess past what's
    # confirmed" rule as everywhere else.
    versioned_apps = sorted(
        (
            {"identifier": str(a.get('identifier')).lower(), "name": a.get('name'), "version": str(a.get('version'))}
            for a in payload.apps
            if isinstance(a, dict) and a.get('identifier') and a.get('version')
        ),
        key=lambda a: a['identifier'],
    )
    now_iso = datetime.now(timezone.utc).isoformat()
    platform_path = _platform_path_segment(payload.platform) or payload.platform

    # Resolve serial → Applivery device id against whatever's already
    # cached — deliberately never a live Applivery call from a webhook
    # handler (same principle as /api/device-data/report above).
    device_id = None
    device_name = payload.serialNumber
    cached_devices = _live_cache_get(slug_key, DEVICES_CACHE_SOURCE)
    if cached_devices:
        match = next((d for d in cached_devices.get('items', []) if d.get('serialNumber') == payload.serialNumber), None)
        if match:
            device_id = match.get('id')
            device_name = match.get('displayName') or device_name

    record = {
        "identifiers": identifiers,
        "apps": versioned_apps,
        "platform": platform_path,
        "fetchedAt": now_iso,
        "error": None,
        "source": "self_reported",
        "agentVersion": payload.agentVersion,
        "clientReportedAt": payload.reportedAt,
    }

    if device_id:
        store = _load_installed_apps_store(slug_key)
        store[str(device_id)] = record
        _save_installed_apps_store(slug_key, store)
        matched = True
        # In case an earlier report for this same serial got buffered as
        # pending before the device was known — clear it now.
        pending = _load_pending_app_reports(slug_key)
        if payload.serialNumber in pending:
            del pending[payload.serialNumber]
            _save_pending_app_reports(slug_key, pending)
    else:
        # Not in our cached device list yet (not enrolled, or the 15-min
        # device cache just hasn't refreshed) — buffer by serial number;
        # installed_apps_refresher_loop reconciles these on its next tick
        # (see _reconcile_pending_app_reports).
        pending = _load_pending_app_reports(slug_key)
        pending[payload.serialNumber] = record
        _save_pending_app_reports(slug_key, pending)
        matched = False

    _record_audit_event(
        slug_key, category="system", action="device_apps_received", actor="device",
        target_type="device", target_id=payload.serialNumber, target_name=device_name,
        message=f'Received self-reported app inventory from "{device_name}" ({payload.platform}) — {len(identifiers)} app(s)' + ('' if matched else ' (buffered — device not yet matched to Applivery)'),
    )
    return {"status": "ok", "serialNumber": payload.serialNumber, "appsReported": len(identifiers), "matched": matched}

