_COMPLIANCE_TEMPLATES_BY_ID = {t["id"]: t for t in COMPLIANCE_POLICY_TEMPLATES}

@app.get("/api/compliance/templates", dependencies=[Depends(verify_dashboard_token)])
async def get_compliance_policy_templates(framework: Optional[str] = None):
    """Curated per-framework Compliance Policy starting points — see
    COMPLIANCE_POLICY_TEMPLATES above for the full scope notes. Returns the
    framework catalog (for grouping/filter UI) alongside the templates
    themselves; ?framework=iso27001 (etc.) narrows to one framework."""
    templates = COMPLIANCE_POLICY_TEMPLATES
    if framework:
        if framework not in _COMPLIANCE_FRAMEWORKS_BY_KEY:
            raise HTTPException(status_code=404, detail=f"Unknown framework '{framework}'")
        templates = [t for t in templates if t["framework"] == framework]
    return {"frameworks": COMPLIANCE_FRAMEWORKS, "items": templates}

@app.get("/api/compliance/smart-attribute-names", dependencies=[Depends(verify_dashboard_token)])
async def get_smart_attribute_names(
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
):
    """Distinct Smart Attribute names seen across the current device fleet —
    powers an autocomplete in the policy builder instead of free-typing a name
    that may not match what a script/3rd party actually wrote."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
    names = set()
    for d in devices_resp.get('items', []):
        for attr in (d.get('smartAttributes') or []):
            if attr.get('name'):
                names.add(attr['name'])
    return {"items": sorted(names)}

@app.get("/api/compliance/self-reported-attribute-names", dependencies=[Depends(verify_dashboard_token)])
async def get_self_reported_attribute_names(
    x_workspace_slug: Optional[str] = Header(None),
    platform: Optional[str] = None,
):
    """Distinct attribute names ever pushed to the device-data webhook for
    this workspace (see 'DEVICE PUSH DATA' section) — same autocomplete
    role as get_smart_attribute_names above, but for self-reported data
    instead of Applivery Smart Attributes. Reads straight from the local
    push-data store rather than a live Applivery call, so this is cheap and
    always current the moment a device reports a field the policy builder
    hasn't seen before — no admin action needed for it to show up.
    ?platform=windows|macos narrows to attribute names actually seen from
    that platform; omitted returns the union across both."""
    slug_key = x_workspace_slug or 'global'
    store = _load_device_pushdata(slug_key)
    names = set()
    for entry in store.values():
        if platform and entry.get('platform') != platform:
            continue
        names.update((entry.get('attributes') or {}).keys())
    return {"items": sorted(names)}

def _version_tuple(v: str) -> tuple:
    parts = re.split(r'[.\-_]', str(v or '0'))
    out = []
    for p in parts:
        try:
            out.append(int(p))
        except ValueError:
            out.append(0)
    return tuple(out)

def _get_by_path(obj: Any, path: str) -> Any:
    """Dot-path lookup into a nested dict, e.g. 'mdmUser.email' or 'identifiers.udid'."""
    cur = obj
    for part in (path or '').split('.'):
        if isinstance(cur, dict):
            cur = cur.get(part)
        else:
            return None
    return cur

def _compare_scalar(actual: Any, operator: str, target: Any) -> bool:
    """Generic equals/notEquals/contains/greaterThan/lessThan/exists/missing
    comparison, used by the string-type catalog fields plus the smartAttribute
    and customField escape hatches. Numeric operators fall back to string
    comparison if either side isn't numeric."""
    if operator == 'exists':
        return actual is not None and actual != ''
    if operator == 'missing':
        return actual is None or actual == ''
    if operator == 'contains':
        return str(target or '').lower() in str(actual if actual is not None else '').lower()
    if operator in ('greaterThan', 'lessThan'):
        try:
            actual_num, target_num = float(actual), float(target)
            return actual_num > target_num if operator == 'greaterThan' else actual_num < target_num
        except (TypeError, ValueError):
            return False
    if operator == 'notEquals':
        return str(actual if actual is not None else '') != str(target if target is not None else '')
    return str(actual if actual is not None else '') == str(target if target is not None else '')

def _evaluate_condition(device: dict, condition: dict, slug: Optional[str] = None) -> bool:
    """Returns True if `device` matches this single condition (i.e. the condition
    is 'triggered' for this device). `slug` is only needed by the App List
    conditions (requiredAppList/disallowedAppList), which have to resolve the
    List id into its member apps' identifiers — everything else ignores it."""
    field = condition.get('field')
    operator = condition.get('operator')
    value = condition.get('value')

    try:
        if field in ('manufacturer', 'model', 'serialNumber', 'imei'):
            return _compare_scalar(device.get(field), operator, value)

        if field == 'mdmUserEmail':
            return _compare_scalar((device.get('mdmUser') or {}).get('email'), operator, value)

        if field == 'totalStorageGb' or field == 'ramGb':
            return _compare_scalar(device.get(field), operator, value)

        if field in ('riskScore', 'riskTier'):
            # Populated onto every device dict by _compute_device_risk, called
            # once per device inside get_devices_full — see that function for
            # the scoring formula.
            return _compare_scalar(device.get(field), operator, value)

        if field == 'osUpdatePendingCount':
            # osUpdateStatus is Windows-only (None on every other platform,
            # and None if the catalog hasn't confirmed a build match yet —
            # see _compute_windows_pending_updates) — a None pendingCount
            # here correctly never satisfies greaterThan/lessThan below.
            status = device.get('osUpdateStatus')
            actual = status.get('pendingCount') if status else None
            if actual is None:
                return False
            target = float(value or 0)
            return actual < target if operator == 'lessThan' else actual > target

        if field == 'osUpdateExploitedPending':
            status = device.get('osUpdateStatus')
            actual = any(kb.get('exploited') for kb in ((status or {}).get('pendingKbs') or []))
            return actual == bool(value)

        if field == 'vulnPendingCveCount':
            # vulnStatus is Apple/Android-only (see get_devices_full) and None
            # when the EUVD catalog hasn't confirmed a fixed-version match.
            status = device.get('vulnStatus')
            actual = status.get('pendingCount') if status and status.get('confidence') != 'unknown' else None
            if actual is None:
                return False
            target = float(value or 0)
            return actual < target if operator == 'lessThan' else actual > target

        if field == 'vulnExploitedPending':
            status = device.get('vulnStatus')
            actual = any(c.get('exploited') for c in ((status or {}).get('pendingCves') or []))
            return actual == bool(value)

        if field == 'vulnServiceCriticalHighCount':
            # vulnServiceStatus is None on workspaces without the integration
            # enabled, and {checked: False, ...} on enabled workspaces before
            # a device's first refresh — both correctly never satisfy this.
            status = device.get('vulnServiceStatus')
            if not status or not status.get('checked'):
                return False
            counts = status.get('counts') or {}
            actual = (counts.get('CRITICAL') or 0) + (counts.get('HIGH') or 0)
            target = float(value or 0)
            return actual < target if operator == 'lessThan' else actual > target

        if field == 'vulnServiceHasKev':
            status = device.get('vulnServiceStatus')
            actual = bool(status.get('hasKev')) if status and status.get('checked') else False
            return actual == bool(value)

        if field == 'vulnServiceChecked':
            status = device.get('vulnServiceStatus')
            actual = bool(status and status.get('checked'))
            return actual == bool(value)

        if field == 'osEol':
            # osLifecycleStatus.isEol is a tri-state (True/False/None —
            # None meaning "version train not found in the endoflife.date
            # catalog yet"). bool(None) == False, so an unconfirmed device
            # never satisfies `osEol equals true` — it doesn't get treated
            # as compliant either, it's just not a match for THIS condition,
            # same reasoning as every other confidence-gated field here.
            status = device.get('osLifecycleStatus')
            actual = bool(status.get('isEol')) if status else False
            return actual == bool(value)

        if field == 'appleAppUpdatesPending':
            # appleAppUpdateStatus is Apple/macOS-only and None until this
            # device's first HasUpdateAvailable sync (see
            # installed_apps_refresher_loop) — same never-guess pattern.
            status = device.get('appleAppUpdateStatus')
            actual = status.get('pendingCount') if status else None
            if actual is None:
                return False
            target = float(value or 0)
            return actual < target if operator == 'lessThan' else actual > target

        if field == 'smartAttribute':
            # value: {"name": "AttributeName", "compareValue": "..."}
            target = value or {}
            attrs = {a.get('name'): a.get('value') for a in (device.get('smartAttributes') or [])}
            attr_name = target.get('name')
            if operator == 'exists':
                return attr_name in attrs
            if operator == 'missing':
                return attr_name not in attrs
            if attr_name not in attrs:
                return False
            return _compare_scalar(attrs[attr_name], operator, target.get('compareValue'))

        if field == 'customField':
            # value: {"path": "identifiers.udid", "compareValue": "..."}
            target = value or {}
            actual = _get_by_path(device, target.get('path') or '')
            return _compare_scalar(actual, operator, target.get('compareValue'))

        if field == 'selfReportedAttribute':
            # value: {"name": "diskEncryptionEnabled", "compareValue": "..."} —
            # same shape as smartAttribute, reading device.selfReported.attributes
            # (populated by the push webhook, see _normalize_device_full) instead
            # of Applivery's own smartAttributes.
            target = value or {}
            attrs = ((device.get('selfReported') or {}).get('attributes')) or {}
            attr_name = target.get('name')
            if operator == 'exists':
                return attr_name in attrs
            if operator == 'missing':
                return attr_name not in attrs
            if attr_name not in attrs:
                return False
            return _compare_scalar(attrs[attr_name], operator, target.get('compareValue'))

        if field == 'hasSelfReported':
            return bool(device.get('selfReported')) == bool(value)

        if field == 'selfReportDaysAgo':
            self_reported = device.get('selfReported')
            last_reported = self_reported.get('lastReportedAt') if self_reported else None
            if not last_reported:
                # Never reported at all (no agent, or agent never checked in) —
                # treated as "infinitely stale": triggers greaterThan (catches
                # missing-agent devices too), never triggers lessThan.
                return operator == 'greaterThan'
            try:
                dt = datetime.fromisoformat(str(last_reported).replace('Z', '+00:00'))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
            except Exception:
                return operator == 'greaterThan'
            days = (datetime.now(timezone.utc) - dt).total_seconds() / 86400.0
            target = float(value or 0)
            return days > target if operator == 'greaterThan' else days < target

        if field in ('requiredAppList', 'disallowedAppList'):
            # value: App List id. installedApps is attached onto the device
            # dict by the caller from the persistent installed-apps store
            # (_read_installed_apps_from_store) — see _run_compliance_evaluation
            # and _maybe_prefetch_installed_apps — only for policies that
            # actually have one of these conditions, never unconditionally.
            if not slug or not value:
                return False
            app_list = next((l for l in _load_app_lists(slug) if l.get('id') == value), None)
            if not app_list:
                return False
            catalog_by_id = {e['id']: e for e in _load_app_catalog(slug)}
            list_identifiers = {catalog_by_id[aid]['identifier'].lower() for aid in (app_list.get('appIds') or []) if aid in catalog_by_id and catalog_by_id[aid].get('identifier')}
            if not list_identifiers:
                return False
            installed = device.get('installedApps')
            if installed is None:
                # Never synced yet by installed_apps_refresher_loop — don't
                # flag a violation off the absence of data; wait for the
                # first real inventory instead of treating "unknown" as
                # "every required app is missing."
                return False
            if field == 'requiredAppList':
                return not list_identifiers.issubset(installed)  # violated if ANY required app is missing
            return bool(list_identifiers & installed)  # disallowedAppList — violated if ANY listed app IS present

        if field == 'isCompliant':
            return bool(device.get('isCompliant')) == bool(value)

        if field == 'platform':
            actual = device.get('platform')
            return (actual == value) if operator == 'equals' else (actual != value)

        if field == 'osVersion':
            actual = _version_tuple(device.get('osVersion'))
            target = _version_tuple(value)
            if operator == 'lessThan':
                return actual < target
            if operator == 'greaterThan':
                return actual > target
            return actual == target

        if field == 'lastSeenDaysAgo':
            last_seen = device.get('lastSeen')
            if not last_seen:
                return False
            try:
                dt = datetime.fromisoformat(str(last_seen).replace('Z', '+00:00'))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
            except Exception:
                return False
            days = (datetime.now(timezone.utc) - dt).total_seconds() / 86400.0
            target = float(value or 0)
            return days > target if operator == 'greaterThan' else days < target

        if field == 'daysSinceEnrollment':
            # value: {"amount": number, "unit": "minutes"|"hours"|"days"} —
            # same amount/unit convention as the Wait step, for consistency.
            enrolled_at = device.get('enrolledAt')
            if not enrolled_at:
                return False
            try:
                dt = datetime.fromisoformat(str(enrolled_at).replace('Z', '+00:00'))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
            except Exception:
                return False
            elapsed_seconds = (datetime.now(timezone.utc) - dt).total_seconds()
            target = value or {}
            seconds_per_unit = {'minutes': 60, 'hours': 3600, 'days': 86400}
            try:
                target_seconds = float(target.get('amount') or 0) * seconds_per_unit.get(target.get('unit') or 'days', 86400)
            except (TypeError, ValueError, AttributeError):
                return False
            return elapsed_seconds > target_seconds if operator == 'greaterThan' else elapsed_seconds < target_seconds

        if field == 'battery':
            actual = device.get('battery')
            if actual is None:
                return False
            target = float(value or 0)
            return actual < target if operator == 'lessThan' else actual > target

        if field == 'availableStorageGb':
            actual = device.get('availableStorageGb')
            if actual is None:
                return False
            target = float(value or 0)
            return actual < target if operator == 'lessThan' else actual > target

        if field == 'segmentId':
            actual = str(device.get('segmentId') or '')
            target = str(value or '')
            return (actual == target) if operator == 'equals' else (actual != target)

        if field == 'tags':
            tags = device.get('tags') or []
            present = value in tags
            return present if operator == 'includes' else (not present)

        if field == 'state':
            actual = device.get('state')
            return (actual == value) if operator == 'equals' else (actual != value)

        if field == 'deviceAudienceId':
            # Device Audiences (Applivery's dynamic, cross-platform device
            # grouping feature — tags/serial numbers/employee assignment
            # selectors) — membership is precomputed onto the device record
            # as `deviceAudiences` (see _fetch_device_audience_membership_map),
            # not queried live here.
            audience_ids = {str(a.get('id')) for a in (device.get('deviceAudiences') or [])}
            is_member = str(value or '') in audience_ids
            return is_member if operator == 'includes' else not is_member

        if field == 'missingPolicyId':
            # value: {"policyId": ..., "platform": ...} — platform-scoped, so devices
            # on a different platform simply don't apply to this condition.
            target = value or {}
            if target.get('platform') and device.get('platform') != target.get('platform'):
                return False
            active_ids = {p.get('id') for p in (device.get('activePolicies') or [])}
            return target.get('policyId') not in active_ids

    except Exception:
        return False

    return False

def _policy_violated(device: dict, policy: dict, slug: Optional[str] = None) -> List[dict]:
    """Returns the list of matched (triggered) conditions if the policy is
    violated for this device, per its conditionLogic ('any' or 'all'); empty
    list means not violated. `slug` is forwarded to _evaluate_condition for
    App List conditions — see there."""
    conditions = policy.get('conditions') or []
    if not conditions:
        return []
    matched = [c for c in conditions if _evaluate_condition(device, c, slug)]
    logic = policy.get('conditionLogic', 'any')
    if logic == 'all':
        return matched if len(matched) == len(conditions) else []
    return matched  # 'any' — non-empty match list already means violated

# ── Storage ──
# _slug_clean is now defined once, near the top of the file (see "STORAGE
# (SQLite-backed generic store)") — every *_file(slug) path helper below
# still exists (now used only to resolve where a workspace's LEGACY JSON
# file lives, for the one-time SQLite import) and calls that shared version.

