# Widget/report source keys → framework key, for the per-framework
# Compliance reports (see COMPLIANCE_FRAMEWORKS / COMPLIANCE_POLICY_
# TEMPLATES and the "2.55 Compliance Framework reports" block in
# get_widget_data). 'compliance_framework_coverage' is handled separately
# there (it spans all frameworks at once) but is included here too so a
# single membership check (`source in _COMPLIANCE_FRAMEWORK_WIDGET_SOURCES`)
# covers every source this feature adds.
_COMPLIANCE_FRAMEWORK_WIDGET_SOURCES = {
    'compliance_framework_coverage': None,
    'iso27001_compliance_status': 'iso27001',
    'ens_compliance_status': 'ens',
    'nis2_compliance_status': 'nis2',
}

def _compliance_framework_rows(slug: str, framework_key: str) -> tuple:
    """Per-control status for one framework: for every COMPLIANCE_POLICY_
    TEMPLATES entry in that framework, find live policies tagged with a
    matching (framework, controlRef) pair (see CompliancePolicyPayload.
    framework/controlRef) and report whether the control has any policy at
    all ('configured'), whether at least one of those is enabled
    ('enabled' — a disabled policy doesn't actually enforce anything), and
    how many devices are currently violating it. A control with zero
    matching policies still appears with violatingDeviceCount=0 rather than
    being omitted — the report's job is as much to surface gaps as to show
    what's covered. Returns (rows, all_violating_device_ids) — the caller
    decides whether it needs the per-control breakdown, the deduplicated
    fleet-wide violator count, or both (a device violating two controls of
    the same framework must only count once in a framework-wide total)."""
    templates = [t for t in COMPLIANCE_POLICY_TEMPLATES if t["framework"] == framework_key]
    policies = _load_compliance_policies(slug)
    state = _load_compliance_state(slug)
    rows = []
    all_violating_ids = set()
    for t in templates:
        matching = [p for p in policies if p.get("framework") == framework_key and p.get("controlRef") == t["controlRef"]]
        enabled_matching = [p for p in matching if p.get("enabled", True)]
        violating_ids = set()
        for p in enabled_matching:
            pid = p.get("id")
            for key in state.keys():
                if key.startswith(f"{pid}:"):
                    violating_ids.add(key.split(":", 1)[1])
        all_violating_ids |= violating_ids
        rows.append({
            "templateId": t["id"], "controlRef": t["controlRef"], "title": t["title"], "severity": t["severity"],
            "configured": bool(matching), "enabled": bool(enabled_matching),
            "policyIds": [p.get("id") for p in matching],
            "violatingDeviceCount": len(violating_ids),
        })
    return rows, all_violating_ids

# ── Pydantic models ──

class ConditionRule(BaseModel):
    field: str
    operator: str
    value: Any = None

def _resolve_autorun_batch_cap(policy: dict) -> Optional[int]:
    """Resolves CompliancePolicyPayload.autoRunBatchCap for enforcement in
    _run_compliance_evaluation. `.get(..., 15)` — not `.get(...) or 15` — so
    a genuinely-absent key (a policy saved before this field existed)
    defaults to 15, while an explicitly-stored None (opted into "no limit"
    via the Policy Builder's own toggle) is preserved rather than coerced
    back to 15 by `or`'s falsy handling. A stored 0/negative isn't trusted
    as meaning "no limit" either (not reachable via the UI, but not assumed
    safe from a direct API caller) — it falls back to the same default."""
    raw = policy.get('autoRunBatchCap', 15)
    if raw is None:
        return None
    return raw if raw > 0 else 15

def _workflow_has_destructive_step(workflow: Optional[dict]) -> bool:
    """True if any mdm_action step in this workflow is flagged destructive
    in MDM_ACTIONS (wipe, unenroll, disable, clear app data, etc.) — used to
    gate autoRun behind an explicit acknowledgment (see
    CompliancePolicyPayload.autoRunDestructiveAck) so a policy can't fire an
    irreversible action against real devices unattended without someone
    having consciously opted into that."""
    if not workflow:
        return False
    for step in workflow.get('steps') or []:
        if step.get('type') == 'mdm_action':
            action_key = (step.get('config') or {}).get('action')
            if MDM_ACTIONS.get(action_key, {}).get('destructive'):
                return True
    return False

class CompliancePolicyPayload(BaseModel):
    name: str
    description: Optional[str] = ""
    enabled: bool = True
    autoRun: bool = False  # off = violations go to the review queue; on = workflow fires immediately
    # Carried onto every Case this policy opens (see _upsert_case_for_violation)
    # — purely an analyst-triage aid, has no effect on evaluation or autoRun.
    severity: str = "medium"  # "low" | "medium" | "high" | "critical"
    conditionLogic: str = "any"  # "any" | "all"
    conditions: List[ConditionRule] = []
    workflowId: Optional[str] = None
    # Applied to the device as an Applivery Tag the moment this policy is
    # newly violated, removed the moment it recovers — see
    # _apply_compliance_tag. Tags are the only per-device attribute
    # confirmed writable via Applivery's API for this purpose (their native
    # Compliance Status flag is server-computed from Applivery's own
    # Policies with no documented write endpoint; Smart Attributes only
    # expose an API for editing an attribute's org-wide definition, not a
    # per-device value). Leave blank to disable tagging for this policy.
    # Give each policy its own distinct tag — reusing the same tag string
    # across policies means recovering from ONE of them removes a tag that
    # another still-violated policy also relies on.
    nonComplianceTag: Optional[str] = None
    # Alternative/complementary marker: attach an existing Smart Attribute
    # (admin creates it once in Applivery) to the device while this policy is
    # violated, detach it on recovery — see _apply_compliance_smart_attribute
    # for exactly what this can and can't do. Independent of nonComplianceTag;
    # a policy can use either, both, or neither.
    nonComplianceSmartAttributeId: Optional[str] = None
    # Case Management integration (see _upsert_case_for_violation_inmem /
    # _mark_case_recovered_inmem). Both default to preserve this app's
    # original behavior for policies created before Cases existed.
    #   openCaseOnViolation: opens (or reuses/reopens) a Case the moment this
    #     policy is newly violated, same as every policy did before this
    #     field existed. Turn off for noisy/low-value policies you don't
    #     want cluttering the Cases queue — violations/tags/workflow firing
    #     are completely unaffected either way.
    #   autoResolveCaseOnRecovery: when the device stops violating, flips the
    #     linked Case straight to "resolved" instead of just leaving a
    #     timeline note on it. Off by default — an analyst confirming the
    #     fix themselves before closing is the safer default for anything
    #     that isn't trivially self-healing; policies covering flaky/
    #     transient conditions are the best fit for turning this on.
    openCaseOnViolation: bool = True
    autoResolveCaseOnRecovery: bool = False
    # MITRE ATT&CK Enterprise technique IDs this policy corresponds to (see
    # MITRE_TECHNIQUES / GET /api/mitre/techniques for the catalog) — e.g. a
    # policy watching for a disabled firewall might tag T1562 (Impair
    # Defenses). Purely a classification aid: carried onto every Case this
    # policy opens (same "carried onto the Case" pattern as `severity`
    # above), has no effect on evaluation, autoRun, or Case-opening.
    mitreTechniques: List[str] = []
    # Set automatically when this policy is instantiated from a Compliance
    # Policy Template (see COMPLIANCE_POLICY_TEMPLATES / TemplateGallery.jsx)
    # — None for hand-built policies. Same "classification aid, no effect on
    # evaluation" spirit as mitreTechniques above. Powers the
    # framework-scoped widget/report sources (iso27001_compliance_status /
    # ens_compliance_status / nis2_compliance_status /
    # compliance_framework_coverage) that roll live policies up by which
    # framework control they enforce. An admin editing the policy afterward
    # (renaming it, tweaking conditions) keeps this tag unless they clear
    # it — intentional, since it's still the thing enforcing that control
    # even once it no longer matches the template verbatim.
    framework: Optional[str] = None
    controlRef: Optional[str] = None
    # Which devices this policy is even evaluated against. Blank/None = every
    # device in the fleet (original, backward-compatible behavior). Set to a
    # Device Audience id to scope evaluation to just that audience's current
    # members — membership is resolved fresh each run via each device's
    # `deviceAudiences` (see _fetch_device_audience_membership_map), so it
    # stays current as the audience's dynamic selectors change.
    targetDeviceAudienceId: Optional[str] = None
    # How often the background scheduler automatically re-evaluates THIS
    # policy. None = use the org-wide default (COMPLIANCE_DEFAULT_EVAL_
    # INTERVAL_MINUTES). Clamped to [COMPLIANCE_MIN_EVAL_INTERVAL_MINUTES,
    # COMPLIANCE_MAX_EVAL_INTERVAL_MINUTES] on save — floor protects the
    # Applivery API (device state doesn't change fast enough to justify
    # checking more often, and it sets how fine-grained the scheduler's own
    # polling has to be), ceiling keeps a policy meaningfully "automated"
    # rather than effectively dormant. Manual "Evaluate now" always checks
    # every enabled policy immediately, ignoring this.
    evaluationIntervalMinutes: Optional[int] = None
    # Safety cap — the max number of devices this policy's autoRun will fire
    # its workflow against in a single evaluation pass. Additional violators
    # found in that same pass are queued for manual review instead of firing
    # unattended (status "autorun_capped" on the violation record). This
    # exists because autoRun otherwise fires once per violating device with
    # no limit — a bad condition, a stale Applivery sync, or a whole Device
    # Audience flipping non-compliant at once could otherwise unattended-fire
    # a destructive workflow against far more devices than anyone intended in
    # one shot. Sized well above ordinary single/few-device drift, well below
    # "the whole fleet at once". A human reviewing the queue can always
    # approve the rest manually.
    #
    # None is an explicit, deliberate "no limit" — an admin who genuinely
    # wants every violating device fired against in one pass (e.g. a
    # well-tested, non-destructive notify-only workflow, or a fleet small
    # enough that a cap is pure friction) can opt into that per policy. This
    # is opt-in per policy rather than a global setting on purpose — the
    # same "admin decides, one policy at a time" model as
    # autoRunDestructiveAck below, so removing the cap on one policy can't
    # silently remove it everywhere. Only reachable via an explicit "No
    # limit" control in the UI (never the bare number field itself) —
    # 0/negative is NOT treated as unlimited, since that'd be the least
    # intuitive possible reading of "0" for anyone calling the API
    # directly; 0/negative/missing all just fall back to the 15 default,
    # same as before this field became optional.
    autoRunBatchCap: Optional[int] = 15
    # Required explicit acknowledgment to save autoRun=True when the linked
    # workflow contains a destructive MDM action (see
    # _workflow_has_destructive_step / MDM_ACTIONS[...]['destructive']) —
    # enforced at save time in create/update_compliance_policy. Without this,
    # a policy could be configured to unattended-wipe/unenroll/disable
    # devices with the same one-line toggle as a harmless "send a Slack
    # notification" workflow. Irrelevant (and harmless to leave False) for
    # non-destructive workflows or when autoRun is off.
    autoRunDestructiveAck: bool = False
    # Severity-tiered workflow branching — closes the "one workflow per
    # policy, no branching" gap. `workflowId` above always stays the
    # default/gentle response; a policy's own `severity` field is static
    # (set once by whoever creates the policy), so it can't be what
    # branching keys off. What DOES genuinely vary per violating device is
    # its own risk tier (already computed by _compute_device_risk —
    # low/medium/high/critical), so that's the signal used here: the same
    # compliance issue on an already-high-risk device gets escalated
    # straight to a tougher workflow (e.g. quarantine/restrict) instead of
    # the same gentle notify every other violator gets. Only takes effect
    # when autoRun is on AND escalatedWorkflowId is set; leave unset to keep
    # today's "always the one workflow" behavior.
    escalatedWorkflowId: Optional[str] = None
    escalatedWorkflowMinRiskTier: str = "high"  # "low" | "medium" | "high" | "critical" — device's own riskTier at/above which escalatedWorkflowId fires instead of workflowId

# Ranks low/medium/high/critical for both a device's own riskTier
# (_compute_device_risk) and Case severity — shared here since escalation
# above compares a policy's configured threshold against a device's live
# riskTier using this same ordering.
RISK_TIER_RANK = {"low": 0, "medium": 1, "high": 2, "critical": 3}

# Bounds for CompliancePolicyPayload.evaluationIntervalMinutes.
COMPLIANCE_MIN_EVAL_INTERVAL_MINUTES = 60
COMPLIANCE_MAX_EVAL_INTERVAL_MINUTES = 1440  # 24 hours
COMPLIANCE_DEFAULT_EVAL_INTERVAL_MINUTES = 60  # applied when a policy doesn't set its own interval

def _clamp_eval_interval(minutes: Optional[int]) -> Optional[int]:
    """None passes through unchanged (means "use the org default" — resolved
    at evaluation time, not baked in here, so lowering the org default later
    doesn't require re-saving every policy). Any explicit value gets clamped
    into bounds."""
    if minutes is None:
        return None
    return max(COMPLIANCE_MIN_EVAL_INTERVAL_MINUTES, min(COMPLIANCE_MAX_EVAL_INTERVAL_MINUTES, int(minutes)))

# ── CRUD ──

@app.get("/api/compliance/policies", dependencies=[Depends(verify_dashboard_token)])
async def list_compliance_policies(x_workspace_slug: Optional[str] = Header(None)):
    return {"items": _load_compliance_policies(x_workspace_slug or 'global')}

@app.post("/api/compliance/policies", dependencies=[Depends(verify_dashboard_token)])
async def create_compliance_policy(
    payload: CompliancePolicyPayload,
    background_tasks: BackgroundTasks,
    x_workspace_slug: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    slug_key = x_workspace_slug or 'global'
    policies = _load_compliance_policies(slug_key)

    if payload.autoRun and (payload.workflowId or payload.escalatedWorkflowId):
        all_workflows = _load_workflows(slug_key)
        for wf_id in (payload.workflowId, payload.escalatedWorkflowId):
            if not wf_id:
                continue
            linked_workflow = next((w for w in all_workflows if w.get('id') == wf_id), None)
            if _workflow_has_destructive_step(linked_workflow) and not payload.autoRunDestructiveAck:
                raise HTTPException(
                    status_code=400,
                    detail=f'Workflow "{linked_workflow.get("name")}" contains a destructive action (wipe, unenroll, disable, etc.) — enabling autoRun with it requires explicit acknowledgment.',
                )

    now = datetime.now(timezone.utc).isoformat()
    new_policy = payload.dict()
    new_policy['evaluationIntervalMinutes'] = _clamp_eval_interval(payload.evaluationIntervalMinutes)
    new_policy['id'] = str(uuid.uuid4())
    new_policy['createdAt'] = now
    new_policy['updatedAt'] = now
    new_policy['lastEvaluatedAt'] = None  # scheduler-managed; not part of the request payload
    # autoRun circuit breaker state — see _autorun_circuit_breaker_check.
    # Always starts closed on a brand-new policy.
    new_policy['autoRunTripped'] = False
    new_policy['autoRunTrippedAt'] = None
    new_policy['autoRunTrippedReason'] = None
    policies.append(new_policy)
    _save_compliance_policies(slug_key, policies)
    _record_audit_event(slug_key, category="policy", action="policy_created", actor=dash.get('sub'),
                         target_type="policy", target_id=new_policy['id'], target_name=new_policy.get('name'),
                         message=f'Compliance policy "{new_policy.get("name")}" created')

    # Check the new policy against the fleet right away, in the background,
    # instead of waiting on compliance_scheduler_loop's next tick — that
    # loop only runs at all if AUTOMATION_ORG_SLUG/AUTOMATION_API_TOKEN are
    # configured, so without this a freshly created policy could otherwise
    # sit unevaluated indefinitely. Uses the creating admin's own session
    # token, same as "Evaluate now", so it works regardless.
    if new_policy.get('enabled', True) and authorization:
        background_tasks.add_task(_run_compliance_evaluation, authorization, x_workspace_slug, [new_policy['id']], dash.get('sub'))

    return new_policy

@app.put("/api/compliance/policies/{policy_id}", dependencies=[Depends(verify_dashboard_token)])
async def update_compliance_policy(
    policy_id: str,
    payload: CompliancePolicyPayload,
    background_tasks: BackgroundTasks,
    x_workspace_slug: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    slug_key = x_workspace_slug or 'global'
    policies = _load_compliance_policies(slug_key)
    idx = next((i for i, p in enumerate(policies) if p.get('id') == policy_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Compliance policy not found")

    if payload.autoRun and (payload.workflowId or payload.escalatedWorkflowId):
        all_workflows = _load_workflows(slug_key)
        for wf_id in (payload.workflowId, payload.escalatedWorkflowId):
            if not wf_id:
                continue
            linked_workflow = next((w for w in all_workflows if w.get('id') == wf_id), None)
            if _workflow_has_destructive_step(linked_workflow) and not payload.autoRunDestructiveAck:
                raise HTTPException(
                    status_code=400,
                    detail=f'Workflow "{linked_workflow.get("name")}" contains a destructive action (wipe, unenroll, disable, etc.) — enabling autoRun with it requires explicit acknowledgment.',
                )

    was_enabled = policies[idx].get('enabled', True)
    updated = payload.dict()
    updated['evaluationIntervalMinutes'] = _clamp_eval_interval(payload.evaluationIntervalMinutes)
    updated['id'] = policy_id
    updated['createdAt'] = policies[idx].get('createdAt') or datetime.now(timezone.utc).isoformat()
    updated['updatedAt'] = datetime.now(timezone.utc).isoformat()
    # Preserve scheduler-tracked state across an edit — it isn't part of the
    # request payload, so a naive replace would silently reset it, making
    # the policy immediately "due" again regardless of when it last ran.
    updated['lastEvaluatedAt'] = policies[idx].get('lastEvaluatedAt')
    # An explicit save is treated as the human review/reset step for the
    # autoRun circuit breaker (see _autorun_circuit_breaker_check) — whoever
    # is editing the policy has had the chance to notice why it tripped
    # (surfaced in the UI) and address it, so saving clears the trip and lets
    # autoRun resume on the next evaluation. It re-trips on its own again if
    # the same failure pattern repeats.
    updated['autoRunTripped'] = False
    updated['autoRunTrippedAt'] = None
    updated['autoRunTrippedReason'] = None
    policies[idx] = updated
    _save_compliance_policies(slug_key, policies)
    _record_audit_event(slug_key, category="policy", action="policy_updated", actor=dash.get('sub'),
                         target_type="policy", target_id=policy_id, target_name=updated.get('name'),
                         message=f'Compliance policy "{updated.get("name")}" updated')

    # Same immediate-check logic as create, but only on the disabled→enabled
    # transition — a routine edit to an already-enabled policy still follows
    # its normal schedule (lastEvaluatedAt is preserved above), so this
    # doesn't fire on every save, just the moment a policy starts watching
    # again.
    if updated.get('enabled', True) and not was_enabled and authorization:
        background_tasks.add_task(_run_compliance_evaluation, authorization, x_workspace_slug, [policy_id], dash.get('sub'))

    return updated

@app.delete("/api/compliance/policies/{policy_id}", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="compliance", level="manage", action="canDeletePolicyOrWorkflow"))])
async def delete_compliance_policy(policy_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    policies = _load_compliance_policies(slug_key)
    deleted = next((p for p in policies if p.get('id') == policy_id), None)
    remaining = [p for p in policies if p.get('id') != policy_id]
    _save_compliance_policies(slug_key, remaining)
    if deleted:
        _record_audit_event(slug_key, category="policy", action="policy_deleted", actor=dash.get('sub'), severity="warning",
                             target_type="policy", target_id=policy_id, target_name=deleted.get('name'),
                             message=f'Compliance policy "{deleted.get("name")}" deleted')
    return {"status": "ok"}

# ── autoRun circuit breaker ──
# autoRun otherwise fires unattended, once per violating device, with no
# limit and no awareness of whether it's actually working. These two guards
# close that gap without touching the deep execution engine:
#   1. A per-pass batch cap (CompliancePolicyPayload.autoRunBatchCap) — see
#      the firing block in _run_compliance_evaluation below.
#   2. A "last N auto-fired runs all failed" trip (this section) — if a
#      policy's own recent autoRun history shows nothing but failures
#      (wrong libraryId, revoked automation credential, Applivery outage,
#      etc.), that's a sign autoRun itself is broken, not that devices are
#      hard to remediate — so it pauses rather than keep repeating the same
#      failure against every new violator until a human notices.

AUTORUN_CIRCUIT_BREAKER_THRESHOLD = 3  # consecutive fully-failed auto-fired runs on the same policy before autoRun trips

def _lookup_workflow_run(slug_key: str, run_id: str) -> Optional[dict]:
    """Checks the in-memory active-run table first (cheap, covers anything
    still running or just finished), falling back to the persisted run
    history file. Mirrors the same two sources _gather_workflow_runs merges,
    just for a single id instead of a full listing."""
    run = _active_runs.get(run_id)
    if run and run.get('slugKey') == slug_key:
        return run
    for r in _load_workflow_runs(slug_key):
        if r.get('id') == run_id:
            return r
    return None

def _run_fully_failed(run: dict) -> bool:
    """True only if EVERY device result in this run failed outright — a
    'partial' or any 'success' means autoRun is at least doing something
    real, so it shouldn't count toward the failure streak."""
    results = run.get('results') or []
    if not results:
        return False
    return not any(r.get('finalStatus') in ('success', 'partial') for r in results)

def _autorun_circuit_breaker_check(slug_key: str, policy: dict, violations: List[dict]) -> Optional[str]:
    """Returns a human-readable trip reason if this policy's autoRun should
    be considered broken, else None. Walks this policy's own violations list
    (already sorted most-recent-first — see _run_compliance_evaluation,
    new records are inserted at index 0) looking at auto_fired entries'
    linked workflow runs. Stops counting (streak broken, breaker stays
    closed) the moment it hits a run that wasn't a total failure. Runs still
    in progress ('running'/'waiting') are skipped rather than counted either
    way — they haven't told us anything yet."""
    policy_id = policy.get('id')
    checked = 0
    for v in violations:
        if v.get('policyId') != policy_id or v.get('status') != 'auto_fired' or not v.get('workflowRunId'):
            continue
        run = _lookup_workflow_run(slug_key, v['workflowRunId'])
        if not run or run.get('status') in ('running', 'waiting'):
            continue
        checked += 1
        if not _run_fully_failed(run):
            return None
        if checked >= AUTORUN_CIRCUIT_BREAKER_THRESHOLD:
            return f"Last {AUTORUN_CIRCUIT_BREAKER_THRESHOLD} auto-run workflow executions for this policy failed on every targeted device"
    return None

# ── Evaluation engine ──
# Shared by the manual "Evaluate now" endpoint and the automatic scheduler
# loop below — both call this one function so behavior never drifts between
# the two triggers.

async def _run_compliance_evaluation(authorization: str, x_workspace_slug: str, policy_ids: Optional[List[str]] = None, actor: Optional[str] = None) -> dict:
    """Shared by the manual 'Evaluate now' endpoint (policy_ids=None — every
    enabled policy, regardless of its configured interval, actor=the admin
    who clicked it) and the scheduler loop (policy_ids=[the ones currently
    due], actor=None → logged as 'system'). Both share one devices fetch
    either way, so narrowing to just the due policies doesn't cost anything
    extra API-wise; it just skips redundant Python-side re-evaluation of
    policies that aren't due yet."""
    slug_key = x_workspace_slug or 'global'
    audit_events: List[dict] = []  # collected through Pass 1, appended once at the end — see _append_audit_events
    all_policies = _load_compliance_policies(slug_key)
    policies = [p for p in all_policies if p.get('enabled', True) and (policy_ids is None or p.get('id') in policy_ids)]
    summary = {"evaluatedPolicies": len(policies), "devicesChecked": 0, "violationsFound": 0, "autoFired": 0, "queuedForReview": 0, "recovered": 0, "autoRunSafetyBlocked": 0}
    if not policies:
        return summary

    # refresh=True deliberately, unlike most callers of get_devices_full —
    # this pass decides real violations/autoRun firings, and the Devices
    # view's own live cache (DEVICES_CACHE_TTL_SECONDS, 15 minutes) can be
    # stale relative to changes made directly in Applivery's own console
    # (e.g. a Device Audience just created/assigned there). A policy scoped
    # to that audience via targetDeviceAudienceId would otherwise silently
    # evaluate against whatever deviceAudiences membership was baked into
    # a snapshot from before the audience existed — indistinguishable from
    # "this audience genuinely has no members" to everything downstream
    # (the violating-device-ids endpoint, the Devices view's policy filter,
    # the Playground globe's policy filter). Both the immediate on-create/
    # on-enable check and "Evaluate now" exist specifically so an admin
    # doesn't have to wait — reusing a stale cache defeats that purpose.
    devices_resp = await get_devices_full(refresh=True, authorization=authorization, x_workspace_slug=x_workspace_slug)
    devices = devices_resp.get('items', [])
    # NOTE: summary["devicesChecked"] is NOT set to len(devices) here — that
    # would report the whole fleet regardless of each policy's own
    # targetDeviceAudienceId scoping, which is exactly what confused an
    # admin into thinking audience scoping wasn't being applied at all (a
    # policy scoped to a 2-device audience reported "Checked 5 devices").
    # Instead it's accumulated below as the sum of each evaluated policy's
    # actually-scoped device count (summary["devicesChecked"] += len(scoped_devices)),
    # so the number in the "Evaluate now" result always matches what was
    # really checked. For an unscoped policy (no audience set), that's the
    # same as the fleet size; for a scoped one, it's the audience's size.

    # Attach installed-app inventories, but ONLY for devices actually scoped
    # by a policy with a requiredAppList/disallowedAppList condition —
    # everyone else pays zero extra cost for a feature they don't use. This
    # is a pure read from the persistent store (installed_apps_refresher_loop
    # is what actually keeps that store fresh, on its own paced schedule) —
    # no live Applivery calls happen here, so evaluation stays instant
    # regardless of fleet size or Applivery's own responsiveness.
    needs_apps_device_ids = _app_list_scoped_device_ids(devices, policies)
    if needs_apps_device_ids:
        devices_by_id = {d['id']: d for d in devices}
        for did in needs_apps_device_ids:
            d = devices_by_id.get(did)
            if d is not None:
                d['installedApps'] = _read_installed_apps_from_store(slug_key, did)

    workflows_by_id = {w['id']: w for w in _load_workflows(slug_key)}
    state = _load_compliance_state(slug_key)
    violations = _load_compliance_violations(slug_key)
    cases = _load_cases(slug_key)  # loaded/saved once per pass, same batching as violations/state — see _upsert_case_for_violation_inmem
    case_notify_events: List[tuple] = []  # (case, event_type) — dispatched to Ticketing/Chat integrations after the pass, see below
    now_iso = datetime.now(timezone.utc).isoformat()

    # Pass 1 — pure in-memory decision making (no network calls): for every
    # policy x device pair, decide whether it's a new violation, a recovery,
    # or unchanged, and queue up whatever marker (tag/Smart Attribute) writes
    # each device needs. This used to be interleaved with the actual PUT
    # calls below, which meant one sequential awaited round-trip per
    # violated/recovered device — fine for tens of devices, but a policy that
    # flips hundreds of devices at once could take minutes end to end.
    marker_actions: List[tuple] = []  # (device, tag_or_None, smart_attr_id_or_None, present)
    policies_changed = False  # set True if any policy's autoRun trip state changes this pass — triggers a save at the end

    for policy in policies:
        workflow = workflows_by_id.get(policy.get('workflowId'))
        # Severity-tiered branching — see CompliancePolicyPayload.escalatedWorkflowId.
        # Only meaningful alongside a primary workflow (same "default/gentle
        # response always required" constraint as autoRun itself).
        escalated_workflow = workflows_by_id.get(policy.get('escalatedWorkflowId')) if workflow else None
        escalated_min_rank = RISK_TIER_RANK.get(policy.get('escalatedWorkflowMinRiskTier') or 'high', 2)
        tag = policy.get('nonComplianceTag')
        smart_attr_id = policy.get('nonComplianceSmartAttributeId')
        target_audience_id = policy.get('targetDeviceAudienceId')
        if target_audience_id:
            scoped_devices = [d for d in devices if any(str(a.get('id')) == str(target_audience_id) for a in (d.get('deviceAudiences') or []))]
        else:
            scoped_devices = devices
        summary["devicesChecked"] += len(scoped_devices)

        # autoRun circuit breaker — resolved once per policy, per pass, not
        # per device (see the "── autoRun circuit breaker ──" section above).
        autorun_block_reason = None
        if policy.get('autoRun') and workflow:
            if policy.get('autoRunTripped'):
                autorun_block_reason = policy.get('autoRunTrippedReason') or "autoRun previously tripped — re-save the policy to re-arm it"
            elif (_workflow_has_destructive_step(workflow) or _workflow_has_destructive_step(escalated_workflow)) and not policy.get('autoRunDestructiveAck'):
                # Defense in depth: the save-time gate in create/update_compliance_policy
                # is the primary check — this catches the case where the linked
                # workflow (primary OR escalated) was edited to ADD a destructive
                # step after the policy was last saved with the acknowledgment.
                offending = workflow if _workflow_has_destructive_step(workflow) else escalated_workflow
                autorun_block_reason = f'Linked workflow "{offending.get("name")}" now contains a destructive action — re-save this policy to acknowledge it before autoRun can fire again'
            else:
                fresh_trip_reason = _autorun_circuit_breaker_check(slug_key, policy, violations)
                if fresh_trip_reason:
                    policy['autoRunTripped'] = True
                    policy['autoRunTrippedAt'] = now_iso
                    policy['autoRunTrippedReason'] = fresh_trip_reason
                    policies_changed = True
                    autorun_block_reason = fresh_trip_reason
                    audit_events.append({
                        "id": str(uuid.uuid4()), "timestamp": now_iso, "category": "policy", "action": "autorun_tripped",
                        "severity": "critical", "actor": actor or "system", "targetType": "policy", "targetId": policy.get('id'),
                        "targetName": policy.get('name'),
                        "message": f'autoRun disabled for "{policy.get("name")}" — {fresh_trip_reason}. Review and re-save the policy to re-enable it.',
                    })
        autorun_batch_cap = _resolve_autorun_batch_cap(policy)
        policy_autofired_count = 0
        policy_new_violations = 0
        policy_recovered = 0
        for device in scoped_devices:
            key = f"{policy['id']}:{device['id']}"
            matched = _policy_violated(device, policy, slug_key)

            if not matched:
                # Device no longer violates — clear any active suppression so a
                # future violation is treated as new, not a repeat.
                if key in state:
                    recovered_violation_id = state[key].get('violationId')
                    del state[key]
                    summary["recovered"] += 1
                    policy_recovered += 1
                    if tag:
                        marker_actions.append((device, tag, None, False))
                    if smart_attr_id:
                        marker_actions.append((device, None, smart_attr_id, False))
                    audit_events.append({
                        "id": str(uuid.uuid4()), "timestamp": now_iso, "category": "violation", "action": "violation_recovered",
                        "severity": "info", "actor": actor or "system", "targetType": "device", "targetId": device.get('id'),
                        "targetName": device.get('displayName'), "message": f'{device.get("displayName")} recovered from "{policy.get("name")}"',
                    })
                    _mark_case_recovered_inmem(cases, recovered_violation_id, now_iso, auto_resolve=policy.get('autoResolveCaseOnRecovery', False), notify_events=case_notify_events)
                continue

            if key in state:
                continue  # already flagged (pending/approved/auto-fired) and still violating — don't re-trigger

            summary["violationsFound"] += 1
            policy_new_violations += 1
            if tag:
                marker_actions.append((device, tag, None, True))
            if smart_attr_id:
                marker_actions.append((device, None, smart_attr_id, True))
            violation_id = str(uuid.uuid4())

            # Escalation decision — this device's OWN live riskTier (already
            # computed by _compute_device_risk) against the policy's
            # configured threshold, not the policy's static severity field
            # (which can't branch since it never varies violation to
            # violation). See CompliancePolicyPayload.escalatedWorkflowId.
            escalated = bool(escalated_workflow) and RISK_TIER_RANK.get(device.get('riskTier', 'low'), 0) >= escalated_min_rank
            effective_workflow = escalated_workflow if escalated else workflow

            record = {
                "id": violation_id,
                "policyId": policy['id'],
                "policyName": policy.get('name'),
                "workflowId": effective_workflow.get('id') if effective_workflow else policy.get('workflowId'),
                "workflowName": effective_workflow.get('name') if effective_workflow else None,
                "escalated": escalated,
                "deviceId": device['id'],
                "deviceName": device.get('displayName'),
                "platform": device.get('platform'),
                "platformDeviceId": device.get('platformDeviceId'),
                "matchedConditions": matched,
                "detectedAt": now_iso,
                "resolvedAt": None,
                "workflowRunId": None,
                "status": "pending",
                "severity": policy.get('severity') or 'medium',
            }
            record["caseId"] = _upsert_case_for_violation_inmem(cases, policy, device, record, now_iso, notify_events=case_notify_events) if policy.get('openCaseOnViolation', True) else None

            if policy.get('autoRun') and workflow and autorun_block_reason:
                record["status"] = "autorun_blocked"
                summary["autoRunSafetyBlocked"] += 1
                summary["queuedForReview"] += 1
                audit_events.append({
                    "id": str(uuid.uuid4()), "timestamp": now_iso, "category": "violation", "action": "violation_detected",
                    "severity": "critical", "actor": actor or "system", "targetType": "device", "targetId": device.get('id'),
                    "targetName": device.get('displayName'),
                    "message": f'{device.get("displayName")} violated "{policy.get("name")}" — autoRun blocked ({autorun_block_reason}), queued for review',
                })
            elif policy.get('autoRun') and workflow and autorun_batch_cap is not None and policy_autofired_count >= autorun_batch_cap:
                record["status"] = "autorun_capped"
                summary["autoRunSafetyBlocked"] += 1
                summary["queuedForReview"] += 1
                audit_events.append({
                    "id": str(uuid.uuid4()), "timestamp": now_iso, "category": "violation", "action": "violation_detected",
                    "severity": "warning", "actor": actor or "system", "targetType": "device", "targetId": device.get('id'),
                    "targetName": device.get('displayName'),
                    "message": f'{device.get("displayName")} violated "{policy.get("name")}" — autoRun batch cap ({autorun_batch_cap}) reached this pass, queued for manual review',
                })
            elif policy.get('autoRun') and workflow:
                policy_autofired_count += 1
                device_ref = WorkflowDeviceRef(id=device['id'], displayName=device.get('displayName'), platform=device['platform'], platformDeviceId=device['platformDeviceId'], osLifecycleStatus=device.get('osLifecycleStatus'))
                run_record = await _launch_workflow_run(effective_workflow, [device_ref], authorization, x_workspace_slug)
                escalation_note = f' — escalated (device risk tier: {device.get("riskTier", "low")})' if escalated else ''
                if run_record is None:
                    # Workflow has a 'wait' step but DATABASE_URL isn't
                    # configured — log it clearly instead of crashing the
                    # scheduler loop or silently dropping the violation.
                    record["status"] = "workflow_unavailable"
                    audit_events.append({
                        "id": str(uuid.uuid4()), "timestamp": now_iso, "category": "violation", "action": "violation_detected",
                        "severity": "critical", "actor": actor or "system", "targetType": "device", "targetId": device.get('id'),
                        "targetName": device.get('displayName'),
                        "message": f'{device.get("displayName")} violated "{policy.get("name")}" — workflow "{effective_workflow.get("name")}" could not run (durable storage not configured){escalation_note}',
                    })
                else:
                    record["status"] = "auto_fired"
                    record["workflowRunId"] = run_record["id"]
                    summary["autoFired"] += 1
                    audit_events.append({
                        "id": str(uuid.uuid4()), "timestamp": now_iso, "category": "violation", "action": "violation_auto_fired",
                        "severity": "warning", "actor": actor or "system", "targetType": "device", "targetId": device.get('id'),
                        "targetName": device.get('displayName'),
                        "message": f'{device.get("displayName")} violated "{policy.get("name")}" — auto-ran "{effective_workflow.get("name")}"{escalation_note}',
                    })
                    case_match = next((c for c in cases if c.get('id') == record.get('caseId')), None)
                    if case_match:
                        case_match.setdefault('workflowRunIds', []).append(run_record['id'])
                        case_match.setdefault('timeline', []).append(_case_timeline_entry('workflow_run_linked', f'Auto-ran "{effective_workflow.get("name")}" (policy autoRun is on){escalation_note}'))
                        case_match['updatedAt'] = now_iso
            elif not workflow:
                record["status"] = "no_workflow"  # policy has no linked workflow — logged, nothing to run
                audit_events.append({
                    "id": str(uuid.uuid4()), "timestamp": now_iso, "category": "violation", "action": "violation_detected",
                    "severity": "warning", "actor": actor or "system", "targetType": "device", "targetId": device.get('id'),
                    "targetName": device.get('displayName'),
                    "message": f'{device.get("displayName")} violated "{policy.get("name")}" — no workflow linked',
                })
            else:
                summary["queuedForReview"] += 1
                audit_events.append({
                    "id": str(uuid.uuid4()), "timestamp": now_iso, "category": "violation", "action": "violation_detected",
                    "severity": "warning", "actor": actor or "system", "targetType": "device", "targetId": device.get('id'),
                    "targetName": device.get('displayName'),
                    "message": f'{device.get("displayName")} violated "{policy.get("name")}" — queued for review',
                })

            violations.insert(0, record)
            state[key] = {"violationId": violation_id, "status": record["status"], "lastDetectedAt": now_iso}

        # One summary entry per policy per evaluation pass, regardless of
        # outcome — this is what gives a clean run (0 violations) a visible
        # audit trail, not just an updated lastEvaluatedAt timestamp on the
        # policy card. Violation-specific events above already cover the
        # detail when something's actually wrong.
        if policy_new_violations:
            eval_message = f'"{policy.get("name")}" evaluated — {policy_new_violations} new violation(s) found among {len(scoped_devices)} device(s)'
            eval_severity = "warning"
        elif policy_recovered:
            eval_message = f'"{policy.get("name")}" evaluated — clean ({policy_recovered} device(s) recovered) among {len(scoped_devices)} device(s)'
            eval_severity = "info"
        else:
            eval_message = f'"{policy.get("name")}" evaluated — no violations found among {len(scoped_devices)} device(s)'
            eval_severity = "info"
        audit_events.append({
            "id": str(uuid.uuid4()), "timestamp": now_iso, "category": "policy", "action": "policy_evaluated",
            "severity": eval_severity, "actor": actor or "system", "targetType": "policy", "targetId": policy.get('id'),
            "targetName": policy.get('name'), "message": eval_message,
        })

    _save_compliance_state(slug_key, state)
    _save_compliance_violations(slug_key, violations)
    _save_cases(slug_key, cases)
    if policies_changed:
        _save_compliance_policies(slug_key, all_policies)
    if audit_events:
        _append_audit_events(slug_key, audit_events)

    # Ticketing/Chat integrations, dispatched now that the pass is done —
    # each entry is a (case, event_type) pair queued by
    # _upsert_case_for_violation_inmem / _mark_case_recovered_inmem above.
    # Usually 0-2 entries even on a fleet-wide policy flip (case de-dup means
    # this fires once per newly-opened/reopened/resolved case, not once per
    # violation), so doing this as individual awaited calls rather than
    # further batching is fine.
    if case_notify_events:
        cases_changed = False
        for case, event_type in case_notify_events:
            refs = await _dispatch_case_integrations(slug_key, case, event_type)
            if refs:
                _attach_external_refs(case, refs)
                cases_changed = True
        if cases_changed:
            _save_cases(slug_key, cases)

    # Pass 2 — dispatch the marker writes. Concurrency is bounded *across
    # devices* (COMPLIANCE_WRITE_CONCURRENCY), but each device's own actions
    # run strictly in order within it: _apply_compliance_tag/_smart_attribute
    # do a read-modify-write on the device's full tag/attribute list, so two
    # concurrent writes to the SAME device (e.g. two policies each adding
    # their own tag) could race and clobber each other if parallelized
    # naively. Grouping by device keeps that read-modify-write safe while
    # still parallelizing across the fleet — which is the axis that actually
    # matters at thousands-of-devices scale. The shared Applivery rate
    # limiter (_applivery_call) paces the real network traffic regardless of
    # how much of this runs "concurrently" here.
    actions_by_device: Dict[str, list] = {}
    for action in marker_actions:
        actions_by_device.setdefault(action[0]['id'], []).append(action)

    tags_changed = False
    if actions_by_device:
        async with httpx.AsyncClient(timeout=30.0) as client:
            headers = {"Authorization": authorization, "Content-Type": "application/json"}
            org_base = await _resolve_org_base(client, headers, x_workspace_slug)
            sem = asyncio.Semaphore(COMPLIANCE_WRITE_CONCURRENCY)

            async def apply_device_actions(dev_actions):
                nonlocal tags_changed
                async with sem:
                    for device, tag, smart_attr_id, present in dev_actions:
                        try:
                            if tag:
                                changed = await _apply_compliance_tag(client, headers, org_base, device, tag, present)
                            else:
                                changed = await _apply_compliance_smart_attribute(client, headers, org_base, device, smart_attr_id, present)
                            if changed:
                                tags_changed = True
                        except Exception as e:
                            print(f"[Compliance] Marker write failed for device {device.get('id')}: {e}")

            await asyncio.gather(*[apply_device_actions(a) for a in actions_by_device.values()])

    if tags_changed:
        _invalidate_devices_cache(slug_key)

    # Stamp lastEvaluatedAt on every policy actually evaluated this pass —
    # this is what the scheduler uses to decide when each policy is next due.
    evaluated_ids = {p['id'] for p in policies}
    for p in all_policies:
        if p.get('id') in evaluated_ids:
            p['lastEvaluatedAt'] = now_iso
    _save_compliance_policies(slug_key, all_policies)

    return summary

class EvaluateNowPayload(BaseModel):
    # None (or the field omitted entirely — FastAPI treats a missing JSON
    # body the same as {} for an all-optional model) evaluates every
    # enabled policy, matching the original "Evaluate now" behavior and
    # what the scheduler does automatically on each policy's own schedule.
    # Set this to scope a manual run to exactly one policy — added so
    # testing/tuning a single policy's conditions doesn't also re-fire
    # every OTHER enabled policy's autoRun workflows at the same time, a
    # real risk when a workspace has several autoRun policies and someone
    # is just trying to iterate on one of them.
    policyId: Optional[str] = None

@app.post("/api/compliance/evaluate", dependencies=[Depends(verify_dashboard_token)])
async def evaluate_compliance_now(
    payload: EvaluateNowPayload = EvaluateNowPayload(),
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    slug_key = x_workspace_slug or 'global'
    policy_ids = [payload.policyId] if payload.policyId else None
    summary = await _run_compliance_evaluation(authorization, x_workspace_slug, policy_ids=policy_ids, actor=dash.get('sub'))
    # Only worth an Audit Log entry when something was actually found — a
    # clean "0 violations" run logged every time (manual clicks + every
    # scheduled tick) drowned out everything else in the log. See the
    # scheduled evaluation loop below, which already gated on this same
    # condition; this manual endpoint was the one place still logging
    # unconditionally.
    if summary["violationsFound"] > 0:
        _record_audit_event(
            slug_key, category="policy", action="policy_evaluation_run", actor=dash.get('sub'),
            message=(
                f'Manually evaluated {summary["evaluatedPolicies"]} polic{"y" if summary["evaluatedPolicies"] == 1 else "ies"} '
                f'against {summary["devicesChecked"]} device{"s" if summary["devicesChecked"] != 1 else ""} — '
                f'{summary["violationsFound"]} new violation{"s" if summary["violationsFound"] != 1 else ""}'
            ),
        )
    return summary

@app.get("/api/compliance/policies/{policy_id}/violating-device-ids", dependencies=[Depends(verify_dashboard_token)])
async def get_policy_violating_device_ids(policy_id: str, x_workspace_slug: Optional[str] = Header(None)):
    """Device ids currently failing a given Compliance Policy right now — for
    the Playground globe's per-policy filter. Reads _load_compliance_state,
    which holds one entry per still-violating policy+device pair (deleted the
    moment a device recovers, see _run_compliance_evaluation), so this is
    always the live "who's out of compliance for this policy" set, not a
    historical log."""
    state = _load_compliance_state(x_workspace_slug or 'global')
    device_ids = [key.split(':', 1)[1] for key in state.keys() if key.startswith(f"{policy_id}:")]
    return {"deviceIds": device_ids}

# ── Review queue ──

@app.get("/api/compliance/violations", dependencies=[Depends(verify_dashboard_token)])
async def list_compliance_violations(status: Optional[str] = None, limit: int = 100, offset: int = 0, x_workspace_slug: Optional[str] = Header(None)):
    items = _load_compliance_violations(x_workspace_slug or 'global')
    if status:
        items = [v for v in items if v.get('status') == status]
    total = len(items)
    page = items[offset:offset + max(1, min(limit, 500))]
    return {"items": page, "total": total, "offset": offset, "limit": limit}

@app.get("/api/compliance/violations/export", dependencies=[Depends(verify_dashboard_token)])
async def export_compliance_violations(status: Optional[str] = None, x_workspace_slug: Optional[str] = Header(None)):
    """CSV export of the violation history — mirrors export_audit_logs below.
    Unlike the paginated list endpoint, this is unbounded (a workspace's
    violation store is already capped at 500 by _save_compliance_violations,
    so there's no unbounded-export risk here)."""
    slug_key = x_workspace_slug or 'global'
    items = _load_compliance_violations(slug_key)
    if status:
        items = [v for v in items if v.get('status') == status]
    items = sorted(items, key=lambda v: v.get('createdAt', ''))

    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(["Created At", "Resolved At", "Status", "Policy", "Device", "Platform", "Case ID"])
    for v in items:
        writer.writerow([
            v.get('createdAt', ''), v.get('resolvedAt') or '', v.get('status', ''), v.get('policyName', ''),
            v.get('deviceName', ''), v.get('platform', ''), v.get('caseId') or '',
        ])
    buf.seek(0)
    filename = f"compliance-violations-{_audit_slug_clean(slug_key)}-{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')}.csv"
    return StreamingResponse(iter([buf.getvalue()]), media_type="text/csv", headers={"Content-Disposition": f"attachment; filename={filename}"})

async def _approve_violation_core(violation_id: str, authorization: str, x_workspace_slug: str, dash: dict) -> dict:
    """Shared body behind both the single-violation approve endpoint and the
    bulk-approve endpoint below — kept as one function so bulk approvals get
    the exact same workflow-launch, state-sync and case-timeline behavior as
    approving one at a time, just looped."""
    slug_key = x_workspace_slug or 'global'
    violations = _load_compliance_violations(slug_key)
    idx = next((i for i, v in enumerate(violations) if v.get('id') == violation_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Violation not found")
    violation = violations[idx]
    if violation.get('status') != 'pending':
        raise HTTPException(status_code=400, detail=f"Violation already '{violation.get('status')}'")

    workflows = _load_workflows(slug_key)
    workflow = next((w for w in workflows if w.get('id') == violation.get('workflowId')), None)
    if not workflow:
        raise HTTPException(status_code=400, detail="Linked workflow no longer exists")

    device_ref = WorkflowDeviceRef(id=violation['deviceId'], displayName=violation.get('deviceName'), platform=violation['platform'], platformDeviceId=violation['platformDeviceId'])
    run_record = await _launch_workflow_run(workflow, [device_ref], authorization, x_workspace_slug)
    if run_record is None:
        raise HTTPException(status_code=400, detail="This workflow includes a 'wait' or 'run script and wait for result' step, which requires durable storage. Set DATABASE_URL on the server to enable it.")

    violation['status'] = 'approved'
    violation['resolvedAt'] = datetime.now(timezone.utc).isoformat()
    violation['workflowRunId'] = run_record['id']
    violations[idx] = violation
    _save_compliance_violations(slug_key, violations)
    _record_audit_event(slug_key, category="violation", action="violation_approved", actor=dash.get('sub'),
                         target_type="device", target_id=violation.get('deviceId'), target_name=violation.get('deviceName'),
                         message=f'{violation.get("deviceName")} violation of "{violation.get("policyName")}" approved — running "{workflow.get("name")}"')

    state = _load_compliance_state(slug_key)
    key = f"{violation['policyId']}:{violation['deviceId']}"
    if key in state:
        state[key]['status'] = 'approved'
        _save_compliance_state(slug_key, state)

    # Note the remediation run on the linked Case, but don't touch its
    # status — approving a violation only confirms the workflow ran, not that
    # the device actually came back compliant. The analyst closes the case
    # themselves once they've verified that.
    if violation.get('caseId'):
        cases = _load_cases(slug_key)
        case_idx = next((i for i, c in enumerate(cases) if c.get('id') == violation['caseId']), None)
        if case_idx is not None:
            cases[case_idx].setdefault('workflowRunIds', []).append(run_record['id'])
            cases[case_idx].setdefault('timeline', []).append(_case_timeline_entry('workflow_run_linked', f'Violation approved by {dash.get("sub")} — ran "{workflow.get("name")}"', dash.get('sub')))
            cases[case_idx]['updatedAt'] = datetime.now(timezone.utc).isoformat()
            _save_cases(slug_key, cases)

    return violation

@app.post("/api/compliance/violations/{violation_id}/approve", dependencies=[Depends(verify_dashboard_token)])
async def approve_compliance_violation(
    violation_id: str,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    return await _approve_violation_core(violation_id, authorization, x_workspace_slug, dash)

class BulkViolationIdsPayload(BaseModel):
    violationIds: List[str]

@app.post("/api/compliance/violations/bulk-approve", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="compliance", level="manage", action="canBulkTriage"))])
async def bulk_approve_compliance_violations(
    payload: BulkViolationIdsPayload,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    approved, failed = [], []
    for vid in payload.violationIds:
        try:
            await _approve_violation_core(vid, authorization, x_workspace_slug, dash)
            approved.append(vid)
        except HTTPException as e:
            failed.append({"id": vid, "error": e.detail})
    return {"approved": approved, "failed": failed}

def _dismiss_violation_core(violation_id: str, slug_key: str, dash: dict) -> dict:
    """Shared body behind both the single-violation dismiss endpoint and the
    bulk-dismiss endpoint below."""
    violations = _load_compliance_violations(slug_key)
    idx = next((i for i, v in enumerate(violations) if v.get('id') == violation_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Violation not found")
    violations[idx]['status'] = 'dismissed'
    violations[idx]['resolvedAt'] = datetime.now(timezone.utc).isoformat()
    _save_compliance_violations(slug_key, violations)
    _record_audit_event(slug_key, category="violation", action="violation_dismissed", actor=dash.get('sub'),
                         target_type="device", target_id=violations[idx].get('deviceId'), target_name=violations[idx].get('deviceName'),
                         message=f'{violations[idx].get("deviceName")} violation of "{violations[idx].get("policyName")}" dismissed')

    state = _load_compliance_state(slug_key)
    key = f"{violations[idx]['policyId']}:{violations[idx]['deviceId']}"
    if key in state:
        state[key]['status'] = 'dismissed'
        _save_compliance_state(slug_key, state)

    if violations[idx].get('caseId'):
        cases = _load_cases(slug_key)
        case_idx = next((i for i, c in enumerate(cases) if c.get('id') == violations[idx]['caseId']), None)
        if case_idx is not None:
            cases[case_idx].setdefault('timeline', []).append(_case_timeline_entry('note_added', f'Violation dismissed by {dash.get("sub")} — remediation not run', dash.get('sub')))
            cases[case_idx]['updatedAt'] = datetime.now(timezone.utc).isoformat()
            _save_cases(slug_key, cases)

    return violations[idx]

@app.post("/api/compliance/violations/{violation_id}/dismiss", dependencies=[Depends(verify_dashboard_token)])
async def dismiss_compliance_violation(violation_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    return _dismiss_violation_core(violation_id, x_workspace_slug or 'global', dash)

@app.post("/api/compliance/violations/bulk-dismiss", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="compliance", level="manage", action="canBulkTriage"))])
async def bulk_dismiss_compliance_violations(
    payload: BulkViolationIdsPayload,
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    slug_key = x_workspace_slug or 'global'
    dismissed, failed = [], []
    for vid in payload.violationIds:
        try:
            _dismiss_violation_core(vid, slug_key, dash)
            dismissed.append(vid)
        except HTTPException as e:
            failed.append({"id": vid, "error": e.detail})
    return {"dismissed": dismissed, "failed": failed}

# ─── MITRE ATT&CK TAGGING ───
# A static, curated catalog of MITRE ATT&CK Enterprise techniques relevant to
# endpoint/MDM-visible detections — not the full ~600-technique matrix (most
# of it, e.g. cloud-control-plane or network-appliance techniques, isn't
# something this app could ever observe). Deliberately a hardcoded list
# rather than a live pull from MITRE's own ATT&CK STIX/TAXII feed: technique
# IDs/names are stable enough that a periodic manual refresh is simpler and
# more reliable than adding a dependency on an external feed just to render
# a picker. Attached to Compliance Policies (see CompliancePolicyPayload.
# mitreTechniques) and inherited onto every Case that policy opens — see
# _upsert_case_for_violation_inmem — purely a classification/reporting aid,
# no effect on evaluation.
