# The curated list above is still deliberately hand-picked (see module
# comment: MDM-visible techniques only, not the full ~600-technique
# matrix) — that scoping decision hasn't changed. What WAS missing is any
# signal that it could silently drift from upstream ATT&CK as MITRE renames,
# deprecates, or revokes technique IDs over time. This periodically pulls
# MITRE's own published STIX bundle (the canonical source ATT&CK Navigator
# and every other serious ATT&CK tool builds from) and cross-checks it
# against the curated ~41 IDs — surfacing live names/status/lastFetchedAt
# rather than replacing the curation itself.
MITRE_CATALOG_TICK_SECONDS = 86400  # ATT&CK content updates roughly quarterly; daily is a harmless upper bound, same cadence as the other "static-ish external feed" catalogs in this file
MITRE_STIX_BUNDLE_URL = "https://raw.githubusercontent.com/mitre-attack/attack-stix-data/master/enterprise-attack/enterprise-attack.json"

def _load_mitre_catalog() -> dict:
    return _store_load(_GLOBAL_STORE_SLUG, 'mitre_catalog', lambda: {"techniques": [], "lastFetchedAt": None, "lastError": None})

def _save_mitre_catalog(catalog: dict):
    _store_save(_GLOBAL_STORE_SLUG, 'mitre_catalog', catalog)

async def _refresh_mitre_catalog() -> dict:
    """Fetches MITRE's Enterprise ATT&CK STIX bundle and extracts every
    attack-pattern object into a flat {id, name, tactics, revoked,
    deprecated} list. On any failure (network, unexpected shape), the
    previously-cached catalog is left untouched and only lastError is set —
    same "never wipe good data because of one bad fetch" behavior as every
    other catalog refresher in this file (OS update/vuln/lifecycle/GDMF)."""
    catalog = _load_mitre_catalog()
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(60.0)) as client:
            res = await client.get(MITRE_STIX_BUNDLE_URL)
            res.raise_for_status()
            bundle = res.json()
        techniques = []
        for obj in bundle.get('objects', []):
            if obj.get('type') != 'attack-pattern':
                continue
            external_id = None
            for ref in (obj.get('external_references') or []):
                if ref.get('source_name') == 'mitre-attack' and ref.get('external_id', '').startswith('T'):
                    external_id = ref['external_id']
                    break
            if not external_id:
                continue
            tactics = [
                phase.get('phase_name') for phase in (obj.get('kill_chain_phases') or [])
                if phase.get('kill_chain_name') == 'mitre-attack'
            ]
            techniques.append({
                "id": external_id, "name": obj.get('name'), "tactics": tactics,
                "revoked": bool(obj.get('revoked', False)), "deprecated": bool(obj.get('x_mitre_deprecated', False)),
                "isSubtechnique": bool(obj.get('x_mitre_is_subtechnique', False)),
            })
        if not techniques:
            raise ValueError("STIX bundle parsed but yielded zero attack-pattern objects — unexpected shape")
        catalog['techniques'] = techniques
        catalog['lastFetchedAt'] = datetime.now(timezone.utc).isoformat()
        catalog['lastError'] = None
    except Exception as e:
        catalog['lastError'] = str(e)[:300]
        print(f"[MITRE Catalog] Refresh failed: {e}")
    _save_mitre_catalog(catalog)
    return catalog

async def mitre_catalog_refresh_loop():
    while True:
        try:
            catalog = await _refresh_mitre_catalog()
            _record_job_heartbeat('mitre_catalog_refresh', 'ok' if not catalog.get('lastError') else 'error', catalog.get('lastError'))
        except Exception as e:
            print(f"[MITRE Catalog] Error: {e}")
            _record_job_heartbeat('mitre_catalog_refresh', 'error', str(e))
        await asyncio.sleep(MITRE_CATALOG_TICK_SECONDS)

@app.get("/api/mitre/techniques", dependencies=[Depends(verify_dashboard_token)])
async def get_mitre_techniques():
    """Serves the curated MDM-relevant subset (unchanged scope), but with
    each entry's name/status cross-checked against the live MITRE catalog
    when one has been fetched — a rename upstream shows up here instead of
    silently drifting, and a technique MITRE has revoked/deprecated is
    flagged rather than presented as current. Falls back to the static
    name/no-flags for any curated technique the live catalog hasn't been
    fetched yet (first boot) or doesn't (yet) contain."""
    catalog = _load_mitre_catalog()
    live_by_id = {t['id']: t for t in (catalog.get('techniques') or [])}
    items = []
    for t in MITRE_TECHNIQUES:
        live = live_by_id.get(t['id'])
        items.append({
            **t,
            "name": (live.get('name') if live else None) or t['name'],
            "revoked": bool(live.get('revoked')) if live else False,
            "deprecated": bool(live.get('deprecated')) if live else False,
            "liveDataAvailable": live is not None,
        })
    return {
        "items": items, "tactics": MITRE_TACTICS,
        "catalogLastFetchedAt": catalog.get('lastFetchedAt'), "catalogLastError": catalog.get('lastError'),
        "catalogTechniqueCount": len(catalog.get('techniques') or []),
    }

@app.post("/api/mitre/refresh", dependencies=[Depends(verify_dashboard_token)])
async def refresh_mitre_catalog_now():
    catalog = await _refresh_mitre_catalog()
    _record_job_heartbeat('mitre_catalog_refresh', 'ok' if not catalog.get('lastError') else 'error', catalog.get('lastError'))
    return {"lastFetchedAt": catalog.get('lastFetchedAt'), "lastError": catalog.get('lastError'), "techniqueCount": len(catalog.get('techniques') or [])}

# ─── CASE MANAGEMENT ───
# The incident layer above raw Compliance Violations. A violation is a single
# detected condition on a single device at a point in time; a Case is the
# thing an analyst actually works — it survives across repeated detections of
# the same underlying problem (a device that stays broken across several
# evaluation cycles reuses one case instead of spawning a new one each time),
# carries its own investigative status independent of whether the
# remediation workflow already ran, and gives a place to assign an owner,
# leave notes, and see everything that happened in order. Three sources:
#   - "compliance_violation": auto-opened by the in-memory case helpers below
#     the moment a policy is newly violated (see _run_compliance_evaluation).
#     Approving/dismissing the underlying violation does NOT resolve the
#     case — that only reflects whether remediation ran, not whether the
#     issue is actually fixed. An analyst closes the case themselves once
#     they've confirmed the device is clean.
#   - "workflow_trigger": opened by an inbound webhook trigger, if that
#     trigger has openCase=True — see Inbound Webhook Triggers below.
#   - "manual": created directly by an analyst from the Cases view.
CASES_DIR = os.path.join(DATA_DIR, "cases")
if not os.path.exists(CASES_DIR):
    os.makedirs(CASES_DIR)

CASE_OPEN_STATUSES = ("open", "investigating")
CASE_STATUSES = ("open", "investigating", "resolved", "closed", "false_positive")
CASE_SEVERITIES = ("low", "medium", "high", "critical")

def _cases_file(slug: str) -> str:
    return os.path.join(CASES_DIR, f"{_slug_clean(slug)}.json")

_register_legacy_json('cases', lambda slug, key: _cases_file(slug))

def _load_cases(slug: str) -> List[Dict[str, Any]]:
    return _store_load(slug, 'cases', list)

def _save_cases(slug: str, cases: List[Dict[str, Any]]):
    _store_save(slug, 'cases', cases)

def _case_timeline_entry(event_type: str, message: str, actor: Optional[str] = None) -> dict:
    return {
        "id": str(uuid.uuid4()),
        "type": event_type,  # 'created' | 'status_changed' | 'severity_changed' | 'note_added' | 'violation_linked' | 'workflow_run_linked' | 'assigned' | 'reopened'
        "message": message,
        "actor": actor or "system",
        "at": datetime.now(timezone.utc).isoformat(),
    }

def _upsert_case_for_violation_inmem(cases: List[Dict[str, Any]], policy: dict, device: dict, violation_record: dict, now_iso: str, notify_events: Optional[List[tuple]] = None) -> str:
    """Pure in-memory mutation of an already-loaded `cases` list — no I/O.
    Called once per NEW violation from inside _run_compliance_evaluation's
    per-policy loop, which itself loads `cases` once and saves once after the
    whole pass, the same batching this file already applies to violations/
    state/audit_events so a fleet-wide policy flip doesn't do a file
    read+write per device. Returns the case id.

    `notify_events`, if given, collects (case, event_type) pairs for Ticketing/
    Chat integrations to fire on AFTER the pass finishes (see
    _dispatch_case_integrations) — deliberately not dispatched inline here,
    since this function runs inside a tight in-memory loop and dispatching
    real HTTP calls per device would defeat the whole point of batching. A
    case that already has an open violation linked to it doesn't renotify —
    only genuinely new or reopened cases do, so a device that's been broken
    for a week doesn't page anyone twice."""
    existing = next((c for c in cases if c.get('policyId') == policy['id'] and c.get('deviceId') == device['id'] and c.get('status') in CASE_OPEN_STATUSES), None)
    if existing:
        existing['violationIds'].append(violation_record['id'])
        existing['updatedAt'] = now_iso
        existing.setdefault('timeline', []).append(_case_timeline_entry('violation_linked', f'New violation detected — case re-triggered ({len(existing["violationIds"])} total)'))
        return existing['id']

    # A CLOSED/resolved/false_positive case for this exact (policy, device)
    # pair recurring is still the same underlying incident, not a brand new
    # one — reopen it and keep its history rather than starting fresh.
    closed_match = next((c for c in cases if c.get('policyId') == policy['id'] and c.get('deviceId') == device['id'] and c.get('status') not in CASE_OPEN_STATUSES), None)
    if closed_match:
        closed_match['status'] = 'open'
        closed_match['closedAt'] = None
        closed_match['updatedAt'] = now_iso
        closed_match['violationIds'].append(violation_record['id'])
        # Recurrence is a fresh incident from an SLA standpoint — restart the
        # clock (slaClockStartedAt, NOT createdAt, which stays the case's
        # original open date for history) rather than leaving it stamped
        # from months ago, and clear both breach markers so a genuinely new
        # occurrence isn't born already "breached and already notified".
        closed_match['acknowledgedAt'] = None
        closed_match['slaClockStartedAt'] = now_iso
        closed_match['slaAckBreachNotifiedAt'] = None
        closed_match['slaResolveBreachNotifiedAt'] = None
        # The policy's MITRE tags may have changed since this case was first
        # opened (an admin editing the policy later) — refresh onto reopen
        # rather than leaving a stale tag set from months ago.
        closed_match['mitreTechniques'] = list(policy.get('mitreTechniques') or [])
        closed_match.setdefault('timeline', []).append(_case_timeline_entry('reopened', 'Violation recurred — case reopened'))
        if notify_events is not None:
            notify_events.append((closed_match, 'reopened'))
        return closed_match['id']

    case_id = str(uuid.uuid4())
    new_case = {
        "id": case_id,
        "title": f'{device.get("displayName") or device.get("id")} — {policy.get("name")}',
        "status": "open",
        "severity": policy.get('severity') or 'medium',
        "source": "compliance_violation",
        "deviceId": device.get('id'),
        "deviceName": device.get('displayName'),
        "segmentId": device.get('segmentId'),
        "policyId": policy.get('id'),
        "policyName": policy.get('name'),
        "violationIds": [violation_record['id']],
        "workflowRunIds": [],
        "assignee": None,
        "createdBy": "system",
        "createdAt": now_iso,
        "updatedAt": now_iso,
        "closedAt": None,
        "acknowledgedAt": None,
        "slaClockStartedAt": now_iso,
        "slaAckBreachNotifiedAt": None,
        "slaResolveBreachNotifiedAt": None,
        "notes": [],
        # Inherited from the policy at the moment of first detection — see
        # CompliancePolicyPayload.mitreTechniques. Editable afterward on the
        # Case itself (PUT /api/cases/{id}) independent of the policy.
        "mitreTechniques": list(policy.get('mitreTechniques') or []),
        # Threat intel lookups an analyst runs against IOCs while
        # investigating — see POST /api/cases/{id}/enrich. Empty until an
        # analyst actually enriches something; never populated automatically.
        "threatIntel": [],
        "timeline": [_case_timeline_entry('created', f'Case opened — "{policy.get("name")}" violated by {device.get("displayName")}')],
    }
    cases.insert(0, new_case)
    if notify_events is not None:
        notify_events.append((new_case, 'created'))
    return case_id

def _mark_case_recovered_inmem(cases: List[Dict[str, Any]], violation_id: Optional[str], now_iso: str, auto_resolve: bool = False, notify_events: Optional[List[tuple]] = None):
    """Companion to the upsert above, called from the recovery branch.
    `auto_resolve` is the policy's own autoResolveCaseOnRecovery setting —
    default False leaves status untouched (an analyst confirms and closes
    deliberately), just a breadcrumb that the device stopped violating so
    whoever's triaging it isn't working blind. True flips the case straight
    to 'resolved', same as if an analyst had done it from the Cases view —
    and, if `notify_events` is given, queues a 'closed' Ticketing/Chat event
    for it."""
    if not violation_id:
        return
    case = next((c for c in cases if violation_id in (c.get('violationIds') or []) and c.get('status') in CASE_OPEN_STATUSES), None)
    if not case:
        return
    case['updatedAt'] = now_iso
    if auto_resolve:
        case['status'] = 'resolved'
        case['closedAt'] = now_iso
        case.setdefault('timeline', []).append(_case_timeline_entry('status_changed', 'Device no longer violates the linked policy — case auto-resolved (policy has autoResolveCaseOnRecovery on)'))
        if notify_events is not None:
            notify_events.append((case, 'closed'))
    else:
        case.setdefault('timeline', []).append(_case_timeline_entry('device_recovered', 'Device no longer violates the linked policy — case left open for confirmation'))

class CaseCreatePayload(BaseModel):
    title: str
    severity: str = "medium"
    deviceId: Optional[str] = None
    deviceName: Optional[str] = None
    notes: Optional[str] = None  # optional first note, added at creation
    mitreTechniques: List[str] = []

class CaseUpdatePayload(BaseModel):
    title: Optional[str] = None
    status: Optional[str] = None
    severity: Optional[str] = None
    assignee: Optional[str] = None
    mitreTechniques: Optional[List[str]] = None  # None = leave untouched; [] explicitly clears

class CaseNotePayload(BaseModel):
    text: str

class CaseBulkUpdatePayload(BaseModel):
    caseIds: List[str]
    status: Optional[str] = None
    assignee: Optional[str] = None

@app.get("/api/cases", dependencies=[Depends(verify_dashboard_token)])
async def list_cases(x_workspace_slug: Optional[str] = Header(None)):
    slug_key = x_workspace_slug or 'global'
    cases = _load_cases(slug_key)
    thresholds = _load_case_sla_settings(slug_key).get('thresholds', {})
    for c in cases:
        c['slaStatus'] = _case_sla_status(c, thresholds)
    return {"items": cases}

@app.get("/api/cases/export", dependencies=[Depends(verify_dashboard_token)])
async def export_cases(x_workspace_slug: Optional[str] = Header(None)):
    """CSV export of the case list — same shape/convention as export_audit_logs
    and export_compliance_violations above."""
    slug_key = x_workspace_slug or 'global'
    cases = sorted(_load_cases(slug_key), key=lambda c: c.get('createdAt', ''))
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(["Created At", "Closed At", "Title", "Status", "Severity", "Source", "Device", "Assignee", "Policy", "Notes Count"])
    for c in cases:
        writer.writerow([
            c.get('createdAt', ''), c.get('closedAt') or '', c.get('title', ''), c.get('status', ''),
            c.get('severity', ''), c.get('source', ''), c.get('deviceName') or '', c.get('assignee') or '',
            c.get('policyName') or '', len(c.get('notes') or []),
        ])
    buf.seek(0)
    filename = f"cases-{_audit_slug_clean(slug_key)}-{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')}.csv"
    return StreamingResponse(iter([buf.getvalue()]), media_type="text/csv", headers={"Content-Disposition": f"attachment; filename={filename}"})

@app.get("/api/cases/assignee-suggestions", dependencies=[Depends(verify_dashboard_token)])
async def case_assignee_suggestions(x_workspace_slug: Optional[str] = Header(None)):
    """Distinct actor emails recently seen in this workspace's audit log — a
    cheap 'who's around to assign this to' list. There's no local user
    directory in this app; every admin authenticates with their own Applivery
    credentials (see /api/auth/login), so the audit trail IS the roster."""
    slug_key = x_workspace_slug or 'global'
    entries = _load_audit_log(slug_key)
    seen: List[str] = []
    for e in entries[:500]:
        actor = e.get('actor')
        if actor and actor != 'system' and actor not in seen:
            seen.append(actor)
        if len(seen) >= 20:
            break
    return {"items": seen}

@app.get("/api/cases/{case_id}", dependencies=[Depends(verify_dashboard_token)])
async def get_case(case_id: str, x_workspace_slug: Optional[str] = Header(None)):
    slug_key = x_workspace_slug or 'global'
    case = next((c for c in _load_cases(slug_key) if c.get('id') == case_id), None)
    if not case:
        raise HTTPException(status_code=404, detail="Case not found")
    case['slaStatus'] = _case_sla_status(case, _load_case_sla_settings(slug_key).get('thresholds', {}))
    return case

@app.post("/api/cases", dependencies=[Depends(verify_dashboard_token)])
async def create_case(
    payload: CaseCreatePayload,
    background_tasks: BackgroundTasks,
    x_workspace_slug: Optional[str] = Header(None),
    authorization: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    if payload.severity not in CASE_SEVERITIES:
        raise HTTPException(status_code=400, detail=f"severity must be one of {CASE_SEVERITIES}")
    slug_key = x_workspace_slug or 'global'
    cases = _load_cases(slug_key)
    now = datetime.now(timezone.utc).isoformat()
    actor = dash.get('sub')
    case_id = str(uuid.uuid4())
    new_case = {
        "id": case_id, "title": payload.title, "status": "open", "severity": payload.severity,
        "source": "manual", "deviceId": payload.deviceId, "deviceName": payload.deviceName,
        "segmentId": None, "policyId": None, "policyName": None,
        "violationIds": [], "workflowRunIds": [], "assignee": None,
        "createdBy": actor, "createdAt": now, "updatedAt": now, "closedAt": None,
        "acknowledgedAt": None, "slaClockStartedAt": now, "slaAckBreachNotifiedAt": None, "slaResolveBreachNotifiedAt": None,
        "mitreTechniques": [t for t in (payload.mitreTechniques or []) if t in _MITRE_TECHNIQUES_BY_ID],
        "threatIntel": [],
        "notes": [], "timeline": [_case_timeline_entry('created', f'Case opened manually by {actor}', actor)],
    }
    if payload.notes and payload.notes.strip():
        new_case['notes'].append({"id": str(uuid.uuid4()), "authorEmail": actor, "text": payload.notes.strip(), "createdAt": now})
    cases.insert(0, new_case)
    _save_cases(slug_key, cases)
    _record_audit_event(slug_key, category="case", action="case_created", actor=actor,
                         target_type="case", target_id=case_id, target_name=new_case['title'],
                         message=f'Case "{new_case["title"]}" opened manually by {actor}')

    refs = await _dispatch_case_integrations(slug_key, new_case, 'created')
    if refs:
        _attach_external_refs(new_case, refs)  # mutates new_case, which is the same object already inside `cases`
        _save_cases(slug_key, cases)

    if await _auto_enrich_case_from_text(slug_key, new_case, payload.notes, actor):
        _save_cases(slug_key, cases)

    # Case Auto-Run Rules — the manually-created-Case equivalent of
    # Compliance Policy autoRun / Inbound Webhook Triggers (see module
    # comment above _try_case_autorun). Best-effort: a rule failing to fire
    # shouldn't block the Case itself from being created.
    if authorization:
        try:
            run_record = await _try_case_autorun(slug_key, new_case, authorization, x_workspace_slug, background_tasks)
            if run_record:
                new_case.setdefault('workflowRunIds', []).append(run_record['id'])
                new_case.setdefault('timeline', []).append(_case_timeline_entry('workflow_run_linked', f'Auto-ran a workflow via Case Auto-Run rule (run {run_record["id"][:8]})'))
                new_case['updatedAt'] = datetime.now(timezone.utc).isoformat()
                _save_cases(slug_key, cases)
        except Exception as e:
            print(f"[Case Auto-Run] Error evaluating rules for case {case_id}: {e}")

    return new_case

async def _auto_enrich_case_from_text(slug_key: str, case: dict, text: Optional[str], actor: Optional[str]) -> bool:
    """Scans `text` (a case's initial note, or a newly added note) for
    IOC-looking tokens and, if any are found and at least one Threat Intel
    provider is configured, runs enrichment automatically instead of waiting
    for an analyst to manually paste the value into the enrich box — the
    audit gap this closes. Mutates `case` in place (appends to threatIntel/
    timeline) and returns whether anything changed, so the caller knows
    whether it needs to persist. Best-effort: provider failures already
    degrade to an 'error' verdict entry inside _run_threat_intel_lookup, so
    this never raises and never blocks the note/case creation it's attached to."""
    candidates = _extract_ioc_candidates(text or '')
    if not candidates or not _load_threat_intel_providers(slug_key):
        return False
    changed = False
    already_checked = {r.get('ioc', '').lower() for r in (case.get('threatIntel') or [])}
    for ioc_value in candidates:
        if ioc_value.lower() in already_checked:
            continue
        try:
            results = await _run_threat_intel_lookup(slug_key, ioc_value, actor or 'system')
        except Exception:
            continue
        if not results:
            continue
        case.setdefault('threatIntel', []).extend(results)
        verdicts = {r['verdict'] for r in results if r.get('provider')}
        summary = 'malicious' if 'malicious' in verdicts else ('suspicious' if 'suspicious' in verdicts else ('clean' if verdicts else 'no result'))
        case.setdefault('timeline', []).append(_case_timeline_entry(
            'note_added', f'Threat intel: auto-detected "{ioc_value}" and enriched it — {summary}', 'system',
        ))
        already_checked.add(ioc_value.lower())
        changed = True
    if changed:
        case['updatedAt'] = datetime.now(timezone.utc).isoformat()
    return changed

@app.put("/api/cases/{case_id}", dependencies=[Depends(verify_dashboard_token)])
async def update_case(case_id: str, payload: CaseUpdatePayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    cases = _load_cases(slug_key)
    idx = next((i for i, c in enumerate(cases) if c.get('id') == case_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Case not found")
    case = cases[idx]
    now = datetime.now(timezone.utc).isoformat()
    actor = dash.get('sub')

    if payload.title is not None and payload.title != case.get('title'):
        case['title'] = payload.title

    if payload.severity is not None and payload.severity != case.get('severity'):
        if payload.severity not in CASE_SEVERITIES:
            raise HTTPException(status_code=400, detail=f"severity must be one of {CASE_SEVERITIES}")
        case.setdefault('timeline', []).append(_case_timeline_entry('severity_changed', f'Severity changed from {case.get("severity")} to {payload.severity}', actor))
        case['severity'] = payload.severity

    if payload.assignee is not None and payload.assignee != case.get('assignee'):
        case.setdefault('timeline', []).append(_case_timeline_entry('assigned', f'Assigned to {payload.assignee}' if payload.assignee else 'Unassigned', actor))
        case['assignee'] = payload.assignee or None
        # First assignee is treated as "acknowledged" for SLA purposes — see
        # the same check below for the "moved to investigating" path, either
        # of which stops the acknowledge clock (whichever happens first).
        if case.get('acknowledgedAt') is None and case['assignee']:
            case['acknowledgedAt'] = now

    if payload.mitreTechniques is not None:
        cleaned = [t for t in payload.mitreTechniques if t in _MITRE_TECHNIQUES_BY_ID]
        if cleaned != case.get('mitreTechniques', []):
            case.setdefault('timeline', []).append(_case_timeline_entry('note_added', f'MITRE ATT&CK tags updated by {actor}', actor))
            case['mitreTechniques'] = cleaned

    notify_event = None  # set below if this update crosses the open/closed boundary — dispatched after saving
    if payload.status is not None and payload.status != case.get('status'):
        if payload.status not in CASE_STATUSES:
            raise HTTPException(status_code=400, detail=f"status must be one of {CASE_STATUSES}")
        was_closed = case.get('status') not in CASE_OPEN_STATUSES
        now_closed = payload.status not in CASE_OPEN_STATUSES
        case.setdefault('timeline', []).append(_case_timeline_entry('status_changed', f'Status changed from {case.get("status")} to {payload.status}', actor))
        case['status'] = payload.status
        if case.get('acknowledgedAt') is None and payload.status == 'investigating':
            case['acknowledgedAt'] = now
        if now_closed and not was_closed:
            case['closedAt'] = now
            notify_event = 'closed'
        elif not now_closed and was_closed:
            case['closedAt'] = None
            notify_event = 'reopened'
            # Same "fresh incident" reasoning as the auto-reopen path in
            # _upsert_case_for_violation_inmem — restart the SLA clock and
            # clear both breach markers rather than the case coming back
            # instantly re-flagged from a window that closed months ago.
            case['acknowledgedAt'] = None
            case['slaClockStartedAt'] = now
            case['slaAckBreachNotifiedAt'] = None
            case['slaResolveBreachNotifiedAt'] = None

    case['updatedAt'] = now
    cases[idx] = case
    _save_cases(slug_key, cases)
    _record_audit_event(slug_key, category="case", action="case_updated", actor=actor,
                         target_type="case", target_id=case_id, target_name=case.get('title'),
                         message=f'Case "{case.get("title")}" updated by {actor}')

    if notify_event:
        refs = await _dispatch_case_integrations(slug_key, case, notify_event)
        if refs:
            _attach_external_refs(case, refs)
            _save_cases(slug_key, cases)

    return case

class CaseRunWorkflowPayload(BaseModel):
    workflowId: str

@app.post("/api/cases/{case_id}/run-workflow", dependencies=[Depends(verify_dashboard_token)])
async def run_workflow_from_case(
    case_id: str,
    payload: CaseRunWorkflowPayload,
    background_tasks: BackgroundTasks,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
    access: dict = Depends(require_permission(area="cases", level="manage")),
):
    """Closes a real gap: compliance violations can auto-fire a workflow on
    approval (see approve_compliance_violation), but a Case opened any other
    way (manual, inbound trigger) had no equivalent — an analyst investigating
    a Case could only go to the Devices view, find the device again, and run
    a workflow from there, disconnected from the Case itself. This launches a
    workflow against the Case's linked device directly and records the run on
    the Case's timeline, same bookkeeping as the violation-approval path."""
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing credentials")
    slug_key = x_workspace_slug or 'global'
    cases = _load_cases(slug_key)
    idx = next((i for i, c in enumerate(cases) if c.get('id') == case_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Case not found")
    case = cases[idx]
    if not case.get('deviceId'):
        raise HTTPException(status_code=400, detail="This case has no linked device to target")

    workflows = _load_workflows(slug_key)
    workflow = next((w for w in workflows if w.get('id') == payload.workflowId), None)
    if not workflow:
        raise HTTPException(status_code=404, detail="Workflow not found")
    if _workflow_has_destructive_step(workflow) and not access.get("isSuperAdmin") and not (access.get("role") or {}).get("riskyActions", {}).get("canRunDestructiveWorkflow"):
        raise HTTPException(status_code=403, detail="This workflow contains a destructive MDM action (wipe/unenroll/etc.) — your role isn't permitted to run destructive workflows.")

    devices_res = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
    device = next((d for d in (devices_res.get('items') or []) if d.get('id') == case['deviceId']), None)
    if not device:
        raise HTTPException(status_code=404, detail="Linked device was not found in the current fleet (it may have been unenrolled)")

    device_ref = WorkflowDeviceRef(id=device['id'], displayName=device.get('displayName'), platform=device['platform'], platformDeviceId=device['platformDeviceId'])
    run_record = await _launch_workflow_run(workflow, [device_ref], authorization, x_workspace_slug, background_tasks=background_tasks)
    if run_record is None:
        raise HTTPException(status_code=400, detail="This workflow includes a 'wait' or 'run script and wait for result' step, which requires durable storage. Set DATABASE_URL on the server to enable it.")

    case.setdefault('workflowRunIds', []).append(run_record['id'])
    case.setdefault('timeline', []).append(_case_timeline_entry('workflow_run_linked', f'{dash.get("sub")} ran "{workflow.get("name")}" against {device.get("displayName")}', dash.get('sub')))
    case['updatedAt'] = datetime.now(timezone.utc).isoformat()
    cases[idx] = case
    _save_cases(slug_key, cases)
    _record_audit_event(slug_key, category="case", action="case_workflow_run", actor=dash.get('sub'),
                         target_type="case", target_id=case_id, target_name=case.get('title'),
                         message=f'Workflow "{workflow.get("name")}" run against {device.get("displayName")} from case "{case.get("title")}"')
    return {"case": case, "runId": run_record['id']}

@app.post("/api/cases/{case_id}/retry-integrations", dependencies=[Depends(verify_dashboard_token)])
async def retry_case_integrations(case_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    """Re-fires ticketing/chat dispatch for one case — for when an
    integration failed (bad webhook URL, expired Jira token, etc.), got
    fixed, and the case's original open/close event needs to be replayed
    rather than waiting for the next status change. Event type is inferred
    from the case's current status so this works whether the case is still
    open (retries the 'created'-shaped notification) or already closed
    (retries the close-sync)."""
    slug_key = x_workspace_slug or 'global'
    cases = _load_cases(slug_key)
    idx = next((i for i, c in enumerate(cases) if c.get('id') == case_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Case not found")
    case = cases[idx]
    event_type = 'created' if case.get('status') in CASE_OPEN_STATUSES else 'closed'
    refs = await _dispatch_case_integrations(slug_key, case, event_type)
    if refs:
        _attach_external_refs(case, refs)
    case['updatedAt'] = datetime.now(timezone.utc).isoformat()
    cases[idx] = case
    _save_cases(slug_key, cases)
    _record_audit_event(slug_key, category="case", action="integration_retry", actor=dash.get('sub'),
                         target_type="case", target_id=case_id, target_name=case.get('title'),
                         message=f'Integration dispatch retried for case "{case.get("title")}" by {dash.get("sub")}')
    return case

@app.post("/api/cases/{case_id}/sync-ticket-status", dependencies=[Depends(verify_dashboard_token)])
async def sync_case_ticket_status(case_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    """Manual, on-demand version of what ticket_status_sync_loop does on its
    own schedule — pulls live status from Jira/ServiceNow for whatever
    ticket(s) are linked to this case (the inbound half of ticket sync; see
    the module comment above _sync_case_ticket_refs). If a ticket just came
    back resolved and its integration has autoCloseCaseOnRemoteResolve
    enabled, resolves the case to match; otherwise just records the status
    on the case's externalRefs/timeline for the analyst to act on."""
    slug_key = x_workspace_slug or 'global'
    cases = _load_cases(slug_key)
    idx = next((i for i, c in enumerate(cases) if c.get('id') == case_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Case not found")
    case = cases[idx]
    refs = case.get('externalRefs') or []
    if not any(r.get('type') in ('jira', 'servicenow') for r in refs):
        raise HTTPException(status_code=400, detail="This case has no linked Jira or ServiceNow ticket to sync")

    integrations = _load_integrations(slug_key)
    integrations_by_type = {i['type']: i for i in integrations if i.get('type') in ('jira', 'servicenow')}

    async with httpx.AsyncClient() as client:
        newly_resolved = await _sync_case_ticket_refs(client, integrations_by_type, case)

    auto_closed = False
    if newly_resolved and case.get('status') in CASE_OPEN_STATUSES:
        ref = newly_resolved[0]
        integ = integrations_by_type.get(ref.get('type'))
        if integ and integ.get('autoCloseCaseOnRemoteResolve'):
            _close_case_from_remote_resolve(case, ref)
            auto_closed = True
        else:
            case.setdefault('timeline', []).append(_case_timeline_entry(
                'note_added', f'Linked {ref.get("type", "").title()} ticket {ref.get("id")} is now marked done externally (auto-close is off for this integration)',
            ))

    case['updatedAt'] = datetime.now(timezone.utc).isoformat()
    cases[idx] = case
    _save_cases(slug_key, cases)
    _record_audit_event(slug_key, category="case", action="case_ticket_synced", actor=dash.get('sub'),
                         target_type="case", target_id=case_id, target_name=case.get('title'),
                         message=f'Ticket status synced for case "{case.get("title")}" by {dash.get("sub")}' + (' — auto-resolved' if auto_closed else ''))
    return {"case": case, "autoClosed": auto_closed}

@app.post("/api/cases/bulk-update", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="cases", level="manage", action="canBulkTriage"))])
async def bulk_update_cases(payload: CaseBulkUpdatePayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    """Bulk close/assign for the case list — reuses update_case per id rather
    than duplicating its status-transition/notify/timeline logic, so bulk
    actions get exactly the same ticketing-dispatch and timeline behavior as
    updating one case at a time."""
    if payload.status is None and payload.assignee is None:
        raise HTTPException(status_code=400, detail="Provide at least one of status or assignee")
    per_case_patch = CaseUpdatePayload(status=payload.status, assignee=payload.assignee)
    updated, failed = [], []
    for cid in payload.caseIds:
        try:
            await update_case(cid, per_case_patch, x_workspace_slug, dash)
            updated.append(cid)
        except HTTPException as e:
            failed.append({"id": cid, "error": e.detail})
    return {"updated": updated, "failed": failed}

@app.post("/api/cases/{case_id}/notes", dependencies=[Depends(verify_dashboard_token)])
async def add_case_note(case_id: str, payload: CaseNotePayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    if not payload.text or not payload.text.strip():
        raise HTTPException(status_code=400, detail="Note text is required")
    slug_key = x_workspace_slug or 'global'
    cases = _load_cases(slug_key)
    idx = next((i for i, c in enumerate(cases) if c.get('id') == case_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Case not found")
    now = datetime.now(timezone.utc).isoformat()
    actor = dash.get('sub')
    cases[idx].setdefault('notes', []).append({"id": str(uuid.uuid4()), "authorEmail": actor, "text": payload.text.strip(), "createdAt": now})
    cases[idx].setdefault('timeline', []).append(_case_timeline_entry('note_added', f'{actor} added a note', actor))
    cases[idx]['updatedAt'] = now
    await _auto_enrich_case_from_text(slug_key, cases[idx], payload.text, actor)
    _save_cases(slug_key, cases)
    return cases[idx]

# ─── CASE SLA TRACKING ───
# Cases already carry every timestamp needed for this (createdAt, closedAt,
# assignee) except one — there was no record of when an analyst actually
# picked a case up, only when it was created and when it was closed. That's
# "acknowledgedAt" (set above in update_case, the first time a case gets an
# assignee OR moves to 'investigating' — whichever happens first) plus
# "slaClockStartedAt", a separate anchor that starts equal to createdAt but
# resets on reopen (see both reopen paths above) so a case that recurs isn't
# born already breached from a window that closed months ago.
#
# Per-severity thresholds are workspace-configurable (Settings > Case SLA);
# breach status itself is never stored — _case_sla_status recomputes it fresh
# on every read, so tightening a threshold takes effect on every existing
# open case immediately instead of only ones opened afterward. The one thing
# that IS persisted is a one-time "already notified" marker per case per
# clock (slaAckBreachNotifiedAt/slaResolveBreachNotifiedAt), written by
# case_sla_monitor_loop below the first time each clock crosses its
# threshold, so a case that's been breached for days doesn't renotify every
# tick.
CASE_SLA_DIR = os.path.join(DATA_DIR, "case_sla")
if not os.path.exists(CASE_SLA_DIR):
    os.makedirs(CASE_SLA_DIR)

DEFAULT_CASE_SLA_THRESHOLDS = {
    "low":      {"acknowledgeMinutes": 480, "resolveMinutes": 4320},  # 8h / 3d
    "medium":   {"acknowledgeMinutes": 240, "resolveMinutes": 1440},  # 4h / 1d
    "high":     {"acknowledgeMinutes": 60,  "resolveMinutes": 480},   # 1h / 8h
    "critical": {"acknowledgeMinutes": 15,  "resolveMinutes": 240},   # 15m / 4h
}

def _case_sla_file(slug: str) -> str:
    return os.path.join(CASE_SLA_DIR, f"{_slug_clean(slug)}.json")

_register_legacy_json('case_sla_settings', lambda slug, key: _case_sla_file(slug))

def _backfill_case_sla_thresholds(settings: Dict[str, Any]) -> Dict[str, Any]:
    thresholds = settings.setdefault('thresholds', {})
    for sev, defaults in DEFAULT_CASE_SLA_THRESHOLDS.items():
        thresholds.setdefault(sev, dict(defaults))  # backfills any severity added after a workspace's settings were first saved
    return settings

def _load_case_sla_settings(slug: str) -> Dict[str, Any]:
    return _store_load(
        slug, 'case_sla_settings',
        lambda: {"enabled": True, "notifyOnBreach": True, "thresholds": {}},
        post_load=_backfill_case_sla_thresholds,
    )

def _save_case_sla_settings(slug: str, settings: Dict[str, Any]):
    _store_save(slug, 'case_sla_settings', settings)

def _case_sla_status(case: Dict[str, Any], thresholds: Dict[str, Any]) -> Dict[str, Any]:
    """Pure function, no I/O — safe to call once per case on every /api/cases
    read. Either half of the result goes quiet (both fields None) once its
    own clock has stopped: ackDueAt/ackBreached once acknowledgedAt is set,
    resolveDueAt/resolveBreached once the case is no longer open."""
    result = {"ackDueAt": None, "ackBreached": False, "resolveDueAt": None, "resolveBreached": False}
    anchor = case.get('slaClockStartedAt') or case.get('createdAt')
    if not anchor:
        return result
    try:
        anchor_dt = datetime.fromisoformat(str(anchor).replace('Z', '+00:00'))
    except Exception:
        return result
    sev = case.get('severity') or 'medium'
    sla = thresholds.get(sev) or DEFAULT_CASE_SLA_THRESHOLDS.get(sev) or DEFAULT_CASE_SLA_THRESHOLDS['medium']
    now = datetime.now(timezone.utc)

    if case.get('acknowledgedAt') is None:
        ack_due = anchor_dt + timedelta(minutes=sla.get('acknowledgeMinutes', 240))
        result['ackDueAt'] = ack_due.isoformat()
        result['ackBreached'] = now > ack_due

    if case.get('status') in CASE_OPEN_STATUSES:
        resolve_due = anchor_dt + timedelta(minutes=sla.get('resolveMinutes', 1440))
        result['resolveDueAt'] = resolve_due.isoformat()
        result['resolveBreached'] = now > resolve_due

    return result

class CaseSlaThresholdPayload(BaseModel):
    acknowledgeMinutes: int = 240
    resolveMinutes: int = 1440

class CaseSlaSettingsPayload(BaseModel):
    enabled: bool = True
    notifyOnBreach: bool = True
    thresholds: Dict[str, CaseSlaThresholdPayload] = {}

@app.get("/api/case-sla-settings", dependencies=[Depends(verify_dashboard_token)])
async def get_case_sla_settings(x_workspace_slug: Optional[str] = Header(None)):
    return _load_case_sla_settings(x_workspace_slug or 'global')

@app.put("/api/case-sla-settings", dependencies=[Depends(verify_dashboard_token)])
async def update_case_sla_settings(payload: CaseSlaSettingsPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    thresholds = {}
    for sev in CASE_SEVERITIES:
        t = payload.thresholds.get(sev)
        defaults = DEFAULT_CASE_SLA_THRESHOLDS[sev]
        thresholds[sev] = {
            "acknowledgeMinutes": max(1, t.acknowledgeMinutes) if t else defaults['acknowledgeMinutes'],
            "resolveMinutes": max(1, t.resolveMinutes) if t else defaults['resolveMinutes'],
        }
    settings = {"enabled": payload.enabled, "notifyOnBreach": payload.notifyOnBreach, "thresholds": thresholds}
    _save_case_sla_settings(slug_key, settings)
    _record_audit_event(slug_key, category="settings", action="case_sla_updated", actor=dash.get('sub'),
                         message=f'Case SLA settings updated by {dash.get("sub")} — {"enabled" if payload.enabled else "disabled"}')
    return settings

# ─── CASE AUTO-RUN RULES ───
# Compliance Policy violations can auto-fire a workflow (autoRun) and Inbound
# Webhook Triggers always do — but a Case opened manually (POST /api/cases,
# source='manual') had no unattended path at all; an analyst always had to
# open it and click "Run workflow" themselves, even for a case severe enough
# that everyone would want the same response every time. This closes that
# specific gap: an ordered list of rules, evaluated once, at creation time
# only, against manually-created Cases only. Deliberately narrower than the
# Compliance engine in two ways: (1) it never re-evaluates a Case later
# (a Case is a one-shot event here, not a standing condition to re-check
# on a schedule — reopening a case does NOT re-run rules), and (2) it isn't
# wired into the Compliance-violation or Trigger paths, which already have
# their own auto-fire mechanism and would otherwise double-fire a second
# workflow on top of the one they already ran.
CASE_AUTORUN_RULES_DIR = os.path.join(DATA_DIR, "case_autorun_rules")
if not os.path.exists(CASE_AUTORUN_RULES_DIR):
    os.makedirs(CASE_AUTORUN_RULES_DIR)

def _case_autorun_rules_file(slug: str) -> str:
    return os.path.join(CASE_AUTORUN_RULES_DIR, f"{_slug_clean(slug)}.json")

_register_legacy_json('case_autorun_rules', lambda slug, key: _case_autorun_rules_file(slug))

def _load_case_autorun_rules(slug: str) -> List[Dict[str, Any]]:
    return _store_load(slug, 'case_autorun_rules', list)

def _save_case_autorun_rules(slug: str, rules: List[Dict[str, Any]]):
    _store_save(slug, 'case_autorun_rules', rules)

class CaseAutoRunRulePayload(BaseModel):
    name: str
    enabled: bool = True
    minSeverity: str = "high"  # only manually-created Cases at/above this severity match
    # Empty = no MITRE filter (matches regardless of tags). Non-empty =
    # the Case must carry at least one of these technique ids.
    mitreTechniques: List[str] = []
    workflowId: str
    # Same acknowledgment gate as Compliance Policies' autoRun — see
    # _workflow_has_destructive_step. Required to save enabled=True with a
    # destructive workflow linked.
    autoRunDestructiveAck: bool = False
    # Simple rolling-window safety valve rather than the Compliance engine's
    # full trip/circuit-breaker: manually-created Cases are one-shot events,
    # not a periodic re-evaluation of the same entity, so there's no
    # "still-violating-and-still-failing" streak to detect the same way —
    # what actually matters here is capping a sudden burst (e.g. a script or
    # integration creating many Cases in a short window) from firing a
    # destructive workflow unattended against far more devices than intended.
    maxFiresPerHour: int = 10

@app.get("/api/case-autorun-rules", dependencies=[Depends(verify_dashboard_token)])
async def list_case_autorun_rules(x_workspace_slug: Optional[str] = Header(None)):
    return {"items": _load_case_autorun_rules(x_workspace_slug or 'global')}

def _validate_case_autorun_destructive(slug_key: str, payload: CaseAutoRunRulePayload):
    if not payload.enabled:
        return
    workflow = next((w for w in _load_workflows(slug_key) if w.get('id') == payload.workflowId), None)
    if _workflow_has_destructive_step(workflow) and not payload.autoRunDestructiveAck:
        raise HTTPException(
            status_code=400,
            detail=f'Workflow "{workflow.get("name")}" contains a destructive action (wipe, unenroll, disable, etc.) — enabling this rule requires explicit acknowledgment.',
        )

@app.post("/api/case-autorun-rules", dependencies=[Depends(verify_dashboard_token)])
async def create_case_autorun_rule(payload: CaseAutoRunRulePayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    if payload.minSeverity not in CASE_SEVERITIES:
        raise HTTPException(status_code=400, detail=f"minSeverity must be one of {CASE_SEVERITIES}")
    slug_key = x_workspace_slug or 'global'
    _validate_case_autorun_destructive(slug_key, payload)
    rules = _load_case_autorun_rules(slug_key)
    now = datetime.now(timezone.utc).isoformat()
    new_rule = payload.dict()
    new_rule.update({"id": str(uuid.uuid4()), "createdAt": now, "updatedAt": now, "recentFires": []})
    rules.append(new_rule)
    _save_case_autorun_rules(slug_key, rules)
    _record_audit_event(slug_key, category="case", action="case_autorun_rule_created", actor=dash.get('sub'),
                         target_type="case_autorun_rule", target_id=new_rule['id'], target_name=new_rule.get('name'),
                         message=f'Case Auto-Run rule "{new_rule.get("name")}" created by {dash.get("sub")}')
    return new_rule

@app.put("/api/case-autorun-rules/{rule_id}", dependencies=[Depends(verify_dashboard_token)])
async def update_case_autorun_rule(rule_id: str, payload: CaseAutoRunRulePayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    if payload.minSeverity not in CASE_SEVERITIES:
        raise HTTPException(status_code=400, detail=f"minSeverity must be one of {CASE_SEVERITIES}")
    slug_key = x_workspace_slug or 'global'
    _validate_case_autorun_destructive(slug_key, payload)
    rules = _load_case_autorun_rules(slug_key)
    idx = next((i for i, r in enumerate(rules) if r.get('id') == rule_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Case Auto-Run rule not found")
    updated = payload.dict()
    updated.update({
        "id": rule_id, "createdAt": rules[idx].get('createdAt'), "updatedAt": datetime.now(timezone.utc).isoformat(),
        "recentFires": rules[idx].get('recentFires', []),  # preserve rate-limit history across an edit
    })
    rules[idx] = updated
    _save_case_autorun_rules(slug_key, rules)
    _record_audit_event(slug_key, category="case", action="case_autorun_rule_updated", actor=dash.get('sub'),
                         target_type="case_autorun_rule", target_id=rule_id, target_name=updated.get('name'),
                         message=f'Case Auto-Run rule "{updated.get("name")}" updated by {dash.get("sub")}')
    return updated

@app.delete("/api/case-autorun-rules/{rule_id}", dependencies=[Depends(verify_dashboard_token)])
async def delete_case_autorun_rule(rule_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    rules = _load_case_autorun_rules(slug_key)
    deleted = next((r for r in rules if r.get('id') == rule_id), None)
    remaining = [r for r in rules if r.get('id') != rule_id]
    _save_case_autorun_rules(slug_key, remaining)
    if deleted:
        _record_audit_event(slug_key, category="case", action="case_autorun_rule_deleted", actor=dash.get('sub'), severity="warning",
                             target_type="case_autorun_rule", target_id=rule_id, target_name=deleted.get('name'),
                             message=f'Case Auto-Run rule "{deleted.get("name")}" deleted by {dash.get("sub")}')
    return {"status": "ok"}

async def _try_case_autorun(slug_key: str, case: dict, authorization: Optional[str], x_workspace_slug: Optional[str], background_tasks: Optional[BackgroundTasks]) -> Optional[dict]:
    """Evaluated once, right after a manually-created Case is saved (see
    create_case) — walks enabled rules in list order, first match wins.
    A rule "matches but can't fire" (no device on the case, linked workflow
    missing, or the rate cap is hit) stops evaluation rather than falling
    through to a weaker rule, so a capped/misconfigured rule can't be
    silently bypassed by whatever's next in the list. Returns the launched
    run_record, or None if nothing fired."""
    if not case.get('deviceId') or not authorization:
        return None
    rules = _load_case_autorun_rules(slug_key)
    if not rules:
        return None
    severity_rank = CASE_SEVERITY_RANK.get(case.get('severity', 'medium'), 1)
    case_techniques = set(case.get('mitreTechniques') or [])

    for rule in rules:
        if not rule.get('enabled', True):
            continue
        if severity_rank < CASE_SEVERITY_RANK.get(rule.get('minSeverity', 'high'), 2):
            continue
        rule_techniques = set(rule.get('mitreTechniques') or [])
        if rule_techniques and not (rule_techniques & case_techniques):
            continue

        workflow = next((w for w in _load_workflows(slug_key) if w.get('id') == rule.get('workflowId')), None)
        if not workflow:
            return None  # matched but misconfigured — don't fall through
        if _workflow_has_destructive_step(workflow) and not rule.get('autoRunDestructiveAck'):
            # Defense in depth, same reasoning as the Compliance engine's
            # equivalent check — catches a workflow edited to add a
            # destructive step after this rule was last saved with the ack.
            return None

        now = datetime.now(timezone.utc)
        cutoff = now - timedelta(hours=1)
        recent_fires = []
        for ts in (rule.get('recentFires') or []):
            try:
                dt = datetime.fromisoformat(ts)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                if dt >= cutoff:
                    recent_fires.append(ts)
            except Exception:
                pass
        max_per_hour = rule.get('maxFiresPerHour') or 10
        if len(recent_fires) >= max_per_hour:
            _record_audit_event(slug_key, category="case", action="case_autorun_rate_limited", actor="system", severity="warning",
                                 target_type="case", target_id=case.get('id'), target_name=case.get('title'),
                                 message=f'Case Auto-Run rule "{rule.get("name")}" matched case "{case.get("title")}" but hit its {max_per_hour}/hour rate cap — not fired')
            return None

        devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
        device = next((d for d in (devices_resp.get('items') or []) if d.get('id') == case['deviceId']), None)
        if not device:
            return None

        device_ref = WorkflowDeviceRef(id=device['id'], displayName=device.get('displayName'), platform=device['platform'], platformDeviceId=device['platformDeviceId'])
        run_record = await _launch_workflow_run(workflow, [device_ref], authorization, x_workspace_slug, background_tasks=background_tasks)
        if run_record is None:
            return None

        recent_fires.append(now.isoformat())
        all_rules = _load_case_autorun_rules(slug_key)
        idx = next((i for i, r in enumerate(all_rules) if r.get('id') == rule.get('id')), None)
        if idx is not None:
            all_rules[idx]['recentFires'] = recent_fires[-200:]
            _save_case_autorun_rules(slug_key, all_rules)

        _record_audit_event(slug_key, category="case", action="case_autorun_fired", actor="system",
                             target_type="case", target_id=case.get('id'), target_name=case.get('title'),
                             message=f'Case Auto-Run rule "{rule.get("name")}" auto-ran "{workflow.get("name")}" against {device.get("displayName")} for case "{case.get("title")}"')
        return run_record
    return None

# ─── INBOUND WEBHOOK TRIGGERS ───
# Lets an external system (EDR, firewall, SIEM, IDS — anything that can POST
# JSON to a URL) fire a specific Workflow directly, without going through the
# Compliance Policy detection loop. Each Trigger gets its own self-contained
# URL — the trigger id AND its secret both live in the path itself, the same
# pattern Slack/Teams/PagerDuty use for their own incoming webhooks — so it
# works from any tool that can send a plain POST, no custom headers required.
# Firing runs the linked workflow using this workspace's automation
# credential (the same one the compliance auto-fire path already uses),
# since the caller here is always an unattended external system.
TRIGGERS_DIR = os.path.join(DATA_DIR, "triggers")
if not os.path.exists(TRIGGERS_DIR):
    os.makedirs(TRIGGERS_DIR)

def _triggers_file(slug: str) -> str:
    return os.path.join(TRIGGERS_DIR, f"{_slug_clean(slug)}.json")

_register_legacy_json('triggers', lambda slug, key: _triggers_file(slug))

def _load_triggers(slug: str) -> List[Dict[str, Any]]:
    return _store_load(slug, 'triggers', list)

def _save_triggers(slug: str, triggers: List[Dict[str, Any]]):
    _store_save(slug, 'triggers', triggers)

def _find_trigger_by_id(trigger_id: str) -> Optional[tuple]:
    """Scans every workspace's trigger store to find one by id — the inbound
    /fire URL is deliberately self-contained (id + secret only, no
    X-Workspace-Slug an external caller would have to be configured to send),
    so resolving which workspace owns a given trigger has to happen by search
    rather than direct lookup. Cheap in practice — one small SQLite row set
    per workspace. Returns (slug, trigger) or None."""
    for slug in _known_workspace_slugs():
        triggers = _load_triggers(slug)
        match = next((t for t in triggers if t.get('id') == trigger_id), None)
        if match:
            return slug, match
    return None

class TriggerPayload(BaseModel):
    name: str
    description: Optional[str] = ""
    workflowId: str
    enabled: bool = True
    # Auto-opens (or reuses/reopens) a Case every time this trigger fires —
    # same Case object Compliance Violations use, source="workflow_trigger".
    openCase: bool = False
    caseSeverity: str = "medium"
    # A key expected in the inbound JSON body; its value is matched against
    # each device's serialNumber, id, then mdmUser.email (see
    # _resolve_trigger_device) — covers the shapes most EDR/SIEM tools
    # already send without requiring them to know this app's field names.
    # Leave blank for a device-less trigger (workflow only uses
    # notification/HTTP steps, no MDM action/script steps needing a target).
    deviceLookupField: Optional[str] = None

@app.get("/api/triggers", dependencies=[Depends(verify_dashboard_token)])
async def list_triggers(x_workspace_slug: Optional[str] = Header(None)):
    return {"items": _load_triggers(x_workspace_slug or 'global')}

@app.post("/api/triggers", dependencies=[Depends(verify_dashboard_token)])
async def create_trigger(payload: TriggerPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    if not any(w.get('id') == payload.workflowId for w in _load_workflows(slug_key)):
        raise HTTPException(status_code=400, detail="Linked workflow not found")
    triggers = _load_triggers(slug_key)
    now = datetime.now(timezone.utc).isoformat()
    trigger_id = str(uuid.uuid4())
    new_trigger = payload.dict()
    new_trigger.update({
        "id": trigger_id, "secret": secrets.token_urlsafe(24),
        "createdBy": dash.get('sub'), "createdAt": now, "updatedAt": now,
        "lastFiredAt": None, "fireCount": 0,
    })
    triggers.append(new_trigger)
    _save_triggers(slug_key, triggers)
    _record_audit_event(slug_key, category="trigger", action="trigger_created", actor=dash.get('sub'),
                         target_type="trigger", target_id=trigger_id, target_name=new_trigger.get('name'),
                         message=f'Inbound webhook trigger "{new_trigger.get("name")}" created by {dash.get("sub")}')
    return new_trigger

@app.put("/api/triggers/{trigger_id}", dependencies=[Depends(verify_dashboard_token)])
async def update_trigger(trigger_id: str, payload: TriggerPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    if not any(w.get('id') == payload.workflowId for w in _load_workflows(slug_key)):
        raise HTTPException(status_code=400, detail="Linked workflow not found")
    triggers = _load_triggers(slug_key)
    idx = next((i for i, t in enumerate(triggers) if t.get('id') == trigger_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Trigger not found")
    existing = triggers[idx]
    updated = payload.dict()
    updated.update({
        "id": trigger_id, "secret": existing.get('secret'),
        "createdBy": existing.get('createdBy'), "createdAt": existing.get('createdAt'),
        "updatedAt": datetime.now(timezone.utc).isoformat(),
        "lastFiredAt": existing.get('lastFiredAt'), "fireCount": existing.get('fireCount', 0),
    })
    triggers[idx] = updated
    _save_triggers(slug_key, triggers)
    _record_audit_event(slug_key, category="trigger", action="trigger_updated", actor=dash.get('sub'),
                         target_type="trigger", target_id=trigger_id, target_name=updated.get('name'),
                         message=f'Inbound webhook trigger "{updated.get("name")}" updated by {dash.get("sub")}')
    return updated

@app.delete("/api/triggers/{trigger_id}", dependencies=[Depends(verify_dashboard_token)])
async def delete_trigger(trigger_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    triggers = _load_triggers(slug_key)
    idx = next((i for i, t in enumerate(triggers) if t.get('id') == trigger_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Trigger not found")
    removed = triggers.pop(idx)
    _save_triggers(slug_key, triggers)
    _record_audit_event(slug_key, category="trigger", action="trigger_deleted", actor=dash.get('sub'), severity="warning",
                         target_type="trigger", target_id=trigger_id, target_name=removed.get('name'),
                         message=f'Inbound webhook trigger "{removed.get("name")}" deleted by {dash.get("sub")} — its URL stops working immediately')
    return {"status": "ok"}

@app.post("/api/triggers/{trigger_id}/rotate-secret", dependencies=[Depends(verify_dashboard_token)])
async def rotate_trigger_secret(trigger_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    triggers = _load_triggers(slug_key)
    idx = next((i for i, t in enumerate(triggers) if t.get('id') == trigger_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Trigger not found")
    triggers[idx]['secret'] = secrets.token_urlsafe(24)
    triggers[idx]['updatedAt'] = datetime.now(timezone.utc).isoformat()
    _save_triggers(slug_key, triggers)
    _record_audit_event(slug_key, category="trigger", action="trigger_secret_rotated", actor=dash.get('sub'), severity="warning",
                         target_type="trigger", target_id=trigger_id, target_name=triggers[idx].get('name'),
                         message=f'Webhook URL rotated for trigger "{triggers[idx].get("name")}" by {dash.get("sub")} — the old URL stops working immediately')
    return triggers[idx]

def _resolve_trigger_device(trigger: dict, body: Dict[str, Any], devices: List[dict]) -> Optional[dict]:
    field = trigger.get('deviceLookupField')
    if not field:
        return None
    raw_value = body.get(field)
    if raw_value is None:
        return None
    value = str(raw_value).strip().lower()
    if not value:
        return None
    for d in devices:
        if str(d.get('serialNumber') or '').strip().lower() == value:
            return d
        if str(d.get('id') or '').strip().lower() == value:
            return d
        mdm_user = d.get('mdmUser') or {}
        if str(mdm_user.get('email') or '').strip().lower() == value:
            return d
    return None

@app.post("/api/triggers/fire/{trigger_id}/{secret}")
async def fire_trigger(trigger_id: str, secret: str, request: Request):
    """The actual inbound URL — deliberately NOT dashboard-token protected
    (the caller is an external system, not a logged-in admin) and
    deliberately not header-based auth (many webhook-capable SIEM/EDR tools
    can only be configured with a URL, not custom headers). Both the trigger
    id and its secret live in the path, same pattern Slack/Teams/PagerDuty
    use for their own incoming webhooks."""
    try:
        body = await request.json()
        if not isinstance(body, dict):
            body = {}
    except Exception:
        body = {}

    found = _find_trigger_by_id(trigger_id)
    if found is None:
        raise HTTPException(status_code=404, detail="Unknown trigger")
    slug_key, trigger = found
    if not hmac.compare_digest(secret, trigger.get('secret') or ''):
        raise HTTPException(status_code=401, detail="Invalid trigger secret")
    if not trigger.get('enabled', True):
        raise HTTPException(status_code=403, detail="This trigger is disabled")

    workflow = next((w for w in _load_workflows(slug_key) if w.get('id') == trigger.get('workflowId')), None)
    if not workflow:
        raise HTTPException(status_code=400, detail="Linked workflow no longer exists")

    authorization = await _get_automation_bearer(slug_key)
    if not authorization:
        raise HTTPException(status_code=503, detail="No automation credential configured for this workspace — set one in Settings > Workspace Automation so unattended triggers can run workflows.")

    devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=slug_key)
    devices = devices_resp.get('items', [])
    matched_device = _resolve_trigger_device(trigger, body, devices)

    device_refs: List[WorkflowDeviceRef] = []
    if matched_device:
        device_refs = [WorkflowDeviceRef(
            id=matched_device['id'], displayName=matched_device.get('displayName'),
            platform=matched_device['platform'], platformDeviceId=matched_device['platformDeviceId'],
            serialNumber=matched_device.get('serialNumber'), osVersion=matched_device.get('osVersion'),
            manufacturer=matched_device.get('manufacturer'), model=matched_device.get('model'),
            udid=matched_device.get('udid'), mdmUser=matched_device.get('mdmUser'),
        )]
    elif trigger.get('deviceLookupField'):
        # Configured to look a device up but couldn't find one — fail loudly
        # rather than silently running a device-scoped workflow against
        # nobody, which would look like success but do nothing.
        _record_audit_event(slug_key, category="trigger", action="trigger_fired_no_device", actor="external", severity="warning",
                             target_type="trigger", target_id=trigger_id, target_name=trigger.get('name'),
                             message=f'Trigger "{trigger.get("name")}" fired but no device matched {trigger.get("deviceLookupField")}={body.get(trigger.get("deviceLookupField"))!r} — workflow not run')
        raise HTTPException(status_code=404, detail=f"No device matched on field '{trigger.get('deviceLookupField')}'")

    run_record = await _launch_workflow_run(workflow, device_refs, authorization, slug_key)
    if run_record is None:
        raise HTTPException(status_code=400, detail="This workflow includes a 'wait' step, which requires durable storage (DATABASE_URL) not configured on this server.")

    triggers = _load_triggers(slug_key)
    idx = next((i for i, t in enumerate(triggers) if t.get('id') == trigger_id), None)
    now_iso = datetime.now(timezone.utc).isoformat()
    if idx is not None:
        triggers[idx]['lastFiredAt'] = now_iso
        triggers[idx]['fireCount'] = triggers[idx].get('fireCount', 0) + 1
        _save_triggers(slug_key, triggers)

    case_id = None
    if trigger.get('openCase'):
        cases = _load_cases(slug_key)
        title = f'Trigger: {trigger.get("name")}' + (f' — {matched_device.get("displayName")}' if matched_device else '')
        new_case = {
            "id": str(uuid.uuid4()), "title": title, "status": "open",
            "severity": trigger.get('caseSeverity') or 'medium', "source": "workflow_trigger",
            "deviceId": matched_device.get('id') if matched_device else None,
            "deviceName": matched_device.get('displayName') if matched_device else None,
            "segmentId": matched_device.get('segmentId') if matched_device else None,
            "policyId": None, "policyName": None, "violationIds": [],
            "workflowRunIds": [run_record['id']], "assignee": None,
            "createdBy": "system", "createdAt": now_iso, "updatedAt": now_iso, "closedAt": None,
            "acknowledgedAt": None, "slaClockStartedAt": now_iso, "slaAckBreachNotifiedAt": None, "slaResolveBreachNotifiedAt": None,
            "notes": [], "timeline": [_case_timeline_entry('created', f'Case opened by inbound trigger "{trigger.get("name")}" — ran workflow "{workflow.get("name")}"')],
        }
        cases.insert(0, new_case)
        _save_cases(slug_key, cases)
        case_id = new_case['id']
        refs = await _dispatch_case_integrations(slug_key, new_case, 'created')
        if refs:
            _attach_external_refs(new_case, refs)
            _save_cases(slug_key, cases)

    _record_audit_event(slug_key, category="trigger", action="trigger_fired", actor="external",
                         target_type="workflow", target_id=workflow.get('id'), target_name=workflow.get('name'),
                         message=f'Inbound trigger "{trigger.get("name")}" fired — ran "{workflow.get("name")}"' + (f' against {matched_device.get("displayName")}' if matched_device else ' (no device context)'))

    return {"status": "ok", "workflowRunId": run_record['id'], "caseId": case_id, "matchedDevice": matched_device.get('displayName') if matched_device else None}

# ─── APPLIVERY EVENT WEBHOOK ───
# Applivery has its own native webhook system — configured entirely inside
# Applivery's own Workspace/App > Integrations settings (see "Custom
# webhooks", https://www.applivery.com/docs/platform/integrations/webhooks/),
# where an admin pastes a URL and picks which events to send. There's no API
# on Applivery's side for us to register as a subscriber programmatically —
# the admin has to do that paste-and-pick step in Applivery's own UI — so
# this feature is a purpose-built RECEIVER for that payload shape, paired
# with a per-event-type rule engine (log / open Case / auto-run Workflow),
# giving external Applivery-side changes on devices ({os}_device_enrolled,
# {os}_device_added_mdm_user) and on the system as a whole (build_created,
# bug_created, feedback_created, certificate_will_expire,
# apple_push_certification_renovation, {os}_enrollment-token_created,
# inventory item events) the same detection→automation depth Compliance
# Policies and Inbound Webhook Triggers already have.
#
# Applivery's own event catalog is still thin today — a handful of build/
# device/feedback events — but is expected to grow (confirmed with their
# PM). Hard-coding a fixed enum here would mean a code change every time
# Applivery adds one, so instead every event's normalized "action" key
# becomes its own configurable rule the FIRST TIME it's ever received,
# auto-registered disabled/log-only. An admin just flips on automation for
# whichever ones show up — zero code changes needed as Applivery's catalog
# expands.
APPLIVERY_WEBHOOK_DIR = os.path.join(DATA_DIR, "applivery_webhook")
if not os.path.exists(APPLIVERY_WEBHOOK_DIR):
    os.makedirs(APPLIVERY_WEBHOOK_DIR)

# Applivery prefixes several action keys with the platform they occurred on
# (apple_device_enrolled, android_device_enrolled, windows_device_enrolled…)
# — stripped off so "device enrolled" is ONE configurable rule covering
# every platform, with the platform surfaced separately per received event
# instead of fragmenting into 3 near-identical rules an admin has to keep in
# sync with each other.
APPLIVERY_WEBHOOK_OS_PREFIXES = ("apple_", "android_", "windows_", "aosp_", "macos_", "ios_")

APPLIVERY_WEBHOOK_EVENT_LABELS = {
    "device_enrolled": "Device enrolled",
    "device_added_mdm_user": "Device MDM user changed",
    "enrollment-token_created": "Enrollment token created",
    "build_created": "Build uploaded",
    "build_processed": "Build processed",
    "bug_created": "Bug report received",
    "feedback_created": "Feedback report received",
    "certificate_will_expire": "App certificate expiring",
    "push_certification_renovation": "Apple push certificate expiring",
}

def _applivery_webhook_file(slug: str) -> str:
    return os.path.join(APPLIVERY_WEBHOOK_DIR, f"{_slug_clean(slug)}.json")

_register_legacy_json('applivery_webhook_config', lambda slug, key: _applivery_webhook_file(slug))

def _load_applivery_webhook_config(slug: str) -> Dict[str, Any]:
    return _store_load(slug, 'applivery_webhook_config', lambda: {
        "enabled": True, "secret": None, "rules": [], "recentEvents": [], "receivedCount": 0, "lastReceivedAt": None
    })

def _save_applivery_webhook_config(slug: str, config: Dict[str, Any]):
    _store_save(slug, 'applivery_webhook_config', config)

def _find_applivery_webhook_config_by_secret(secret: str) -> Optional[tuple]:
    """Scans every workspace's config to find the one whose secret matches —
    same reasoning as _find_trigger_by_id: the inbound URL is self-contained
    (secret only, no X-Workspace-Slug an external caller would have to be
    configured to send — and Applivery's own webhook UI only takes a URL),
    so resolving which workspace owns it happens by search rather than
    direct lookup. Returns (slug, config) or None."""
    for slug in _known_workspace_slugs():
        config = _load_applivery_webhook_config(slug)
        if config.get('secret') and hmac.compare_digest(config['secret'], secret):
            return slug, config
    return None

def _normalize_applivery_webhook_action(action: str) -> tuple:
    """Splits a raw Applivery `action` value like "apple_device_enrolled"
    into (os, canonical_key) — e.g. ("apple", "device_enrolled"). Actions
    with no OS prefix (build_created, bug_created, certificate_will_expire…)
    return (None, action) unchanged."""
    raw = (action or "").strip()
    for prefix in APPLIVERY_WEBHOOK_OS_PREFIXES:
        if raw.startswith(prefix):
            return prefix.rstrip('_'), raw[len(prefix):]
    return None, raw

def _applivery_webhook_label(canonical_key: str) -> str:
    if canonical_key in APPLIVERY_WEBHOOK_EVENT_LABELS:
        return APPLIVERY_WEBHOOK_EVENT_LABELS[canonical_key]
    return canonical_key.replace('_', ' ').replace('-', ' ').strip().title() or "Unknown event"

def _applivery_webhook_extract_device_hint(body: Dict[str, Any]) -> List[str]:
    """Applivery hasn't published exact field names for every event's device
    payload shape, and it's expected to change as their catalog expands — so
    rather than betting on one field name, this tries every plausible id/
    serial candidate across the body's likely nesting (top-level, body.data,
    body.device). _resolve_applivery_webhook_device stops at the first
    device match against this list, tried in order."""
    candidates: List[str] = []
    containers = [body]
    if isinstance(body.get('data'), dict):
        containers.append(body['data'])
    if isinstance(body.get('device'), dict):
        containers.append(body['device'])
    for container in containers:
        for key in ('id', '_id', 'deviceId', 'serialNumber', 'serial', 'udid', 'platformDeviceId'):
            v = container.get(key)
            if v:
                candidates.append(str(v).strip().lower())
    return candidates

def _resolve_applivery_webhook_device(body: Dict[str, Any], devices: List[dict]) -> Optional[dict]:
    for value in _applivery_webhook_extract_device_hint(body):
        for d in devices:
            if str(d.get('id') or '').strip().lower() == value:
                return d
            if str(d.get('serialNumber') or '').strip().lower() == value:
                return d
            if str(d.get('platformDeviceId') or '').strip().lower() == value:
                return d
            if str(d.get('udid') or '').strip().lower() == value:
                return d
    return None

class AppliveryWebhookRulePayload(BaseModel):
    actionKey: str
    label: Optional[str] = None
    enabled: bool = False
    openCase: bool = False
    caseSeverity: str = "medium"
    runWorkflow: bool = False
    workflowId: Optional[str] = None
    autoRunDestructiveAck: bool = False

class AppliveryWebhookConfigPayload(BaseModel):
    enabled: bool = True
    rules: List[AppliveryWebhookRulePayload] = []

@app.get("/api/applivery-webhook", dependencies=[Depends(verify_dashboard_token)])
async def get_applivery_webhook_config(x_workspace_slug: Optional[str] = Header(None)):
    slug_key = x_workspace_slug or 'global'
    config = _load_applivery_webhook_config(slug_key)
    first_load = not config.get('secret')
    if first_load:
        config['secret'] = secrets.token_urlsafe(24)
        # Pre-seed a disabled rule for every event Applivery's catalog
        # documents today, so there's something to configure immediately
        # instead of an empty list — any event type Applivery adds later
        # still self-registers on first receipt (see receive_applivery_webhook),
        # this just saves the wait for the ones already known.
        config['rules'] = [
            {"actionKey": key, "label": label, "enabled": False, "openCase": False,
             "caseSeverity": "medium", "runWorkflow": False, "workflowId": None, "autoRunDestructiveAck": False}
            for key, label in APPLIVERY_WEBHOOK_EVENT_LABELS.items()
        ]
        _save_applivery_webhook_config(slug_key, config)
    return config

@app.put("/api/applivery-webhook", dependencies=[Depends(verify_dashboard_token)])
async def update_applivery_webhook_config(payload: AppliveryWebhookConfigPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    existing = _load_applivery_webhook_config(slug_key)
    workflows_by_id = {w['id']: w for w in _load_workflows(slug_key)}
    rules = []
    for r in payload.rules:
        rd = r.dict()
        if rd.get('runWorkflow'):
            workflow = workflows_by_id.get(rd.get('workflowId') or '')
            if not workflow:
                raise HTTPException(status_code=400, detail=f"Rule \"{_applivery_webhook_label(rd.get('actionKey'))}\" is set to run a workflow but no valid workflow is selected")
            if _workflow_has_destructive_step(workflow) and not rd.get('autoRunDestructiveAck'):
                raise HTTPException(status_code=400, detail=f"Workflow \"{workflow.get('name')}\" contains a destructive action step — acknowledge this before rule \"{_applivery_webhook_label(rd.get('actionKey'))}\" can auto-run it unattended")
        rules.append(rd)
    config = {
        "enabled": payload.enabled,
        "secret": existing.get('secret') or secrets.token_urlsafe(24),
        "rules": rules,
        "recentEvents": existing.get('recentEvents', []),
        "receivedCount": existing.get('receivedCount', 0),
        "lastReceivedAt": existing.get('lastReceivedAt'),
    }
    _save_applivery_webhook_config(slug_key, config)
    _record_audit_event(slug_key, category="settings", action="applivery_webhook_updated", actor=dash.get('sub'),
                         message=f'Applivery event webhook settings updated by {dash.get("sub")} — {sum(1 for r in rules if r.get("enabled"))} rule(s) enabled, webhook {"on" if payload.enabled else "off"}')
    return config

@app.post("/api/applivery-webhook/rotate-secret", dependencies=[Depends(verify_dashboard_token)])
async def rotate_applivery_webhook_secret(x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    config = _load_applivery_webhook_config(slug_key)
    config['secret'] = secrets.token_urlsafe(24)
    _save_applivery_webhook_config(slug_key, config)
    _record_audit_event(slug_key, category="settings", action="applivery_webhook_secret_rotated", actor=dash.get('sub'), severity="warning",
                         message=f'Applivery event webhook URL rotated by {dash.get("sub")} — update it in Applivery\'s own Integrations settings or events stop arriving')
    return config

@app.post("/api/applivery-webhook/receive/{secret}")
async def receive_applivery_webhook(secret: str, request: Request):
    """The URL an admin pastes into Applivery's own Workspace/App >
    Integrations > Webhook settings. Deliberately NOT dashboard-token
    protected (the caller is Applivery's own webhook engine, not a logged-in
    admin) and deliberately not header-auth (Applivery's webhook config UI
    only takes a URL, no custom headers) — the secret lives in the path
    instead, same pattern as /api/triggers/fire/{id}/{secret}."""
    try:
        body = await request.json()
        if not isinstance(body, dict):
            body = {}
    except Exception:
        body = {}

    found = _find_applivery_webhook_config_by_secret(secret)
    if found is None:
        raise HTTPException(status_code=404, detail="Unknown webhook secret")
    slug_key, _stale_config = found
    now_iso = datetime.now(timezone.utc).isoformat()

    raw_action = str(body.get('action') or body.get('event') or 'unknown')
    os_hint, canonical_key = _normalize_applivery_webhook_action(raw_action)

    # Reload fresh rather than reusing the config _find_applivery_webhook_config_by_secret
    # already read — two events landing back to back shouldn't clobber each
    # other's rule auto-registration or recentEvents append.
    config = _load_applivery_webhook_config(slug_key)
    rule = next((r for r in config.get('rules', []) if r.get('actionKey') == canonical_key), None)
    if rule is None:
        rule = {"actionKey": canonical_key, "label": _applivery_webhook_label(canonical_key), "enabled": False,
                 "openCase": False, "caseSeverity": "medium", "runWorkflow": False, "workflowId": None, "autoRunDestructiveAck": False}
        config.setdefault('rules', []).append(rule)

    config['receivedCount'] = config.get('receivedCount', 0) + 1
    config['lastReceivedAt'] = now_iso

    event_record = {
        "id": str(uuid.uuid4()), "receivedAt": now_iso, "actionKey": raw_action, "canonicalKey": canonical_key,
        "os": os_hint, "outcome": "logged", "deviceId": None, "deviceName": None, "caseId": None, "workflowRunId": None,
    }

    webhook_off = not config.get('enabled', True)
    rule_off = not rule.get('enabled')
    if webhook_off or rule_off:
        event_record['outcome'] = 'webhook_disabled' if webhook_off else 'logged'
        config.setdefault('recentEvents', []).insert(0, event_record)
        config['recentEvents'] = config['recentEvents'][:50]
        _save_applivery_webhook_config(slug_key, config)
        _record_audit_event(slug_key, category="webhook", action="applivery_event_received", actor="applivery",
                             message=f'Applivery event "{raw_action}" received — ' + ('webhook is disabled' if webhook_off else 'no automation configured for this event yet'))
        return {"status": event_record['outcome']}

    authorization = await _get_automation_bearer(slug_key)
    matched_device = None
    if authorization:
        try:
            devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=slug_key)
            matched_device = _resolve_applivery_webhook_device(body, devices_resp.get('items', []))
        except Exception:
            matched_device = None
    if matched_device:
        event_record['deviceId'] = matched_device.get('id')
        event_record['deviceName'] = matched_device.get('displayName')

    # Tracked as separate parts and joined at the end rather than one
    # mutable `outcome` string overwritten in place — a case can open fine
    # while the workflow half of the same rule fails (missing workflow, no
    # automation credential, destructive block, etc.), and both halves need
    # to survive into the recent-events feed rather than the second
    # silently clobbering the first.
    outcome_parts: List[str] = []

    case_id = None
    if rule.get('openCase'):
        cases = _load_cases(slug_key)
        title = _applivery_webhook_label(canonical_key) + (f' — {matched_device.get("displayName")}' if matched_device else '')
        new_case = {
            "id": str(uuid.uuid4()), "title": title, "status": "open",
            "severity": rule.get('caseSeverity') or 'medium', "source": "applivery_webhook",
            "deviceId": matched_device.get('id') if matched_device else None,
            "deviceName": matched_device.get('displayName') if matched_device else None,
            "segmentId": matched_device.get('segmentId') if matched_device else None,
            "policyId": None, "policyName": None, "violationIds": [],
            "workflowRunIds": [], "assignee": None,
            "createdBy": "system", "createdAt": now_iso, "updatedAt": now_iso, "closedAt": None,
            "acknowledgedAt": None, "slaClockStartedAt": now_iso, "slaAckBreachNotifiedAt": None, "slaResolveBreachNotifiedAt": None,
            "notes": [], "timeline": [_case_timeline_entry('created', f'Case opened by Applivery event "{raw_action}"')],
        }
        cases.insert(0, new_case)
        _save_cases(slug_key, cases)
        case_id = new_case['id']
        refs = await _dispatch_case_integrations(slug_key, new_case, 'created')
        if refs:
            _attach_external_refs(new_case, refs)
            _save_cases(slug_key, cases)
        event_record['caseId'] = case_id
        outcome_parts.append('case_opened')

    if rule.get('runWorkflow') and rule.get('workflowId'):
        workflow = next((w for w in _load_workflows(slug_key) if w.get('id') == rule.get('workflowId')), None)
        if not workflow:
            outcome_parts.append('workflow_missing')
        elif not authorization:
            outcome_parts.append('no_automation_credential')
        elif _workflow_has_destructive_step(workflow) and not rule.get('autoRunDestructiveAck'):
            outcome_parts.append('workflow_blocked_destructive')
            _record_audit_event(slug_key, category="webhook", action="applivery_event_workflow_blocked", actor="applivery", severity="critical",
                                 target_type="workflow", target_id=workflow.get('id'), target_name=workflow.get('name'),
                                 message=f'Applivery event "{raw_action}" — workflow "{workflow.get("name")}" contains a destructive action and was not acknowledged, so it did not run')
        else:
            device_refs: List[WorkflowDeviceRef] = []
            if matched_device:
                device_refs = [WorkflowDeviceRef(
                    id=matched_device['id'], displayName=matched_device.get('displayName'),
                    platform=matched_device['platform'], platformDeviceId=matched_device['platformDeviceId'],
                    serialNumber=matched_device.get('serialNumber'), osVersion=matched_device.get('osVersion'),
                    manufacturer=matched_device.get('manufacturer'), model=matched_device.get('model'),
                    udid=matched_device.get('udid'), mdmUser=matched_device.get('mdmUser'),
                )]
            run_record = await _launch_workflow_run(workflow, device_refs, authorization, slug_key)
            if run_record is not None:
                event_record['workflowRunId'] = run_record['id']
                outcome_parts.append('workflow_fired')
                if case_id:
                    cases = _load_cases(slug_key)
                    case_match = next((c for c in cases if c.get('id') == case_id), None)
                    if case_match:
                        case_match.setdefault('workflowRunIds', []).append(run_record['id'])
                        case_match.setdefault('timeline', []).append(_case_timeline_entry('workflow_run_linked', f'Ran "{workflow.get("name")}" (Applivery event automation)'))
                        case_match['updatedAt'] = now_iso
                        _save_cases(slug_key, cases)
            else:
                outcome_parts.append('workflow_unavailable')

    event_record['outcome'] = '+'.join(outcome_parts) if outcome_parts else 'logged'

    config.setdefault('recentEvents', []).insert(0, event_record)
    config['recentEvents'] = config['recentEvents'][:50]
    _save_applivery_webhook_config(slug_key, config)

    _record_audit_event(slug_key, category="webhook", action="applivery_event_received", actor="applivery",
                         target_type="device" if matched_device else None, target_id=matched_device.get('id') if matched_device else None,
                         target_name=matched_device.get('displayName') if matched_device else None,
                         message=f'Applivery event "{raw_action}" — {event_record["outcome"].replace("_", " ")}' + (f' ({matched_device.get("displayName")})' if matched_device else ''))
    return {"status": event_record['outcome'], "caseId": case_id, "workflowRunId": event_record['workflowRunId']}

# ─── TICKETING / CHAT INTEGRATIONS ───
# The last piece of the SOAR roadmap — outbound notifications when a Case
# opens or closes, to wherever a team actually works: a Slack/Teams/Discord
# channel, or a ticket created directly in Jira/ServiceNow. Deliberately
# scoped to Cases, not raw Violations — Cases are already the de-duplicated,
# analyst-facing signal (see CASE MANAGEMENT above), so this doesn't fire
# once per evaluation cycle for a device that's been broken for a week.
#
# Ticketing types (Jira/ServiceNow) fire on OPEN events (created/reopened) by
# creating a new ticket, and on CLOSE events by transitioning/resolving the
# ticket that's already linked via externalRefs (see _transition_jira_issue /
# _close_servicenow_incident) — that's the outbound half (App → ticket
# system).
#
# Inbound sync (ticket system → App) is polling-based, not webhook-based —
# see _fetch_jira_issue_status / _fetch_servicenow_incident_status /
# _sync_case_ticket_refs and ticket_status_sync_loop below. A background loop
# periodically pulls live status for every open Case's linked ticket(s) and,
# if an integration opts in via autoCloseCaseOnRemoteResolve, closes the Case
# to match once the ticket is marked done on the other side. Off by default —
# same "analyst confirms before closing" posture as autoResolveCaseOnRecovery
# on Compliance Policies. Deliberately polling rather than a webhook
# receiver: it needs zero inbound network/webhook configuration on Jira's or
# ServiceNow's own side (which would mean asking each customer's ticketing
# admin to open a hole to us), at the cost of being up to
# TICKET_SYNC_TICK_SECONDS stale rather than instant.
INTEGRATIONS_DIR = os.path.join(DATA_DIR, "integrations")
if not os.path.exists(INTEGRATIONS_DIR):
    os.makedirs(INTEGRATIONS_DIR)

INTEGRATION_TYPES = ('slack', 'teams', 'discord', 'jira', 'servicenow', 'generic_webhook', 'pagerduty', 'opsgenie')
CASE_SEVERITY_RANK = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}

def _integrations_file(slug: str) -> str:
    return os.path.join(INTEGRATIONS_DIR, f"{_slug_clean(slug)}.json")

_register_legacy_json('integrations', lambda slug, key: _integrations_file(slug))

def _load_integrations(slug: str) -> List[Dict[str, Any]]:
    items = _store_load(slug, 'integrations', list)
    out = []
    for item in items:
        item = dict(item)
        item['config'] = _decrypt_integration_config(item.get('type'), item.get('config') or {})
        out.append(item)
    return out

def _save_integrations(slug: str, integrations: List[Dict[str, Any]]):
    to_store = []
    for item in integrations:
        item = dict(item)
        item['config'] = _encrypt_integration_config(item.get('type'), item.get('config') or {})
        to_store.append(item)
    _store_save(slug, 'integrations', to_store)

class IntegrationPayload(BaseModel):
    name: str
    type: str  # one of INTEGRATION_TYPES
    enabled: bool = True
    notifyOnOpen: bool = True
    # Ignored for type in ('jira', 'servicenow') — see module comment above;
    # kept here (rather than rejected) so the UI can just grey it out instead
    # of needing type-conditional validation on every save.
    notifyOnClose: bool = False
    minSeverity: str = 'low'  # only Cases at/above this severity notify
    # Inbound sync opt-in — only meaningful for type in ('jira', 'servicenow');
    # ignored otherwise, same "kept here, greyed out in UI" trade-off as
    # notifyOnClose above. When true, ticket_status_sync_loop (and the manual
    # POST /api/cases/{id}/sync-ticket-status) will auto-resolve a Case the
    # moment its linked ticket from THIS integration is found marked done on
    # Jira/ServiceNow's own side. Off by default — the ticket coming back
    # resolved is recorded on the Case's timeline either way; this only
    # controls whether that also flips the Case's own status automatically.
    autoCloseCaseOnRemoteResolve: bool = False
    # Opt-in: also page this destination when a background job (compliance
    # scheduler, catalog refresher, SLA monitor, etc.) goes unhealthy — see
    # system_health_monitor_loop. Off by default for every type, chat
    # integrations included, since "the OS update catalog refresh failed
    # once" is a very different audience/urgency than "a Case opened."
    # Meaningful mainly for pagerduty/opsgenie (that's what they're for) but
    # not restricted to them — a Slack channel can opt in too.
    notifyOnSystemHealth: bool = False
    # Type-specific shape:
    #   slack/teams/discord: {"webhookUrl": "..."}  (Teams: a Workflows
    #     webhook URL — see _send_chat_notification comment; legacy O365
    #     Connector webhooks stopped working when Microsoft retired them
    #     across May 2026)
    #   jira: {"baseUrl", "email", "apiToken", "projectKey", "issueType"}
    #   servicenow: {"instanceUrl", "username", "password", "table"}
    #   generic_webhook: {"url", "headers": {...}}
    #   pagerduty: {"routingKey": "..."} — Events API v2 integration key,
    #     from a PagerDuty service's "Events API V2" integration.
    #   opsgenie: {"apiKey": "...", "region": "us"|"eu"} — a Genie Key from
    #     Opsgenie Settings > API key management. region picks the API host
    #     (api.opsgenie.com vs api.eu.opsgenie.com); defaults to "us".
    config: Dict[str, Any] = {}

@app.get("/api/integrations", dependencies=[Depends(verify_dashboard_token)])
async def list_integrations(x_workspace_slug: Optional[str] = Header(None)):
    # Never echo secrets (Jira apiToken, ServiceNow password, webhook URLs
    # carry a secret token in the path) back in a way that lands in a list
    # view a screen-share might show — the edit form re-fetches the single
    # integration via GET /api/integrations (list) same as everywhere else in
    # this app that already does this trade-off (e.g. device-report-secret);
    # kept simple by NOT redacting here, since this is dashboard-token-gated
    # exactly like every other settings list. Documented rather than silently
    # inconsistent with the rest of the app.
    return {"items": _load_integrations(x_workspace_slug or 'global')}

@app.post("/api/integrations", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def create_integration(payload: IntegrationPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    if payload.type not in INTEGRATION_TYPES:
        raise HTTPException(status_code=400, detail=f"type must be one of {INTEGRATION_TYPES}")
    if payload.minSeverity not in CASE_SEVERITIES:
        raise HTTPException(status_code=400, detail=f"minSeverity must be one of {CASE_SEVERITIES}")
    slug_key = x_workspace_slug or 'global'
    integrations = _load_integrations(slug_key)
    now = datetime.now(timezone.utc).isoformat()
    integration_id = str(uuid.uuid4())
    new_integration = payload.dict()
    new_integration.update({
        "id": integration_id, "createdBy": dash.get('sub'), "createdAt": now, "updatedAt": now,
        "lastFiredAt": None, "fireCount": 0, "lastError": None,
    })
    integrations.append(new_integration)
    _save_integrations(slug_key, integrations)
    _record_audit_event(slug_key, category="integration", action="integration_created", actor=dash.get('sub'),
                         target_type="integration", target_id=integration_id, target_name=new_integration.get('name'),
                         message=f'{new_integration.get("type")} integration "{new_integration.get("name")}" created by {dash.get("sub")}')
    return new_integration

@app.put("/api/integrations/{integration_id}", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def update_integration(integration_id: str, payload: IntegrationPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    if payload.type not in INTEGRATION_TYPES:
        raise HTTPException(status_code=400, detail=f"type must be one of {INTEGRATION_TYPES}")
    if payload.minSeverity not in CASE_SEVERITIES:
        raise HTTPException(status_code=400, detail=f"minSeverity must be one of {CASE_SEVERITIES}")
    slug_key = x_workspace_slug or 'global'
    integrations = _load_integrations(slug_key)
    idx = next((i for i, t in enumerate(integrations) if t.get('id') == integration_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Integration not found")
    existing = integrations[idx]
    updated = payload.dict()
    updated.update({
        "id": integration_id, "createdBy": existing.get('createdBy'), "createdAt": existing.get('createdAt'),
        "updatedAt": datetime.now(timezone.utc).isoformat(),
        "lastFiredAt": existing.get('lastFiredAt'), "fireCount": existing.get('fireCount', 0), "lastError": existing.get('lastError'),
    })
    integrations[idx] = updated
    _save_integrations(slug_key, integrations)
    _record_audit_event(slug_key, category="integration", action="integration_updated", actor=dash.get('sub'),
                         target_type="integration", target_id=integration_id, target_name=updated.get('name'),
                         message=f'Integration "{updated.get("name")}" updated by {dash.get("sub")}')
    return updated

@app.delete("/api/integrations/{integration_id}", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def delete_integration(integration_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    integrations = _load_integrations(slug_key)
    idx = next((i for i, t in enumerate(integrations) if t.get('id') == integration_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Integration not found")
    removed = integrations.pop(idx)
    _save_integrations(slug_key, integrations)
    _record_audit_event(slug_key, category="integration", action="integration_deleted", actor=dash.get('sub'), severity="warning",
                         target_type="integration", target_id=integration_id, target_name=removed.get('name'),
                         message=f'Integration "{removed.get("name")}" deleted by {dash.get("sub")}')
    return {"status": "ok"}

async def _send_chat_notification(client: httpx.AsyncClient, webhook_url: str, case: dict, event_type: str, kind: str):
    """Slack incoming webhooks and Teams Workflows webhooks both accept the
    same simple {"text": "..."} payload (Teams' migration off the retired
    O365 Connectors explicitly kept MessageCard/plain-text payloads working
    "without reformatting" — see module comment). Discord's webhook API uses
    "content" instead of "text" and doesn't render Slack-style *bold*
    markdown the same way, hence the light per-kind formatting below."""
    if not webhook_url:
        raise ValueError("No webhook URL configured")
    verb = {
        'created': 'opened', 'reopened': 'reopened', 'closed': 'resolved/closed',
        'sla_acknowledge_breached': 'SLA BREACH — not yet acknowledged', 'sla_resolve_breached': 'SLA BREACH — not yet resolved',
    }.get(event_type, event_type)
    text = f'*Case {verb}:* {case.get("title")}\nSeverity: *{case.get("severity")}*  ·  Status: *{case.get("status")}*  ·  Source: {case.get("source")}'
    if case.get('deviceName'):
        text += f'\nDevice: {case.get("deviceName")}'
    body = {"content": text.replace('*', '**')} if kind == 'discord' else {"text": text}
    res = await client.post(webhook_url, json=body, timeout=15.0)
    res.raise_for_status()

# PagerDuty (Events API v2) and Opsgenie (Alert API) — the two on-call
# paging tools this app can escalate to, alongside chat/ticketing above.
# Both are "fire and forget an alert, later fire a resolve for the same
# incident" APIs, so every call site below passes a stable `dedup_key`
# (PagerDuty) / `alias` (Opsgenie) derived from what caused the page — a
# case id, or "system_health:{job_key}" for a background-job failure — so
# a still-open incident doesn't spawn a second page on every tick, and the
# eventual resolve call closes the SAME incident it opened rather than a
# new one.
_PD_SEVERITY_MAP = {'low': 'info', 'medium': 'warning', 'high': 'error', 'critical': 'critical'}
_OG_PRIORITY_MAP = {'low': 'P5', 'medium': 'P3', 'high': 'P2', 'critical': 'P1'}

async def _send_pagerduty_event(client: httpx.AsyncClient, cfg: dict, dedup_key: str, action: str, summary: str, severity: str = 'high', details: Optional[dict] = None):
    """action: 'trigger' | 'resolve'. https://developer.pagerduty.com/docs/events-api-v2"""
    routing_key = cfg.get('routingKey')
    if not routing_key:
        raise ValueError("PagerDuty integration is missing its Events API v2 routing key")
    body: Dict[str, Any] = {"routing_key": routing_key, "event_action": action, "dedup_key": dedup_key}
    if action == 'trigger':
        body["payload"] = {
            "summary": summary,
            "source": "Applivery SOAR",
            "severity": _PD_SEVERITY_MAP.get(severity, 'error'),
            "custom_details": details or {},
        }
    res = await client.post("https://events.pagerduty.com/v2/enqueue", json=body, timeout=15.0)
    if res.status_code >= 300:
        raise ValueError(f"PagerDuty returned {res.status_code}: {res.text[:300]}")

async def _send_opsgenie_event(client: httpx.AsyncClient, cfg: dict, alias: str, action: str, summary: str, severity: str = 'high', details: Optional[dict] = None):
    """action: 'trigger' | 'resolve'. https://docs.opsgenie.com/docs/alert-api"""
    api_key = cfg.get('apiKey')
    if not api_key:
        raise ValueError("Opsgenie integration is missing its API key")
    host = "api.eu.opsgenie.com" if cfg.get('region') == 'eu' else "api.opsgenie.com"
    headers = {"Authorization": f"GenieKey {api_key}"}
    if action == 'trigger':
        body = {
            "message": summary[:130],
            "alias": alias,
            "description": summary,
            "priority": _OG_PRIORITY_MAP.get(severity, 'P2'),
            "details": {k: str(v) for k, v in (details or {}).items()},
            "source": "Applivery SOAR",
        }
        res = await client.post(f"https://{host}/v2/alerts", json=body, headers=headers, timeout=15.0)
        if res.status_code >= 300:
            raise ValueError(f"Opsgenie returned {res.status_code}: {res.text[:300]}")
    else:  # resolve — Opsgenie has no "trigger a fresh alert vs. resolve" verb distinction like PD's dedup_key; it closes by alias instead
        res = await client.post(
            f"https://{host}/v2/alerts/{quote(alias, safe='')}/close",
            params={"identifierType": "alias"}, json={"source": "Applivery SOAR"}, headers=headers, timeout=15.0,
        )
        if res.status_code >= 300 and res.status_code != 404:  # 404 = already closed/never opened — not an error for a resolve call
            raise ValueError(f"Opsgenie returned {res.status_code}: {res.text[:300]}")

async def _send_paging_event(client: httpx.AsyncClient, itype: str, cfg: dict, dedup_key: str, action: str, summary: str, severity: str = 'high', details: Optional[dict] = None):
    """Common entry point for the two paging integration types, so call
    sites (case dispatch, SLA breach, system health) don't need their own
    if/elif over itype."""
    if itype == 'pagerduty':
        await _send_pagerduty_event(client, cfg, dedup_key, action, summary, severity, details)
    elif itype == 'opsgenie':
        await _send_opsgenie_event(client, cfg, dedup_key, action, summary, severity, details)
    else:
        raise ValueError(f"Unknown paging integration type '{itype}'")

async def _send_alert_email(slug: str, subject: str, body_text: str):
    """Best-effort email alert using the workspace's existing SMTP config
    (Settings > Email (SMTP)) — reuses the same host/port/user/pass/from
    already configured for scheduled report delivery, so there's no second
    SMTP form to fill in. Recipients come from a new smtpConfig.alertRecipients
    field (comma-separated), kept separate from scheduledReports'
    emailRecipients since "who gets the weekly PDF" and "who gets paged
    when a case breaches SLA or a job dies at 3am" are often different
    lists. A no-op (not an error) when SMTP or alert recipients aren't
    configured — email is one of several channels here, not the only one."""
    try:
        state = _load_state(slug)
        smtp_config = state.get('smtpConfig') or {}
        recipients = smtp_config.get('alertRecipients')
        if not smtp_config.get('host') or not smtp_config.get('user') or not recipients:
            return
        def _send():
            msg = EmailMessage()
            msg['Subject'] = subject
            msg['From'] = smtp_config.get('from') or smtp_config.get('user')
            msg['To'] = recipients
            msg.set_content(body_text)
            with smtplib.SMTP(smtp_config['host'], int(smtp_config.get('port', 587))) as server:
                server.starttls()
                server.login(smtp_config['user'], smtp_config['pass'])
                server.send_message(msg)
        await asyncio.to_thread(_send)
    except Exception as e:
        print(f"[Alert Email] Failed to send '{subject}': {e}")

async def _create_jira_issue(client: httpx.AsyncClient, cfg: dict, case: dict) -> dict:
    """Jira Cloud REST API v2 (not v3) — v3's `description` field requires
    Atlassian Document Format (a structured rich-text tree), v2 still accepts
    a plain string, which is all this needs and avoids pulling in an ADF
    builder for one field."""
    base_url = (cfg.get('baseUrl') or '').rstrip('/')
    if not base_url or not cfg.get('email') or not cfg.get('apiToken') or not cfg.get('projectKey'):
        raise ValueError("Jira integration is missing baseUrl/email/apiToken/projectKey")
    description = (
        f'Opened from Applivery SOAR.\n\n'
        f'Severity: {case.get("severity")}\nStatus: {case.get("status")}\nSource: {case.get("source")}\n'
        f'Device: {case.get("deviceName") or "—"}\nPolicy: {case.get("policyName") or "—"}'
    )
    body = {"fields": {
        "project": {"key": cfg['projectKey']},
        "summary": case.get('title') or 'Untitled case',
        "description": description,
        "issuetype": {"name": cfg.get('issueType') or 'Task'},
    }}
    res = await client.post(f"{base_url}/rest/api/2/issue", json=body, auth=(cfg['email'], cfg['apiToken']), timeout=20.0)
    if res.status_code >= 300:
        raise ValueError(f"Jira returned {res.status_code}: {res.text[:300]}")
    data = res.json()
    key = data.get('key')
    return {"type": "jira", "id": key, "url": f"{base_url}/browse/{key}"}

async def _create_servicenow_incident(client: httpx.AsyncClient, cfg: dict, case: dict) -> dict:
    instance_url = (cfg.get('instanceUrl') or '').rstrip('/')
    if not instance_url or not cfg.get('username') or not cfg.get('password'):
        raise ValueError("ServiceNow integration is missing instanceUrl/username/password")
    table = cfg.get('table') or 'incident'
    urgency = {'critical': '1', 'high': '1', 'medium': '2', 'low': '3'}.get(case.get('severity'), '2')
    body = {
        "short_description": case.get('title') or 'Untitled case',
        "description": (
            f'Opened from Applivery SOAR.\n'
            f'Severity: {case.get("severity")}\nStatus: {case.get("status")}\nSource: {case.get("source")}\n'
            f'Device: {case.get("deviceName") or "—"}'
        ),
        "urgency": urgency, "impact": urgency,
    }
    res = await client.post(
        f"{instance_url}/api/now/table/{table}", json=body,
        auth=(cfg['username'], cfg['password']), headers={"Accept": "application/json"}, timeout=20.0,
    )
    if res.status_code >= 300:
        raise ValueError(f"ServiceNow returned {res.status_code}: {res.text[:300]}")
    result = res.json().get('result') or {}
    number = result.get('number')
    sys_id = result.get('sys_id')
    # sysId is kept on the ref (not just baked into the URL) so a later case
    # close can PATCH this exact record back — see _close_servicenow_incident.
    return {"type": "servicenow", "id": number, "sysId": sys_id, "url": f"{instance_url}/nav_to.do?uri={table}.do%3Fsys_id%3D{sys_id}"}

async def _transition_jira_issue(client: httpx.AsyncClient, cfg: dict, issue_key: str):
    """Closes the loop the other direction from _create_jira_issue: called
    when a Case closes and a Jira ticket is already linked to it. Jira
    workflows are per-project/custom, so there's no fixed "closed" transition
    id to target — this looks up the issue's currently-available transitions
    and fires whichever one's name suggests done/resolved/closed. Best-effort
    by design; if a project's workflow uses unusual naming, this raises and
    the failure is recorded on the integration's lastError like any other
    dispatch failure, rather than silently doing nothing."""
    base_url = (cfg.get('baseUrl') or '').rstrip('/')
    auth = (cfg.get('email'), cfg.get('apiToken'))
    res = await client.get(f"{base_url}/rest/api/2/issue/{issue_key}/transitions", auth=auth, timeout=20.0)
    if res.status_code >= 300:
        raise ValueError(f"Jira transitions lookup for {issue_key} returned {res.status_code}: {res.text[:200]}")
    transitions = (res.json() or {}).get('transitions') or []
    match = next((t for t in transitions if any(k in (t.get('name') or '').lower() for k in ('done', 'resolve', 'close'))), None)
    if not match:
        names = ', '.join(t.get('name', '?') for t in transitions) or 'none available'
        raise ValueError(f"No done/resolved/closed transition found on {issue_key} (available: {names})")
    res2 = await client.post(f"{base_url}/rest/api/2/issue/{issue_key}/transitions", auth=auth, timeout=20.0, json={"transition": {"id": match['id']}})
    if res2.status_code >= 300:
        raise ValueError(f"Jira transition on {issue_key} returned {res2.status_code}: {res2.text[:200]}")

async def _close_servicenow_incident(client: httpx.AsyncClient, cfg: dict, sys_id: str):
    """Companion to _transition_jira_issue for ServiceNow — PATCHes the
    incident's state to Resolved (6), the standard out-of-box ServiceNow ITSM
    value. Instances that customize state values would need to override this,
    but 6 covers the default install most workspaces run."""
    instance_url = (cfg.get('instanceUrl') or '').rstrip('/')
    table = cfg.get('table') or 'incident'
    res = await client.patch(
        f"{instance_url}/api/now/table/{table}/{sys_id}",
        json={"state": "6", "close_code": "Closed/Resolved by Caller", "close_notes": "Closed automatically from Applivery SOAR — linked Case was closed."},
        auth=(cfg.get('username'), cfg.get('password')), headers={"Accept": "application/json"}, timeout=20.0,
    )
    if res.status_code >= 300:
        raise ValueError(f"ServiceNow close for sys_id {sys_id} returned {res.status_code}: {res.text[:200]}")

async def _fetch_jira_issue_status(client: httpx.AsyncClient, cfg: dict, issue_key: str) -> Optional[dict]:
    """Inbound counterpart to _transition_jira_issue — reads back the
    issue's current status rather than pushing one. Uses Jira's
    statusCategory.key ('new' | 'indeterminate' | 'done') rather than the
    status name itself, since that's the one status signal that's stable
    across arbitrary per-project custom workflows (the same reason
    _transition_jira_issue has to name-match instead of using a fixed
    transition id when pushing the other direction)."""
    base_url = (cfg.get('baseUrl') or '').rstrip('/')
    auth = (cfg.get('email'), cfg.get('apiToken'))
    res = await client.get(f"{base_url}/rest/api/2/issue/{issue_key}", params={"fields": "status"}, auth=auth, timeout=20.0)
    if res.status_code == 404:
        return {"name": "Not found", "resolved": False, "missing": True}
    if res.status_code >= 300:
        raise ValueError(f"Jira status lookup for {issue_key} returned {res.status_code}: {res.text[:200]}")
    status = ((res.json() or {}).get('fields') or {}).get('status') or {}
    category = ((status.get('statusCategory') or {}).get('key') or '').lower()
    return {"name": status.get('name'), "resolved": category == 'done'}

async def _fetch_servicenow_incident_status(client: httpx.AsyncClient, cfg: dict, sys_id: str) -> Optional[dict]:
    """Inbound counterpart to _close_servicenow_incident. state 6/7 (Resolved/
    Closed) are the standard out-of-box ServiceNow ITSM values — same caveat
    as the close path: instances that customize state values would need to
    override this."""
    instance_url = (cfg.get('instanceUrl') or '').rstrip('/')
    table = cfg.get('table') or 'incident'
    res = await client.get(
        f"{instance_url}/api/now/table/{table}/{sys_id}", params={"sysparm_fields": "state"},
        auth=(cfg.get('username'), cfg.get('password')), headers={"Accept": "application/json"}, timeout=20.0,
    )
    if res.status_code == 404:
        return {"name": "Not found", "resolved": False, "missing": True}
    if res.status_code >= 300:
        raise ValueError(f"ServiceNow status lookup for {sys_id} returned {res.status_code}: {res.text[:200]}")
    result = (res.json() or {}).get('result') or {}
    state = str(result.get('state') or '')
    return {"name": state, "resolved": state in ('6', '7')}

async def _sync_case_ticket_refs(client: httpx.AsyncClient, integrations_by_type: Dict[str, dict], case: dict) -> List[dict]:
    """Pulls live status for every Jira/ServiceNow externalRef on this case
    from whichever integration created it (matched by type). Mutates each
    ref in place with remoteStatus/remoteResolved/remoteStatusCheckedAt (or
    remoteStatusError on failure) — caller is responsible for persisting the
    case afterward. Returns the refs that just transitioned from
    not-resolved to resolved on THIS call, for the caller to decide whether
    to auto-close the case."""
    newly_resolved: List[dict] = []
    for ref in case.get('externalRefs') or []:
        itype = ref.get('type')
        if itype not in ('jira', 'servicenow'):
            continue
        integ = integrations_by_type.get(itype)
        if not integ:
            continue
        cfg = integ.get('config') or {}
        was_resolved = ref.get('remoteResolved', False)
        try:
            if itype == 'jira':
                status = await _fetch_jira_issue_status(client, cfg, ref['id'])
            else:
                sys_id = ref.get('sysId')
                status = await _fetch_servicenow_incident_status(client, cfg, sys_id) if sys_id else None
            if status is None:
                continue
            ref['remoteStatus'] = status.get('name')
            ref['remoteResolved'] = bool(status.get('resolved'))
            ref['remoteStatusCheckedAt'] = datetime.now(timezone.utc).isoformat()
            ref.pop('remoteStatusError', None)
            if ref['remoteResolved'] and not was_resolved:
                newly_resolved.append(ref)
        except Exception as e:
            ref['remoteStatusError'] = str(e)[:300]
    return newly_resolved

def _close_case_from_remote_resolve(case: dict, ref: dict):
    """Resolves a Case in response to its linked ticket coming back done on
    Jira/ServiceNow's own side (see autoCloseCaseOnRemoteResolve). Deliberate
    status choice: 'resolved', not 'closed' — mirrors autoResolveCaseOnRecovery's
    choice elsewhere in this file, leaving the final 'closed' as an explicit
    analyst action if this workspace's process wants that distinction."""
    now = datetime.now(timezone.utc).isoformat()
    case['status'] = 'resolved'
    case['closedAt'] = now
    case['updatedAt'] = now
    case.setdefault('timeline', []).append(_case_timeline_entry(
        'status_changed',
        f'Auto-resolved — linked {ref.get("type", "").title()} ticket {ref.get("id")} was marked done externally',
    ))

async def _send_generic_webhook(client: httpx.AsyncClient, cfg: dict, case: dict, event_type: str):
    """Escape hatch for anything without a dedicated type above (PagerDuty,
    Opsgenie, an internal ticketing system, etc.) — POSTs the full case
    object as-is plus the event type, so the receiving side decides what to
    do with it."""
    url = cfg.get('url')
    if not url:
        raise ValueError("No URL configured")
    res = await client.post(url, json={"event": event_type, "case": case}, headers=(cfg.get('headers') or {}), timeout=20.0)
    res.raise_for_status()

async def _dispatch_case_integrations(slug: str, case: dict, event_type: str) -> List[dict]:
    """event_type: 'created' | 'reopened' | 'closed'. Fires every enabled
    integration configured for this workspace that's gated in for this event
    (notifyOnOpen/notifyOnClose) and severity (minSeverity), same shape as
    Log Export Destinations' real-time dispatch and Inbound Webhook Triggers
    elsewhere in this file. Per-integration failures are caught and recorded
    on that integration's own lastError — one bad Slack webhook doesn't stop
    a Jira ticket from being created, or vice versa. Returns any externalRefs
    created (Jira/ServiceNow ticket links); the caller attaches them to the
    case and persists it — this function only persists the integrations list
    (lastFiredAt/fireCount/lastError), never the case itself."""
    integrations = _load_integrations(slug)
    if not integrations:
        return []
    is_open_event = event_type in ('created', 'reopened')
    is_close_event = event_type == 'closed'
    case_rank = CASE_SEVERITY_RANK.get(case.get('severity', 'medium'), 1)
    new_refs: List[dict] = []
    touched = False
    async with httpx.AsyncClient() as client:
        for integ in integrations:
            if not integ.get('enabled', True):
                continue
            itype = integ.get('type')
            is_ticketing = itype in ('jira', 'servicenow')

            # Ticketing close-sync: rather than skipping ticket types on
            # close (the old behavior), transition/resolve the already-linked
            # ticket if one exists for this integration. This is handled as
            # its own branch (not the open/generic dispatch below) since it
            # updates an existing ticket instead of creating one.
            if is_close_event and is_ticketing:
                ref = next((r for r in (case.get('externalRefs') or []) if r.get('type') == itype), None)
                if not ref:
                    continue  # no ticket from this integration to close
                if case_rank < CASE_SEVERITY_RANK.get(integ.get('minSeverity', 'low'), 0):
                    continue
                cfg = integ.get('config') or {}
                touched = True
                try:
                    if itype == 'jira':
                        await _transition_jira_issue(client, cfg, ref['id'])
                    else:  # servicenow
                        sys_id = ref.get('sysId')
                        if not sys_id:
                            raise ValueError("No ServiceNow sys_id on record for this ticket (opened before close-sync was added) — close it manually")
                        await _close_servicenow_incident(client, cfg, sys_id)
                    integ['lastFiredAt'] = datetime.now(timezone.utc).isoformat()
                    integ['fireCount'] = integ.get('fireCount', 0) + 1
                    integ['lastError'] = None
                except Exception as e:
                    integ['lastError'] = str(e)[:300]
                    print(f"[Integrations] '{integ.get('name')}' ({itype}) close-sync failed for case {case.get('id')}: {e}")
                continue

            if is_open_event:
                if not integ.get('notifyOnOpen', True):
                    continue
            elif is_close_event:
                if not integ.get('notifyOnClose', False):
                    continue
            else:
                continue
            if case_rank < CASE_SEVERITY_RANK.get(integ.get('minSeverity', 'low'), 0):
                continue
            cfg = integ.get('config') or {}
            touched = True
            try:
                if itype in ('slack', 'teams', 'discord'):
                    await _send_chat_notification(client, cfg.get('webhookUrl'), case, event_type, itype)
                elif itype == 'jira':
                    new_refs.append(await _create_jira_issue(client, cfg, case))
                elif itype == 'servicenow':
                    new_refs.append(await _create_servicenow_incident(client, cfg, case))
                elif itype == 'generic_webhook':
                    await _send_generic_webhook(client, cfg, case, event_type)
                elif itype in ('pagerduty', 'opsgenie'):
                    # is_open_event -> page (trigger); is_close_event -> resolve
                    # the same incident, keyed on the case id so PD/Opsgenie
                    # tie them together instead of treating them as unrelated.
                    action = 'trigger' if is_open_event else 'resolve'
                    summary = f'Case {"opened" if event_type == "created" else event_type}: {case.get("title")}'
                    await _send_paging_event(
                        client, itype, cfg, dedup_key=f'case:{case["id"]}', action=action, summary=summary,
                        severity=case.get('severity', 'medium'),
                        details={"status": case.get('status'), "source": case.get('source'), "device": case.get('deviceName')},
                    )
                integ['lastFiredAt'] = datetime.now(timezone.utc).isoformat()
                integ['fireCount'] = integ.get('fireCount', 0) + 1
                integ['lastError'] = None
            except Exception as e:
                integ['lastError'] = str(e)[:300]
                print(f"[Integrations] '{integ.get('name')}' ({itype}) failed for case {case.get('id')}: {e}")
    if touched:
        _save_integrations(slug, integrations)
    return new_refs

async def _dispatch_case_sla_breach(slug: str, case: dict, breach_kind: str):
    """Fired once per case per clock by case_sla_monitor_loop below, the
    moment a Case's acknowledge or resolve SLA is first crossed. Chat-only
    (slack/teams/discord/generic_webhook) — deliberately its own function
    rather than a new event_type on _dispatch_case_integrations above,
    because that function's jira/servicenow branches CREATE a new ticket for
    'open' events; routing an SLA breach through it would silently open a
    SECOND ticket for a case that likely already has one. `breach_kind` is
    'acknowledge' or 'resolve'. Reuses the same enabled/notifyOnOpen/
    minSeverity gate as a normal open notification, since "this needs
    attention" is the same signal either way."""
    integrations = _load_integrations(slug)
    case_rank = CASE_SEVERITY_RANK.get(case.get('severity', 'medium'), 1)
    event_type = f'sla_{breach_kind}_breached'
    touched = False
    if integrations:
        async with httpx.AsyncClient() as client:
            for integ in integrations:
                if not integ.get('enabled', True) or not integ.get('notifyOnOpen', True):
                    continue
                itype = integ.get('type')
                if itype not in ('slack', 'teams', 'discord', 'generic_webhook', 'pagerduty', 'opsgenie'):
                    continue
                if case_rank < CASE_SEVERITY_RANK.get(integ.get('minSeverity', 'low'), 0):
                    continue
                cfg = integ.get('config') or {}
                touched = True
                try:
                    if itype in ('slack', 'teams', 'discord'):
                        await _send_chat_notification(client, cfg.get('webhookUrl'), case, event_type, itype)
                    elif itype == 'generic_webhook':
                        await _send_generic_webhook(client, cfg, case, event_type)
                    else:  # pagerduty / opsgenie — a distinct incident per (case, breach clock), not the case's own open/close incident
                        await _send_paging_event(
                            client, itype, cfg, dedup_key=f'case_sla:{case["id"]}:{breach_kind}', action='trigger',
                            summary=f'SLA breach ({breach_kind}) on case: {case.get("title")}',
                            severity=case.get('severity', 'medium'),
                            details={"status": case.get('status'), "device": case.get('deviceName')},
                        )
                    integ['lastFiredAt'] = datetime.now(timezone.utc).isoformat()
                    integ['fireCount'] = integ.get('fireCount', 0) + 1
                    integ['lastError'] = None
                except Exception as e:
                    integ['lastError'] = str(e)[:300]
                    print(f"[Integrations] '{integ.get('name')}' ({itype}) SLA breach notify failed for case {case.get('id')}: {e}")
    if touched:
        _save_integrations(slug, integrations)
    await _send_alert_email(
        slug,
        subject=f'[SLA Breach] {case.get("title")}',
        body_text=(
            f'A Case has breached its {breach_kind} SLA and has not been {"acknowledged" if breach_kind == "acknowledge" else "resolved"} in time.\n\n'
            f'Title: {case.get("title")}\nSeverity: {case.get("severity")}\nStatus: {case.get("status")}\n'
            f'Device: {case.get("deviceName") or "—"}\nCase ID: {case.get("id")}\n'
        ),
    )

def _attach_external_refs(case: dict, refs: List[dict]):
    """Mutates `case` in place — caller (already holding the case inside an
    in-memory `cases` list, or about to save a freshly-loaded one) is
    responsible for persisting it afterward."""
    if not refs:
        return
    case.setdefault('externalRefs', []).extend(refs)
    now_iso = datetime.now(timezone.utc).isoformat()
    case['updatedAt'] = now_iso
    for ref in refs:
        case.setdefault('timeline', []).append(_case_timeline_entry('note_added', f'Ticket created: {ref["type"]} {ref["id"]}'))

_JIRA_REQUIRED_CFG = ('baseUrl', 'email', 'apiToken', 'projectKey')
_SERVICENOW_REQUIRED_CFG = ('instanceUrl', 'username', 'password')

@app.post("/api/integrations/{integration_id}/test", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def test_integration(
    integration_id: str,
    dry_run: bool = False,
    x_workspace_slug: Optional[str] = Header(None),
    dash: dict = Depends(verify_dashboard_token),
):
    """dry_run=true validates the integration's config shape (required fields
    present) without making any outbound request — added so Jira/ServiceNow
    can be sanity-checked without creating a real ticket every time someone
    clicks Test. Chat/webhook types are already low-risk (a message, not a
    persistent record), but honor dry_run the same way for consistency."""
    slug_key = x_workspace_slug or 'global'
    integrations = _load_integrations(slug_key)
    integ = next((t for t in integrations if t.get('id') == integration_id), None)
    if not integ:
        raise HTTPException(status_code=404, detail="Integration not found")
    itype = integ.get('type')
    cfg = integ.get('config') or {}

    if dry_run:
        required = {
            'jira': _JIRA_REQUIRED_CFG, 'servicenow': _SERVICENOW_REQUIRED_CFG,
            'slack': ('webhookUrl',), 'teams': ('webhookUrl',), 'discord': ('webhookUrl',),
            'generic_webhook': ('url',), 'pagerduty': ('routingKey',), 'opsgenie': ('apiKey',),
        }.get(itype, ())
        missing = [f for f in required if not cfg.get(f)]
        if missing:
            raise HTTPException(status_code=400, detail=f"Dry run: missing required config field(s): {', '.join(missing)}")
        return {"status": "ok", "dryRun": True, "detail": "Required config fields are present. No request was sent."}

    fake_case = {
        "id": "test", "title": "Test case — Applivery SOAR", "severity": "high",
        "status": "open", "source": "manual", "deviceName": "TEST-DEVICE-01", "policyName": None,
    }
    async with httpx.AsyncClient() as client:
        try:
            if itype in ('slack', 'teams', 'discord'):
                await _send_chat_notification(client, cfg.get('webhookUrl'), fake_case, 'created', itype)
            elif itype == 'jira':
                await _create_jira_issue(client, cfg, fake_case)
            elif itype == 'servicenow':
                await _create_servicenow_incident(client, cfg, fake_case)
            elif itype == 'generic_webhook':
                await _send_generic_webhook(client, cfg, fake_case, 'created')
            elif itype in ('pagerduty', 'opsgenie'):
                # Trigger then immediately resolve — proves the credentials
                # and routing work without leaving a dangling test page open
                # in the on-call tool for someone to notice at 3am.
                dedup_key = f'test:{integration_id}'
                await _send_paging_event(client, itype, cfg, dedup_key, 'trigger', 'Test alert — Applivery SOAR', severity='low')
                await _send_paging_event(client, itype, cfg, dedup_key, 'resolve', 'Test alert — Applivery SOAR', severity='low')
            else:
                raise ValueError(f"Unknown integration type '{itype}'")
        except Exception as e:
            raise HTTPException(status_code=400, detail=f"Test failed: {e}")
    return {"status": "ok"}

# ─── THREAT INTEL ENRICHMENT ───
# Manual, analyst-driven IOC lookup against configured threat intel
# providers — deliberately NOT an automatic background scan. This app is an
# MDM, not an EDR: devices don't carry network-flow or process telemetry, so
# there's no reliable source of IOCs to auto-enrich against. Instead, an
# analyst working a Case pastes in an IP/domain/hash/URL they've found
# elsewhere (an installed-app identifier, a log line, a phishing report) and
# gets it checked against every enabled provider that supports that IOC
# type — same "configure once, fires everywhere" shape as Ticketing/Chat
# Integrations just above, reusing its per-workspace JSON-file-store pattern.
THREAT_INTEL_DIR = os.path.join(DATA_DIR, "threat_intel")
if not os.path.exists(THREAT_INTEL_DIR):
    os.makedirs(THREAT_INTEL_DIR)

THREAT_INTEL_PROVIDER_TYPES = ('virustotal', 'abuseipdb', 'hibp', 'generic_rest')
# Which IOC types each provider type can actually look up — gates which
# providers get called for a given enrichment request.
THREAT_INTEL_PROVIDER_IOC_SUPPORT = {
    'virustotal': ('ip', 'domain', 'md5', 'sha1', 'sha256', 'url'),
    'abuseipdb': ('ip',),
    # Have I Been Pwned — breach/credential-exposure monitoring, the "has
    # this account shown up in a known data breach" signal none of the
    # existing IOC-reputation providers cover. Email-only: HIBP's breach
    # search API has no IP/domain/hash/url lookup.
    'hibp': ('email',),
    'generic_rest': ('ip', 'domain', 'md5', 'sha1', 'sha256', 'url', 'unknown'),  # blind passthrough — supports anything
}

def _threat_intel_file(slug: str) -> str:
    return os.path.join(THREAT_INTEL_DIR, f"{_slug_clean(slug)}.json")

_register_legacy_json('threat_intel_providers', lambda slug, key: _threat_intel_file(slug))

def _load_threat_intel_providers(slug: str) -> List[Dict[str, Any]]:
    items = _store_load(slug, 'threat_intel_providers', list)
    out = []
    for item in items:
        item = dict(item)
        item['config'] = _decrypt_threat_intel_config(item.get('type'), item.get('config') or {})
        out.append(item)
    return out

def _save_threat_intel_providers(slug: str, providers: List[Dict[str, Any]]):
    to_store = []
    for item in providers:
        item = dict(item)
        item['config'] = _encrypt_threat_intel_config(item.get('type'), item.get('config') or {})
        to_store.append(item)
    _store_save(slug, 'threat_intel_providers', to_store)

_IOC_SCAN_PATTERNS = [
    re.compile(r'https?://[^\s"\'<>]+'),
    re.compile(r'\b(?:\d{1,3}\.){3}\d{1,3}\b'),
    re.compile(r'\b[a-fA-F0-9]{64}\b'),
    re.compile(r'\b[a-fA-F0-9]{40}\b'),
    re.compile(r'\b[a-fA-F0-9]{32}\b'),
    re.compile(r'\b[^\s@]+@[^\s@]+\.[a-zA-Z]{2,}\b'),  # email — before the domain pattern below, else "user@" gets discarded and only the domain half matches
    re.compile(r'\b(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}\b'),
]

def _extract_ioc_candidates(text: str, limit: int = 3) -> List[str]:
    """Best-effort scan of free text (a case's initial note, or a newly added
    note) for IOC-looking tokens — URLs, IPs, hex hashes, or domain-like
    strings — so Threat Intel enrichment can auto-trigger on case/note
    creation instead of requiring an analyst to manually copy the value into
    the enrich box (see call sites in create_case/add_case_note). Patterns
    are tried most-specific-first (url/hash before the loose domain pattern),
    and a span already claimed by an earlier pattern isn't re-offered by a
    later one — otherwise an IP embedded in a URL would also get reported as
    a bare domain-shaped fragment."""
    text = text or ''
    found: List[str] = []
    claimed_spans: List[tuple] = []
    for pattern in _IOC_SCAN_PATTERNS:
        for m in pattern.finditer(text):
            if any(m.start() < e and s < m.end() for s, e in claimed_spans):
                continue
            value = m.group(0).rstrip('.,;:)')
            if value and value not in found:
                found.append(value)
                claimed_spans.append((m.start(), m.end()))
            if len(found) >= limit:
                return found
    return found

def _detect_ioc_type(value: str) -> str:
    v = (value or '').strip()
    if re.match(r'^https?://', v, re.IGNORECASE):
        return 'url'
    if re.match(r'^(\d{1,3}\.){3}\d{1,3}$', v):
        return 'ip'
    if re.match(r'^[a-fA-F0-9]{64}$', v):
        return 'sha256'
    if re.match(r'^[a-fA-F0-9]{40}$', v):
        return 'sha1'
    if re.match(r'^[a-fA-F0-9]{32}$', v):
        return 'md5'
    if re.match(r'^[^\s@]+@[^\s@]+\.[a-zA-Z]{2,}$', v):
        return 'email'
    if re.match(r'^[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}$', v) and ' ' not in v:
        return 'domain'
    return 'unknown'

async def _lookup_virustotal(client: httpx.AsyncClient, cfg: dict, ioc_type: str, ioc_value: str) -> dict:
    """VirusTotal API v3. Verdict/score derived from `last_analysis_stats`,
    the same aggregate every VT UI page surfaces front-and-center."""
    api_key = cfg.get('apiKey')
    if not api_key:
        raise ValueError("VirusTotal integration is missing an API key")
    headers = {"x-apikey": api_key}
    if ioc_type == 'ip':
        endpoint, gui_path = f"ip_addresses/{ioc_value}", f"ip-address/{ioc_value}"
    elif ioc_type == 'domain':
        endpoint, gui_path = f"domains/{ioc_value}", f"domain/{ioc_value}"
    elif ioc_type in ('md5', 'sha1', 'sha256'):
        endpoint, gui_path = f"files/{ioc_value}", f"file/{ioc_value}"
    elif ioc_type == 'url':
        url_id = base64.urlsafe_b64encode(ioc_value.encode()).decode().rstrip('=')
        endpoint, gui_path = f"urls/{url_id}", f"url/{url_id}"
    else:
        raise ValueError(f"VirusTotal doesn't support IOC type '{ioc_type}'")
    res = await client.get(f"https://www.virustotal.com/api/v3/{endpoint}", headers=headers, timeout=20.0)
    if res.status_code == 404:
        return {"verdict": "unknown", "score": None, "detail": "Not found in VirusTotal's dataset", "link": f"https://www.virustotal.com/gui/{gui_path}"}
    if res.status_code >= 300:
        raise ValueError(f"VirusTotal returned {res.status_code}: {res.text[:200]}")
    stats = ((res.json().get('data') or {}).get('attributes') or {}).get('last_analysis_stats') or {}
    malicious, suspicious = stats.get('malicious', 0), stats.get('suspicious', 0)
    total = sum(stats.values()) or 1
    verdict = 'malicious' if malicious > 0 else ('suspicious' if suspicious > 0 else 'clean')
    return {
        "verdict": verdict, "score": malicious,
        "detail": f"{malicious}/{total} engines flagged malicious, {suspicious} suspicious",
        "link": f"https://www.virustotal.com/gui/{gui_path}",
    }

async def _lookup_abuseipdb(client: httpx.AsyncClient, cfg: dict, ioc_value: str) -> dict:
    """AbuseIPDB — IP reputation only. abuseConfidenceScore is 0-100."""
    api_key = cfg.get('apiKey')
    if not api_key:
        raise ValueError("AbuseIPDB integration is missing an API key")
    headers = {"Key": api_key, "Accept": "application/json"}
    res = await client.get(
        "https://api.abuseipdb.com/api/v2/check",
        params={"ipAddress": ioc_value, "maxAgeInDays": 90},
        headers=headers, timeout=20.0,
    )
    if res.status_code >= 300:
        raise ValueError(f"AbuseIPDB returned {res.status_code}: {res.text[:200]}")
    data = res.json().get('data') or {}
    score = data.get('abuseConfidenceScore', 0)
    verdict = 'malicious' if score >= 75 else ('suspicious' if score >= 25 else 'clean')
    reports = data.get('totalReports', 0)
    return {
        "verdict": verdict, "score": score,
        "detail": f"Abuse confidence {score}/100 from {reports} report{'s' if reports != 1 else ''}",
        "link": f"https://www.abuseipdb.com/check/{ioc_value}",
    }

async def _lookup_hibp(client: httpx.AsyncClient, cfg: dict, ioc_value: str) -> dict:
    """Have I Been Pwned's breach-search API — confirmed shape via HIBP's
    own public API docs (haveibeenpwned.com/API/v3). Requires a paid API key
    (subscription-based rate limiting; there is no free tier for this
    endpoint — HIBP's only free API is Pwned Passwords, a different k-
    anonymity hash-range lookup this doesn't use) sent via the `hibp-api-key`
    header, plus a descriptive User-Agent — HIBP rejects requests without one.
    404 means the email has never appeared in a breach HIBP knows about
    (genuinely "clean", not "unknown" — HIBP's coverage is broad enough that
    this app treats it as a real verdict rather than hedging). A breach
    whose DataClasses includes "Passwords" is treated as 'malicious' (a
    credential, not just an email address, was exposed); any other breach is
    'suspicious'."""
    api_key = cfg.get('apiKey')
    if not api_key:
        raise ValueError("Have I Been Pwned integration is missing an API key")
    headers = {"hibp-api-key": api_key, "User-Agent": "Applivery-Big-Picture-SOAR"}
    res = await client.get(
        f"https://haveibeenpwned.com/api/v3/breachedaccount/{quote(ioc_value, safe='')}",
        params={"truncateResponse": "false"}, headers=headers, timeout=20.0,
    )
    if res.status_code == 404:
        return {"verdict": "clean", "score": 0, "detail": "Not found in any known breach", "link": "https://haveibeenpwned.com/"}
    if res.status_code == 429:
        raise ValueError("Have I Been Pwned rate limit hit — its API is throttled per API-key subscription tier")
    if res.status_code >= 300:
        raise ValueError(f"Have I Been Pwned returned {res.status_code}: {res.text[:200]}")
    breaches = res.json() or []
    breach_names = [b.get('Name') or b.get('Title') or 'Unknown breach' for b in breaches]
    has_password_exposure = any('Passwords' in (b.get('DataClasses') or []) for b in breaches)
    verdict = 'malicious' if has_password_exposure else ('suspicious' if breaches else 'clean')
    return {
        "verdict": verdict, "score": len(breaches),
        "detail": f"Found in {len(breaches)} breach{'es' if len(breaches) != 1 else ''}: {', '.join(breach_names[:5])}{'…' if len(breach_names) > 5 else ''}" + (" (includes exposed passwords)" if has_password_exposure else ""),
        "link": "https://haveibeenpwned.com/",
    }

async def _lookup_generic_rest(client: httpx.AsyncClient, cfg: dict, ioc_value: str) -> dict:
    """Escape hatch for any provider without a dedicated type above. `{{ ioc }}`
    in urlTemplate is substituted with the (URL-encoded) IOC value; the raw
    response is surfaced as-is since there's no generic way to parse an
    arbitrary API's verdict shape — an analyst reads the detail themselves."""
    template = cfg.get('urlTemplate')
    if not template:
        raise ValueError("No URL template configured")
    url = template.replace('{{ ioc }}', quote(ioc_value, safe='')).replace('{{ioc}}', quote(ioc_value, safe=''))
    res = await client.get(url, headers=(cfg.get('headers') or {}), timeout=20.0)
    if res.status_code >= 300:
        raise ValueError(f"Provider returned {res.status_code}: {res.text[:200]}")
    return {"verdict": "unknown", "score": None, "detail": res.text[:300], "link": None}

THREAT_INTEL_CACHE_TTL_SECONDS = 6 * 3600  # 6 hours — long enough to spare rate-limited free-tier providers (e.g. VirusTotal's 4 req/min) from being re-hit every time the same IOC is re-checked, short enough that a "clean" verdict doesn't go stale for days.

async def _run_threat_intel_lookup(slug: str, ioc_value: str, actor: Optional[str], use_cache: bool = True) -> List[dict]:
    """Runs `ioc_value` against every enabled provider that supports its
    detected type, in parallel (asyncio.gather — previously sequential, which
    meant a slow/rate-limited provider serialized behind the others for no
    reason since they're independent HTTP calls). One provider failing
    doesn't stop the others — each result (success or error) is still
    recorded so the analyst can see what was actually tried.

    Results for a given IOC are cached for THREAT_INTEL_CACHE_TTL_SECONDS
    (reuses the same _live_cache used for Applivery widget data, just keyed
    under a 'threat_intel:' namespace) — re-checking the same value shortly
    after just replays the cached verdict instead of burning another API call
    against every provider. `use_cache=False` bypasses this for an explicit
    "force re-check"."""
    ioc_type = _detect_ioc_type(ioc_value)
    cache_key = f"threat_intel:{ioc_type}:{ioc_value.lower()}"
    if use_cache:
        cached = _live_cache_get(slug, cache_key)
        if cached is not None:
            # Stamp a fresh id/checkedBy per replay so it reads as "you looked
            # this up again" in the Case timeline, while keeping the original
            # checkedAt/cached marker so the UI can show it wasn't a live call.
            return [{**r, "id": str(uuid.uuid4()), "checkedBy": actor, "cached": True} for r in cached]

    providers = [p for p in _load_threat_intel_providers(slug) if p.get('enabled', True) and ioc_type in THREAT_INTEL_PROVIDER_IOC_SUPPORT.get(p.get('type'), ())]
    now_iso = datetime.now(timezone.utc).isoformat()

    async def run_one(client: httpx.AsyncClient, provider: dict) -> dict:
        cfg = provider.get('config') or {}
        entry = {
            "id": str(uuid.uuid4()), "ioc": ioc_value, "iocType": ioc_type,
            "provider": provider.get('name'), "providerType": provider.get('type'),
            "checkedAt": now_iso, "checkedBy": actor, "cached": False,
        }
        try:
            if provider['type'] == 'virustotal':
                entry.update(await _lookup_virustotal(client, cfg, ioc_type, ioc_value))
            elif provider['type'] == 'abuseipdb':
                entry.update(await _lookup_abuseipdb(client, cfg, ioc_value))
            elif provider['type'] == 'hibp':
                entry.update(await _lookup_hibp(client, cfg, ioc_value))
            elif provider['type'] == 'generic_rest':
                entry.update(await _lookup_generic_rest(client, cfg, ioc_value))
        except Exception as e:
            entry.update({"verdict": "error", "score": None, "detail": str(e)[:300], "link": None})
        return entry

    async with httpx.AsyncClient() as client:
        results = list(await asyncio.gather(*[run_one(client, p) for p in providers]))

    if results:
        _live_cache_set(slug, cache_key, results, ttl_seconds=THREAT_INTEL_CACHE_TTL_SECONDS)

    if ioc_type == 'unknown' and not providers:
        # Nothing could classify this value AND no generic_rest provider (the
        # only type willing to attempt an 'unknown' IOC) is configured —
        # surface that clearly instead of silently returning an empty list.
        results.append({
            "id": str(uuid.uuid4()), "ioc": ioc_value, "iocType": "unknown", "provider": None, "providerType": None,
            "verdict": "unknown", "score": None,
            "detail": "Couldn't classify this value as an IP, domain, URL, or file hash — no provider was queried",
            "link": None, "checkedAt": now_iso, "checkedBy": actor,
        })
    return results

class ThreatIntelProviderPayload(BaseModel):
    name: str
    type: str  # one of THREAT_INTEL_PROVIDER_TYPES
    enabled: bool = True
    # Type-specific shape:
    #   virustotal/abuseipdb: {"apiKey": "..."}
    #   generic_rest: {"urlTemplate": "https://api.example.com/lookup?q={{ ioc }}", "headers": {...}}
    config: Dict[str, Any] = {}

@app.get("/api/threat-intel/providers", dependencies=[Depends(verify_dashboard_token)])
async def list_threat_intel_providers(x_workspace_slug: Optional[str] = Header(None)):
    return {"items": _load_threat_intel_providers(x_workspace_slug or 'global')}

@app.post("/api/threat-intel/providers", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def create_threat_intel_provider(payload: ThreatIntelProviderPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    if payload.type not in THREAT_INTEL_PROVIDER_TYPES:
        raise HTTPException(status_code=400, detail=f"type must be one of {THREAT_INTEL_PROVIDER_TYPES}")
    slug_key = x_workspace_slug or 'global'
    providers = _load_threat_intel_providers(slug_key)
    now = datetime.now(timezone.utc).isoformat()
    provider_id = str(uuid.uuid4())
    new_provider = payload.dict()
    new_provider.update({"id": provider_id, "createdBy": dash.get('sub'), "createdAt": now, "updatedAt": now})
    providers.append(new_provider)
    _save_threat_intel_providers(slug_key, providers)
    _record_audit_event(slug_key, category="threat_intel", action="threat_intel_provider_created", actor=dash.get('sub'),
                         target_type="threat_intel_provider", target_id=provider_id, target_name=new_provider.get('name'),
                         message=f'Threat intel provider "{new_provider.get("name")}" ({new_provider.get("type")}) created by {dash.get("sub")}')
    return new_provider

@app.put("/api/threat-intel/providers/{provider_id}", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def update_threat_intel_provider(provider_id: str, payload: ThreatIntelProviderPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    if payload.type not in THREAT_INTEL_PROVIDER_TYPES:
        raise HTTPException(status_code=400, detail=f"type must be one of {THREAT_INTEL_PROVIDER_TYPES}")
    slug_key = x_workspace_slug or 'global'
    providers = _load_threat_intel_providers(slug_key)
    idx = next((i for i, p in enumerate(providers) if p.get('id') == provider_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Provider not found")
    existing = providers[idx]
    updated = payload.dict()
    updated.update({"id": provider_id, "createdBy": existing.get('createdBy'), "createdAt": existing.get('createdAt'), "updatedAt": datetime.now(timezone.utc).isoformat()})
    providers[idx] = updated
    _save_threat_intel_providers(slug_key, providers)
    _record_audit_event(slug_key, category="threat_intel", action="threat_intel_provider_updated", actor=dash.get('sub'),
                         target_type="threat_intel_provider", target_id=provider_id, target_name=updated.get('name'),
                         message=f'Threat intel provider "{updated.get("name")}" updated by {dash.get("sub")}')
    return updated

@app.delete("/api/threat-intel/providers/{provider_id}", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def delete_threat_intel_provider(provider_id: str, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    providers = _load_threat_intel_providers(slug_key)
    idx = next((i for i, p in enumerate(providers) if p.get('id') == provider_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Provider not found")
    removed = providers.pop(idx)
    _save_threat_intel_providers(slug_key, providers)
    _record_audit_event(slug_key, category="threat_intel", action="threat_intel_provider_deleted", actor=dash.get('sub'), severity="warning",
                         target_type="threat_intel_provider", target_id=provider_id, target_name=removed.get('name'),
                         message=f'Threat intel provider "{removed.get("name")}" deleted by {dash.get("sub")}')
    return {"status": "ok"}

@app.post("/api/threat-intel/providers/{provider_id}/test", dependencies=[Depends(verify_dashboard_token), Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def test_threat_intel_provider(provider_id: str, x_workspace_slug: Optional[str] = Header(None)):
    """Looks up a well-known, benign IP (Google Public DNS, 8.8.8.8) — works
    for every provider type including generic_rest, and won't trip a
    provider's abuse/report-noise heuristics the way a random malicious hash
    might."""
    slug_key = x_workspace_slug or 'global'
    provider = next((p for p in _load_threat_intel_providers(slug_key) if p.get('id') == provider_id), None)
    if not provider:
        raise HTTPException(status_code=404, detail="Provider not found")
    cfg = provider.get('config') or {}
    async with httpx.AsyncClient() as client:
        try:
            if provider['type'] == 'virustotal':
                result = await _lookup_virustotal(client, cfg, 'ip', '8.8.8.8')
            elif provider['type'] == 'abuseipdb':
                result = await _lookup_abuseipdb(client, cfg, '8.8.8.8')
            elif provider['type'] == 'hibp':
                # HIBP's own official test account for integration testing —
                # documented in their API docs, always returns a fixed set
                # of breaches, never a real person's data. 8.8.8.8 isn't a
                # valid email, so this provider needs its own test value.
                result = await _lookup_hibp(client, cfg, 'account-exists@hibp-integration-tests.com')
            elif provider['type'] == 'generic_rest':
                result = await _lookup_generic_rest(client, cfg, '8.8.8.8')
            else:
                raise ValueError(f"Unknown provider type '{provider['type']}'")
        except Exception as e:
            raise HTTPException(status_code=400, detail=f"Test failed: {e}")
    return {"status": "ok", "result": result}

class CaseEnrichPayload(BaseModel):
    value: str
    forceRefresh: bool = False  # bypasses the cache described on _run_threat_intel_lookup — for when an analyst wants a live re-check, not the last cached verdict

@app.post("/api/cases/{case_id}/enrich", dependencies=[Depends(verify_dashboard_token)])
async def enrich_case(case_id: str, payload: CaseEnrichPayload, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    if not payload.value or not payload.value.strip():
        raise HTTPException(status_code=400, detail="value is required")
    slug_key = x_workspace_slug or 'global'
    cases = _load_cases(slug_key)
    idx = next((i for i, c in enumerate(cases) if c.get('id') == case_id), None)
    if idx is None:
        raise HTTPException(status_code=404, detail="Case not found")
    case = cases[idx]
    actor = dash.get('sub')
    ioc_value = payload.value.strip()

    if not _load_threat_intel_providers(slug_key):
        raise HTTPException(status_code=400, detail="No threat intel providers configured yet — add one under Settings > Threat Intel.")

    # De-dup guard: skip if this exact IOC was already enriched on this case
    # (the audit's "results just accumulate, no dedup" gap) — a forced
    # refresh always proceeds regardless.
    if not payload.forceRefresh:
        already = next((r for r in (case.get('threatIntel') or []) if r.get('ioc', '').lower() == ioc_value.lower()), None)
        if already:
            raise HTTPException(status_code=409, detail=f"'{ioc_value}' was already checked on this case ({already.get('checkedAt', 'earlier')}) — use force refresh to re-check.")

    results = await _run_threat_intel_lookup(slug_key, ioc_value, actor, use_cache=not payload.forceRefresh)
    case.setdefault('threatIntel', []).extend(results)
    verdicts = {r['verdict'] for r in results if r.get('provider')}
    summary = 'malicious' if 'malicious' in verdicts else ('suspicious' if 'suspicious' in verdicts else ('clean' if verdicts else 'no result'))
    case.setdefault('timeline', []).append(_case_timeline_entry('note_added', f'Threat intel: {ioc_value} enriched by {actor} — {summary} ({len(results)} provider result{"s" if len(results) != 1 else ""})', actor))
    case['updatedAt'] = datetime.now(timezone.utc).isoformat()
    cases[idx] = case
    _save_cases(slug_key, cases)
    return case

# ─── THE MASTER WIDGET PROXY ───

def _widget_trend_date_map(dateIni: Optional[str], dateEnd: Optional[str], default_days: int = 14, max_days: int = 60) -> Dict[str, int]:
    """Shared date-bucket skeleton for the widget system's newer SOAR trend
    sources (cases_trend, workflow_runs_trend) — an ordered {"MM-DD": 0, ...}
    map covering either the requested date range or the last `default_days`
    days, ready to be incremented while scanning timestamped records. Mirrors
    the inline date-map logic compliance_violations_trend already used
    (left as-is below, to avoid touching working code) — factored out here
    only for the sources added alongside it."""
    today = datetime.now(timezone.utc)
    date_map: Dict[str, int] = {}
    if dateIni and dateEnd:
        try:
            d_start = datetime.fromisoformat(dateIni + "T00:00:00+00:00")
            d_stop = datetime.fromisoformat(dateEnd + "T23:59:59+00:00")
            delta_days = min((d_stop - d_start).days + 1, max_days)
            for i in range(delta_days):
                date_map[(d_start + timedelta(days=i)).strftime("%m-%d")] = 0
            return date_map
        except Exception:
            pass
    for i in range(default_days - 1, -1, -1):
        date_map[(today - timedelta(days=i)).strftime("%m-%d")] = 0
    return date_map

@app.get("/api/analytics/widget", dependencies=[Depends(verify_dashboard_token)])
async def get_widget_data(
    source: str,
    chart_type: str,
    filters: str = "{}",
    dateIni: Optional[str] = None,
    dateEnd: Optional[str] = None,
    timeLapse: Optional[str] = None,
    authorization: Optional[str] = Header(None),
    x_workspace_slug: Optional[str] = Header(None)
):
    if not authorization or not x_workspace_slug:
        raise HTTPException(401, "Missing credentials")

    try: filter_dict = json.loads(filters)
    except: filter_dict = {}

    # ── CACHE + SNAPSHOT ROUTING ──
    # Three-tier strategy to keep data fresh without blasting the Applivery API:
    #
    #  Tier 1 — "Today" (no date filter or dateIni==today):
    #    Serve from in-memory live cache (TTL=5min). On cache miss → one live API call,
    #    result cached in memory AND saved as today's snapshot. Max 1 API call per 5 min
    #    per source regardless of how many widgets/users are loading simultaneously.
    #
    #  Tier 2 — Any historical range (dateIni < today):
    #    Served 100% from disk snapshots. Zero live API calls.
    #
    #  Tier 3 — No snapshots exist yet for a historical range:
    #    Fall through to live API as a one-time fallback (snapshot saved for next time).

    today_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    slug_key = x_workspace_slug or 'global'

    # Tier 2: Historical range → snapshots only, no live call
    if dateIni and dateEnd:
        is_today_only = (dateIni == today_str and dateEnd == today_str)
        if not is_today_only:
            snap = _aggregate_snapshots_for_range(slug_key, source, dateIni, dateEnd)
            if snap is not None:
                return snap
            # Tier 3 fallback: no snapshots yet, fall through to live API below

    # Tier 1: Today (or no date filter) → check in-memory live cache first
    if not (dateIni and dateEnd and dateIni < today_str):
        cached = _live_cache_get(slug_key, source)
        if cached is not None:
            return cached

    base_params = {}
    if filter_dict.get('segmentId') and str(filter_dict['segmentId']) != '0':
        base_params['segmentId'] = filter_dict['segmentId']

    timeout_config = httpx.Timeout(60.0, connect=15.0, read=60.0)

    async with httpx.AsyncClient(timeout=timeout_config) as client:
        headers = {"Authorization": authorization, "Content-Type": "application/json"}
        base_url = "https://api.applivery.io/v1"

        hex_id = x_workspace_slug
        if not re.match(r'^[a-fA-F0-9]{24}$', hex_id):
            org_res = await _applivery_call(client, 'GET', f"{base_url}/organizations/{x_workspace_slug}", headers=headers)
            if org_res.status_code == 200:
                d = org_res.json().get("data", org_res.json())
                hex_id = d.get("_id", d.get("id", hex_id))

        org_base = f"{base_url}/organizations/{hex_id}"

        response_data = {
            "chartData": [], "trendData": {"labels": [], "series": [], "os_totals": {'apple': 0, 'android': 0, 'windows': 0}},
            "scorecardValue": 0, "items": [], "orgProfile": {}
        }

        # 0. System Health — global across every workspace (see the "SYSTEM
        # HEALTH" module comment near start_scheduler), not scoped to
        # slug_key like everything else here. Returned before any org/hex_id
        # resolution above needs to happen, since this widget touches no
        # Applivery data at all — no reason to spend a live API call finding
        # out which org slug_key maps to just to ignore it.
        if source == 'system_health_summary':
            jobs = (await get_system_health())['items']
            agg = {"Healthy": 0, "Overdue": 0, "Erroring": 0, "No data yet": 0}
            for job in jobs:
                if job['overdue']:
                    agg["Overdue"] += 1
                elif job['lastStatus'] == 'error':
                    agg["Erroring"] += 1
                elif job['lastStatus'] == 'ok':
                    agg["Healthy"] += 1
                else:
                    agg["No data yet"] += 1
            response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items() if v > 0]
            response_data["scorecardValue"] = agg["Overdue"] + agg["Erroring"]
            response_data["items"] = jobs
            return response_data

        # 0.5 OS Update Catalog summary — pure local read of the MSRC-sourced
        # catalog (see "OS UPDATE INTELLIGENCE" section), global not
        # workspace-scoped, same early-return reasoning as System Health
        # above: no Applivery data needed, so no reason to resolve org/hex_id
        # first.
        if source == 'os_updates_catalog_summary':
            catalog = _load_os_update_catalog()
            entries = catalog.get('kbEntries') or []
            agg: Dict[str, int] = {}
            for e in entries:
                sev = (e.get('maxSeverity') or 'Unknown').title()
                agg[sev] = agg.get(sev, 0) + 1
            response_data["chartData"] = sorted(
                [{"name": k, "value": v} for k, v in agg.items() if v > 0],
                key=lambda x: x["value"], reverse=True,
            )
            response_data["scorecardValue"] = len(entries)
            response_data["items"] = entries[:100]
            response_data["orgProfile"] = {
                "monthsFetched": catalog.get('monthsFetched') or [],
                "lastFetchedAt": catalog.get('lastFetchedAt'),
                "lastError": catalog.get('lastError'),
            }
            return response_data

        # 0.6 Apple/Android Vulnerability Catalog summary — pure local read
        # of the EUVD-sourced catalog (see "APPLE & ANDROID VULNERABILITY
        # INTELLIGENCE" section), global not workspace-scoped, same
        # early-return reasoning as the two sources above it.
        if source == 'vuln_catalog_summary':
            vcatalog = _load_vuln_catalog()
            ventries = vcatalog.get('entries') or []
            agg: Dict[str, int] = {}
            for e in ventries:
                sev = e.get('baseSeverity') or 'Unknown'
                agg[sev] = agg.get(sev, 0) + 1
            response_data["chartData"] = sorted(
                [{"name": k, "value": v} for k, v in agg.items() if v > 0],
                key=lambda x: x["value"], reverse=True,
            )
            response_data["scorecardValue"] = len(ventries)
            response_data["items"] = ventries[:100]
            response_data["orgProfile"] = {
                "lastFetchedAt": vcatalog.get('lastFetchedAt'), "lastError": vcatalog.get('lastError'),
                "windowFrom": vcatalog.get('windowFrom'),
            }
            return response_data

        # 0.7 OS Lifecycle summary — pure local read of the endoflife.date
        # catalog (see "OS LIFECYCLE" section), global not workspace-scoped,
        # same early-return reasoning as the two sources above it.
        if source == 'os_lifecycle_summary':
            lcatalog = _load_os_lifecycle_catalog()
            platforms = lcatalog.get('platforms') or {}
            agg: Dict[str, int] = {}
            total = 0
            for plat, releases in platforms.items():
                for r in releases:
                    total += 1
                    bucket = "EOL" if r.get('isEol') else ("Maintained" if r.get('isMaintained') else "Unknown")
                    agg[bucket] = agg.get(bucket, 0) + 1
            response_data["chartData"] = sorted(
                [{"name": k, "value": v} for k, v in agg.items() if v > 0],
                key=lambda x: x["value"], reverse=True,
            )
            response_data["scorecardValue"] = agg.get("EOL", 0)
            response_data["items"] = [r for releases in platforms.values() for r in releases][:100]
            response_data["orgProfile"] = {"lastFetchedAt": lcatalog.get('lastFetchedAt'), "lastError": lcatalog.get('lastError')}
            return response_data

        # 0.8 Apple pending app updates (HasUpdateAvailable) — per-workspace,
        # pure local read of the installed-apps store populated by
        # installed_apps_refresher_loop (see "Apple pending app updates"
        # section). Unlike the OS-level catalogs above this is tenant data,
        # not a global feed, so it's keyed by slug_key rather than being
        # workspace-independent — but still no live Applivery call needed to
        # render the widget itself.
        if source == 'apple_app_updates_summary':
            iastore = _load_installed_apps_store(slug_key)
            apple_entries = [(did, e) for did, e in iastore.items() if e.get('platform') == 'apple' and e.get('appleAppUpdates')]
            devices_with_pending = 0
            total_pending_instances = 0
            app_frequency: Dict[str, int] = {}
            pending_items = []
            for did, e in apple_entries:
                pending_apps = (e.get('appleAppUpdates') or {}).get('pendingApps') or []
                if pending_apps:
                    devices_with_pending += 1
                    total_pending_instances += len(pending_apps)
                    for a in pending_apps:
                        name = a.get('name') or a.get('identifier') or 'Unknown app'
                        app_frequency[name] = app_frequency.get(name, 0) + 1
                        pending_items.append({"deviceId": did, **a})
            response_data["chartData"] = sorted(
                [{"name": k, "value": v} for k, v in app_frequency.items()],
                key=lambda x: x["value"], reverse=True,
            )[:15]
            response_data["scorecardValue"] = devices_with_pending
            response_data["items"] = pending_items[:200]
            response_data["orgProfile"] = {
                "devicesSynced": len(apple_entries),
                "devicesWithPendingUpdates": devices_with_pending,
                "totalPendingAppInstances": total_pending_instances,
            }
            return response_data

        # 1. Organization Profile
        if source == 'org_profile':
            res = await _applivery_call(client, 'GET', org_base, headers=headers)
            mdm_res = await _applivery_call(client, 'GET', f"{org_base}/mdm/", headers=headers)
            if res.status_code == 200:
                raw_json = res.json()
                org_data = raw_json.get("data", raw_json)
                if mdm_res.status_code == 200:
                    org_data["mdmInfo"] = mdm_res.json().get("data", {})
                response_data["orgProfile"] = org_data
            return response_data

        # 2. Segments
        if source == 'mdm_segments':
            res = await _applivery_call(client, 'GET', f"{org_base}/segments/by-user", headers=headers)
            if res.status_code == 200:
                raw_items = extract_items(res.json())
                flat_items = flatten_segments(raw_items, 0)
                agg = {}
                for item in flat_items:
                    name = str(item.get("name") or "Unnamed")
                    count = int(item.get("counts", {}).get("devices") or item.get("deviceCount") or 1)
                    agg[name] = agg.get(name, 0) + count
                response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items()]
                response_data["scorecardValue"] = len(flat_items)
                response_data["items"] = flat_items
            return response_data

        # 2.5 Compliance (SOAR) — computed entirely from our own policy/violation
        # store, not Applivery's analytics API. `state` (see _load_compliance_state)
        # holds one entry per currently-still-violating policy+device pair — it's
        # deleted the moment a device recovers — so it's the live "who's out of
        # compliance right now" set. `violations` is the append-only historical
        # log (detectedAt timestamps), used for the trend chart. Cheap local
        # reads, so these skip the live-cache/snapshot machinery entirely (same
        # pattern as org_profile/mdm_segments above).
        if source in ('compliance_policies_summary', 'compliance_devices_violating', 'compliance_violations_by_policy', 'compliance_violations_trend', 'compliance_review_queue', 'autorun_safety_summary'):
            policies = _load_compliance_policies(slug_key)
            state = _load_compliance_state(slug_key)
            violations = _load_compliance_violations(slug_key)
            policies_by_id = {p.get('id'): p for p in policies}

            if source == 'compliance_policies_summary':
                enabled_count = sum(1 for p in policies if p.get('enabled', True))
                response_data["scorecardValue"] = len(policies)
                response_data["chartData"] = [
                    {"name": "Enabled", "value": enabled_count},
                    {"name": "Disabled", "value": len(policies) - enabled_count},
                ]
                response_data["items"] = policies
                return response_data

            if source == 'compliance_devices_violating':
                devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
                all_devices = devices_resp.get('items', [])
                violating_ids = {k.split(':', 1)[1] for k in state.keys() if ':' in k}
                violating = [d for d in all_devices if d.get('id') in violating_ids]
                response_data["scorecardValue"] = len(violating)
                response_data["chartData"] = [
                    {"name": "Non-compliant", "value": len(violating)},
                    {"name": "Compliant", "value": len(all_devices) - len(violating)},
                ]
                response_data["items"] = violating
                return response_data

            if source == 'compliance_violations_by_policy':
                agg = {}
                for key in state.keys():
                    policy_id = key.split(':', 1)[0]
                    policy = policies_by_id.get(policy_id)
                    name = policy.get('name') if policy else 'Deleted policy'
                    agg[name] = agg.get(name, 0) + 1
                response_data["chartData"] = sorted([{"name": k, "value": v} for k, v in agg.items()], key=lambda x: x["value"], reverse=True)
                response_data["scorecardValue"] = len(state)
                return response_data

            if source == 'compliance_violations_trend':
                today = datetime.now(timezone.utc)
                date_map = {}
                if dateIni and dateEnd:
                    try:
                        d_start = datetime.fromisoformat(dateIni + "T00:00:00+00:00")
                        d_stop = datetime.fromisoformat(dateEnd + "T23:59:59+00:00")
                        delta_days = min((d_stop - d_start).days + 1, 60)
                        for i in range(delta_days):
                            date_map[(d_start + timedelta(days=i)).strftime("%m-%d")] = 0
                    except Exception:
                        for i in range(13, -1, -1):
                            date_map[(today - timedelta(days=i)).strftime("%m-%d")] = 0
                else:
                    for i in range(13, -1, -1):
                        date_map[(today - timedelta(days=i)).strftime("%m-%d")] = 0
                for v in violations:
                    detected = v.get('detectedAt')
                    if not detected:
                        continue
                    try:
                        dt = datetime.fromisoformat(str(detected).replace('Z', '+00:00'))
                        d_str = dt.strftime("%m-%d")
                        if d_str in date_map:
                            date_map[d_str] += 1
                    except Exception:
                        pass
                response_data["trendData"] = {"labels": list(date_map.keys()), "series": list(date_map.values()), "os_totals": {'apple': 0, 'android': 0, 'windows': 0}}
                response_data["scorecardValue"] = sum(date_map.values())
                return response_data

            if source == 'compliance_review_queue':
                status_labels = {"pending": "Pending review", "auto_fired": "Auto-fired", "no_workflow": "No workflow", "approved": "Approved", "dismissed": "Dismissed"}
                agg = {}
                for entry in state.values():
                    label = status_labels.get(entry.get('status'), entry.get('status') or 'Unknown')
                    agg[label] = agg.get(label, 0) + 1
                response_data["chartData"] = sorted([{"name": k, "value": v} for k, v in agg.items()], key=lambda x: x["value"], reverse=True)
                response_data["scorecardValue"] = len(state)
                return response_data

            if source == 'autorun_safety_summary':
                # Surfaces the autoRun circuit breaker / blast-radius cap /
                # destructive-ack gate work — how much of autoRun's recent
                # activity was a normal fire vs. a safety mechanism stepping in.
                status_labels = {"auto_fired": "Auto-fired", "autorun_blocked": "Blocked (safety)", "autorun_capped": "Capped (batch limit)"}
                agg = {label: 0 for label in status_labels.values()}
                for v in violations:
                    label = status_labels.get(v.get('status'))
                    if label:
                        agg[label] += 1
                response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items()]
                response_data["scorecardValue"] = agg["Blocked (safety)"] + agg["Capped (batch limit)"]
                return response_data

        # 2.55 Compliance Framework reports (ISO27001/ENS/NIS2) — rolls live
        # policies up by which COMPLIANCE_POLICY_TEMPLATES control they
        # enforce (via the framework/controlRef tags CompliancePolicyPayload
        # carries — see TemplateGallery.jsx/PolicyBuilder.jsx). A control
        # with no matching policy still shows up (configured=False) — the
        # point of a framework report is as much "here's the gap" as
        # "here's what's covered". DORA was deliberately never given a
        # source here — see the COMPLIANCE_FRAMEWORKS comment in this file
        # for why it was dropped from the catalog entirely.
        if source in _COMPLIANCE_FRAMEWORK_WIDGET_SOURCES:
            if source == 'compliance_framework_coverage':
                chart_data, items, coverage_pcts = [], [], []
                for fw in COMPLIANCE_FRAMEWORKS:
                    rows, _violating_ids = _compliance_framework_rows(slug_key, fw['key'])
                    total = len(rows)
                    configured_count = sum(1 for r in rows if r['configured'])
                    enabled_count = sum(1 for r in rows if r['enabled'])
                    pct = round((enabled_count / total) * 100) if total else 0
                    coverage_pcts.append(pct)
                    chart_data.append({"name": fw['shortLabel'], "value": pct})
                    items.append({
                        "framework": fw['key'], "label": fw['label'], "shortLabel": fw['shortLabel'],
                        "controlsTotal": total, "controlsConfigured": configured_count,
                        "controlsEnabled": enabled_count, "coveragePercent": pct,
                    })
                response_data["chartData"] = chart_data
                response_data["scorecardValue"] = round(sum(coverage_pcts) / len(coverage_pcts)) if coverage_pcts else 0
                response_data["items"] = items
                return response_data

            framework_key = _COMPLIANCE_FRAMEWORK_WIDGET_SOURCES[source]
            rows, violating_ids = _compliance_framework_rows(slug_key, framework_key)
            response_data["chartData"] = [{"name": r["title"], "value": r["violatingDeviceCount"]} for r in rows]
            response_data["scorecardValue"] = len(violating_ids)
            response_data["items"] = rows
            return response_data

        # 2.6 Cases (SOAR) — the Cases store, same in-memory-then-scan pattern
        # as Compliance above. Not scoped to a single origin — a Case's
        # `source` field (manual / compliance_violation / workflow_trigger)
        # is itself one of the breakdowns below, precisely to show how cases
        # actually enter the system across every path Cases now supports.
        if source in ('cases_summary', 'cases_by_severity', 'cases_by_source', 'cases_trend', 'cases_sla_summary', 'cases_mttr_trend'):
            cases = _load_cases(slug_key)

            if source == 'cases_sla_summary':
                thresholds = _load_case_sla_settings(slug_key).get('thresholds', {})
                agg = {"On track": 0, "Acknowledge overdue": 0, "Resolve overdue": 0}
                for c in cases:
                    if c.get('status') not in CASE_OPEN_STATUSES:
                        continue
                    status = _case_sla_status(c, thresholds)
                    # A case can be breached on both clocks at once — bucketed
                    # by the more severe one (resolve) so the totals below
                    # still add up to "open cases", rather than double-counting.
                    if status['resolveBreached']:
                        agg["Resolve overdue"] += 1
                    elif status['ackBreached']:
                        agg["Acknowledge overdue"] += 1
                    else:
                        agg["On track"] += 1
                response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items()]
                response_data["scorecardValue"] = agg["Resolve overdue"] + agg["Acknowledge overdue"]
                response_data["items"] = [c for c in cases if c.get('status') in CASE_OPEN_STATUSES]
                return response_data

            if source == 'cases_mttr_trend':
                date_map = _widget_trend_date_map(dateIni, dateEnd)
                hour_sums = {k: 0.0 for k in date_map}
                counts = {k: 0 for k in date_map}
                for c in cases:
                    closed = c.get('closedAt')
                    created = c.get('createdAt')
                    if not closed or not created:
                        continue
                    try:
                        closed_dt = datetime.fromisoformat(str(closed).replace('Z', '+00:00'))
                        created_dt = datetime.fromisoformat(str(created).replace('Z', '+00:00'))
                        d_str = closed_dt.strftime("%m-%d")
                        if d_str in date_map:
                            hour_sums[d_str] += (closed_dt - created_dt).total_seconds() / 3600.0
                            counts[d_str] += 1
                    except Exception:
                        pass
                averages = [round(hour_sums[k] / counts[k], 1) if counts[k] else 0 for k in date_map]
                response_data["trendData"] = {"labels": list(date_map.keys()), "series": averages, "os_totals": {'apple': 0, 'android': 0, 'windows': 0}}
                resolved_total = sum(counts.values())
                response_data["scorecardValue"] = round(sum(hour_sums.values()) / resolved_total, 1) if resolved_total else 0
                return response_data

            if source == 'cases_summary':
                status_labels = {"open": "Open", "investigating": "Investigating", "resolved": "Resolved", "closed": "Closed", "false_positive": "False positive"}
                agg = {}
                for c in cases:
                    label = status_labels.get(c.get('status'), c.get('status') or 'Unknown')
                    agg[label] = agg.get(label, 0) + 1
                response_data["scorecardValue"] = sum(1 for c in cases if c.get('status') in CASE_OPEN_STATUSES)
                response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items()]
                response_data["items"] = cases
                return response_data

            if source == 'cases_by_severity':
                sev_order = ['low', 'medium', 'high', 'critical']
                agg = {s: 0 for s in sev_order}
                for c in cases:
                    if c.get('status') not in CASE_OPEN_STATUSES:
                        continue
                    sev = c.get('severity') or 'medium'
                    if sev in agg:
                        agg[sev] += 1
                response_data["chartData"] = [{"name": s.title(), "value": agg[s]} for s in sev_order]
                response_data["scorecardValue"] = sum(agg.values())
                return response_data

            if source == 'cases_by_source':
                source_labels = {"manual": "Manual", "compliance_violation": "Compliance violation", "workflow_trigger": "Inbound trigger", "applivery_webhook": "Applivery event"}
                agg = {}
                for c in cases:
                    label = source_labels.get(c.get('source'), c.get('source') or 'Unknown')
                    agg[label] = agg.get(label, 0) + 1
                response_data["chartData"] = sorted([{"name": k, "value": v} for k, v in agg.items()], key=lambda x: x["value"], reverse=True)
                response_data["scorecardValue"] = len(cases)
                return response_data

            if source == 'cases_trend':
                date_map = _widget_trend_date_map(dateIni, dateEnd)
                for c in cases:
                    created = c.get('createdAt')
                    if not created:
                        continue
                    try:
                        dt = datetime.fromisoformat(str(created).replace('Z', '+00:00'))
                        d_str = dt.strftime("%m-%d")
                        if d_str in date_map:
                            date_map[d_str] += 1
                    except Exception:
                        pass
                response_data["trendData"] = {"labels": list(date_map.keys()), "series": list(date_map.values()), "os_totals": {'apple': 0, 'android': 0, 'windows': 0}}
                response_data["scorecardValue"] = sum(date_map.values())
                return response_data

        # 2.6 Applivery Event Webhook — see the "APPLIVERY EVENT WEBHOOK"
        # module comment above receive_applivery_webhook. recentEvents is
        # capped at 50 (see that endpoint), so these three widgets reflect
        # "the last 50 events received", not a true rolling window — worth
        # remembering on a workspace where Applivery's own webhook fires
        # often, but this is the same store the Settings > Applivery Events
        # page's own recent-events feed already reads, so it stays consistent
        # with what an admin sees there.
        if source in ('applivery_events_by_type', 'applivery_events_trend', 'applivery_automation_outcomes'):
            events = _load_applivery_webhook_config(slug_key).get('recentEvents', [])

            if source == 'applivery_events_by_type':
                agg = {}
                for ev in events:
                    label = _applivery_webhook_label(ev.get('canonicalKey') or ev.get('actionKey') or '')
                    agg[label] = agg.get(label, 0) + 1
                response_data["chartData"] = sorted([{"name": k, "value": v} for k, v in agg.items()], key=lambda x: x["value"], reverse=True)
                response_data["scorecardValue"] = len(events)
                response_data["items"] = events
                return response_data

            if source == 'applivery_events_trend':
                date_map = _widget_trend_date_map(dateIni, dateEnd)
                for ev in events:
                    received = ev.get('receivedAt')
                    if not received:
                        continue
                    try:
                        dt = datetime.fromisoformat(str(received).replace('Z', '+00:00'))
                        d_str = dt.strftime("%m-%d")
                        if d_str in date_map:
                            date_map[d_str] += 1
                    except Exception:
                        pass
                response_data["trendData"] = {"labels": list(date_map.keys()), "series": list(date_map.values()), "os_totals": {'apple': 0, 'android': 0, 'windows': 0}}
                response_data["scorecardValue"] = sum(date_map.values())
                return response_data

            if source == 'applivery_automation_outcomes':
                outcome_labels = {
                    "logged": "Logged only", "webhook_disabled": "Webhook disabled", "case_opened": "Case opened",
                    "workflow_fired": "Workflow fired", "workflow_blocked_destructive": "Blocked (destructive)",
                    "workflow_missing": "Workflow missing", "no_automation_credential": "No automation credential",
                    "workflow_unavailable": "Workflow unavailable",
                }
                agg = {}
                for ev in events:
                    outcome = ev.get('outcome') or 'logged'
                    label = outcome_labels.get(outcome) or outcome.replace('+', ' + ').replace('_', ' ').title()
                    agg[label] = agg.get(label, 0) + 1
                response_data["chartData"] = sorted([{"name": k, "value": v} for k, v in agg.items()], key=lambda x: x["value"], reverse=True)
                response_data["scorecardValue"] = len(events)
                return response_data

        # 2.65 Inbound Webhook Triggers — the generic 3rd-party channel (EDR,
        # MTD, DEX, SIEM, or anything else that can POST JSON to a URL — see
        # the "INBOUND WEBHOOK TRIGGERS" module comment above fire_trigger).
        # Deliberately its own catalog group, separate from "Applivery Events
        # (SOAR)": Applivery's native webhook is one fixed source we
        # integrate with directly, where triggers are an open-ended set of
        # whatever 3rd-party tools an admin has wired up, each with its own
        # name/purpose. triggers_summary reads the live fireCount/lastFiredAt
        # each Trigger already tracks on itself (a running counter, not a
        # capped recent-events window like Applivery's), so unlike every
        # other *_trend source here it isn't date-range limited — it's
        # always "since this trigger was created". triggers_fired_trend is
        # the one that needs a real time axis, so it scans the Audit Log
        # instead (every fire already writes a category='trigger' entry).
        if source in ('triggers_summary', 'triggers_fired_trend'):
            if source == 'triggers_summary':
                triggers = _load_triggers(slug_key)
                response_data["chartData"] = sorted(
                    [{"name": t.get('name') or 'Unnamed trigger', "value": t.get('fireCount', 0)} for t in triggers],
                    key=lambda x: x["value"], reverse=True,
                )
                response_data["scorecardValue"] = sum(t.get('fireCount', 0) for t in triggers)
                response_data["items"] = triggers
                return response_data

            if source == 'triggers_fired_trend':
                date_map = _widget_trend_date_map(dateIni, dateEnd)
                for entry in _load_audit_log(slug_key):
                    if entry.get('category') != 'trigger' or entry.get('action') not in ('trigger_fired', 'trigger_fired_no_device'):
                        continue
                    ts = entry.get('timestamp')
                    if not ts:
                        continue
                    try:
                        dt = datetime.fromisoformat(str(ts).replace('Z', '+00:00'))
                        d_str = dt.strftime("%m-%d")
                        if d_str in date_map:
                            date_map[d_str] += 1
                    except Exception:
                        pass
                response_data["trendData"] = {"labels": list(date_map.keys()), "series": list(date_map.values()), "os_totals": {'apple': 0, 'android': 0, 'windows': 0}}
                response_data["scorecardValue"] = sum(date_map.values())
                return response_data

        # 2.66 OS Update device status — fleet-wide rollup of the per-device
        # osUpdateStatus get_devices_full already attaches (see "OS UPDATE
        # INTELLIGENCE" section). Windows-only foundation phase: non-Windows
        # devices are excluded entirely rather than lumped into an "N/A"
        # bucket that would just be noise on a mixed fleet.
        if source == 'os_updates_device_status_summary':
            devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
            win_devices = [d for d in (devices_resp.get('items') or []) if d.get('platform') == 'windows' and d.get('osUpdateStatus')]
            agg = {"Up to date": 0, "Behind (confirmed)": 0, "Possibly behind (unconfirmed)": 0}
            for d in win_devices:
                status = d['osUpdateStatus']
                if status['confidence'] == 'unknown':
                    agg["Possibly behind (unconfirmed)"] += 1
                elif status['pendingCount'] > 0:
                    agg["Behind (confirmed)"] += 1
                else:
                    agg["Up to date"] += 1
            response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items() if v > 0]
            response_data["scorecardValue"] = agg["Behind (confirmed)"]
            response_data["items"] = [
                {"id": d['id'], "displayName": d.get('displayName'), **d['osUpdateStatus']} for d in win_devices
            ]
            return response_data

        # 2.67 Apple/Android vulnerability device status — fleet-wide rollup
        # of the per-device vulnStatus get_devices_full already attaches
        # (see "APPLE & ANDROID VULNERABILITY INTELLIGENCE" section).
        if source == 'vuln_device_status_summary':
            devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
            scoped_devices = [d for d in (devices_resp.get('items') or []) if d.get('platform') in ('apple', 'macos', 'android') and d.get('vulnStatus')]
            agg = {"Up to date": 0, "Behind (confirmed)": 0, "Possibly behind (unconfirmed)": 0}
            for d in scoped_devices:
                status = d['vulnStatus']
                if status['confidence'] == 'unknown':
                    agg["Possibly behind (unconfirmed)"] += 1
                elif status['pendingCount'] > 0:
                    agg["Behind (confirmed)"] += 1
                else:
                    agg["Up to date"] += 1
            response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items() if v > 0]
            response_data["scorecardValue"] = agg["Behind (confirmed)"]
            response_data["items"] = [
                {"id": d['id'], "displayName": d.get('displayName'), "platform": d.get('platform'), **d['vulnStatus']} for d in scoped_devices
            ]
            return response_data

        # 2.68 OS Lifecycle device status — fleet-wide rollup of the
        # per-device osLifecycleStatus get_devices_full already attaches
        # (see "OS LIFECYCLE" section). Covers all 4 platforms, unlike the
        # Windows-only and Apple/Android-only sources above.
        if source == 'os_lifecycle_device_status_summary':
            devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
            lc_devices = [d for d in (devices_resp.get('items') or []) if d.get('osLifecycleStatus')]
            agg = {"Supported": 0, "End of life": 0, "Unknown": 0}
            for d in lc_devices:
                status = d['osLifecycleStatus']
                if status['confidence'] == 'unknown' or status['isEol'] is None:
                    agg["Unknown"] += 1
                elif status['isEol']:
                    agg["End of life"] += 1
                else:
                    agg["Supported"] += 1
            response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items() if v > 0]
            response_data["scorecardValue"] = agg["End of life"]
            response_data["items"] = [
                {"id": d['id'], "displayName": d.get('displayName'), "platform": d.get('platform'), **d['osLifecycleStatus']} for d in lc_devices
            ]
            return response_data

        # 2.69 Vulnerability Service device status — fleet-wide rollup of the
        # per-device vulnServiceStatus get_devices_full already attaches (see
        # "VULNERABILITY SERVICE" section). Independent of, and additive to,
        # 2.67's EUVD-based vuln_device_status_summary above — this one
        # covers all 4 platforms (incl. Windows and both OS + individual
        # apps), but only for workspaces that opted into the integration.
        # Devices never checked yet (integration just enabled) are excluded
        # from the buckets entirely, same "don't lump unconfirmed into a
        # bucket" reasoning as 2.66/2.67/2.68.
        if source == 'vuln_service_device_status_summary':
            devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
            checked_devices = [d for d in (devices_resp.get('items') or []) if d.get('vulnServiceStatus') and d['vulnServiceStatus'].get('checked')]
            agg = {"Known-exploited (KEV)": 0, "Critical/high": 0, "Medium/low only": 0, "Clean": 0}
            for d in checked_devices:
                status = d['vulnServiceStatus']
                counts = status.get('counts') or {}
                if status.get('hasKev'):
                    agg["Known-exploited (KEV)"] += 1
                elif (counts.get('CRITICAL') or 0) + (counts.get('HIGH') or 0) > 0:
                    agg["Critical/high"] += 1
                elif (counts.get('MEDIUM') or 0) + (counts.get('LOW') or 0) > 0:
                    agg["Medium/low only"] += 1
                else:
                    agg["Clean"] += 1
            response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items() if v > 0]
            response_data["scorecardValue"] = agg["Known-exploited (KEV)"] + agg["Critical/high"]
            response_data["items"] = [
                {"id": d['id'], "displayName": d.get('displayName'), "platform": d.get('platform'), **d['vulnServiceStatus']} for d in checked_devices
            ]
            return response_data

        # 2.7 Workflow runs — reuses _gather_workflow_runs, the same merge of
        # in-progress/durable/history runs the Workflows view's Recent Runs
        # panel and CSV export already share, so this always agrees with what
        # an analyst sees there.
        if source in ('workflow_runs_summary', 'workflow_runs_trend'):
            runs = await _gather_workflow_runs(slug_key)

            if source == 'workflow_runs_summary':
                agg = {"Running": 0, "Waiting": 0, "Completed": 0, "Partial": 0, "Failed": 0}
                for r in runs:
                    status = r.get('status')
                    if status == 'running':
                        agg["Running"] += 1
                        continue
                    if status == 'waiting':
                        agg["Waiting"] += 1
                        continue
                    statuses = [res.get('finalStatus') for res in (r.get('results') or [])]
                    if statuses and all(s == 'success' for s in statuses):
                        agg["Completed"] += 1
                    elif any(s in ('success', 'partial') for s in statuses):
                        agg["Partial"] += 1
                    else:
                        agg["Failed"] += 1
                response_data["chartData"] = [{"name": k, "value": v} for k, v in agg.items()]
                response_data["scorecardValue"] = len(runs)
                return response_data

            if source == 'workflow_runs_trend':
                date_map = _widget_trend_date_map(dateIni, dateEnd)
                for r in runs:
                    started = r.get('startedAt')
                    if not started:
                        continue
                    try:
                        dt = datetime.fromisoformat(str(started).replace('Z', '+00:00'))
                        d_str = dt.strftime("%m-%d")
                        if d_str in date_map:
                            date_map[d_str] += 1
                    except Exception:
                        pass
                response_data["trendData"] = {"labels": list(date_map.keys()), "series": list(date_map.values()), "os_totals": {'apple': 0, 'android': 0, 'windows': 0}}
                response_data["scorecardValue"] = sum(date_map.values())
                return response_data

        # 2.8 Device risk — distribution reads the live fleet (same riskTier
        # every device already carries from _compute_device_risk); trend
        # reads back the daily 'device_risk_summary' snapshots (see
        # GET /api/analytics/device-risk-trend, which this mirrors) rather
        # than recomputing risk for the whole fleet on every widget refresh.
        if source in ('device_risk_distribution', 'device_risk_trend'):
            if source == 'device_risk_distribution':
                devices_resp = await get_devices_full(refresh=False, authorization=authorization, x_workspace_slug=x_workspace_slug)
                all_devices = devices_resp.get('items', [])
                tier_order = ['low', 'medium', 'high', 'critical']
                agg = {t: 0 for t in tier_order}
                for d in all_devices:
                    tier = d.get('riskTier', 'low')
                    if tier in agg:
                        agg[tier] += 1
                response_data["chartData"] = [{"name": t.title(), "value": agg[t]} for t in tier_order]
                response_data["scorecardValue"] = len(all_devices)
                return response_data

            if source == 'device_risk_trend':
                dates = _list_snapshot_dates(slug_key)[-30:]
                labels, series = [], []
                for date_str in dates:
                    summary = _load_snapshot(slug_key, date_str, "device_risk_summary")
                    if summary:
                        labels.append(date_str[5:] if len(date_str) > 5 else date_str)  # MM-DD, same trimmed style as other trend labels
                        series.append(summary.get('avgRiskScore', 0))
                response_data["trendData"] = {"labels": labels, "series": series, "os_totals": {'apple': 0, 'android': 0, 'windows': 0}}
                response_data["scorecardValue"] = series[-1] if series else 0
                return response_data

        # 2.9 MITRE ATT&CK coverage — how much of the technique catalog is
        # actually represented across either a Compliance Policy or a Case's
        # tags. Purely a classification rollup (see mitreTechniques on both
        # models); doesn't imply detection quality, just breadth of mapping.
        if source == 'mitre_coverage':
            policies = _load_compliance_policies(slug_key)
            cases = _load_cases(slug_key)
            covered = set()
            for p in policies:
                covered.update(p.get('mitreTechniques') or [])
            for c in cases:
                covered.update(c.get('mitreTechniques') or [])
            covered &= set(_MITRE_TECHNIQUES_BY_ID.keys())
            total = len(MITRE_TECHNIQUES)
            response_data["scorecardValue"] = len(covered)
            response_data["chartData"] = [
                {"name": "Covered", "value": len(covered)},
                {"name": "Not covered", "value": max(total - len(covered), 0)},
            ]
            return response_data

        # 2.10 Threat Intel — verdict breakdown across every IOC check ever
        # recorded on a Case (case['threatIntel'], written by both manual and
        # auto-enrichment — see _auto_enrich_case_from_text). Cached replays
        # count too, since they still represent a real check an analyst
        # relied on, not just a fresh provider call.
        if source == 'threat_intel_summary':
            cases = _load_cases(slug_key)
            agg = {"malicious": 0, "suspicious": 0, "clean": 0, "unknown": 0, "error": 0}
            total_checks = 0
            for c in cases:
                for entry in (c.get('threatIntel') or []):
                    verdict = entry.get('verdict') or 'unknown'
                    agg[verdict if verdict in agg else 'unknown'] += 1
                    total_checks += 1
            response_data["chartData"] = [{"name": k.title(), "value": v} for k, v in agg.items()]
            response_data["scorecardValue"] = total_checks
            return response_data

        # 2.11 Ticketing — how many Jira/ServiceNow tickets Cases have ever
        # linked (externalRefs), and how many of those the inbound sync loop
        # (ticket_status_sync_loop) has confirmed are resolved on the ticket
        # system's own side. A "Resolved" count near zero with a nonzero
        # total is a sign inbound sync isn't configured/enabled anywhere yet.
        if source == 'ticketing_summary':
            cases = _load_cases(slug_key)
            total_tickets = 0
            resolved = 0
            for c in cases:
                for ref in (c.get('externalRefs') or []):
                    if ref.get('type') in ('jira', 'servicenow'):
                        total_tickets += 1
                        if ref.get('remoteResolved'):
                            resolved += 1
            response_data["scorecardValue"] = total_tickets
            response_data["chartData"] = [
                {"name": "Resolved", "value": resolved},
                {"name": "Open / unknown", "value": max(total_tickets - resolved, 0)},
            ]
            return response_data

        # 3. LINE CHARTS
        if source == 'stats_devices_trend':
            # Paginated — a single limit=500 page silently truncated the trend
            # for fleets bigger than 500 devices.
            items_all = await _fetch_all_pages(client, headers, f"{org_base}/mdm/devices/", base_params=base_params)
            today = datetime.now(timezone.utc)
            date_map = {}
            # Use user-supplied range for the trend window if provided
            if dateIni and dateEnd:
                try:
                    d_start = datetime.fromisoformat(dateIni + "T00:00:00+00:00")
                    d_stop = datetime.fromisoformat(dateEnd + "T23:59:59+00:00")
                    delta_days = min((d_stop - d_start).days + 1, 60)  # cap at 60 days
                    for i in range(delta_days):
                        d = (d_start + timedelta(days=i)).strftime("%m-%d")
                        date_map[d] = {'apple': 0, 'android': 0, 'windows': 0, 'total': 0}
                except:
                    for i in range(13, -1, -1):
                        d = (today - timedelta(days=i)).strftime("%m-%d")
                        date_map[d] = {'apple': 0, 'android': 0, 'windows': 0, 'total': 0}
            else:
                for i in range(13, -1, -1):
                    d = (today - timedelta(days=i)).strftime("%m-%d")
                    date_map[d] = {'apple': 0, 'android': 0, 'windows': 0, 'total': 0}
            for dev in items_all:
                enrolled = dev.get('enrolledDate') or dev.get('createdAt')
                if not enrolled: continue
                try:
                    dt = datetime.fromisoformat(str(enrolled).replace('Z', '+00:00'))
                    d_str = dt.strftime("%m-%d")
                    if d_str in date_map:
                        plat = normalize_platform(dev.get('type') or dev.get('platform') or '')
                        date_map[d_str]['total'] += 1
                        if plat in date_map[d_str]:
                            date_map[d_str][plat] += 1
                except: pass
            response_data["trendData"] = {"labels": list(date_map.keys()), "series": [v['total'] for v in date_map.values()], "os_totals": {'apple': sum(v['apple'] for v in date_map.values()), 'android': sum(v['android'] for v in date_map.values()), 'windows': sum(v['windows'] for v in date_map.values())}}
            response_data["scorecardValue"] = sum(response_data["trendData"]["series"])
            response_data["items"] = items_all
            return response_data

        if source in ['stats_downloads_trend', 'stats_builds_trend']:
            # Use user-supplied date range if provided; fallback to last 30 days
            if dateIni and dateEnd:
                d_ini_str = dateIni + "T00:00:00.000Z"
                d_end_str = dateEnd + "T23:59:59.000Z"
            else:
                date_end = datetime.now(timezone.utc)
                date_ini = date_end - timedelta(days=30)
                d_end_str = date_end.strftime("%Y-%m-%dT%H:%M:%S.000Z")
                d_ini_str = date_ini.strftime("%Y-%m-%dT%H:%M:%S.000Z")
            stat_type_map = {'stats_downloads_trend': 'downloads-by-os-by-day', 'stats_builds_trend': 'builds-by-os-by-day'}
            stat_type = stat_type_map[source]
            url = f"{org_base}/stats/by-day?statTypes[]={stat_type}&dateIni={d_ini_str}&dateEnd={d_end_str}"
            if 'segmentId' in base_params: url += f"&segmentId={base_params['segmentId']}"
            res = await _applivery_call(client, 'GET', url, headers=headers)
            if res.status_code == 200:
                top_data = res.json().get("data", {})
                raw_data = top_data.get("data", {}).get(stat_type, {})
                labels, series = [], []
                os_totals = {'apple': 0, 'android': 0, 'windows': 0}
                if isinstance(raw_data, dict):
                    for date_val, counts in sorted(raw_data.items()):
                        label_str = str(date_val)
                        if "T" in label_str and label_str.startswith("20"): label_str = label_str.split("T")[0][-5:]
                        labels.append(label_str)
                        total = 0
                        if isinstance(counts, dict):
                            for os_name, os_val in counts.items():
                                if isinstance(os_val, (int, float)):
                                    total += os_val
                                    n = normalize_platform(os_name)
                                    if n in os_totals: os_totals[n] += os_val
                        elif isinstance(counts, (int, float)): total = counts
                        series.append(total)
                response_data["trendData"] = {"labels": labels[-14:], "series": series[-14:], "os_totals": os_totals}
                response_data["scorecardValue"] = sum(series)
            return response_data

        # 4a. OS AVAILABLE UPDATES ENGINE
        if source == 'stats_os_updates_all':
            os_filter = filter_dict.get('type', 'all')
            url = f"{org_base}/mdm/devices/available-updates?limit=500"
            if os_filter and os_filter != 'all':
                url += f"&type={os_filter}"
            res = await _applivery_call(client, 'GET', url, headers=headers)
            if res.status_code == 200:
                items = extract_items(res.json())
                agg = {}
                for item in items:
                    ver = (item.get('version') or item.get('osVersion') or
                           item.get('targetVersion') or 'Unknown')
                    os_name = str(item.get('os') or item.get('type') or '').lower()
                    count = float(item.get('deviceCount') or item.get('count') or
                                  item.get('devices') or 1)
                    if os_filter == 'all' and os_name:
                        prefix = {'apple': '🍎', 'ios': '🍎', 'android': '🤖', 'windows': '🪟'}.get(os_name, '')
                        key = f"{prefix} {ver}".strip()
                    else:
                        key = str(ver)
                    agg[key] = agg.get(key, 0) + count
                response_data["chartData"] = sorted(
                    [{"name": k, "value": int(v)} for k, v in agg.items() if v > 0],
                    key=lambda x: x["value"], reverse=True
                )
                response_data["scorecardValue"] = len(items)
                response_data["items"] = items
            return response_data

        # 4a-2. OS VERSION DISTRIBUTION ENGINE
        if source == 'stats_os_versions':
            os_filter = filter_dict.get('type', 'all')
            url = f"{org_base}/mdm/devices/os-versions"
            if os_filter and os_filter != 'all':
                url += f"?os={os_filter}"
            res = await _applivery_call(client, 'GET', url, headers=headers)
            if res.status_code == 200:
                items = extract_items(res.json())
                agg = {}
                for item in items:
                    ver = item.get("value", "Unknown")
                    os_name = str(item.get("os", "")).lower()
                    count = float(item.get("count", 1))
                    if os_filter == 'all' and os_name:
                        prefix = {'apple': '🍎', 'ios': '🍎', 'android': '🤖', 'windows': '🪟'}.get(os_name, '')
                        key = f"{prefix} {ver}".strip()
                    else:
                        key = str(ver)
                    agg[key] = agg.get(key, 0) + count
                response_data["chartData"] = sorted(
                    [{"name": k, "value": int(v)} for k, v in agg.items() if v > 0],
                    key=lambda x: x["value"], reverse=True
                )
                response_data["scorecardValue"] = sum(agg.values())
                response_data["items"] = items
            return response_data

        # 4a-3. SYNC FAILURES ENGINE
        if source == 'stats_sync_errors':
            url = f"{org_base}/mdm/devices/sync-errors?limit=500"
            res = await _applivery_call(client, 'GET', url, headers=headers)
            if res.status_code == 200:
                items = extract_items(res.json())
                agg = {}
                for item in items:
                    target_type = str(item.get("target", "Unknown")).replace("Device", "").title()
                    agg[target_type] = agg.get(target_type, 0) + 1
                response_data["chartData"] = sorted(
                    [{"name": k, "value": int(v)} for k, v in agg.items() if v > 0],
                    key=lambda x: x["value"], reverse=True
                )
                response_data["scorecardValue"] = len(items)
                response_data["items"] = items
            return response_data

# 4b. BUILDS BY OS ENGINE
        if source == 'stats_builds_os':
            # 1. Fetch apps first (FIX: Added trailing slash to /apps/)
            res_apps = await _applivery_call(client, 'GET', f"{org_base}/apps/", headers=headers, params={"limit": 200, **base_params})
            apps = extract_items(res_apps.json()) if res_apps.status_code == 200 else []
            
            agg = {'Apple': 0, 'Android': 0, 'Windows': 0}
            total_builds = 0
            all_builds = []
            
            # 2. Fetch builds for each app concurrently
            sem = asyncio.Semaphore(5)
            async def fetch_app_builds(app_id):
                async with sem:
                    url = f"{org_base}/apps/{app_id}/builds/?limit=500"
                    r = await _applivery_call(client, 'GET', url, headers=headers)
                    if r.status_code == 200:
                        return extract_items(r.json())
                    return []
            
            coros = [fetch_app_builds(a.get('id') or a.get('_id')) for a in apps if (a.get('id') or a.get('_id'))]
            if coros:
                results = await asyncio.gather(*coros)
                for build_list in results:
                    all_builds.extend(build_list)
                    for b in build_list:
                        total_builds += 1
                        os_val = normalize_platform(b.get('os') or b.get('buildPlatform') or '')
                        label = human_platform(os_val)
                        agg[label] = agg.get(label, 0) + 1
                        
            response_data["chartData"] = sorted(
                [{"name": k, "value": int(v)} for k, v in agg.items() if v > 0],
                key=lambda x: x["value"], reverse=True
            )
            response_data["scorecardValue"] = total_builds
            response_data["items"] = all_builds # Enables clicking to view individual builds!
            return response_data

        # 4c. ENTERPRISE APPS ENGINE
        if source == 'app_dist_apps':
            # FIX: Added trailing slash to /apps/
            res = await _applivery_call(client, 'GET', f"{org_base}/apps/", headers=headers,
                                   params={"limit": 200, **base_params})
            items = extract_items(res.json()) if res.status_code == 200 else []
            agg = {}
            for app in items:
                for os_key in (app.get('oss') or []):
                    label = human_platform(normalize_platform(str(os_key)))
                    agg[label] = agg.get(label, 0) + 1
            response_data["items"] = items
            response_data["scorecardValue"] = len(items)
            response_data["chartData"] = sorted(
                [{"name": k, "value": v} for k, v in agg.items() if v > 0],
                key=lambda x: x["value"], reverse=True
            )
            return response_data

        # 4d. DEVICE ENGINE 
        device_sources = ['mdm_devices', 'stats_devices_os', 'stats_devices_status', 'stats_compliance', 'stats_battery', 'stats_models']
        if source in device_sources:
            req_params = {**base_params}
            req_params_comp = {"isCompliance": "true", **base_params}
            if filter_dict.get('type') and filter_dict['type'] != 'all':
                os_map = {'apple': 'ios', 'macos': 'macos', 'android': 'android', 'windows': 'windows'}
                req_params["os"] = os_map.get(filter_dict['type'], filter_dict['type'])
                req_params_comp["os"] = req_params["os"]
            # Paginated — this feeds the Devices widgets AND the Playground
            # globe (mdm_devices), so a single limit=500 page meant fleets
            # over 500 devices silently lost devices off the globe/dashboards.
            items_all = await _fetch_all_pages(client, headers, f"{org_base}/mdm/devices/", base_params=req_params)
            items_comp = await _fetch_all_pages(client, headers, f"{org_base}/mdm/devices/", base_params=req_params_comp)
            comp_ids = set(str(i.get('id', i.get('_id', ''))) for i in items_comp)
            
            # LOAD LOCATIONS CACHE
            try:
                loc_cache = _load_locations_cache()
            except Exception:
                loc_cache = {}

            for i in items_all:
                dev_id = str(i.get('id', i.get('_id', '')))
                i['is_compliant_normalized'] = dev_id in comp_ids
                i['platform_normalized'] = normalize_platform(i.get('type') or i.get('platform') or '')
                i['state_normalized'] = str(i.get('state') or i.get('status') or 'unknown').lower()
                
                # Attach GPS cache if available!
                if dev_id in loc_cache:
                    i['locationCache'] = loc_cache[dev_id]

            if filter_dict.get('complianceStatus') in ['compliant', 'non_compliant']:
                want_comp = filter_dict['complianceStatus'] == 'compliant'
                items_all = [i for i in items_all if i['is_compliant_normalized'] == want_comp]
            if filter_dict.get('inactive24h'):
                threshold = datetime.now(timezone.utc) - timedelta(hours=24)
                items_all = [i for i in items_all if not i.get('lastSeen') or datetime.fromisoformat(i.get('lastSeen').replace('Z', '+00:00')) < threshold]
            response_data["items"] = items_all
            response_data["scorecardValue"] = len(items_all)
            agg = {}
            if source == 'stats_compliance':
                comp_count = sum(1 for i in items_all if i['is_compliant_normalized'])
                if comp_count > 0: agg["Compliant"] = comp_count
                if (len(items_all) - comp_count) > 0: agg["Not compliant"] = len(items_all) - comp_count
            elif source in ['stats_devices_os', 'mdm_devices']:
                for i in items_all:
                    label = human_platform(i['platform_normalized'])
                    agg[label] = agg.get(label, 0) + 1
            elif source == 'stats_devices_status':
                for i in items_all:
                    status = i['state_normalized'].title()
                    agg[status] = agg.get(status, 0) + 1
            elif source == 'stats_models':
                for d in items_all:
                    label = d.get("summary", {}).get("model") or "Unknown"
                    agg[label] = agg.get(label, 0) + 1
            elif source == 'stats_battery':
                agg = {"More than 70%": 0, "Between 70% and 20%": 0, "Less than 20%": 0}
                for i in items_all:
                    bat = i.get('summary', {}).get('battery')
                    if bat is not None:
                        try:
                            b_val = float(bat)
                            if b_val > 70: agg["More than 70%"] += 1
                            elif b_val >= 20: agg["Between 70% and 20%"] += 1
                            else: agg["Less than 20%"] += 1
                        except: pass
            response_data["chartData"] = sorted([{"name": k, "value": v} for k, v in agg.items() if v > 0], key=lambda x: x["value"], reverse=True)
            return response_data

        # 5. USER ENGINE
        collab_sources = ['stats_collaborators', 'mdm_collaborators', 'app_dist_collaborators', 'mdm_users', 'app_dist_store_users']
        if source in collab_sources:
            # FIX: Added trailing slashes to /employees/, /mdm/users/, and /collaborators/
            endpoint = '/employees/' if source == 'app_dist_store_users' else '/mdm/users/' if source == 'mdm_users' else '/collaborators/'
            res = await _applivery_call(client, 'GET', f"{org_base}{endpoint}", headers=headers, params={"limit": 500, **base_params})
            items = extract_items(res.json()) if res.status_code == 200 else []
            for i in items:
                i['role_normalized'] = str(i.get('role') or 'user').lower()
                i['sso_normalized'] = bool(i.get('user', {}).get('ssoUser') or i.get('ssoUser'))
            if filter_dict.get('role') and filter_dict['role'] != 'all': 
                items = [i for i in items if i['role_normalized'] == filter_dict['role'].lower()]
            if filter_dict.get('authOrigin') and filter_dict['authOrigin'] != 'all':
                f_auth = filter_dict['authOrigin'].lower()
                items = [i for i in items if (f_auth == 'sso' and i['sso_normalized']) or (f_auth == 'dashboard' and not i['sso_normalized'])]
            
            response_data["items"] = items
            response_data["scorecardValue"] = len(items)
            
            agg = {}
            for c in items:
                # Aggregate correctly by Role
                role_str = str(c.get('role') or 'User').title()
                agg[role_str] = agg.get(role_str, 0) + 1
                
            response_data["chartData"] = sorted([{"name": k, "value": v} for k, v in agg.items()], key=lambda x: x["value"], reverse=True)
            return response_data

        # Save to in-memory live cache (Tier 1) and today's snapshot (Tier 2 seed)
        _live_cache_set(slug_key, source, response_data)
        _save_snapshot(slug_key, today_str, source, response_data)
        return response_data

# ─── SNAPSHOT CAPTURE ENGINE ───

ALL_SNAPSHOT_SOURCES = [
    'mdm_devices', 'stats_devices_os', 'stats_devices_status', 'stats_compliance',
    'stats_battery', 'stats_models', 'stats_os_versions', 'stats_sync_errors',
    'stats_devices_trend', 'stats_downloads_trend', 'stats_builds_trend',
    'mdm_users', 'mdm_collaborators', 'stats_collaborators',
    'app_dist_apps', 'app_dist_store_users', 'app_dist_collaborators',
    'mdm_segments',
]

async def _fetch_live_widget_data(source: str, filter_dict: dict, base_params: dict,
                                  authorization: str, org_slug: str) -> Optional[dict]:
    """
    Direct live fetch bypassing the in-memory cache. Used by the snapshot scheduler
    so it always gets fresh data regardless of what's currently cached.
    Reuses the same logic as get_widget_data but without the cache/snapshot routing.
    """
    try:
        # Call get_widget_data with force_live=True sentinel via a special filter flag
        # Simpler: just call get_widget_data normally — the snapshot scheduler
        # passes dateIni=None/dateEnd=None so it goes straight to live fetch anyway.
        data = await get_widget_data(
            source=source,
            chart_type='list',
            filters=json.dumps(filter_dict) if filter_dict else '{}',
            dateIni=None,
            dateEnd=None,
            timeLapse=None,
            authorization=authorization,
            x_workspace_slug=org_slug,
        )
        return data
    except Exception as e:
        print(f"[LiveFetch] {source}: {e}")
        return None

async def _capture_daily_snapshot(authorization: str, org_slug: str, date_str: str) -> int:
    """
    Fetches live data for all snapshot sources sequentially with a delay between each.
    Sequential (not concurrent) to avoid API rate-limit blocks.
    Delay of 3s between sources = ~54s total for 18 sources — safe for any API.
    Returns number of sources successfully captured.
    """
    captured = 0
    for i, src in enumerate(ALL_SNAPSHOT_SOURCES):
        # Polite delay between API calls — no hammering
        if i > 0:
            await asyncio.sleep(3)
        try:
            # Bypass live cache for snapshot capture — always fetch fresh from API
            data = await _fetch_live_widget_data(
                source=src,
                filter_dict={},
                base_params={},
                authorization=authorization,
                org_slug=org_slug,
            )
            if data:
                _save_snapshot(org_slug, date_str, src, data)
                captured += 1
                print(f"[Snapshot] ✓ {src} ({i+1}/{len(ALL_SNAPSHOT_SOURCES)})")
        except Exception as e:
            print(f"[Snapshot] ✗ {src}: {e}")

    # Device risk trend — not an Applivery widget source like the ones above
    # (it's computed locally by _compute_device_risk), so it bypasses
    # ALL_SNAPSHOT_SOURCES/get_widget_data entirely and is saved directly
    # under its own source key. Answers "is the fleet's risk drifting up or
    # down over time", which the point-in-time Devices view alone can't show.
    try:
        devices_res = await get_devices_full(refresh=True, authorization=authorization, x_workspace_slug=org_slug)
        items = devices_res.get('items') or []
        if items:
            scores = [d.get('riskScore', 0) for d in items]
            tier_counts = {"low": 0, "medium": 0, "high": 0, "critical": 0}
            for d in items:
                tier_counts[d.get('riskTier', 'low')] = tier_counts.get(d.get('riskTier', 'low'), 0) + 1
            summary = {
                "deviceCount": len(items),
                "avgRiskScore": round(sum(scores) / len(scores), 1),
                "maxRiskScore": max(scores),
                "tierCounts": tier_counts,
            }
            _save_snapshot(org_slug, date_str, "device_risk_summary", summary)
            captured += 1
            print(f"[Snapshot] ✓ device_risk_summary ({len(items)} devices, avg {summary['avgRiskScore']})")
    except Exception as e:
        print(f"[Snapshot] ✗ device_risk_summary: {e}")

    print(f"[Snapshot] Done: {captured}/{len(ALL_SNAPSHOT_SOURCES)} sources captured for {org_slug} on {date_str}")
    _live_cache_invalidate(org_slug)   # Fresh snapshots → invalidate stale cache
    return captured

# ─── REPORT GENERATION ───

@app.post("/api/reports/generate", dependencies=[Depends(verify_dashboard_token)])
async def generate_report(
    payload: ReportPayload,
    background_tasks: BackgroundTasks,
    authorization: Optional[str] = Header(None), 
    x_workspace_slug: Optional[str] = Header(None)
):
    if not authorization or not x_workspace_slug:
        raise HTTPException(status_code=401, detail="Missing Credentials")

    if payload.webhookUrl:
        background_tasks.add_task(send_google_chat_webhook, webhook_url=payload.webhookUrl, workspace=payload.workspace, time_lapse=payload.timeLapse, sources_count=len(payload.sources))

    org_name = payload.workspace
    try:
        org_data = await get_widget_data('org_profile', 'list', "{}", authorization, x_workspace_slug)
        org_name = org_data.get("orgProfile", {}).get("name", payload.workspace)
    except: pass

    # 1. Fetch Dynamic Report Data
    report_data = {}
    for source in payload.sources:
        try:
            data = await get_widget_data(source=source, chart_type='list', filters=json.dumps(payload.filters), authorization=authorization, x_workspace_slug=x_workspace_slug)
            report_data[source] = data
        except Exception as e:
            report_data[source] = {"error": str(e)}

    # 2. Template PDF Generation
    import base64
    from jinja2 import Template
    import weasyprint
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt

    report_sections = []
    for source_name, data in report_data.items():
        clean_title = str(source_name).replace('_', ' ').title()
        chart_data = data.get("chartData", [])
        trend_data = data.get("trendData", {})
        image_source, html_table, is_full_width = None, None, False

        # --- 1. Generate Trend Chart (Base64) ---
        if payload.display.get("trend", True) and trend_data and trend_data.get("series"):
            is_full_width = True
            plt.figure(figsize=(9, 3.0))
            
            trend_type = payload.display.get("trend_type", "line")
            if trend_type == "bar":
                plt.bar(trend_data["labels"], trend_data["series"], color='#0E4FF5', alpha=0.85)
                plt.grid(True, axis='y', linestyle='--', alpha=0.3)
            else:
                plt.plot(trend_data["labels"], trend_data["series"], marker='o', color='#0E4FF5', linewidth=2)
                plt.grid(True, linestyle='--', alpha=0.3)
                
            plt.xticks(rotation=45, ha='right', fontsize=8)
            plt.tight_layout()
            buf = io.BytesIO()
            plt.savefig(buf, format='png', bbox_inches='tight', pad_inches=0.3, transparent=True, dpi=150)
            plt.close()
            image_source = f"data:image/png;base64,{base64.b64encode(buf.getvalue()).decode('utf-8')}"

        # Distribution Chart
        elif payload.display.get("donut", True) and chart_data:
            filtered = [d for d in chart_data[:8] if float(d.get("value", 0)) > 0]
            if filtered and len(filtered) > 1:
                labels, values = [str(d.get("name", "Unknown"))[:20] for d in filtered], [d.get("value", 0) for d in filtered]
                
                def get_color(name, idx):
                    n = name.upper()
                    if 'LESS THAN 20' in n or 'NON' in n or 'NOT' in n: return '#EF4444'
                    if 'MORE THAN 70' in n or 'ACTIVE' in n or 'COMPLIAN' in n: return '#3DDC84'
                    if 'BETWEEN' in n or 'PENDING' in n or 'MEDIUM' in n: return '#F59E0B'
                    if 'APPLE' in n or 'IOS' in n or 'MAC' in n: return '#007AFF'
                    if 'ANDROID' in n: return '#3DDC84'
                    if 'WINDOWS' in n or 'WIN' in n: return '#0078D4'
                    palette = ['#0E4FF5', '#A855F7', '#0078D4', '#EC4899', '#14B8A6', '#F59E0B', '#EF4444', '#3DDC84']
                    return palette[idx % len(palette)]
                    
                colors_list = [get_color(labels[i], i) for i in range(len(labels))]
                dist_type = payload.display.get("donut_type", "donut")
                
                if dist_type == "radar":
                    import math
                    plt.figure(figsize=(7, 4.5))
                    ax = plt.subplot(111, polar=True)
                    angles = [n / float(len(labels)) * 2 * math.pi for n in range(len(labels))]
                    values_closed = values + [values[0]]
                    angles_closed = angles + [angles[0]]
                    
                    ax.plot(angles_closed, values_closed, color='#0E4FF5', linewidth=2, linestyle='solid')
                    ax.fill(angles_closed, values_closed, color='#0E4FF5', alpha=0.25)
                    ax.set_xticks(angles)
                    ax.set_xticklabels(labels, fontsize=9, fontweight='bold', color='#263238')
                    ax.set_yticks([])
                elif dist_type == "bar":
                    plt.figure(figsize=(7, 4))
                    bars = plt.bar(labels, values, color=colors_list)
                    plt.xticks(rotation=45, ha='right', fontsize=8)
                    plt.grid(True, axis='y', linestyle='--', alpha=0.3)
                    for bar in bars:
                        yval = bar.get_height()
                        plt.text(bar.get_x() + bar.get_width()/2.0, yval + (yval * 0.02), int(yval), va='bottom', ha='center', fontsize=9, fontweight='bold', color='#263238')
                elif dist_type == "pie":
                    plt.figure(figsize=(7, 4))
                    plt.pie(values, labels=labels, autopct='%1.1f%%', pctdistance=0.6, startangle=140, colors=colors_list, textprops={'fontsize': 10, 'fontweight': 'bold'})
                    plt.axis('equal')
                else:
                    plt.figure(figsize=(7, 4))
                    plt.pie(values, labels=labels, autopct='%1.1f%%', pctdistance=0.75, startangle=140, colors=colors_list, radius=0.75, wedgeprops=dict(width=0.35, edgecolor='w', linewidth=1.5), textprops={'fontsize': 10, 'fontweight': 'bold'})
                    plt.axis('equal')

                buf = io.BytesIO()
                plt.savefig(buf, format='png', bbox_inches='tight', pad_inches=0.3, transparent=True, dpi=150)
                plt.close()
                image_source = f"data:image/png;base64,{base64.b64encode(buf.getvalue()).decode('utf-8')}"

        # Table / Progress Bars
        if payload.display.get("table", True) and chart_data:
            table_type = payload.display.get("table_type", "standard")
            if table_type == "progress":
                max_val = max([float(d.get("value", 0)) for d in chart_data]) or 1
                rows = ""
                for row in chart_data[:15]:
                    name_str = str(row.get("name", "Unknown")).title()[:60]
                    val = float(row.get("value", 0))
                    pct = (val / max_val) * 100
                    rows += f"""
                    <div style="margin-bottom: 12px; page-break-inside: avoid; break-inside: avoid;">
                        <div style="display: flex; justify-content: space-between; font-size: 12px; margin-bottom: 6px; font-weight: 600; color: #334155;">
                            <span>{name_str}</span><span>{int(val)}</span>
                        </div>
                        <div style="width: 100%; background: #E2E8F0; border-radius: 6px; height: 10px;">
                            <div style="width: {pct}%; background: #0E4FF5; height: 100%; border-radius: 6px;"></div>
                        </div>
                    </div>
                    """
                html_table = f"<div style='margin-top: 10px;'>{rows}</div>"
            else:
                rows = "".join([f"<tr><td>{str(row.get('name', 'Unknown')).title()[:60]}</td><td style='text-align:right;'>{row.get('value', 0)}</td></tr>" for row in chart_data[:20]])
                html_table = f"<table><thead><tr><th>Metric</th><th style='text-align:right;'>Value</th></tr></thead><tbody>{rows}</tbody></table>"

        if image_source or html_table:
            report_sections.append({"section_title": clean_title, "image_source": image_source, "html_table": html_table, "is_full_width": is_full_width})

    # Render Template
    custom_template = None
    try:
        custom_template = _load_state(x_workspace_slug).get("customReportTemplate")
    except Exception:
        pass

    if custom_template and custom_template.strip():
        template_str = custom_template
    else:
        with open("template.html", "r") as f: 
            template_str = f.read()
            
    active_filters = ", ".join([f"{k}: {v}" for k, v in payload.filters.items() if v != 'all' and v is not False]) or "None"
    html_out = Template(template_str).render(Workspace_Name=org_name, Report_Title="Analytics Report", Generated_Date=datetime.now().strftime('%Y-%m-%d %H:%M'), Time_Lapse=payload.timeLapse, metadata=[{"label": "Workspace Slug", "value": payload.workspace}, {"label": "Sources Analyzed", "value": str(len(payload.sources))}, {"label": "Applied Filters", "value": active_filters}], report_sections=report_sections)
    
    pdf_buffer = io.BytesIO()
    weasyprint.HTML(string=html_out).write_pdf(pdf_buffer)
    pdf_bytes = pdf_buffer.getvalue()
    pdf_buffer.seek(0)
    
    # Fire off the email in the background if configured
    if payload.emailRecipients and payload.smtp:
        background_tasks.add_task(send_email_report, smtp_config=payload.smtp, recipients=payload.emailRecipients, pdf_bytes=pdf_bytes, org_name=org_name, time_lapse=payload.timeLapse)
    
    return StreamingResponse(pdf_buffer, media_type="application/pdf", headers={"Content-Disposition": f"attachment; filename=Applivery_Report_{payload.workspace}.pdf"})
