TICKET_SYNC_TICK_SECONDS = 900  # 15 minutes — see module comment above _sync_case_ticket_refs for why this polls instead of using a webhook receiver

def _workspaces_with_integrations() -> List[str]:
    """Every workspace slug that has at least one integration configured —
    ticket status sync only needs a workspace's own stored Jira/ServiceNow
    credentials (IntegrationPayload.config), not an Applivery automation
    credential. Filters the SQLite-wide workspace index down to ones that
    actually have an `integrations` row (was an os.listdir() of the now-
    legacy INTEGRATIONS_DIR, same pattern as _list_audit_workspaces)."""
    return [slug for slug in _known_workspace_slugs() if _store_keys(slug, 'integrations')]

async def ticket_status_sync_loop():
    """Inbound half of ticket sync (see the module comment above the
    TICKETING / CHAT INTEGRATIONS section). Ticks every
    TICKET_SYNC_TICK_SECONDS and, for every workspace with a Jira/ServiceNow
    integration configured, pulls live status for every OPEN case's linked
    ticket(s) from that same integration, auto-resolving the case when the
    integration opts into it (autoCloseCaseOnRemoteResolve). Manual,
    on-demand equivalent: POST /api/cases/{case_id}/sync-ticket-status."""
    await asyncio.sleep(30)  # let the server finish initializing first
    while True:
        try:
            for slug_key in _workspaces_with_integrations():
                integrations = _load_integrations(slug_key)
                integrations_by_type = {
                    i['type']: i for i in integrations
                    if i.get('type') in ('jira', 'servicenow') and i.get('enabled', True)
                }
                if not integrations_by_type:
                    continue
                cases = _load_cases(slug_key)
                open_cases_with_tickets = [
                    c for c in cases
                    if c.get('status') in CASE_OPEN_STATUSES
                    and any(r.get('type') in integrations_by_type for r in (c.get('externalRefs') or []))
                ]
                if not open_cases_with_tickets:
                    continue
                changed = False
                async with httpx.AsyncClient() as client:
                    for case in open_cases_with_tickets:
                        try:
                            newly_resolved = await _sync_case_ticket_refs(client, integrations_by_type, case)
                        except Exception as e:
                            print(f"[Ticket Sync] {slug_key} case {case.get('id')}: {e}")
                            continue
                        changed = True  # remoteStatus/remoteStatusCheckedAt were updated on the refs regardless of resolution
                        if newly_resolved:
                            ref = newly_resolved[0]
                            integ = integrations_by_type.get(ref.get('type'))
                            if integ and integ.get('autoCloseCaseOnRemoteResolve'):
                                _close_case_from_remote_resolve(case, ref)
                                _record_audit_event(slug_key, category="case", action="case_auto_resolved", actor="system",
                                                     target_type="case", target_id=case.get('id'), target_name=case.get('title'),
                                                     message=f'Case "{case.get("title")}" auto-resolved — linked {ref.get("type", "").title()} ticket {ref.get("id")} was marked done externally')
                            else:
                                case.setdefault('timeline', []).append(_case_timeline_entry(
                                    'note_added', f'Linked {ref.get("type", "").title()} ticket {ref.get("id")} is now marked done externally',
                                ))
                if changed:
                    _save_cases(slug_key, cases)
            _record_job_heartbeat('ticket_status_sync', 'ok')
        except Exception as e:
            print(f"[Ticket Sync] Error: {e}")
            _record_job_heartbeat('ticket_status_sync', 'error', str(e))
        await asyncio.sleep(TICKET_SYNC_TICK_SECONDS)

CASE_SLA_MONITOR_TICK_SECONDS = 300  # 5 minutes — SLA windows here run minutes-to-hours, so this granularity is precise enough without adding meaningful staleness to breach detection

def _case_sla_workspaces() -> List[str]:
    """Every workspace that has ever had a case — unlike most loops in this
    file, this doesn't gate on _automation_workspaces() (an Applivery
    credential): notifying chat/webhook integrations and writing the Audit
    Log need neither, so a workspace using Cases without ever configuring
    automation still gets SLA breach detection. Filters the SQLite-wide
    workspace index to ones with a `cases` row (was an os.listdir() of the
    now-legacy CASES_DIR)."""
    return [slug for slug in _known_workspace_slugs() if _store_keys(slug, 'cases')]

async def case_sla_monitor_loop():
    """Scans every workspace's OPEN cases each tick and, the moment a case's
    acknowledge or resolve clock first crosses its configured threshold
    (see _case_sla_status), writes a critical Audit Log entry and — if
    notifyOnBreach is on — fires a one-time chat notification
    (_dispatch_case_sla_breach). 'First' is tracked via
    slaAckBreachNotifiedAt/slaResolveBreachNotifiedAt stamped directly onto
    the case, so a case that's been breached for days doesn't renotify every
    tick — same one-shot-marker pattern _run_compliance_evaluation's `state`
    dict uses for violations, just persisted on the case itself instead of a
    separate store since there's only ever one active breach-notice per
    clock per case."""
    await asyncio.sleep(35)  # let the server finish initializing first
    while True:
        try:
            for slug_key in _case_sla_workspaces():
                settings = _load_case_sla_settings(slug_key)
                if not settings.get('enabled', True):
                    continue
                cases = _load_cases(slug_key)
                open_cases = [c for c in cases if c.get('status') in CASE_OPEN_STATUSES]
                if not open_cases:
                    continue
                thresholds = settings.get('thresholds', {})
                changed = False
                for case in open_cases:
                    status = _case_sla_status(case, thresholds)
                    if status['ackBreached'] and not case.get('slaAckBreachNotifiedAt'):
                        case['slaAckBreachNotifiedAt'] = datetime.now(timezone.utc).isoformat()
                        case.setdefault('timeline', []).append(_case_timeline_entry('sla_breached', 'Acknowledge SLA breached — no assignee or investigation started in time'))
                        changed = True
                        _record_audit_event(slug_key, category="case", action="case_sla_ack_breached", actor="system", severity="critical",
                                             target_type="case", target_id=case.get('id'), target_name=case.get('title'),
                                             message=f'Case "{case.get("title")}" ({case.get("severity")}) breached its acknowledge SLA')
                        if settings.get('notifyOnBreach', True):
                            await _dispatch_case_sla_breach(slug_key, case, 'acknowledge')
                    if status['resolveBreached'] and not case.get('slaResolveBreachNotifiedAt'):
                        case['slaResolveBreachNotifiedAt'] = datetime.now(timezone.utc).isoformat()
                        case.setdefault('timeline', []).append(_case_timeline_entry('sla_breached', 'Resolve SLA breached — case still open past its due time'))
                        changed = True
                        _record_audit_event(slug_key, category="case", action="case_sla_resolve_breached", actor="system", severity="critical",
                                             target_type="case", target_id=case.get('id'), target_name=case.get('title'),
                                             message=f'Case "{case.get("title")}" ({case.get("severity")}) breached its resolve SLA')
                        if settings.get('notifyOnBreach', True):
                            await _dispatch_case_sla_breach(slug_key, case, 'resolve')
                if changed:
                    _save_cases(slug_key, cases)
            _record_job_heartbeat('case_sla_monitor', 'ok')
        except Exception as e:
            print(f"[Case SLA Monitor] Error: {e}")
            _record_job_heartbeat('case_sla_monitor', 'error', str(e))
        await asyncio.sleep(CASE_SLA_MONITOR_TICK_SECONDS)

async def audit_log_rotation_loop():
    """Runs once per day and prunes every workspace's audit log down to its
    own configured retention (see _rotate_audit_log / auditLogRetentionDays
    in Platform Settings). A no-op per workspace when retention is 0 (keep
    forever) — AUDIT_LOG_HARD_CAP is the only ceiling in that case."""
    await asyncio.sleep(30)  # let the server finish initializing first
    while True:
        try:
            for slug in _list_audit_workspaces():
                _rotate_audit_log(slug)
            _record_job_heartbeat('audit_log_rotation', 'ok')
        except Exception as e:
            print(f"[Audit Log Rotation] Error: {e}")
            _record_job_heartbeat('audit_log_rotation', 'error', str(e))
        await asyncio.sleep(86400)  # once a day

@app.post("/api/workflows/resume-due", dependencies=[Depends(verify_trigger_secret)])
async def trigger_resume_due_workflows():
    """External-trigger equivalent of workflow_wait_resumer_loop's tick —
    idempotent and safe to call concurrently with the internal loop or from
    multiple external callers (FOR UPDATE SKIP LOCKED prevents any device
    being resumed twice). Meant for a Cloudflare Worker Cron Trigger to call
    over HTTP; requires the X-Trigger-Secret header."""
    resumed = await _resume_due_workflow_steps()
    return {"resumed": resumed}

@app.post("/api/compliance/evaluate-due", dependencies=[Depends(verify_trigger_secret)])
async def trigger_evaluate_due_compliance():
    """External-trigger equivalent of compliance_scheduler_loop's tick.
    Requires the X-Trigger-Secret header. Runs against every workspace that
    has an automation credential configured (stored, or the legacy env-var
    pair), not just one."""
    workspaces = _automation_workspaces()
    if not workspaces:
        raise HTTPException(status_code=503, detail="No workspace has an automation credential configured. Configure one from Settings, or set AUTOMATION_ORG_SLUG/AUTOMATION_API_TOKEN.")
    total_evaluated = 0
    combined = {"violationsFound": 0}
    for org_slug in workspaces:
        bearer = await _get_automation_bearer(org_slug)
        if not bearer:
            continue
        due_ids = _due_compliance_policy_ids(org_slug)
        if not due_ids:
            continue
        summary = await _run_compliance_evaluation(bearer, org_slug, policy_ids=due_ids)
        total_evaluated += len(due_ids)
        combined["violationsFound"] += summary.get("violationsFound", 0)
    return {"evaluated": total_evaluated, **combined}

async def compliance_scheduler_loop():
    """Automatic side of the Compliance Policy engine. Ticks every
    COMPLIANCE_SCHEDULER_TICK_SECONDS (60s) but only actually evaluates a
    policy once its own configured interval has elapsed — see
    _due_compliance_policy_ids. Ticking this often is cheap: the underlying
    device-list fetch stays served from its own longer cache
    (DEVICES_CACHE_TTL_SECONDS, 15 min) regardless of how often we check for
    due policies, so tightening the tick doesn't multiply real Applivery
    traffic. Iterates every workspace with an automation credential
    configured (see _automation_workspaces/_get_automation_bearer) — never a
    logged-in user's personal session token."""
    await asyncio.sleep(20)  # let the server finish initializing first
    while True:
        workspaces = _automation_workspaces()
        try:
            if workspaces:
                for org_slug in workspaces:
                    bearer = await _get_automation_bearer(org_slug)
                    if not bearer:
                        continue
                    due_ids = _due_compliance_policy_ids(org_slug)
                    if due_ids:
                        summary = await _run_compliance_evaluation(bearer, org_slug, policy_ids=due_ids)
                        if summary.get('violationsFound'):
                            print(f"[Compliance Scheduler] {org_slug}: {summary}")
            else:
                print("[Compliance Scheduler] Skipped — no workspace has an automation credential configured.")
            _record_job_heartbeat('compliance_scheduler', 'ok')
        except Exception as e:
            print(f"[Compliance Scheduler] Error: {e}")
            _record_job_heartbeat('compliance_scheduler', 'error', str(e))
        await asyncio.sleep(COMPLIANCE_SCHEDULER_TICK_SECONDS)

async def snapshot_scheduler_loop():
    """Runs once per day at 00:05 UTC to capture a full snapshot of all
    widget data, for every workspace with an automation credential
    configured."""
    await asyncio.sleep(15)  # Let server fully initialize first
    while True:
        now = datetime.now(timezone.utc)
        # Schedule next run at 00:05 UTC
        next_run = now.replace(hour=0, minute=5, second=0, microsecond=0)
        if now >= next_run:
            next_run += timedelta(days=1)
        sleep_secs = (next_run - now).total_seconds()
        print(f"[Snapshot Scheduler] Next snapshot capture in {int(sleep_secs/3600)}h {int((sleep_secs%3600)/60)}m")
        await asyncio.sleep(sleep_secs)

        workspaces = _automation_workspaces()
        try:
            if workspaces:
                date_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
                for org_slug in workspaces:
                    bearer = await _get_automation_bearer(org_slug)
                    if not bearer:
                        continue
                    await _capture_daily_snapshot(bearer, org_slug, date_str)
                _purge_old_snapshots()
            else:
                print("[Snapshot Scheduler] Skipped — no workspace has an automation credential configured.")
            _record_job_heartbeat('snapshot_scheduler', 'ok')
        except Exception as e:
            print(f"[Snapshot Scheduler] Error: {e}")
            _record_job_heartbeat('snapshot_scheduler', 'error', str(e))

async def report_scheduler_loop():
    # Wait 10 seconds for the server to fully initialize
    await asyncio.sleep(10)

    while True:
        state_path = os.path.join(DATA_DIR, "state_global.json")
        state = {}
        if os.path.exists(state_path):
            try:
                with open(state_path, "r") as f:
                    state = json.load(f)
            except Exception:
                pass

        # 1. Get absolute universal time first
        now_utc = datetime.now(timezone.utc)

        reports = state.get("scheduledReports", [])

        if reports:
            print(f"⏱️ [Scheduler Heartbeat] UTC Time: {now_utc.strftime('%Y-%m-%d %H:%M')} | Active Schedules: {len(reports)}")

            # Generate an internal token to safely bypass FastAPI authentication
            internal_token = jwt.encode({"sub": "scheduler", "exp": now_utc + timedelta(minutes=10)}, DASHBOARD_SECRET, algorithm="HS256")

            for rep in reports:
                sched = rep.get("schedule", {})
                if not sched.get("enabled"): continue

                # Each report remembers which workspace it was built in
                # (workspaceSlug, set when the schedule is saved). Older
                # schedules created before that field existed fall back to
                # the legacy single-org AUTOMATION_ORG_SLUG, if configured.
                org_slug = rep.get("workspaceSlug") or AUTOMATION_ORG_SLUG
                if not org_slug:
                    print(f"  ↳ ⏭️ Skipped '{rep.get('name')}': No workspace is associated with this schedule and no legacy AUTOMATION_ORG_SLUG is set.")
                    continue
                bearer = await _get_automation_bearer(org_slug)
                if not bearer:
                    print(f"  ↳ ⏭️ Skipped '{rep.get('name')}': No automation credential configured for workspace '{org_slug}'. Configure one from Settings.")
                    continue

                # --- 2. PER-REPORT TIMEZONE CALCULATION ---
                tz_str = sched.get("timezone") or state.get("timezone") or "UTC"
                try:
                    from zoneinfo import ZoneInfo
                    tz = ZoneInfo(tz_str)
                except Exception:
                    tz = timezone.utc

                now_local = datetime.now(tz)
                current_time_str = now_local.strftime("%H:%M")
                current_day_of_week = now_local.weekday()  # 0 = Monday
                current_day_of_month = now_local.day
                today_str = now_local.strftime("%Y-%m-%d")

                # 3. Check rules against the LOCAL time of the report creator
                start_date = sched.get("startDate", "2000-01-01")
                if today_str < start_date:
                    print(f"  ↳ ⏭️ Skipped '{rep.get('name')}': Starts in future ({start_date} {tz_str})")
                    continue

                if sched.get("time") != current_time_str:
                    continue

                freq = sched.get("frequency", "weekly")
                if freq == "weekly" and current_day_of_week != 0:
                    print(f"  ↳ ⏭️ Skipped '{rep.get('name')}': Weekly reports only run on Mondays ({tz_str}).")
                    continue
                if freq == "monthly" and current_day_of_month != 1:
                    print(f"  ↳ ⏭️ Skipped '{rep.get('name')}': Monthly reports only run on the 1st ({tz_str}).")
                    continue

                print(f"⏰ Scheduler triggered automated report: {rep.get('name')} (Workspace: {org_slug}, Timezone: {tz_str})")

                try:
                    async with httpx.AsyncClient(timeout=120.0) as client:
                        payload = {
                            "workspace": org_slug,
                            "sources": rep.get("sources", []),
                            "timeLapse": rep.get("timeLapse", "Last 30 Days"),
                            "filters": rep.get("filters", {}),
                            "display": rep.get("display", {}),
                            "webhookUrl": state.get("webhookUrl") if rep.get("delivery", {}).get("chat") else None,
                            "emailRecipients": rep.get("emailRecipients") if rep.get("delivery", {}).get("email") else None,
                            "smtp": state.get("smtpConfig") if rep.get("delivery", {}).get("email") else None
                        }
                        headers = {
                            "Authorization": bearer,
                            "X-Workspace-Slug": org_slug,
                            "X-Dashboard-Token": f"Bearer {internal_token}",
                            "Content-Type": "application/json"
                        }
                        # Call the generation endpoint internally to construct and dispatch the file!
                        await client.post("http://127.0.0.1:8000/api/reports/generate", json=payload, headers=headers)
                except Exception as e:
                    print(f"Failed to execute scheduled report '{rep.get('name')}': {e}")

        # Heartbeat at the end of every tick, unconditionally — this loop
        # has no outer try/except (each report's own generation call is
        # already individually guarded above, and re-indenting this entire
        # ~90-line body just to add one wasn't worth the risk), so 'ok' here
        # simply means the tick reached its end; a genuinely unhandled
        # exception earlier in the tick still kills the loop exactly as it
        # would have before, and Settings > System Health flags that as
        # 'overdue' once heartbeats stop arriving, which is the signal that
        # actually matters.
        _record_job_heartbeat('report_scheduler', 'ok')

        # Sleep until the exact start of the next minute to prevent double-firing
        # (Seconds are universal, so we can just check UTC)
        await asyncio.sleep(60 - datetime.now(timezone.utc).second)

# ─── OS UPDATE INTELLIGENCE (WINDOWS) ───
# Foundation for OS update visibility, phase 1 of a two-phase roadmap: a
# rolling catalog of Microsoft's monthly Windows security updates (sourced
# from MSRC's public CVRF API — free, no key) matched against each device's
# reported osVersion to surface "how far behind is this device," without yet
# touching vulnerability scoring or Compliance Policies. Cross-referencing
# pending updates against CVE data for scoring/compliance is a deliberately
# separate, later phase — the CVE/severity fields captured here are stored
# now (since the catalog fetch surfaces them for free) but not surfaced or
# acted on anywhere yet.
#
# Scope, explicitly: Windows only for now. macOS/Android/iOS don't have an
# equivalent free, structured "latest build per device family" feed the way
# MSRC gives Windows — that's a separate integration to design later. 3rd
# party app updates are out of scope for this pass too (see
# stats_os_updates_all below for Applivery's own generic, all-platform
# "available update" signal, which this is additive to, not a replacement
# for — that endpoint doesn't expose Windows' Security/System/Driver/Feature
# update-type distinction, which is exactly the gap this section fills).
#
# Data-quality note: MSRC's CVRF feed is authoritative for "which KB/CVEs
# shipped this month for which Windows product line," but it does not
# expose a single clean structured field for "the exact OS Build this
# update produces." That number is opportunistically extracted via regex
# from the update's title/notes/remediation text (Microsoft's own KB
# articles are fairly consistent about stating it, e.g. "OS Builds
# 22621.3958 and 22631.3958"). When extraction succeeds, a device gets a
# real "N patch levels behind" comparison (confidence: 'build'); when it
# doesn't, the KB still appears in the catalog for visibility but is never
# counted toward a device's pending total, since a guess there would be
# worse than an honest gap (confidence: 'unknown'). This parsing hasn't
# been verified yet against a live MSRC response — this sandbox's outbound
# network couldn't reach api.msrc.microsoft.com to test against — so treat
# the first real fetch (Settings > OS Updates > Refresh now) as the point
# to sanity-check it, same spirit as the Android nativeSecurity fields
# elsewhere in this file (defensive .get() access throughout, below).

OS_UPDATE_DIR = os.path.join(DATA_DIR, "os_updates")
OS_UPDATE_CATALOG_FILE = os.path.join(OS_UPDATE_DIR, "windows_catalog.json")

# Windows "major build number" (3rd dotted segment of osVersion, e.g. the
# 22631 in 10.0.22631.3958) → human feature-version label. Stable, publicly
# documented Microsoft data — extend as new feature versions ship.
WINDOWS_BUILD_TO_FEATURE = {
    26100: "Windows 11, version 24H2",
    22631: "Windows 11, version 23H2",
    22621: "Windows 11, version 22H2",
    22000: "Windows 11, version 21H2",
    19045: "Windows 10, version 22H2",
    19044: "Windows 10, version 21H2",
    19043: "Windows 10, version 21H1",
    19042: "Windows 10, version 20H2",
    20348: "Windows Server 2022",
    17763: "Windows Server 2019 / version 1809",
}
# Keyword matcher for MSRC's free-text product names (e.g. "Windows 11
# Version 23H2 for x64-based Systems") → the same build-major keys above, so
# a catalog entry and a device can be matched by feature version without
# needing MSRC to expose a raw build number for the product itself.
WINDOWS_PRODUCT_KEYWORDS = {
    26100: ("windows 11", "24h2"),
    22631: ("windows 11", "23h2"),
    22621: ("windows 11", "22h2"),
    22000: ("windows 11", "21h2"),
    19045: ("windows 10", "22h2"),
    19044: ("windows 10", "21h2"),
    19043: ("windows 10", "21h1"),
    19042: ("windows 10", "20h2"),
    20348: ("windows server 2022",),
    17763: ("windows server 2019",),
}
_SEVERITY_RANK = {"low": 0, "moderate": 1, "important": 2, "critical": 3}
_BUILD_REVISION_RE = re.compile(r'\b(' + '|'.join(str(k) for k in WINDOWS_BUILD_TO_FEATURE) + r')\.(\d{1,6})\b')

def _match_windows_build_major(product_name: str) -> Optional[int]:
    name = (product_name or '').lower()
    for build_major, keywords in WINDOWS_PRODUCT_KEYWORDS.items():
        if all(kw in name for kw in keywords):
            return build_major
    return None

def _extract_build_revision(*texts) -> Optional[dict]:
    """Best-effort scan of MSRC free-text fields for an explicit OS Build
    mention (e.g. '22631.3958'). Returns {'buildMajor','ubr'} on the first
    match, else None — see the section docstring's data-quality note."""
    for text in texts:
        if not text:
            continue
        m = _BUILD_REVISION_RE.search(str(text))
        if m:
            return {"buildMajor": int(m.group(1)), "ubr": int(m.group(2))}
    return None

def _windows_device_build(os_version: str) -> Optional[dict]:
    """Parse a device's raw osVersion (e.g. '10.0.22631.3958') into
    {'buildMajor','ubr','featureLabel'}. None for non-Windows-looking
    strings, including the empty osVersion Applivery reports before a
    device's first real check-in."""
    t = _version_tuple(os_version)
    if len(t) < 3 or t[0] != 10 or t[1] != 0:
        return None
    build_major = t[2]
    if build_major < 10000:
        return None
    ubr = t[3] if len(t) > 3 else 0
    return {
        "buildMajor": build_major, "ubr": ubr,
        "featureLabel": WINDOWS_BUILD_TO_FEATURE.get(build_major, f"Windows (build {build_major})"),
    }

_register_legacy_json('os_update_catalog', lambda slug, key: OS_UPDATE_CATALOG_FILE)

def _load_os_update_catalog() -> dict:
    return _store_load(_GLOBAL_STORE_SLUG, 'os_update_catalog', lambda: {"kbEntries": [], "monthsFetched": [], "lastFetchedAt": None, "lastError": None})

def _save_os_update_catalog(catalog: dict):
    _store_save(_GLOBAL_STORE_SLUG, 'os_update_catalog', catalog)

async def _fetch_msrc_month(client: httpx.AsyncClient, year: int, month: int) -> Optional[List[dict]]:
    """Fetch + parse one month's MSRC CVRF security-update bulletin (JSON via
    Accept header content negotiation). Returns a flat list of per-CVE,
    per-affected-Windows-product rows, or None if the month has no bulletin
    yet / the request failed — both treated as 'skip this month' by the
    caller, never a hard error (a future or not-yet-published month is
    expected, not a bug)."""
    month_code = f"{year}-{calendar.month_abbr[month]}"
    url = f"https://api.msrc.microsoft.com/cvrf/v3.0/cvrf/{month_code}"
    try:
        resp = await client.get(url, headers={"Accept": "application/json"}, timeout=30.0)
        if resp.status_code == 404:
            return None
        resp.raise_for_status()
        doc = resp.json()
    except Exception as e:
        print(f"[OS Update Catalog] Failed to fetch {month_code}: {e}")
        return None

    product_names: Dict[str, str] = {}  # ProductID -> FullProductName text

    def _collect_full_product_names(node):
        if not isinstance(node, dict):
            return
        for fpn in (node.get('FullProductName') or []):
            pid, val = fpn.get('ProductID'), fpn.get('Value')
            if pid and val:
                product_names[str(pid)] = val
        for branch in (node.get('Branch') or []):
            _collect_full_product_names(branch)

    _collect_full_product_names(doc.get('ProductTree') or {})

    entries = []
    for vuln in (doc.get('Vulnerability') or []):
        cve = vuln.get('CVE')
        title_raw = vuln.get('Title')
        title = title_raw.get('Value') if isinstance(title_raw, dict) else title_raw
        notes = vuln.get('Notes') or []
        note_texts = [n.get('Value') for n in notes if isinstance(n, dict) and n.get('Value')]

        # Severity is encoded as a Threat with Type 3 ("Severity") whose
        # Description is the human label (Critical/Important/Moderate/Low);
        # exploitation status is a separate free-text Threat Description
        # MSRC conventionally phrases as "...Exploited:Yes...".
        severity = None
        exploited = False
        for threat in (vuln.get('Threats') or []):
            desc = threat.get('Description')
            desc_val = desc.get('Value') if isinstance(desc, dict) else desc
            if not desc_val:
                continue
            if threat.get('Type') == 3:
                severity = desc_val
            if 'exploited:yes' in str(desc_val).lower().replace(' ', ''):
                exploited = True

        affected_product_ids = set()
        remediation_texts = []
        kb = None
        for rem in (vuln.get('Remediations') or []):
            for pid in (rem.get('ProductID') or []):
                affected_product_ids.add(str(pid))
            desc = rem.get('Description')
            desc_val = desc.get('Value') if isinstance(desc, dict) else desc
            if desc_val:
                remediation_texts.append(desc_val)
                # Vendor Fix remediations' Description is conventionally just
                # the bare KB article number.
                if not kb and re.match(r'^\d{5,7}$', str(desc_val).strip()):
                    kb = str(desc_val).strip()
            url_val = rem.get('URL')
            if url_val:
                remediation_texts.append(url_val)
        if not kb:
            m = re.search(r'\bKB(\d{5,7})\b', ' '.join(remediation_texts + note_texts + [title or '']), re.IGNORECASE)
            if m:
                kb = m.group(1)

        build_info = _extract_build_revision(*remediation_texts, *note_texts, title)

        for pid in affected_product_ids:
            product_name = product_names.get(pid, '')
            build_major = _match_windows_build_major(product_name)
            if build_major is None:
                continue  # not a Windows client/server product line we track
            entries.append({
                "kb": kb, "cve": cve, "title": title, "severity": severity, "exploited": exploited,
                "productName": product_name, "buildMajor": build_major,
                "fixedUbr": build_info['ubr'] if (build_info and build_info['buildMajor'] == build_major) else None,
                "releaseMonth": month_code,
            })
    return entries

def _rollup_kb_entries(raw_entries: List[dict]) -> List[dict]:
    """Collapse the per-CVE-per-product rows _fetch_msrc_month returns into
    one row per (KB, product build-major) — 'this KB, for this Windows
    version, fixes N CVEs, highest severity X, resulted in build Y.UBR (if
    known)' — which is what the catalog UI and device comparison want."""
    grouped: Dict[tuple, dict] = {}
    for e in raw_entries:
        if not e.get('kb'):
            continue
        key = (e['kb'], e['buildMajor'])
        g = grouped.setdefault(key, {
            "kb": e['kb'], "buildMajor": e['buildMajor'],
            "featureLabel": WINDOWS_BUILD_TO_FEATURE.get(e['buildMajor'], f"Windows (build {e['buildMajor']})"),
            "productName": e['productName'], "releaseMonth": e['releaseMonth'],
            # MSRC's CVRF feed is, by definition, the Security Update Guide —
            # every KB in this catalog is a Security Update. Driver, Feature,
            # and Quality-only (non-security) updates never appear here
            # because MSRC doesn't track them; there's no equivalent public
            # feed for those, and Applivery gives us no per-device driver
            # inventory to compare against even if there were. This field is
            # constant today but kept explicit rather than assumed, so nothing
            # downstream has to guess at scope.
            "updateType": "Security",
            "cveIds": set(), "maxSeverity": None, "exploited": False, "fixedUbr": None,
        })
        if e.get('cve'):
            g['cveIds'].add(e['cve'])
        if e.get('exploited'):
            g['exploited'] = True
        if e.get('fixedUbr') and not g['fixedUbr']:
            g['fixedUbr'] = e['fixedUbr']
        sev = (e.get('severity') or '').lower()
        if _SEVERITY_RANK.get(sev, -1) > _SEVERITY_RANK.get((g['maxSeverity'] or '').lower(), -1):
            g['maxSeverity'] = e.get('severity')
    out = []
    for g in grouped.values():
        g['cveIds'] = sorted(g['cveIds'])
        g['cveCount'] = len(g['cveIds'])
        out.append(g)
    out.sort(key=lambda x: (x['releaseMonth'], x['buildMajor']), reverse=True)
    return out

OS_UPDATE_CATALOG_MONTHS_BACK = 15  # rolling window — long enough that even a fairly neglected fleet's gap is visible, short enough the catalog file doesn't grow unbounded
OS_UPDATE_CATALOG_TICK_SECONDS = 86400  # MSRC ships monthly; daily is plenty to notice a new month promptly and pick up revisions to the current one

async def _refresh_os_update_catalog() -> dict:
    catalog = _load_os_update_catalog()
    now = datetime.now(timezone.utc)
    months_to_fetch = []
    for i in range(OS_UPDATE_CATALOG_MONTHS_BACK):
        y, m = now.year, now.month - i
        while m <= 0:
            m += 12
            y -= 1
        months_to_fetch.append((y, m))

    all_entries_by_month: Dict[str, List[dict]] = {}
    async with httpx.AsyncClient(timeout=httpx.Timeout(30.0)) as client:
        for idx, (y, m) in enumerate(months_to_fetch):
            month_code = f"{y}-{calendar.month_abbr[m]}"
            # Re-fetch the current + previous month every tick (MSRC sometimes
            # revises a bulletin after initial publish); older months, once
            # fetched successfully, are treated as immutable to avoid N
            # redundant requests every single day.
            already_have = month_code in (catalog.get('monthsFetched') or [])
            if already_have and idx >= 2:
                continue
            entries = await _fetch_msrc_month(client, y, m)
            if entries is None:
                continue
            all_entries_by_month[month_code] = entries
            if month_code not in (catalog.get('monthsFetched') or []):
                catalog.setdefault('monthsFetched', []).append(month_code)

    if all_entries_by_month:
        existing = catalog.get('kbEntries') or []
        refreshed_months = set(all_entries_by_month.keys())
        kept = [e for e in existing if e.get('releaseMonth') not in refreshed_months]
        new_rolled = []
        for entries in all_entries_by_month.values():
            new_rolled.extend(_rollup_kb_entries(entries))
        catalog['kbEntries'] = kept + new_rolled
        catalog['lastFetchedAt'] = datetime.now(timezone.utc).isoformat()
        catalog['lastError'] = None
    elif not catalog.get('kbEntries'):
        catalog['lastError'] = 'No MSRC data fetched yet — check network access to api.msrc.microsoft.com'
    _save_os_update_catalog(catalog)
    return catalog

async def os_update_catalog_refresh_loop():
    while True:
        try:
            await _refresh_os_update_catalog()
            _record_job_heartbeat('os_update_catalog_refresh', 'ok')
        except Exception as e:
            print(f"[OS Update Catalog] Error: {e}")
            _record_job_heartbeat('os_update_catalog_refresh', 'error', str(e))
        await asyncio.sleep(OS_UPDATE_CATALOG_TICK_SECONDS)

def _compute_windows_pending_updates(os_version: str, catalog: dict) -> Optional[dict]:
    """Compare one device's reported osVersion against the current OS Update
    Catalog. None for non-Windows/unparseable osVersion (caller should just
    omit the field then). Otherwise: {'featureLabel','buildMajor','ubr',
    'latestKnownUbr','pendingCount','pendingCveCount','pendingKbs','confidence'}
    — 'pendingKbs' only ever includes KBs whose fixedUbr we actually
    extracted; an unconfirmed KB shows up in the catalog view but is never
    counted here. Every KB here is a Security Update (see updateType note on
    _rollup_kb_entries) — this catalog has no Driver/Feature/Quality data."""
    device_build = _windows_device_build(os_version)
    if not device_build:
        return None
    same_family = [
        e for e in (catalog.get('kbEntries') or [])
        if e.get('buildMajor') == device_build['buildMajor'] and e.get('fixedUbr')
    ]
    pending = sorted(
        (e for e in same_family if e['fixedUbr'] > device_build['ubr']),
        key=lambda e: e['fixedUbr'], reverse=True,
    )
    latest_known_ubr = max((e['fixedUbr'] for e in same_family), default=None)
    all_pending_cves = sorted({cve for e in pending for cve in (e.get('cveIds') or [])})
    return {
        "featureLabel": device_build['featureLabel'], "buildMajor": device_build['buildMajor'], "ubr": device_build['ubr'],
        "latestKnownUbr": latest_known_ubr, "pendingCount": len(pending), "pendingCveCount": len(all_pending_cves),
        "pendingKbs": [{"kb": e['kb'], "fixedUbr": e['fixedUbr'], "updateType": e.get('updateType', 'Security'),
                         "cveIds": e.get('cveIds') or [], "cveCount": e['cveCount'],
                         "maxSeverity": e['maxSeverity'], "exploited": e['exploited'], "releaseMonth": e['releaseMonth']} for e in pending[:10]],
        "confidence": "build" if same_family else "unknown",
    }

@app.get("/api/os-updates/catalog", dependencies=[Depends(verify_dashboard_token)])
async def get_os_update_catalog(buildMajor: Optional[int] = None):
    """Global, not per-workspace — the catalog is Microsoft's public data,
    not tenant-specific, same reasoning as SYSTEM_HEALTH_FILE."""
    catalog = _load_os_update_catalog()
    entries = catalog.get('kbEntries') or []
    if buildMajor:
        entries = [e for e in entries if e.get('buildMajor') == buildMajor]
    return {
        "items": entries, "monthsFetched": catalog.get('monthsFetched') or [],
        "lastFetchedAt": catalog.get('lastFetchedAt'), "lastError": catalog.get('lastError'),
        "featureVersions": WINDOWS_BUILD_TO_FEATURE,
    }

@app.post("/api/os-updates/refresh", dependencies=[Depends(verify_dashboard_token)])
async def refresh_os_update_catalog_now():
    catalog = await _refresh_os_update_catalog()
    _record_job_heartbeat('os_update_catalog_refresh', 'ok' if not catalog.get('lastError') else 'error', catalog.get('lastError'))
    return {"kbCount": len(catalog.get('kbEntries') or []), "lastFetchedAt": catalog.get('lastFetchedAt'), "lastError": catalog.get('lastError')}

# ─── APPLE & ANDROID VULNERABILITY INTELLIGENCE (EUVD) ───
# Same foundation-phase spirit as "OS UPDATE INTELLIGENCE" above, extended to
# the platforms Windows/MSRC doesn't cover. Sourced from ENISA's EU
# Vulnerability Database (euvdservices.enisa.europa.eu) — free, no key,
# JSON, and unlike a raw NVD CPE search it gives exactly what a per-device
# comparison needs directly in the response:
#   - Apple (vendor=apple): each CVE's `enisaIdProduct` entries carry a
#     product_version range like "0 <18.6" per affected product (iOS and
#     iPadOS / macOS / Safari / watchOS / tvOS / visionOS all appear as
#     separate entries on multi-platform CVEs) — the "<X" is the version
#     that fixes it, which is exactly the clean mapping apple-cve turned out
#     not to have (its JSON has module/description/impact/release-date but
#     no structured fixed-version field — see the research note below).
#   - Android (vendor=google, product=android): sourced from the Android
#     Security Bulletins, product_version is normally a bare major version
#     string ("14", "17", "12L") — coarser than Windows' build-level
#     precision (Android's own patch model is monthly-patch-level, not
#     exposed here), so Android comparison is "device's major version has a
#     CVE fixed in a later major version" rather than a confirmed patch-gap
#     count. Entries whose product_version isn't parseable (e.g. "Android
#     kernel", platform-wide with no version tie) are catalog-visible only,
#     same 'don't guess' rule as the Windows UBR extraction.
#
# apple-cve (github.com/Proteas/apple-cve) was evaluated too — real, active,
# one JSON per year, good module/impact/device-scope text — but it has no
# CVSS score and no structured fixed-version field, so EUVD alone (which
# already includes CVSS + EPSS + exploited-in-the-wild signals) covers this
# foundation's needs without a second integration. Worth revisiting later if
# module-level categorization (Kernel/WebKit/etc, which EUVD doesn't carry)
# turns out to matter for reporting.
#
# This has not been verified against this app's own live Applivery device
# data (osVersion formatting for Android in particular — Applivery's Android
# Enterprise passthrough may report a bare major version, a dotted string,
# or something else) — same "verify on first real refresh" caveat as the
# Windows section, defensive .get()/regex parsing throughout.

VULN_CATALOG_DIR = os.path.join(DATA_DIR, "vuln_catalog")
VULN_CATALOG_FILE = os.path.join(VULN_CATALOG_DIR, "apple_android_catalog.json")
EUVD_SEARCH_URL = "https://euvdservices.enisa.europa.eu/api/search"
VULN_CATALOG_MONTHS_BACK = 15
VULN_CATALOG_TICK_SECONDS = 86400  # daily, same cadence reasoning as the Windows catalog

def _cvss_band(score: Optional[float]) -> Optional[str]:
    if score is None:
        return None
    if score >= 9.0: return "Critical"
    if score >= 7.0: return "High"
    if score >= 4.0: return "Medium"
    if score > 0.0: return "Low"
    return None

def _parse_apple_fixed_version(product_version: str) -> Optional[str]:
    """'0 <18.6' / 'unspecified <15.6' -> '18.6'. None if the string doesn't
    match that shape (EUVD's Apple entries use it consistently in the
    entries observed, but this degrades gracefully rather than guessing)."""
    if not product_version:
        return None
    m = re.search(r'<\s*([\d][\d.]*)\s*$', str(product_version))
    return m.group(1) if m else None

def _parse_android_major_version(product_version: str) -> Optional[str]:
    """Android entries are normally a bare major version ('17', '12L');
    return it as-is if it looks like one, else None (e.g. 'Android kernel',
    which is platform-wide and not tied to a specific version)."""
    v = (product_version or '').strip()
    return v if re.match(r'^\d{1,2}[A-Za-z]?$', v) else None

async def _fetch_euvd(client: httpx.AsyncClient, vendor: str, product: str, from_date: str, to_date: str) -> List[dict]:
    """Paginate EUVD's search endpoint for one vendor/product scope within a
    date window. Returns raw EUVD 'items' (not yet normalized to our own
    entry shape — see _parse_euvd_items). Empty list on any failure; this
    integration degrades the same way the MSRC one does — a bad tick just
    means stale-but-present data, never a crash."""
    items: List[dict] = []
    page = 0
    try:
        while True:
            params = {"vendor": vendor, "product": product, "fromDate": from_date, "toDate": to_date, "size": 100, "page": page}
            resp = await client.get(EUVD_SEARCH_URL, params=params, timeout=30.0)
            resp.raise_for_status()
            body = resp.json()
            batch = body.get('items') or []
            items.extend(batch)
            total = body.get('total', len(items))
            page += 1
            if not batch or len(items) >= total or page > 20:  # 20-page (2,000 entry) safety cap per vendor/product/window
                break
    except Exception as e:
        print(f"[Vuln Catalog] EUVD fetch failed for vendor={vendor} product={product}: {e}")
    return items

def _parse_euvd_items(items: List[dict], platform: str, product_name_filter) -> List[dict]:
    """Normalize raw EUVD items into our catalog entry shape, one row per
    (CVE, matching product) — a single EUVD item can carry several
    `enisaIdProduct` entries (e.g. one CVE fixed across iOS, macOS, and
    Safari simultaneously); product_name_filter(name) decides which of
    those sibling entries are relevant to `platform`."""
    entries = []
    for item in items:
        cve_id = None
        for alias in str(item.get('aliases') or '').splitlines():
            alias = alias.strip()
            if alias.startswith('CVE-'):
                cve_id = alias
                break
        score = item.get('baseScore')
        exploited = bool(item.get('exploitedSince'))
        refs = [r for r in str(item.get('references') or '').splitlines() if r.strip()]
        seen_products = set()
        for p in (item.get('enisaIdProduct') or []):
            product = p.get('product') or {}
            name = product.get('name') or ''
            if not product_name_filter(name):
                continue
            version_raw = p.get('product_version') or ''
            fixed_version = _parse_apple_fixed_version(version_raw) if platform == 'apple' else None
            android_major = _parse_android_major_version(version_raw) if platform == 'android' else None
            dedup_key = (item.get('id'), name, version_raw)
            if dedup_key in seen_products:
                continue
            seen_products.add(dedup_key)
            entries.append({
                "cveId": cve_id or item.get('id'), "euvdId": item.get('id'), "platform": platform,
                "productLabel": name, "description": item.get('description'),
                "baseScore": score, "baseSeverity": _cvss_band(score), "epss": item.get('epss'),
                "exploited": exploited, "datePublished": item.get('datePublished'),
                "fixedVersion": fixed_version, "androidMajorVersion": android_major,
                "references": refs[:3],
            })
    return entries

async def _refresh_vuln_catalog() -> dict:
    catalog = _load_vuln_catalog()
    now = datetime.now(timezone.utc)
    from_date = (now - timedelta(days=30 * VULN_CATALOG_MONTHS_BACK)).strftime("%Y-%m-%d")
    to_date = now.strftime("%Y-%m-%d")

    all_entries: List[dict] = []
    had_success = False
    async with httpx.AsyncClient(timeout=httpx.Timeout(30.0)) as client:
        apple_raw = await _fetch_euvd(client, "apple", "ios", from_date, to_date)
        if apple_raw:
            had_success = True
            apple_products = ("ios and ipados", "macos", "ipados")
            all_entries.extend(_parse_euvd_items(apple_raw, "apple", lambda n: n.lower() in apple_products))

        android_raw = await _fetch_euvd(client, "google", "android", from_date, to_date)
        if android_raw:
            had_success = True
            all_entries.extend(_parse_euvd_items(android_raw, "android", lambda n: n.lower() == "android"))

    if had_success:
        # De-dup across the whole catalog by (cveId, platform, productLabel,
        # fixedVersion/androidMajorVersion) — EUVD pagination plus repeated
        # daily refreshes over an overlapping date window would otherwise
        # accumulate exact duplicates.
        dedup: Dict[tuple, dict] = {}
        for e in all_entries:
            key = (e['cveId'], e['platform'], e['productLabel'], e.get('fixedVersion'), e.get('androidMajorVersion'))
            dedup[key] = e
        catalog['entries'] = sorted(dedup.values(), key=lambda e: e.get('datePublished') or '', reverse=True)
        catalog['lastFetchedAt'] = now.isoformat()
        catalog['lastError'] = None
        catalog['windowFrom'] = from_date
    elif not catalog.get('entries'):
        catalog['lastError'] = 'No EUVD data fetched yet — check network access to euvdservices.enisa.europa.eu'
    _save_vuln_catalog(catalog)
    return catalog

_register_legacy_json('vuln_catalog', lambda slug, key: VULN_CATALOG_FILE)

def _load_vuln_catalog() -> dict:
    return _store_load(_GLOBAL_STORE_SLUG, 'vuln_catalog', lambda: {"entries": [], "lastFetchedAt": None, "lastError": None, "windowFrom": None})

def _save_vuln_catalog(catalog: dict):
    _store_save(_GLOBAL_STORE_SLUG, 'vuln_catalog', catalog)

async def vuln_catalog_refresh_loop():
    while True:
        try:
            await _refresh_vuln_catalog()
            _record_job_heartbeat('vuln_catalog_refresh', 'ok')
        except Exception as e:
            print(f"[Vuln Catalog] Error: {e}")
            _record_job_heartbeat('vuln_catalog_refresh', 'error', str(e))
        await asyncio.sleep(VULN_CATALOG_TICK_SECONDS)

def _compute_apple_pending_vulns(platform: str, os_version: str, catalog: dict) -> Optional[dict]:
    """platform: 'apple' (iOS/iPadOS) or 'macos'. None if osVersion is empty
    (device hasn't reported yet). 'pendingCves' only includes entries with a
    parsed fixedVersion strictly newer than the device's own — an entry EUVD
    didn't give us a parseable fixed version for is catalog-visible only,
    never guessed into a device's count."""
    if not os_version:
        return None
    device_v = _version_tuple(os_version)
    product_name = "macOS" if platform == 'macos' else "iOS and iPadOS"
    candidates = [e for e in (catalog.get('entries') or []) if e.get('platform') == 'apple' and e.get('productLabel') == product_name]
    confirmed = [e for e in candidates if e.get('fixedVersion')]
    pending = sorted(
        (e for e in confirmed if _version_tuple(e['fixedVersion']) > device_v),
        key=lambda e: _version_tuple(e['fixedVersion']), reverse=True,
    )
    return {
        "pendingCount": len(pending),
        "pendingCves": [{"cveId": e['cveId'], "baseScore": e['baseScore'], "baseSeverity": e['baseSeverity'],
                          "epss": e['epss'], "exploited": e['exploited'], "fixedVersion": e['fixedVersion']} for e in pending[:10]],
        "confidence": "version" if confirmed else "unknown",
        "unconfirmedCount": len(candidates) - len(confirmed),
    }

def _compute_android_pending_vulns(os_version: str, catalog: dict) -> Optional[dict]:
    """Coarser than Apple/Windows — see the module docstring. 'pending' here
    means 'a CVE exists whose fixed major version is strictly newer than
    this device's major version', not a confirmed patch-level gap."""
    if not os_version:
        return None
    m = re.match(r'^\D*(\d{1,2})', str(os_version))
    if not m:
        return None
    device_major = int(m.group(1))
    candidates = [e for e in (catalog.get('entries') or []) if e.get('platform') == 'android']
    confirmed = [e for e in candidates if e.get('androidMajorVersion')]
    pending = []
    for e in confirmed:
        try:
            fixed_major = int(re.match(r'^(\d{1,2})', e['androidMajorVersion']).group(1))
        except Exception:
            continue
        if fixed_major > device_major:
            pending.append(e)
    pending.sort(key=lambda e: e.get('baseScore') or 0, reverse=True)
    return {
        "pendingCount": len(pending),
        "pendingCves": [{"cveId": e['cveId'], "baseScore": e['baseScore'], "baseSeverity": e['baseSeverity'],
                          "epss": e['epss'], "exploited": e['exploited'], "fixedInMajor": e['androidMajorVersion']} for e in pending[:10]],
        "confidence": "version" if confirmed else "unknown",
        "unconfirmedCount": len(candidates) - len(confirmed),
    }

@app.get("/api/vuln-catalog/catalog", dependencies=[Depends(verify_dashboard_token)])
async def get_vuln_catalog(platform: Optional[str] = None):
    """Global, not per-workspace — same reasoning as the OS Update Catalog."""
    catalog = _load_vuln_catalog()
    entries = catalog.get('entries') or []
    if platform:
        entries = [e for e in entries if e.get('platform') == platform]
    return {
        "items": entries, "lastFetchedAt": catalog.get('lastFetchedAt'),
        "lastError": catalog.get('lastError'), "windowFrom": catalog.get('windowFrom'),
    }

@app.post("/api/vuln-catalog/refresh", dependencies=[Depends(verify_dashboard_token)])
async def refresh_vuln_catalog_now():
    catalog = await _refresh_vuln_catalog()
    _record_job_heartbeat('vuln_catalog_refresh', 'ok' if not catalog.get('lastError') else 'error', catalog.get('lastError'))
    return {"entryCount": len(catalog.get('entries') or []), "lastFetchedAt": catalog.get('lastFetchedAt'), "lastError": catalog.get('lastError')}

# ─── VULNERABILITY SERVICE (Applivery-hosted CVE matching, CloudFlare Worker) ───
#
# A separate, richer vulnerability data source from the EUVD-based
# "VULNERABILITY CATALOG" just above: instead of a scheduled Apple/Android-
# only OS-level catalog fetched wholesale and matched client-side, this
# queries a self-hosted Applivery service (their internal
# vulnerability-detection CloudFlare Worker — an NVD-derived D1 database
# enriched with CISA KEV + FIRST EPSS) per {identifier, version, platform},
# covering ALL FOUR platforms (including Windows, which EUVD doesn't) and
# BOTH the OS and individual installed apps (EUVD is OS-only), with
# confirmed fix versions rather than "a CVE exists, no fix info"
# uncertainty. API contract (3 endpoints, Bearer token):
#   POST /v1/vulnerabilities/apps  {apps: [{identifier, version, platform}]}
#   POST /v1/vulnerabilities/os    {platform, os_version}
#   GET  /v1/cves/:id
# platform is one of macos/ios/android/windows (their spelling, not ours).
#
# Deliberately opt-in and per-workspace (unlike EUVD, which is free/public/
# global): this hits an admin-provided, admin-hosted service instance and
# requires a Bearer token, so it's configured like any other Integration
# (Settings > Vulnerability Service) rather than always-on. Both this and
# EUVD run side by side — independent, additive signals on the same
# device, not a replacement for one another (see COMPLIANCE_FIELDS /
# _compute_device_risk, which score them separately).
#
# The service's own API caches app results (identifier, version, platform)
# for 24h server-side (Cloudflare KV); this app layers its own local cache
# on top with the same 24h horizon (vuln_service_cache, per workspace), so
# the fleet-wide refresh loop below only re-queries combos it hasn't seen
# recently — request volume scales with "new/changed installs since last
# refresh", not the whole fleet every tick. Devices themselves never call
# the Worker directly; per-device status is always a read from this local
# cache (_compute_vuln_service_status), same "compute from an
# already-fetched catalog" shape as every other intelligence signal in
# this file.
VULN_SERVICE_CACHE_TTL_SECONDS = 24 * 3600
VULN_SERVICE_APPS_CHUNK_SIZE = 25  # keep each POST small — the Worker does one D1 round-trip per app, server-side
VULN_SERVICE_MAX_APPS_PER_TICK = 500  # cap per-workspace, per-tick app queries so one large fleet's backlog can't starve other workspaces or run indefinitely inline
VULN_SERVICE_TICK_SECONDS = 3600  # cheap hourly check; actual refresh only fires once a workspace's own refreshIntervalHours has elapsed (see the loop below)

# Our normalized device platform -> the Worker's expected platform string.
# AOSP devices are best-effort mapped to "android" (no separate AOSP
# product line exists on the NVD/CPE side this service is built on).
_VULN_SERVICE_PLATFORM_MAP = {"macos": "macos", "apple": "ios", "android": "android", "aosp": "android", "windows": "windows"}

class VulnServiceConfig(BaseModel):
    enabled: bool = False
    baseUrl: str = ""
    # Plaintext on the wire (input only) — the request body is TLS-protected
    # same as every other secret-carrying payload in this app. Blank/omitted
    # on PUT means "leave the currently-stored token alone" (see
    # update_vuln_service_config) so the frontend never has to know or
    # re-send the real value just to change baseUrl/enabled/interval.
    apiToken: str = ""
    refreshIntervalHours: int = 6

def _load_vuln_service_config(slug: str) -> Dict[str, Any]:
    # Stores apiTokenEncrypted (Fernet ciphertext), never a plaintext
    # apiToken — see "SECRET-AT-REST ENCRYPTION" near DASHBOARD_SECRET.
    return _store_load(slug, 'vuln_service_config', lambda: {
        "enabled": False, "baseUrl": "", "apiTokenEncrypted": "", "refreshIntervalHours": 6,
        "lastRefreshAt": None, "lastRefreshError": None, "lastRefreshStats": None,
    })

def _save_vuln_service_config(slug: str, config: Dict[str, Any]):
    _store_save(slug, 'vuln_service_config', config)

def _vuln_service_decrypt_token(cfg: dict) -> str:
    return _decrypt_secret(cfg.get('apiTokenEncrypted') or '')

def _vuln_service_config_public(cfg: dict) -> Dict[str, Any]:
    """The GET-safe view: everything except the encrypted token, plus a
    redacted apiToken summary (set/last4) so the settings UI can show
    "token configured" without ever receiving the secret itself."""
    public = {k: v for k, v in cfg.items() if k != 'apiTokenEncrypted'}
    public['apiToken'] = _mask_secret_tail(_vuln_service_decrypt_token(cfg))
    return public

def _clamp_vuln_service_refresh_hours(hours: Any) -> int:
    try:
        h = int(hours)
    except (TypeError, ValueError):
        h = 6
    return max(1, min(h, 72))

def _load_vuln_service_cache(slug: str) -> Dict[str, Any]:
    return _store_load(slug, 'vuln_service_cache', lambda: {"apps": {}, "os": {}})

def _save_vuln_service_cache(slug: str, cache: Dict[str, Any]):
    _store_save(slug, 'vuln_service_cache', cache)

def _vuln_service_app_cache_key(identifier: str, version: str, platform: str) -> str:
    return f"{(identifier or '').lower()}|{version or ''}|{platform or ''}"

def _vuln_service_os_cache_key(platform: str, os_version: str) -> str:
    return f"{platform or ''}|{os_version or ''}"

def _vuln_service_cache_is_fresh(entry: Optional[dict]) -> bool:
    if not entry or not entry.get('fetchedAt'):
        return False
    try:
        fetched = datetime.fromisoformat(entry['fetchedAt'])
    except Exception:
        return False
    if fetched.tzinfo is None:
        fetched = fetched.replace(tzinfo=timezone.utc)
    return (datetime.now(timezone.utc) - fetched).total_seconds() < VULN_SERVICE_CACHE_TTL_SECONDS

# Retried, in order: connection-level failures (DNS, refused, timeout) and
# 429/5xx are treated as transient — a momentary blip on an
# admin-self-hosted Worker instance shouldn't burn through this tick's
# whole query budget on the first hiccup, nor get reported as a hard
# refresh failure. Anything else (401 bad token, 400 bad request, 404) is
# permanent for this input and returned as-is on the first attempt — retrying
# it would just waste time and delay the real error surfacing in
# lastRefreshError. Deliberately used only by the unattended batch refresh
# path below, not by the interactive "Test connection" button — a user
# clicking Test wants an immediate, honest answer, not an automatic 1-2s
# retry silently masking a flaky connection.
_VULN_SERVICE_RETRY_STATUSES = {429, 500, 502, 503, 504}
_VULN_SERVICE_MAX_ATTEMPTS = 3
_VULN_SERVICE_RETRY_BACKOFF_SECONDS = (1, 2)  # sleep between attempts 1→2 and 2→3

async def _vuln_service_post_with_retry(client: httpx.AsyncClient, url: str, headers: dict, json_body: dict, timeout: float):
    last_exc: Optional[Exception] = None
    last_res = None
    for attempt in range(_VULN_SERVICE_MAX_ATTEMPTS):
        try:
            res = await client.post(url, headers=headers, json=json_body, timeout=timeout)
        except Exception as e:
            last_exc = e
            last_res = None
        else:
            last_res = res
            last_exc = None
            if res.status_code not in _VULN_SERVICE_RETRY_STATUSES:
                return res
        if attempt < _VULN_SERVICE_MAX_ATTEMPTS - 1:
            await asyncio.sleep(_VULN_SERVICE_RETRY_BACKOFF_SECONDS[attempt])
    if last_res is not None:
        return last_res  # exhausted retries on a persistently-bad status — let the caller's status_code check raise the real error
    raise last_exc

async def _vuln_service_query_apps_batch(client: httpx.AsyncClient, cfg: dict, apps: List[dict]) -> List[dict]:
    """apps: [{identifier, version, platform}]. Chunked POSTs to
    /v1/vulnerabilities/apps — a THIRD-PARTY (admin-hosted, not
    api.applivery.io) service, so this uses a plain client.post like every
    other non-Applivery integration in this file (EUVD, endoflife.date, the
    generic-REST Threat Intel provider), not _applivery_call (that helper's
    rate limiter/retry budget is scoped to Applivery's own API and would
    misattribute traffic either direction if reused here). Returns the
    concatenated `results` list, in the same order as the input — the
    Worker preserves input order within each chunk."""
    headers = {"Authorization": f"Bearer {_vuln_service_decrypt_token(cfg)}", "Content-Type": "application/json"}
    base = (cfg.get('baseUrl') or '').rstrip('/')
    out: List[dict] = []
    for i in range(0, len(apps), VULN_SERVICE_APPS_CHUNK_SIZE):
        chunk = apps[i:i + VULN_SERVICE_APPS_CHUNK_SIZE]
        res = await _vuln_service_post_with_retry(client, f"{base}/v1/vulnerabilities/apps", headers, {"apps": chunk}, timeout=45.0)
        if res.status_code != 200:
            raise RuntimeError(f"Vulnerability Service returned {res.status_code} for an apps batch: {res.text[:300]}")
        out.extend((res.json() or {}).get('results') or [])
    return out

async def _vuln_service_query_os(client: httpx.AsyncClient, cfg: dict, platform: str, os_version: str) -> Optional[dict]:
    headers = {"Authorization": f"Bearer {_vuln_service_decrypt_token(cfg)}", "Content-Type": "application/json"}
    base = (cfg.get('baseUrl') or '').rstrip('/')
    res = await _vuln_service_post_with_retry(client, f"{base}/v1/vulnerabilities/os", headers, {"platform": platform, "os_version": os_version}, timeout=30.0)
    if res.status_code != 200:
        raise RuntimeError(f"Vulnerability Service returned {res.status_code} for an OS check: {res.text[:300]}")
    return res.json()

def _evict_orphaned_vuln_service_cache_entries(cache: dict, os_combos: dict, app_combos: dict) -> int:
    """Removes cache entries for OS versions and app (identifier, version,
    platform) combos no longer present ANYWHERE in the current fleet — an
    uninstalled app or a device that's moved to a new OS build otherwise
    leaves its old cache entry behind forever, since nothing else in this
    pipeline ever deletes one; freshness-gating (_vuln_service_cache_is_fresh)
    stops a stale entry from being trusted, but doesn't stop it from sitting
    in the store indefinitely. Called every refresh tick, driven by
    whatever's actually installed right now — so a flapping app (removed
    then reinstalled) just gets re-queried next tick, same as if it were
    new. Returns the number of entries removed, folded into refresh stats
    so an admin can see the cache isn't just growing unbounded."""
    removed = 0
    os_cache = cache.setdefault('os', {})
    for key in list(os_cache.keys()):
        if key not in os_combos:
            del os_cache[key]
            removed += 1
    apps_cache = cache.setdefault('apps', {})
    for key in list(apps_cache.keys()):
        if key not in app_combos:
            del apps_cache[key]
            removed += 1
    return removed

async def _refresh_vuln_service_for_workspace(slug: str, bearer: str) -> dict:
    """Gathers every distinct (identifier, version, platform) app combo and
    (platform, os_version) combo currently present in the fleet, skips
    anything already cached fresh, queries the rest from the configured
    Worker, and updates the local cache. `bearer` is a ready 'Bearer xxx'
    string for THIS app's own Applivery session (either the background
    loop's automation credential, or the calling admin's own session for a
    manual refresh) — used only to fetch the device/installed-apps
    inventory already stored in this app, never sent to the vuln service
    itself. Returns refresh stats, also persisted onto the config record so
    the settings page can show "last refreshed" without a separate call."""
    cfg = _load_vuln_service_config(slug)
    devices_resp = await get_devices_full(refresh=False, authorization=bearer, x_workspace_slug=slug)
    devices = devices_resp.get('items', [])
    installed_apps_store = _load_installed_apps_store(slug)
    cache = _load_vuln_service_cache(slug)

    os_combos: Dict[str, tuple] = {}
    for d in devices:
        worker_platform = _VULN_SERVICE_PLATFORM_MAP.get(d.get('platform'))
        os_version = d.get('osVersion')
        if worker_platform and os_version:
            os_combos[_vuln_service_os_cache_key(worker_platform, os_version)] = (worker_platform, os_version)

    app_combos: Dict[str, dict] = {}
    for d in devices:
        worker_platform = _VULN_SERVICE_PLATFORM_MAP.get(d.get('platform'))
        if not worker_platform:
            continue
        entry = installed_apps_store.get(str(d.get('id'))) or {}
        for a in (entry.get('apps') or []):
            ident, version = a.get('identifier'), a.get('version')
            if ident and version:
                key = _vuln_service_app_cache_key(ident, version, worker_platform)
                app_combos[key] = {"identifier": ident, "version": version, "platform": worker_platform}

    evicted = _evict_orphaned_vuln_service_cache_entries(cache, os_combos, app_combos)

    os_queried = os_errors = apps_queried = apps_errors = 0
    async with httpx.AsyncClient(timeout=60.0) as client:
        for key, (platform, os_version) in os_combos.items():
            if _vuln_service_cache_is_fresh((cache.get('os') or {}).get(key)):
                continue
            try:
                result = await _vuln_service_query_os(client, cfg, platform, os_version)
                cache.setdefault('os', {})[key] = {"result": result, "fetchedAt": datetime.now(timezone.utc).isoformat()}
                os_queried += 1
            except Exception as e:
                os_errors += 1
                print(f"[Vuln Service] OS query failed ({platform}/{os_version}) for {slug}: {e}")

        to_query = [v for k, v in app_combos.items() if not _vuln_service_cache_is_fresh((cache.get('apps') or {}).get(k))]
        batch_to_query = to_query[:VULN_SERVICE_MAX_APPS_PER_TICK]
        if batch_to_query:
            try:
                results = await _vuln_service_query_apps_batch(client, cfg, batch_to_query)
                now_iso = datetime.now(timezone.utc).isoformat()
                for app_input, result in zip(batch_to_query, results):
                    key = _vuln_service_app_cache_key(app_input['identifier'], app_input['version'], app_input['platform'])
                    cache.setdefault('apps', {})[key] = {"result": result, "fetchedAt": now_iso}
                    apps_queried += 1
            except Exception as e:
                apps_errors += len(batch_to_query)
                print(f"[Vuln Service] Apps batch query failed for {slug}: {e}")

    _save_vuln_service_cache(slug, cache)

    stats = {
        "osQueried": os_queried, "osErrors": os_errors, "osTotal": len(os_combos),
        "appsQueried": apps_queried, "appsErrors": apps_errors, "appsTotal": len(app_combos),
        "appsRemaining": max(0, len(to_query) - len(batch_to_query)),
        "cacheEvicted": evicted,
        "refreshedAt": datetime.now(timezone.utc).isoformat(),
    }
    cfg['lastRefreshAt'] = stats['refreshedAt']
    cfg['lastRefreshError'] = None if (os_errors == 0 and apps_errors == 0) else f"{os_errors} OS + {apps_errors} app quer{'y' if (os_errors + apps_errors) == 1 else 'ies'} failed"
    cfg['lastRefreshStats'] = stats
    _save_vuln_service_config(slug, cfg)
    return stats

async def vuln_service_refresh_loop():
    """Every tick, for every workspace with both an automation credential
    AND the Vulnerability Service enabled+configured, refreshes it once its
    own refreshIntervalHours has elapsed since lastRefreshAt — same
    per-workspace-configurable-cadence shape as Installed Apps' budget,
    rather than one global interval for every tenant."""
    await asyncio.sleep(40)  # stagger startup after the other refreshers
    while True:
        try:
            for slug_key in _automation_workspaces():
                cfg = _load_vuln_service_config(slug_key)
                if not cfg.get('enabled') or not cfg.get('baseUrl') or not cfg.get('apiTokenEncrypted'):
                    continue
                last = cfg.get('lastRefreshAt')
                if last:
                    try:
                        last_dt = datetime.fromisoformat(last)
                        if last_dt.tzinfo is None:
                            last_dt = last_dt.replace(tzinfo=timezone.utc)
                        if (datetime.now(timezone.utc) - last_dt).total_seconds() < _clamp_vuln_service_refresh_hours(cfg.get('refreshIntervalHours')) * 3600:
                            continue
                    except Exception:
                        pass
                bearer = await _get_automation_bearer(slug_key)
                if not bearer:
                    continue
                stats = await _refresh_vuln_service_for_workspace(slug_key, bearer)
                print(f"[Vuln Service] {slug_key}: {stats}")
            _record_job_heartbeat('vuln_service_refresh', 'ok')
        except Exception as e:
            print(f"[Vuln Service Refresher] Error: {e}")
            _record_job_heartbeat('vuln_service_refresh', 'error', str(e))
        await asyncio.sleep(VULN_SERVICE_TICK_SECONDS)

def _vuln_service_sort_key(c: dict) -> tuple:
    """KEV-first, then EPSS, then severity/score — the service's own
    documented prioritization guidance ("Don't rank by CVSS alone")."""
    sev_rank = {"CRITICAL": 4, "HIGH": 3, "MEDIUM": 2, "LOW": 1}
    return (bool(c.get('is_kev')), c.get('epss_score') or 0, sev_rank.get(c.get('severity'), 0), c.get('score') or 0)

def _compute_vuln_service_status(device: dict, cache: dict, apps_entry: Optional[dict]) -> Optional[dict]:
    """Local-cache-only read (never calls the Worker inline) — returns None
    if this platform isn't covered by the integration at all, or a
    checked:False shell if the platform IS covered but nothing usable is
    currently cached for this device (e.g. integration just enabled, first
    refresh hasn't run, or a fresh check came back inconclusive).

    The checked:False shell also carries `lastCheckedAt`: the most recent
    fetchedAt timestamp among ANY cache entry for this device (fresh or
    stale), or None if truly nothing's ever been cached. This is what lets
    the UI tell "never checked yet — waiting on the next scheduled refresh"
    (lastCheckedAt is None) apart from "was checked before, but that data
    aged out and hasn't been refreshed since — possibly a stalled/broken
    refresh loop" (lastCheckedAt is set but old) rather than rendering
    identical nothing for both, which is what prompted this field to exist
    in the first place."""
    worker_platform = _VULN_SERVICE_PLATFORM_MAP.get(device.get('platform'))
    if not worker_platform:
        return None

    # Only ever read FRESH cache entries — same TTL the refresh loop uses to
    # decide what to re-query. Without this, a device whose data hasn't
    # been re-checked in a while (integration disabled, automation
    # credential broke, refresh loop stalled) would keep silently showing
    # its last-known result as current/"checked" indefinitely instead of
    # falling back to the honest "not (recently) checked" shell below —
    # same "never guess past what's confirmed" rule as every other
    # intelligence signal in this file.
    os_version = device.get('osVersion')
    os_key = _vuln_service_os_cache_key(worker_platform, os_version) if os_version else None
    os_entry = (cache.get('os') or {}).get(os_key) if os_key else None
    os_match = os_entry.get('result') if _vuln_service_cache_is_fresh(os_entry) else None

    app_results = []
    app_entry_timestamps = []
    for a in ((apps_entry or {}).get('apps') or []):
        key = _vuln_service_app_cache_key(a.get('identifier'), a.get('version'), worker_platform)
        entry = (cache.get('apps') or {}).get(key)
        if entry and entry.get('fetchedAt'):
            app_entry_timestamps.append(entry['fetchedAt'])
        if entry and _vuln_service_cache_is_fresh(entry) and entry.get('result') and entry['result'].get('mapped'):
            app_results.append(entry['result'])

    if os_match is None and not app_results:
        candidate_timestamps = ([os_entry['fetchedAt']] if os_entry and os_entry.get('fetchedAt') else []) + app_entry_timestamps
        last_checked_at = max(candidate_timestamps) if candidate_timestamps else None
        return {"checked": False, "lastCheckedAt": last_checked_at, "os": None, "appsCheckedCount": 0, "counts": {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0}, "uncertain": 0, "hasKev": False, "maxEpss": 0.0, "topCves": []}

    total_counts = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0}
    total_uncertain = 0
    has_kev = False
    max_epss = 0.0
    all_cves: List[dict] = []
    for r in ([os_match] if os_match else []) + app_results:
        for sev, n in (r.get('counts') or {}).items():
            if sev in total_counts:
                total_counts[sev] += n
        total_uncertain += r.get('uncertain') or 0
        for c in (r.get('cve_list') or []):
            all_cves.append(c)
            if c.get('is_kev'):
                has_kev = True
            max_epss = max(max_epss, c.get('epss_score') or 0)

    all_cves.sort(key=_vuln_service_sort_key, reverse=True)
    return {
        "checked": True, "lastCheckedAt": None, "os": os_match, "appsCheckedCount": len(app_results),
        "counts": total_counts, "uncertain": total_uncertain, "hasKev": has_kev,
        "maxEpss": round(max_epss, 4), "topCves": all_cves[:15],
    }

@app.get("/api/vuln-service/config", dependencies=[Depends(require_permission(area="integrations", level="read"))])
async def get_vuln_service_config(x_workspace_slug: Optional[str] = Header(None)):
    return _vuln_service_config_public(_load_vuln_service_config(x_workspace_slug or 'global'))

@app.put("/api/vuln-service/config", dependencies=[Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def update_vuln_service_config(payload: VulnServiceConfig, x_workspace_slug: Optional[str] = Header(None), dash: dict = Depends(verify_dashboard_token)):
    slug_key = x_workspace_slug or 'global'
    existing = _load_vuln_service_config(slug_key)
    # A blank apiToken on the wire means "leave the stored one alone" — the
    # frontend never has the real value to re-send (GET redacts it), so
    # changing baseUrl/enabled/interval without touching the token has to
    # be possible without the admin re-entering a secret they can't see.
    token_encrypted = _encrypt_secret(payload.apiToken.strip()) if payload.apiToken.strip() else existing.get('apiTokenEncrypted', '')
    config = {
        "enabled": payload.enabled,
        "baseUrl": (payload.baseUrl or '').strip().rstrip('/'),
        "apiTokenEncrypted": token_encrypted,
        "refreshIntervalHours": _clamp_vuln_service_refresh_hours(payload.refreshIntervalHours),
        "lastRefreshAt": existing.get('lastRefreshAt'),
        "lastRefreshError": existing.get('lastRefreshError'),
        "lastRefreshStats": existing.get('lastRefreshStats'),
    }
    _save_vuln_service_config(slug_key, config)
    _record_audit_event(slug_key, category="settings", action="vuln_service_config_updated", actor=dash.get('sub'),
                         message=f'Vulnerability Service integration {"enabled" if payload.enabled else "disabled"} by {dash.get("sub")}')
    return _vuln_service_config_public(config)

@app.post("/api/vuln-service/test", dependencies=[Depends(require_permission(area="integrations", level="manage", action="canEditIntegrationSecrets"))])
async def test_vuln_service_config(payload: VulnServiceConfig, x_workspace_slug: Optional[str] = Header(None)):
    """Tests baseUrl/apiToken from the request body when provided (so an
    admin can verify before saving), falling back to the already-saved,
    still-encrypted token when the field is left blank — same "blank means
    unchanged" semantics as the PUT above, since the settings UI never has
    the real saved token to re-send. Distinguishes an auth failure (401,
    token rejected) from a reachability failure (bad URL / connection
    error) from success."""
    base = (payload.baseUrl or '').strip().rstrip('/')
    token = payload.apiToken.strip() or _vuln_service_decrypt_token(_load_vuln_service_config(x_workspace_slug or 'global'))
    if not base or not token:
        raise HTTPException(status_code=400, detail="Base URL and API token are both required to test the connection.")
    headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
    started = time.monotonic()
    try:
        async with httpx.AsyncClient(timeout=15.0) as client:
            res = await client.post(f"{base}/v1/vulnerabilities/os", headers=headers, json={"platform": "macos", "os_version": "0.0.0-connectivity-test"})
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Could not reach {base}: {e}")
    latency_ms = round((time.monotonic() - started) * 1000)
    if res.status_code == 401:
        raise HTTPException(status_code=401, detail="Reached the service, but the API token was rejected.")
    if res.status_code != 200:
        raise HTTPException(status_code=502, detail=f"Service responded with {res.status_code}: {res.text[:200]}")
    return {"status": "ok", "latencyMs": latency_ms}

@app.post("/api/vuln-service/refresh", dependencies=[Depends(require_permission(area="integrations", level="manage"))])
async def refresh_vuln_service_now(authorization: Optional[str] = Header(None), x_workspace_slug: Optional[str] = Header(None)):
    """Manual trigger — uses the CALLING ADMIN's own Applivery session, not
    the automation credential, so it works even before automation has been
    set up for this workspace (see PER-WORKSPACE AUTOMATION CREDENTIALS)."""
    slug_key = x_workspace_slug or 'global'
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing credentials")
    cfg = _load_vuln_service_config(slug_key)
    if not cfg.get('enabled') or not cfg.get('baseUrl') or not cfg.get('apiTokenEncrypted'):
        raise HTTPException(status_code=400, detail="Vulnerability Service isn't configured/enabled for this workspace yet.")
    stats = await _refresh_vuln_service_for_workspace(slug_key, authorization)
    _record_job_heartbeat('vuln_service_refresh', 'ok' if not stats.get('osErrors') and not stats.get('appsErrors') else 'error')
    return stats

# ─── OS LIFECYCLE (endoflife.date) ───
# Third and last layer of the OS intelligence foundation, alongside "OS
# UPDATE INTELLIGENCE" (Windows/MSRC) and "APPLE & ANDROID VULNERABILITY
# INTELLIGENCE" (EUVD): neither of those sources can answer "is this OS
# version still supported at all" or "what's the actual latest version,
# independent of whether a CVE happens to have been filed against it" — a
# device can have zero pending CVEs simply because nobody's looked, not
# because it's current. endoflife.date (free, public, no key) answers both:
# per major-version "train" (e.g. Windows 11 24H2, iOS 18, Android 15) it
# gives the latest known full version + release date, and whether that
# train has reached end-of-life for security support.
#
# Two known precision limits, both handled by degrading honestly rather
# than guessing:
#   - Windows: endoflife.date splits every feature version into channel
#     variants (Enterprise/IoT-LTS get years longer support than the
#     consumer "W" edition) that share the same build number. We can't
#     tell from Applivery's data which edition a device is running, so a
#     build is only flagged EOL here if every variant sharing that build
#     number has already lapsed — the conservative direction, since a false
#     "still supported" is a missed alert but a false "EOL" is an alarm an
#     admin will (correctly) distrust. MSRC remains the precise source for
#     Windows patch-level gaps; this only adds the EOL fact on top.
#   - Android: endoflife.date has no patch-level "latest" for Android (it
#     only versions by major release), matching the same coarser precision
#     _compute_android_pending_vulns already documents.
#
# Not verified against this app's live device data (Applivery's exact
# osVersion formatting per platform) — same "check on first real refresh"
# caveat as the other two OS intelligence sections.

OS_LIFECYCLE_DIR = os.path.join(DATA_DIR, "os_lifecycle")
OS_LIFECYCLE_FILE = os.path.join(OS_LIFECYCLE_DIR, "catalog.json")
ENDOFLIFE_API_BASE = "https://endoflife.date/api/v1/products"
OS_LIFECYCLE_TICK_SECONDS = 604800  # weekly — lifecycle/EOL metadata changes far less often than KB/CVE data, and this is a free community-run API worth being light on

async def _fetch_endoflife_product(client: httpx.AsyncClient, product: str) -> Optional[dict]:
    try:
        resp = await client.get(f"{ENDOFLIFE_API_BASE}/{product}", timeout=30.0)
        resp.raise_for_status()
        return resp.json().get('result')
    except Exception as e:
        print(f"[OS Lifecycle] Failed to fetch endoflife.date product '{product}': {e}")
        return None

async def _refresh_os_lifecycle_catalog() -> dict:
    catalog = _load_os_lifecycle_catalog()
    had_success = False
    per_platform: Dict[str, List[dict]] = {}
    async with httpx.AsyncClient(timeout=httpx.Timeout(30.0)) as client:
        for platform, product in (("windows", "windows"), ("apple", "ios"), ("macos", "macos"), ("android", "android")):
            result = await _fetch_endoflife_product(client, product)
            if not result:
                continue
            had_success = True
            releases = []
            for r in (result.get('releases') or []):
                latest = r.get('latest') or {}
                releases.append({
                    "name": r.get('name'), "label": r.get('label'), "releaseDate": r.get('releaseDate'),
                    "latestVersion": latest.get('name'), "latestDate": latest.get('date'),
                    "isEol": bool(r.get('isEol')), "eolFrom": r.get('eolFrom'),
                    "isMaintained": bool(r.get('isMaintained')),
                    "isEoes": r.get('isEoes'), "eoesFrom": r.get('eoesFrom'),  # Windows-only: paid Extended Security Updates window
                })
            per_platform[platform] = releases

    if had_success:
        catalog['platforms'] = per_platform
        catalog['lastFetchedAt'] = datetime.now(timezone.utc).isoformat()
        catalog['lastError'] = None
    elif not catalog.get('platforms'):
        catalog['lastError'] = 'No endoflife.date data fetched yet — check network access to endoflife.date'
    _save_os_lifecycle_catalog(catalog)
    return catalog

_register_legacy_json('os_lifecycle_catalog', lambda slug, key: OS_LIFECYCLE_FILE)

def _load_os_lifecycle_catalog() -> dict:
    return _store_load(_GLOBAL_STORE_SLUG, 'os_lifecycle_catalog', lambda: {"platforms": {}, "lastFetchedAt": None, "lastError": None})

def _save_os_lifecycle_catalog(catalog: dict):
    _store_save(_GLOBAL_STORE_SLUG, 'os_lifecycle_catalog', catalog)

async def os_lifecycle_refresh_loop():
    while True:
        try:
            await _refresh_os_lifecycle_catalog()
            _record_job_heartbeat('os_lifecycle_refresh', 'ok')
        except Exception as e:
            print(f"[OS Lifecycle] Error: {e}")
            _record_job_heartbeat('os_lifecycle_refresh', 'error', str(e))
        await asyncio.sleep(OS_LIFECYCLE_TICK_SECONDS)

# ─── APPLE SOFTWARE LOOKUP SERVICE (GDMF) ───
# A precision upgrade to the Apple half of OS Lifecycle above, confirmed
# working against a live curl test (2026-07-19): gdmf.apple.com/v2/pmv is
# Apple's own official feed of currently-signed, installable OS releases —
# the same source Declarative Device Management now expects UEMs to use in
# place of the legacy AvailableOSUpdates MDM command. Public, unauthenticated,
# `Accept: application/json`. It gives what endoflife.date can't: an exact
# Build string per ProductVersion, and an ExpirationDate — Apple stops
# cryptographically signing an update ~180 days after release, so an
# "available" update past its ExpirationDate is actually dead (the device
# will reject the install even if pushed). We use the `AssetSets` root key
# (Apple's own guidance: PublicAssetSets is only the single newest release;
# AssetSets is the fuller list a UEM should reconcile against, since older
# still-signed point releases matter for devices that can't jump straight to
# the newest one). iOS/iPadOS/tvOS/watchOS are bundled under one "iOS" array
# by Apple; we only pull the "iOS" and "macOS" arrays since those are the
# platforms this app tracks.
#
# Apple explicitly asks UEMs not to poll this more than once a day — we
# match that exactly (same interval as the Windows catalog, not tighter).
#
# Hardware gating (SupportedDevices): each release lists which hardware
# identifiers it applies to (e.g. "iPhone15,2"). Matching this precisely
# requires the device's technical model identifier, which is a different
# thing from a human-readable "iPhone 15 Pro" string. Applivery's device
# `model` field format hasn't been confirmed against a live tenant — if it
# turns out to already be the technical identifier (Apple's own MDM
# DeviceInformation command's `Model` key normally is), matching is exact;
# if it's a marketing name instead, matching silently fails and we fall
# back to the fleet-wide newest-non-expired version, flagged with
# hardwareMatched: false rather than pretending certainty either way.
#
# Rapid Security Responses (RSRs — the "(a)"/"(b)" suffixed releases Apple
# ships between full point releases, e.g. "iOS 16.5.1 (a)", often for an
# actively-exploited 0-day): GDMF carries these in a third root array
# alongside AssetSets and PublicAssetSets. This app has not been able to
# fetch a live GDMF response directly (this sandbox's outbound network
# couldn't reach gdmf.apple.com — every attempt returned empty), so the key
# name and per-entry field names below are taken from third-party
# documentation rather than a verified live response, and are tried
# defensively (both plausible key spellings, every field via .get()) so a
# wrong guess degrades to "zero RSR entries found" rather than an error.
# Treat the RSR count on first real refresh as the thing to sanity-check.
# RSR "versions" aren't reliably comparable via a plain numeric tuple (the
# "(a)" suffix isn't a version segment), so an RSR is surfaced as a
# separate supplemental signal — "does a security response exist on top of
# your current version" — rather than folded into the linear
# latestKnownVersion comparison above.
GDMF_RSR_KEYS = ("PublicBackgroundSecurityImprovements", "PublicRapidSecurityResponses")

GDMF_DIR = os.path.join(DATA_DIR, "gdmf")
GDMF_FILE = os.path.join(GDMF_DIR, "catalog.json")
GDMF_URL = "https://gdmf.apple.com/v2/pmv"
GDMF_TICK_SECONDS = 86400  # daily — Apple's own stated limit for UEM polling

def _parse_gdmf_release(a: dict, now: datetime) -> dict:
    expiration = a.get('ExpirationDate')
    is_expired = False
    if expiration:
        try:
            exp_dt = datetime.fromisoformat(str(expiration).replace('Z', '+00:00'))
            is_expired = now > exp_dt
        except Exception:
            pass
    return {
        "productVersion": a.get('ProductVersion'), "build": a.get('Build'),
        "postingDate": a.get('PostingDate'), "expirationDate": expiration,
        "isExpired": is_expired, "supportedDevices": a.get('SupportedDevices') or [],
        # RSR-specific fields, when present — defensive .get() since this
        # entry shape is unverified (see module comment above).
        "supplementalBuildVersion": a.get('SupplementalBuildVersion') or a.get('SEBuildVersion'),
        "cveIds": a.get('CVEs') or a.get('cveIds') or [],
    }

async def _refresh_gdmf_catalog() -> dict:
    catalog = _load_gdmf_catalog()
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(30.0)) as client:
            resp = await client.get(GDMF_URL, headers={"Accept": "application/json"})
            resp.raise_for_status()
            body = resp.json()
        asset_sets = body.get('AssetSets') or {}
        rsr_set = {}
        for rsr_key in GDMF_RSR_KEYS:
            if body.get(rsr_key):
                rsr_set = body[rsr_key]
                break
        now = datetime.now(timezone.utc)
        platforms: Dict[str, List[dict]] = {}
        rsrs: Dict[str, List[dict]] = {}
        for platform, gdmf_key in (("apple", "iOS"), ("macos", "macOS")):
            platforms[platform] = [_parse_gdmf_release(a, now) for a in (asset_sets.get(gdmf_key) or [])]
            try:
                rsrs[platform] = [_parse_gdmf_release(a, now) for a in (rsr_set.get(gdmf_key) or [])]
            except Exception as e:
                print(f"[GDMF] RSR parse failed for '{gdmf_key}' (unverified schema): {e}")
                rsrs[platform] = []
        catalog['platforms'] = platforms
        catalog['rapidSecurityResponses'] = rsrs
        catalog['lastFetchedAt'] = now.isoformat()
        catalog['lastError'] = None
    except Exception as e:
        print(f"[GDMF] Fetch failed: {e}")
        if not catalog.get('platforms'):
            catalog['lastError'] = f'No GDMF data fetched yet: {e}'
    _save_gdmf_catalog(catalog)
    return catalog

_register_legacy_json('gdmf_catalog', lambda slug, key: GDMF_FILE)

def _load_gdmf_catalog() -> dict:
    return _store_load(_GLOBAL_STORE_SLUG, 'gdmf_catalog', lambda: {"platforms": {}, "rapidSecurityResponses": {}, "lastFetchedAt": None, "lastError": None})

def _save_gdmf_catalog(catalog: dict):
    _store_save(_GLOBAL_STORE_SLUG, 'gdmf_catalog', catalog)

async def gdmf_refresh_loop():
    while True:
        try:
            await _refresh_gdmf_catalog()
            _record_job_heartbeat('gdmf_refresh', 'ok')
        except Exception as e:
            print(f"[GDMF] Error: {e}")
            _record_job_heartbeat('gdmf_refresh', 'error', str(e))
        await asyncio.sleep(GDMF_TICK_SECONDS)

def _gdmf_best_target(platform: str, device_model: Optional[str], gdmf_catalog: Optional[dict]) -> Optional[dict]:
    """Pick the release a device should be offered: highest ProductVersion
    among currently-signed (non-expired) entries, preferring ones whose
    SupportedDevices explicitly names this device's model when we can
    confirm that match. Returns None if GDMF has no usable data for this
    platform yet (never raises, never guesses past what's actually there)."""
    if not gdmf_catalog:
        return None
    entries = [e for e in ((gdmf_catalog.get('platforms') or {}).get(platform) or []) if not e.get('isExpired')]
    if not entries:
        return None
    hardware_matched = False
    if device_model:
        matched = [e for e in entries if device_model in (e.get('supportedDevices') or [])]
        if matched:
            entries = matched
            hardware_matched = True
    best = max(entries, key=lambda e: _version_tuple(e.get('productVersion') or ''))
    return {
        "productVersion": best.get('productVersion'), "build": best.get('build'),
        "expirationDate": best.get('expirationDate'), "hardwareMatched": hardware_matched,
    }

def _gdmf_active_rsr(platform: str, base_product_version: Optional[str], device_model: Optional[str], gdmf_catalog: Optional[dict]) -> Optional[dict]:
    """Is there a currently-signed Rapid Security Response attached on top
    of `base_product_version` (the device's GDMF-matched base release)?
    Best-effort — see the GDMF module comment on RSR schema uncertainty.
    Returns None if there's no RSR data at all (not the same as 'none
    active' — see the 'available' flag callers should check)."""
    if not gdmf_catalog or not base_product_version:
        return None
    rsr_entries = (gdmf_catalog.get('rapidSecurityResponses') or {}).get(platform) or []
    if not rsr_entries:
        return {"available": False}
    candidates = [
        e for e in rsr_entries
        if not e.get('isExpired') and (e.get('productVersion') or '').startswith(str(base_product_version))
    ]
    if device_model:
        hw_matched = [e for e in candidates if device_model in (e.get('supportedDevices') or [])]
        if hw_matched:
            candidates = hw_matched
    if not candidates:
        return {"available": False}
    latest = candidates[0]
    return {
        "available": True, "version": latest.get('productVersion'),
        "supplementalBuildVersion": latest.get('supplementalBuildVersion'), "build": latest.get('build'),
        "cveIds": latest.get('cveIds') or [],
    }

def _compute_os_lifecycle_status(platform: str, os_version: str, catalog: dict, device_model: Optional[str] = None, gdmf_catalog: Optional[dict] = None) -> Optional[dict]:
    """None if osVersion is empty or the platform isn't one we track lifecycle
    for. Otherwise {'trainLabel','isEol','isMaintained','onLatestVersion',
    'latestKnownVersion','eolFrom','esuUntil','confidence', + for apple/macos
    when GDMF data is available: 'latestKnownBuild','updateExpirationDate',
    'hardwareMatched'}."""
    if not os_version:
        return None
    releases = (catalog.get('platforms') or {}).get(platform) or []
    if not releases:
        return None

    if platform == 'windows':
        device_build = _windows_device_build(os_version)
        if not device_build:
            return None
        matches = []
        for r in releases:
            lv = _version_tuple(r.get('latestVersion') or '')
            if len(lv) >= 3 and lv[2] == device_build['buildMajor']:
                matches.append(r)
        if not matches:
            return {"trainLabel": device_build['featureLabel'], "isEol": None, "isMaintained": None,
                    "onLatestVersion": None, "latestKnownVersion": None, "eolFrom": None, "esuUntil": None, "confidence": "unknown"}
        # Conservative rule — see section docstring: only EOL if every channel variant sharing this build has lapsed.
        is_eol = all(r['isEol'] for r in matches)
        esu_until = max((r['eoesFrom'] for r in matches if r.get('eoesFrom')), default=None)
        return {
            "trainLabel": device_build['featureLabel'], "isEol": is_eol, "isMaintained": any(r['isMaintained'] for r in matches),
            "onLatestVersion": None, "latestKnownVersion": matches[0].get('latestVersion'),
            "eolFrom": max((r['eolFrom'] for r in matches if r.get('eolFrom')), default=None),
            "esuUntil": esu_until, "confidence": "version",
        }

    # Apple (iOS/iPadOS) / macOS / Android — all major-version-keyed.
    device_v = _version_tuple(os_version)
    if not device_v or device_v[0] == 0:
        return None
    device_major = str(device_v[0])
    match = next((r for r in releases if str(r.get('name')) == device_major), None)
    if not match:
        return {"trainLabel": f"v{device_major}", "isEol": None, "isMaintained": None, "onLatestVersion": None,
                "latestKnownVersion": None, "eolFrom": None, "esuUntil": None, "confidence": "unknown"}
    latest_version = match.get('latestVersion')

    result = {
        "trainLabel": match.get('label') or match.get('name'), "isEol": match.get('isEol'), "isMaintained": match.get('isMaintained'),
        "onLatestVersion": None, "latestKnownVersion": latest_version, "eolFrom": match.get('eolFrom'),
        "esuUntil": None, "confidence": "version",
    }
    if platform in ('apple', 'macos'):
        # GDMF (gdmf.apple.com), when available, is the more precise source
        # for "what's actually installable right now" — exact build +
        # cryptographic-signing validity, vs endoflife.date's marketing
        # version number. Override latestKnownVersion with it and add the
        # extra fields; fall back to endoflife's figure if GDMF has nothing
        # for this platform yet (e.g. before its first successful fetch).
        gdmf_target = _gdmf_best_target(platform, device_model, gdmf_catalog)
        if gdmf_target and gdmf_target.get('productVersion'):
            result['latestKnownVersion'] = gdmf_target['productVersion']
            result['latestKnownBuild'] = gdmf_target.get('build')
            result['updateExpirationDate'] = gdmf_target.get('expirationDate')
            result['hardwareMatched'] = gdmf_target.get('hardwareMatched')
        result['onLatestVersion'] = _version_tuple(os_version) >= _version_tuple(result['latestKnownVersion']) if result['latestKnownVersion'] else None
        # Rapid Security Response check is against the device's own current
        # base version (not the latest target above) — it answers "is there
        # a supplemental security patch sitting on top of what this device
        # already has," independent of whether a full point-release update
        # is also pending.
        result['rapidSecurityResponse'] = _gdmf_active_rsr(platform, os_version, device_model, gdmf_catalog)
    return result

@app.get("/api/os-lifecycle/catalog", dependencies=[Depends(verify_dashboard_token)])
async def get_os_lifecycle_catalog():
    """Global, not per-workspace — same reasoning as the other two catalogs."""
    catalog = _load_os_lifecycle_catalog()
    return {
        "platforms": catalog.get('platforms') or {}, "lastFetchedAt": catalog.get('lastFetchedAt'),
        "lastError": catalog.get('lastError'),
    }

@app.post("/api/os-lifecycle/refresh", dependencies=[Depends(verify_dashboard_token)])
async def refresh_os_lifecycle_catalog_now():
    catalog = await _refresh_os_lifecycle_catalog()
    _record_job_heartbeat('os_lifecycle_refresh', 'ok' if not catalog.get('lastError') else 'error', catalog.get('lastError'))
    platform_counts = {k: len(v) for k, v in (catalog.get('platforms') or {}).items()}
    return {"platformCounts": platform_counts, "lastFetchedAt": catalog.get('lastFetchedAt'), "lastError": catalog.get('lastError')}

@app.get("/api/gdmf/catalog", dependencies=[Depends(verify_dashboard_token)])
async def get_gdmf_catalog():
    """Global, not per-workspace — Apple's own public feed, not tenant data."""
    catalog = _load_gdmf_catalog()
    return {
        "platforms": catalog.get('platforms') or {}, "rapidSecurityResponses": catalog.get('rapidSecurityResponses') or {},
        "lastFetchedAt": catalog.get('lastFetchedAt'), "lastError": catalog.get('lastError'),
    }

@app.post("/api/gdmf/refresh", dependencies=[Depends(verify_dashboard_token)])
async def refresh_gdmf_catalog_now():
    """Manual refresh still respects the same client — Apple's once-a-day
    guidance is about total request volume against their CDN, and a single
    admin-triggered click alongside the daily background tick is the kind
    of occasional use that guidance is aimed at, not automated hammering."""
    catalog = await _refresh_gdmf_catalog()
    _record_job_heartbeat('gdmf_refresh', 'ok' if not catalog.get('lastError') else 'error', catalog.get('lastError'))
    platform_counts = {k: len(v) for k, v in (catalog.get('platforms') or {}).items()}
    return {"platformCounts": platform_counts, "lastFetchedAt": catalog.get('lastFetchedAt'), "lastError": catalog.get('lastError')}

# ─── SYSTEM HEALTH (background job heartbeats) ───
# A lightweight "is this loop actually alive" registry. Every scheduler loop
# above (compliance evaluation, ticketing sync, installed-apps refresher,
# workflow wait-resumer, snapshot capture, scheduled reports, audit log
# rotation, log export, script log reconciliation, Case SLA monitoring)
# records a heartbeat here at the end of every tick — success or caught
# failure. This exists because every one of those loops already swallows its
# own exceptions (`except Exception as e: print(...)`) so a single bad tick
# never kills the loop — but that same design means a *process-wide* crash
# (an exception the try/except doesn't cover, or the loop never getting
# scheduled at all) is currently invisible: no error, just silence, and the
# only symptom is stale data an admin might not notice for days.
#
# Global, not per-workspace: every one of these loops already iterates every
# workspace internally per tick, so "did the loop run" is one process-wide
# fact. Persisted to disk (not just kept in memory) so a restart doesn't
# wipe the last-known state before Settings > System Health has a chance to
# read it.
SYSTEM_HEALTH_FILE = os.path.join(DATA_DIR, "system_health.json")

# label + expected tick interval for every job that calls _record_job_heartbeat
# — used below to flag a job "overdue" (hasn't reported in well over its own
# interval) even when it's never logged an error, which is exactly the
# silent-death case this feature exists to catch.
SYSTEM_HEALTH_JOBS = {
    "compliance_scheduler":     {"label": "Compliance Policy scheduler",  "intervalSeconds": COMPLIANCE_SCHEDULER_TICK_SECONDS},
    "installed_apps_refresher": {"label": "Installed apps refresher",     "intervalSeconds": INSTALLED_APPS_REFRESH_TICK_SECONDS},
    "workflow_wait_resumer":    {"label": "Workflow wait-step resumer",   "intervalSeconds": WORKFLOW_RESUMER_TICK_SECONDS},
    "script_log_reconciler":    {"label": "Script run reconciler",        "intervalSeconds": SCRIPT_RUN_RECONCILE_TICK_SECONDS},
    "ticket_status_sync":       {"label": "Ticketing inbound sync",       "intervalSeconds": TICKET_SYNC_TICK_SECONDS},
    "case_sla_monitor":         {"label": "Case SLA breach monitor",      "intervalSeconds": CASE_SLA_MONITOR_TICK_SECONDS},
    "os_update_catalog_refresh": {"label": "OS update catalog refresh (MSRC)", "intervalSeconds": OS_UPDATE_CATALOG_TICK_SECONDS},
    "vuln_catalog_refresh":     {"label": "Vulnerability catalog refresh (EUVD)", "intervalSeconds": VULN_CATALOG_TICK_SECONDS},
    "vuln_service_refresh":     {"label": "Vulnerability Service refresh",  "intervalSeconds": VULN_SERVICE_TICK_SECONDS},
    "os_lifecycle_refresh":     {"label": "OS lifecycle refresh (endoflife.date)", "intervalSeconds": OS_LIFECYCLE_TICK_SECONDS},
    "gdmf_refresh":             {"label": "Apple Software Lookup Service refresh (GDMF)", "intervalSeconds": GDMF_TICK_SECONDS},
    "mitre_catalog_refresh":    {"label": "MITRE ATT&CK catalog refresh",  "intervalSeconds": MITRE_CATALOG_TICK_SECONDS},
    "audit_log_rotation":       {"label": "Audit log rotation",           "intervalSeconds": 86400},
    "log_export_scheduler":     {"label": "Log export scheduler",         "intervalSeconds": LOG_EXPORT_TICK_SECONDS},
    "snapshot_scheduler":       {"label": "Analytics snapshot capture",   "intervalSeconds": 86400},
    "report_scheduler":         {"label": "Scheduled report delivery",    "intervalSeconds": 60},
    "system_health_monitor":    {"label": "System health alert monitor",  "intervalSeconds": 300},
}

def _system_health_job_overdue(meta: dict, entry: dict, now: datetime) -> bool:
    """Shared by GET /api/system-health (display) and
    system_health_monitor_loop (alerting), so the two never disagree about
    what "overdue" means. 3x a job's own interval, with a 5-minute floor —
    a 60s-tick job missing 3 ticks in a row is meaningfully overdue, but a
    once-a-day job shouldn't need to wait 3 days to flag."""
    last_run_at = entry.get('lastRunAt')
    if not last_run_at:
        return True
    try:
        last_dt = datetime.fromisoformat(last_run_at.replace('Z', '+00:00'))
        return (now - last_dt).total_seconds() > max(meta['intervalSeconds'] * 3, 300)
    except Exception:
        return True

_register_legacy_json('system_health', lambda slug, key: SYSTEM_HEALTH_FILE)

def _load_system_health() -> Dict[str, Any]:
    return _store_load(_GLOBAL_STORE_SLUG, 'system_health', dict)

def _record_job_heartbeat(job_key: str, status: str, detail: Optional[str] = None):
    """status: 'ok' | 'error'. Called at the end of every tick from inside
    each loop's own try/except (the print(f"[X] Error: {e}") lines already
    throughout this file), so those errors surface in Settings > System
    Health too, not just server logs nobody's tailing. Failure to write is
    swallowed — health tracking must never be the thing that takes down a
    scheduler loop."""
    try:
        health = _load_system_health()
        now_iso = datetime.now(timezone.utc).isoformat()
        entry = health.get(job_key, {})
        entry['lastRunAt'] = now_iso
        entry['lastStatus'] = status
        entry['lastDetail'] = (detail or '')[:300] or None
        if status == 'ok':
            entry['lastSuccessAt'] = now_iso
            entry['consecutiveErrors'] = 0
        else:
            entry['lastErrorAt'] = now_iso
            entry['consecutiveErrors'] = entry.get('consecutiveErrors', 0) + 1
        health[job_key] = entry
        _store_save(_GLOBAL_STORE_SLUG, 'system_health', health)
    except Exception as e:
        print(f"[System Health] Failed to record heartbeat for '{job_key}': {e}")

@app.get("/api/system-health", dependencies=[Depends(verify_dashboard_token)])
async def get_system_health():
    """Global, not per-workspace — see SYSTEM_HEALTH_FILE comment above.
    Every dashboard-token holder can see it regardless of which workspace
    they're currently viewing, same as any other cross-workspace
    operational signal in this app would be."""
    health = _load_system_health()
    now = datetime.now(timezone.utc)
    jobs = []
    for key, meta in SYSTEM_HEALTH_JOBS.items():
        entry = health.get(key) or {}
        overdue = _system_health_job_overdue(meta, entry, now)
        jobs.append({
            "key": key, "label": meta['label'], "intervalSeconds": meta['intervalSeconds'],
            "lastRunAt": entry.get('lastRunAt'), "lastStatus": entry.get('lastStatus'), "lastDetail": entry.get('lastDetail'),
            "lastSuccessAt": entry.get('lastSuccessAt'), "lastErrorAt": entry.get('lastErrorAt'),
            "consecutiveErrors": entry.get('consecutiveErrors', 0),
            "overdue": overdue,
            "alertedAt": entry.get('alertedAt'),
        })
    return {"items": jobs, "checkedAt": now.isoformat()}

async def _fire_system_health_alert(job_key: str, meta: dict, action: str, detail: str):
    """action: 'trigger' (job just went unhealthy) | 'resolve' (job just
    recovered). Fired from system_health_monitor_loop below. Uses the
    'global' integrations bucket (system health itself is global, not
    per-workspace — see SYSTEM_HEALTH_FILE comment) and only integrations
    that opted in via notifyOnSystemHealth, since this is a different
    audience/urgency than "a Case opened." Reuses the same chat/webhook
    senders as Case notifications by shaping the alert as a minimal
    case-like dict — same trick test_integration uses for its fake_case."""
    alert_case = {
        "id": f"system_health:{job_key}", "title": f"[System Health] {meta['label']}",
        "severity": "critical" if action == 'trigger' else 'low',
        "status": "open" if action == 'trigger' else 'closed',
        "source": "system_health", "deviceName": None,
    }
    event_type = 'created' if action == 'trigger' else 'closed'
    integrations = _load_integrations(_GLOBAL_STORE_SLUG)
    touched = False
    if integrations:
        async with httpx.AsyncClient() as client:
            for integ in integrations:
                if not integ.get('enabled', True) or not integ.get('notifyOnSystemHealth', False):
                    continue
                itype = integ.get('type')
                cfg = integ.get('config') or {}
                touched = True
                try:
                    if itype in ('slack', 'teams', 'discord'):
                        await _send_chat_notification(client, cfg.get('webhookUrl'), alert_case, event_type, itype)
                    elif itype == 'generic_webhook':
                        await _send_generic_webhook(client, cfg, alert_case, event_type)
                    elif itype in ('pagerduty', 'opsgenie'):
                        await _send_paging_event(
                            client, itype, cfg, dedup_key=f'system_health:{job_key}', action=action,
                            summary=f'{meta["label"]}: {detail}', severity='critical' if action == 'trigger' else 'low',
                            details={"job": job_key},
                        )
                    integ['lastFiredAt'] = datetime.now(timezone.utc).isoformat()
                    integ['fireCount'] = integ.get('fireCount', 0) + 1
                    integ['lastError'] = None
                except Exception as e:
                    integ['lastError'] = str(e)[:300]
                    print(f"[Integrations] '{integ.get('name')}' ({itype}) system health alert failed for '{job_key}': {e}")
    if touched:
        _save_integrations(_GLOBAL_STORE_SLUG, integrations)
    await _send_alert_email(
        _GLOBAL_STORE_SLUG,
        subject=f'[System Health] {meta["label"]} — {"DOWN" if action == "trigger" else "Recovered"}',
        body_text=detail,
    )

async def _check_system_health_and_alert():
    """Scans every job in SYSTEM_HEALTH_JOBS (including this loop itself)
    and fires a one-time alert the moment a job first becomes unhealthy
    (3+ consecutive errors, or overdue past 3x its own interval — same
    definition GET /api/system-health uses), then a one-time recovery
    notice once it reports healthy again. `alertedAt` on each job's health
    entry is the "already notified, don't re-page every tick" marker,
    mirroring Case SLA's slaAckBreachNotifiedAt/slaResolveBreachNotifiedAt
    pattern."""
    health = _load_system_health()
    now = datetime.now(timezone.utc)
    changed = False
    for key, meta in SYSTEM_HEALTH_JOBS.items():
        entry = health.get(key) or {}
        consecutive_errors = entry.get('consecutiveErrors', 0)
        overdue = _system_health_job_overdue(meta, entry, now)
        is_unhealthy = overdue or consecutive_errors >= 3
        was_alerted = bool(entry.get('alertedAt'))
        if is_unhealthy and not was_alerted:
            reason = f"failed {consecutive_errors} times in a row" if consecutive_errors >= 3 else "has not reported in over its expected interval — it may be stalled or crashed"
            detail = f'{meta["label"]} {reason}.'
            await _fire_system_health_alert(key, meta, 'trigger', detail)
            entry['alertedAt'] = now.isoformat()
            health[key] = entry
            changed = True
        elif not is_unhealthy and was_alerted:
            await _fire_system_health_alert(key, meta, 'resolve', f'{meta["label"]} has recovered.')
            entry['alertedAt'] = None
            health[key] = entry
            changed = True
    if changed:
        _store_save(_GLOBAL_STORE_SLUG, 'system_health', health)

async def system_health_monitor_loop():
    await asyncio.sleep(60)  # let every other loop get its first tick in before judging anyone overdue
    while True:
        try:
            await _check_system_health_and_alert()
            _record_job_heartbeat('system_health_monitor', 'ok')
        except Exception as e:
            print(f"[System Health Monitor] Error: {e}")
            _record_job_heartbeat('system_health_monitor', 'error', str(e))
        await asyncio.sleep(SYSTEM_HEALTH_JOBS['system_health_monitor']['intervalSeconds'])

# ─── HELP DOCS (in-app admin guides, rendered from the ⓘ button on every view) ───
# Raw markdown for docs/*.md plus the root README.md/ARCHITECTURE.md, copied
# into the image alongside main.py by the Dockerfile (see the "docs" COPY
# step) so they ship with every deployment rather than depending on the
# source repo being present at runtime. Keyed by a small fixed slug ->
# filename whitelist (not a raw filename param) to keep this from ever
# becoming a path-traversal read-any-file endpoint. Gated by nothing beyond
# a valid dashboard session — this is read-only help text, not sensitive
# configuration, so no RBAC area/level check is warranted.
def _resolve_docs_dir() -> str:
    # Docker: docs/ is copied in alongside main.py (see the Dockerfile),
    # so it's a sibling of this file. Local dev running `uvicorn main:app`
    # straight from big-picture-api/ has no such copy — fall back to the
    # repo-root docs/ two directories up, so nothing extra needs copying
    # just to develop against this endpoint locally.
    here = os.path.dirname(os.path.abspath(__file__))
    sibling = os.path.join(here, "docs")
    if os.path.isdir(sibling):
        return sibling
    repo_root_docs = os.path.join(here, "..", "docs")
    if os.path.isdir(repo_root_docs):
        return repo_root_docs
    return sibling  # neither exists yet — endpoint reports it clearly below

DOCS_DIR = _resolve_docs_dir()
HELP_DOC_SLUGS = {
    "overview": "overview.md",
    "devices": "devices.md",
    "compliance": "compliance.md",
    "cases": "cases.md",
    "workflows": "workflows.md",
    "reporting": "reporting.md",
    "settings": "settings.md",
    "audit-logs": "audit-logs.md",
    "playground": "playground.md",
    "readme": "README.md",
    "architecture": "ARCHITECTURE.md",
}

def _find_help_doc_path(filename: str) -> Optional[str]:
    # README.md/ARCHITECTURE.md live at the repo root, not inside docs/ —
    # the Dockerfile copies both into DOCS_DIR alongside docs/*.md so
    # there's one lookup directory in production, but local dev (running
    # `uvicorn main:app` straight from big-picture-api/, no copy step) only
    # has the repo-root originals. Check both spots rather than requiring
    # a manual copy just to develop against this endpoint locally.
    candidates = [os.path.join(DOCS_DIR, filename), os.path.join(DOCS_DIR, "..", filename)]
    for c in candidates:
        if os.path.isfile(c):
            return c
    return None

@app.get("/api/help/{doc_slug}")
async def get_help_doc(doc_slug: str, dash: dict = Depends(verify_dashboard_token)):
    filename = HELP_DOC_SLUGS.get(doc_slug)
    if not filename:
        raise HTTPException(status_code=404, detail="Unknown help document")
    path = _find_help_doc_path(filename)
    if not path:
        # Deployed image is missing the docs/ folder (e.g. an older build) —
        # fail with a clear, specific message rather than a raw 404 the
        # frontend can't explain to the admin.
        raise HTTPException(status_code=404, detail="This deployment doesn't have its help docs bundled — rebuild the image to include them.")
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    return {"slug": doc_slug, "content": content}

@app.get("/api/help")
async def list_help_docs(dash: dict = Depends(verify_dashboard_token)):
    return {"items": [{"slug": s, "available": _find_help_doc_path(f) is not None} for s, f in HELP_DOC_SLUGS.items()]}

# ─── SERVE REACT FRONTEND (SINGLE CONTAINER MODE) ───
# Ensure the following lines start at the very beginning of the line (no spaces)
from fastapi.staticfiles import StaticFiles
from fastapi.responses import FileResponse

# 1. Mount assets with proper indentation
if os.path.exists("dist/assets"):
    app.mount("/assets", StaticFiles(directory="dist/assets"), name="assets") # <-- This line MUST be indented

# 2. Catch-all route with proper indentation
@app.get("/{full_path:path}")
async def serve_frontend(full_path: str):
    # SECURITY FIX: Prevent path traversal scanners from hitting local system files
    if ".." in full_path or full_path.startswith("/"):
        return FileResponse("dist/index.html")
        
    file_path = os.path.join("dist", full_path)
    if os.path.isfile(file_path):
        return FileResponse(file_path)
        
    # If it's not a file, return the React index.html so React Router can handle it
    return FileResponse("dist/index.html")